        private sealed class BaseMeshLikeOriginal
        {
            public string Name;
            public int VertexFormatLikeOriginal;
            public VertexStreamLikeOriginal ImmediateStreamLikeOriginal;
            public VertexStreamLikeOriginal[] GArrayLikeOriginal;
            public VertexTnLLikeOriginal[][] GArrayVertexPtrLikeOriginal;
            public int[] NInGarrLikeOriginal;
            public int[] MaxInGarrLikeOriginal;
            public VertexTnL2LikeOriginal[] GVERLikeOriginal;
            public int GVERVertexCountLikeOriginal;
            public VertexTnLLikeOriginal[] GVGVertexPtrLikeOriginal;
            public int[] TIDXLikeOriginal;
            public int NGFVERTLikeOriginal;
            public VertexTnL2LikeOriginal[] GroundSourceVerticesLikeOriginal;
            public int GroundSourceVertexCountLikeOriginal;
            public int[] GroundSourceFactureIdsLikeOriginal;
            public bool PreferDot3LikeOriginal;
            public bool UsesVertexPtrLikeOriginal;
            public bool RefreshRuntimeMeshOnDrawLikeOriginal;
            public Mesh RuntimeMeshLikeOriginal;
            public Mesh SharedRuntimeMeshLikeOriginal;
            public Material RuntimeMaterialLikeOriginal;
            public VertexTnL2LikeOriginal[] VertexPtrLikeOriginal;
            public VertexTnL2LikeOriginal[] SharedVertexPtrLikeOriginal;
            public List<SubMeshSubmitRangeLikeOriginal> SharedSubmitRangesLikeOriginal;
            public int ActiveSubmitFirstVertexLikeOriginal;
            public int ActiveSubmitVertexCountLikeOriginal;
            public int ActiveSubMeshIndexLikeOriginal = -1;
            public int NVertLikeOriginal;
            public int NIndLikeOriginal;
            public int NPriLikeOriginal;
            public int BoundFactureIdLikeOriginal = -1;
            public bool BoundDot3LikeOriginal;
            public VertexTnL2LikeOriginal[] UploadScratchVertexPtrLikeOriginal;
            public GroundTextureCatalog GroundCatalogLikeOriginal;
            public GroundRuntimeConfig GroundRuntimeConfigLikeOriginal;
            public Shader LightShaderLikeOriginal;
            public Shader DotShaderLikeOriginal;
            public Texture DefaultFactureTextureLikeOriginal;
            public Vector2Int ViewportLikeOriginal;
            public Shader ActiveShaderLikeOriginal;
            public Texture Texture0LikeOriginal;
            public Texture Texture1LikeOriginal;

            public VertexStreamLikeOriginal ResolveStreamLikeOriginal(int factureId)
            {
                if (GArrayLikeOriginal == null)
                    return ImmediateStreamLikeOriginal;
                if (factureId < 0 || factureId >= GArrayLikeOriginal.Length)
                    return ImmediateStreamLikeOriginal;
                return GArrayLikeOriginal[factureId];
            }

            public void SetVertexPtrLikeOriginal(VertexTnL2LikeOriginal[] vertexPtr)
            {
                VertexPtrLikeOriginal = vertexPtr;
            }

            public void SetNVertLikeOriginal(int nVert)
            {
                NVertLikeOriginal = nVert;
            }

            public void SetNIndLikeOriginal(int nInd)
            {
                NIndLikeOriginal = nInd;
            }

            public void SetNPriLikeOriginal(int nPri)
            {
                NPriLikeOriginal = nPri;
            }

            public bool BindImmediateStreamLikeOriginal()
            {
                return BindStreamLikeOriginal(ImmediateStreamLikeOriginal);
            }

            public bool SetVertexPtrFromGArrayLikeOriginal(int factureId)
            {
                if (GArrayLikeOriginal == null)
                    return BindStreamLikeOriginal(ResolveStreamLikeOriginal(factureId));
                if (factureId < 0 || factureId >= GArrayLikeOriginal.Length)
                    return false;

                VertexStreamLikeOriginal stream = GArrayLikeOriginal[factureId];
                int submitVertexCount = 0;
                if (NInGarrLikeOriginal != null && factureId < NInGarrLikeOriginal.Length)
                    submitVertexCount = Mathf.Max(0, NInGarrLikeOriginal[factureId]);
                if (submitVertexCount <= 0 && stream != null)
                    submitVertexCount = Mathf.Max(0, stream.VertexCountLikeOriginal);
                if (submitVertexCount <= 0 || RuntimeMeshLikeOriginal == null || RuntimeMaterialLikeOriginal == null)
                    return false;

                VertexTnLLikeOriginal[] rawGroundBucketLikeOriginal = null;
                if (GArrayVertexPtrLikeOriginal != null && factureId < GArrayVertexPtrLikeOriginal.Length)
                    rawGroundBucketLikeOriginal = GArrayVertexPtrLikeOriginal[factureId];

                if (rawGroundBucketLikeOriginal != null)
                {
                    EnsureVertexArrayCapacityLikeOriginal(ref UploadScratchVertexPtrLikeOriginal, submitVertexCount);
                    for (int i = 0; i < submitVertexCount; i++)
                        UploadScratchVertexPtrLikeOriginal[i] = ConvertGroundVertexToSubmitLikeOriginal(rawGroundBucketLikeOriginal[i]);
                    SetVertexPtrLikeOriginal(UploadScratchVertexPtrLikeOriginal);
                }
                else
                {
                    if (stream == null || stream.VertexPtrLikeOriginal == null)
                        return false;
                    SetVertexPtrLikeOriginal(stream.VertexPtrLikeOriginal);
                    UploadScratchVertexPtrLikeOriginal = null;
                }

                ActiveSubmitFirstVertexLikeOriginal = 0;
                ActiveSubmitVertexCountLikeOriginal = submitVertexCount;
                ActiveSubMeshIndexLikeOriginal = 0;
                SetNVertLikeOriginal(submitVertexCount);
                SetNIndLikeOriginal(submitVertexCount);
                SetNPriLikeOriginal(submitVertexCount / 3);
                BoundFactureIdLikeOriginal = factureId;
                BoundDot3LikeOriginal = stream != null && stream.Dot3LikeOriginal;
                return true;
            }

            public int ResolveActiveSubMeshFromRangeLikeOriginal()
            {
                if (SharedSubmitRangesLikeOriginal == null || SharedSubmitRangesLikeOriginal.Count == 0)
                    return ActiveSubMeshIndexLikeOriginal;

                int activeFirst = Mathf.Max(0, ActiveSubmitFirstVertexLikeOriginal);
                int activeCount = Mathf.Max(0, ActiveSubmitVertexCountLikeOriginal);
                if (activeCount <= 0)
                    return ActiveSubMeshIndexLikeOriginal;

                for (int i = 0; i < SharedSubmitRangesLikeOriginal.Count; i++)
                {
                    SubMeshSubmitRangeLikeOriginal range = SharedSubmitRangesLikeOriginal[i];
                    if (range == null)
                        continue;
                    if (range.FirstVertexLikeOriginal == activeFirst && range.VertexCountLikeOriginal == activeCount)
                        return i;
                }

                return ActiveSubMeshIndexLikeOriginal;
            }

            private bool BindStreamLikeOriginal(VertexStreamLikeOriginal stream)
            {
                Mesh runtimeMesh = SharedRuntimeMeshLikeOriginal != null ? SharedRuntimeMeshLikeOriginal : (stream != null ? stream.RuntimeMeshLikeOriginal : null);
                if (stream == null || runtimeMesh == null)
                    return false;

                RuntimeMaterialLikeOriginal = stream.Material;
                RuntimeMeshLikeOriginal = runtimeMesh;
                SetVertexPtrLikeOriginal(SharedVertexPtrLikeOriginal ?? stream.VertexPtrLikeOriginal);

                int submitVertexCount = stream.SubmitVertexCountLikeOriginal > 0 ? stream.SubmitVertexCountLikeOriginal : stream.VertexCountLikeOriginal;
                int submitFirstVertex = Mathf.Max(0, stream.SubmitFirstVertexLikeOriginal);

                ActiveSubmitFirstVertexLikeOriginal = submitFirstVertex;
                ActiveSubmitVertexCountLikeOriginal = submitVertexCount;
                ActiveSubMeshIndexLikeOriginal = SharedRuntimeMeshLikeOriginal != null && SharedSubmitRangesLikeOriginal != null && SharedSubmitRangesLikeOriginal.Count > 0
                    ? -1
                    : stream.SubmitSubMeshIndexLikeOriginal;
                SetNVertLikeOriginal(submitVertexCount);
                SetNIndLikeOriginal(submitVertexCount);
                SetNPriLikeOriginal(submitVertexCount / 3);
                BoundFactureIdLikeOriginal = stream.FactureIdLikeOriginal;
                BoundDot3LikeOriginal = stream.Dot3LikeOriginal;
                return true;
            }
        }



        [StructLayout(LayoutKind.Sequential)]
        private struct RuntimeSubmitVertexLikeOriginal
        {
            public Vector3 Position;
            public Color32 Color;
            public Vector2 Uv0;
            public Vector2 Uv1;
            public Vector4 Uv2;

            public RuntimeSubmitVertexLikeOriginal(VertexTnL2LikeOriginal v)
            {
                Position = new Vector3(v.X, v.Y, v.Z);
                Color = VertexTnL2LikeOriginal.UnpackDiffuseLikeOriginal(v.Diffuse);
                Uv0 = new Vector2(v.U, v.V);
                Uv1 = new Vector2(v.U2, v.V2);
                Uv2 = new Vector4(v.W, v.U2, v.V2, 0.0f);
            }
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct VertexTnLLikeOriginal
        {
            public float X;
            public float Y;
            public float Z;
            public float W;
            public uint Diffuse;
            public float U;
            public float V;

            public VertexTnLLikeOriginal(float x, float y, float z, float w, uint diffuse, float u, float v)
            {
                X = x;
                Y = y;
                Z = z;
                W = w;
                Diffuse = diffuse;
                U = u;
                V = v;
            }
        }

        private static VertexTnLLikeOriginal ConvertSurfaceVertexToGroundLikeOriginal(VertexTnL2LikeOriginal v)
        {
            return new VertexTnLLikeOriginal(v.X, v.Y, v.Z, v.W, v.Diffuse, v.U, v.V);
        }

        private static VertexTnL2LikeOriginal ConvertGroundVertexToSubmitLikeOriginal(VertexTnLLikeOriginal v)
        {
            return new VertexTnL2LikeOriginal(v.X, v.Y, v.Z, v.W, v.Diffuse, v.U, v.V, 0.0f, 0.0f);
        }

        private static void EnsureGroundVertexArrayCapacityLikeOriginal(ref VertexTnLLikeOriginal[] arr, int requiredVertices)
        {
            if (arr == null)
            {
                int capacity = 256;
                while (capacity < requiredVertices)
                    capacity <<= 1;
                arr = new VertexTnLLikeOriginal[capacity];
                return;
            }

            if (requiredVertices <= arr.Length)
                return;

            int newCap = arr.Length > 0 ? arr.Length : 256;
            while (newCap < requiredVertices)
                newCap <<= 1;
            Array.Resize(ref arr, newCap);
        }

        private static void AddTriangleToLinearGroundVertexArrayLikeOriginal(ref VertexTnLLikeOriginal[] verticesLikeOriginal, ref int vertexCountLikeOriginal, VertexTnLLikeOriginal v0, VertexTnLLikeOriginal v1, VertexTnLLikeOriginal v2)
        {
            EnsureGroundVertexArrayCapacityLikeOriginal(ref verticesLikeOriginal, vertexCountLikeOriginal + 3);
            verticesLikeOriginal[vertexCountLikeOriginal + 0] = v0;
            verticesLikeOriginal[vertexCountLikeOriginal + 1] = v1;
            verticesLikeOriginal[vertexCountLikeOriginal + 2] = v2;
            vertexCountLikeOriginal += 3;
        }

        private static void EnsureTidxCapacityLikeOriginal(ref int[] tidxLikeOriginal, int requiredVertices)
        {
            if (tidxLikeOriginal == null)
            {
                int capacity = 512 * 3;
                while (capacity < requiredVertices)
                    capacity += 512 * 3;
                tidxLikeOriginal = new int[capacity];
                return;
            }

            if (requiredVertices <= tidxLikeOriginal.Length)
                return;

            int newCap = tidxLikeOriginal.Length > 0 ? tidxLikeOriginal.Length : 512 * 3;
            while (newCap < requiredVertices)
                newCap += 512 * 3;
            Array.Resize(ref tidxLikeOriginal, newCap);
        }

        private struct StrictViewportLikeOriginal
        {
            public int X;
            public int Y;
            public int W;
            public int H;
            public int SurfaceW;
            public int SurfaceH;
            public int Mx;
            public int MLx;
            public int Gy;
            public int Gy1;
            public int ScLimit;
            public int TQuant;
            public int HQuant;
            public int SQuant;
            public int ScShift;
            public int Otstup;
        }

        private int GetStrictScShiftLikeOriginal()
        {
            return Mathf.Clamp(_strictZoomModeIndex, 0, 2);
        }

        private StrictViewportLikeOriginal ComputeStrictViewportLikeOriginal(Camera activeCamera)
        {
            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            int surfaceW = activeCamera != null ? Mathf.Max(1, Mathf.RoundToInt(activeCamera.pixelRect.width)) : Mathf.Max(1, Screen.width);
            int surfaceH = activeCamera != null ? Mathf.Max(1, Mathf.RoundToInt(activeCamera.pixelRect.height)) : Mathf.Max(1, Screen.height);
            int surfaceX = activeCamera != null ? Mathf.RoundToInt(activeCamera.pixelRect.x) : 0;
            int surfaceY = activeCamera != null ? Mathf.RoundToInt(activeCamera.pixelRect.y) : 0;

            int scShiftLikeOriginal = GetStrictScShiftLikeOriginal();
            int otstupLikeOriginal = 0;
            int tQuantLikeOriginal = 32 >> scShiftLikeOriginal;
            int hQuantLikeOriginal = 16 >> scShiftLikeOriginal;
            int sQuantLikeOriginal = 8 >> scShiftLikeOriginal;

            float scaleLikeOriginal = GetStrictScaleLikeOriginal();
            float viewVolLikeOriginal = GetStrictViewVolLikeOriginal(scaleLikeOriginal);

            int gyLikeOriginal = Mathf.FloorToInt(_strictMapY * hQuantLikeOriginal);
            int gy1LikeOriginal = gyLikeOriginal + surfaceH + 64;
            int scLimitLikeOriginal = gyLikeOriginal - (500 >> scShiftLikeOriginal);
            int mxLikeOriginal = runtimeMapLikeOriginal != null
                ? Mathf.Clamp(Mathf.FloorToInt(_strictMapX), 0, Mathf.Max(0, runtimeMapLikeOriginal.VertInLine - 2))
                : 0;
            int mLxLikeOriginal = runtimeMapLikeOriginal != null
                ? Mathf.Clamp(Mathf.CeilToInt(viewVolLikeOriginal / Mathf.Max(1, tQuantLikeOriginal)) + 2, 1, Mathf.Max(1, (runtimeMapLikeOriginal.VertInLine - 1) - mxLikeOriginal))
                : Mathf.Max(1, Mathf.CeilToInt(viewVolLikeOriginal / Mathf.Max(1, tQuantLikeOriginal)) + 2);

            float fracMapXLikeOriginal = _strictMapX - Mathf.Floor(_strictMapX);
            int xLikeOriginal = surfaceX + Mathf.RoundToInt(-fracMapXLikeOriginal * tQuantLikeOriginal) + 32 * otstupLikeOriginal;
            int yLikeOriginal = surfaceY;
            int wLikeOriginal = Mathf.Max(1, (mLxLikeOriginal - otstupLikeOriginal * 2) * tQuantLikeOriginal);
            int hLikeOriginal = Mathf.Max(1, surfaceH);

            return new StrictViewportLikeOriginal
            {
                X = xLikeOriginal,
                Y = yLikeOriginal,
                W = wLikeOriginal,
                H = hLikeOriginal,
                SurfaceW = surfaceW,
                SurfaceH = surfaceH,
                Mx = mxLikeOriginal,
                MLx = mLxLikeOriginal,
                Gy = gyLikeOriginal,
                Gy1 = gy1LikeOriginal,
                ScLimit = scLimitLikeOriginal,
                TQuant = tQuantLikeOriginal,
                HQuant = hQuantLikeOriginal,
                SQuant = sQuantLikeOriginal,
                ScShift = scShiftLikeOriginal,
                Otstup = otstupLikeOriginal
            };
        }

        private StrictViewportLikeOriginal BuildStrictViewportFallbackLikeOriginal(Vector2Int viewport)
        {
            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            int fallbackW = Mathf.Max(1, viewport.x);
            int fallbackH = Mathf.Max(1, viewport.y);
            int scShiftLikeOriginal = GetStrictScShiftLikeOriginal();
            int tQuantLikeOriginal = 32 >> scShiftLikeOriginal;
            int hQuantLikeOriginal = 16 >> scShiftLikeOriginal;
            int sQuantLikeOriginal = 8 >> scShiftLikeOriginal;
            int gyLikeOriginal = Mathf.FloorToInt(_strictMapY * hQuantLikeOriginal);
            return new StrictViewportLikeOriginal
            {
                X = 0,
                Y = 0,
                W = fallbackW,
                H = fallbackH,
                SurfaceW = fallbackW,
                SurfaceH = fallbackH,
                Mx = runtimeMapLikeOriginal != null ? Mathf.Clamp(Mathf.FloorToInt(_strictMapX), 0, Mathf.Max(0, runtimeMapLikeOriginal.VertInLine - 2)) : 0,
                MLx = Mathf.Max(1, Mathf.CeilToInt((float)fallbackW / Mathf.Max(1, tQuantLikeOriginal)) + 2),
                Gy = gyLikeOriginal,
                Gy1 = gyLikeOriginal + fallbackH + 64,
                ScLimit = gyLikeOriginal - (500 >> scShiftLikeOriginal),
                TQuant = tQuantLikeOriginal,
                HQuant = hQuantLikeOriginal,
                SQuant = sQuantLikeOriginal,
                ScShift = scShiftLikeOriginal,
                Otstup = 0
            };
        }

        private static void ApplyStrictViewportToMaterialLikeOriginal(Material mat, StrictViewportLikeOriginal viewportLikeOriginal)
        {
            if (mat == null)
                return;

            if (mat.HasProperty("_C2Viewport"))
                mat.SetVector("_C2Viewport", new Vector4(
                    Mathf.Max(1, viewportLikeOriginal.W),
                    Mathf.Max(1, viewportLikeOriginal.H),
                    viewportLikeOriginal.X,
                    viewportLikeOriginal.Y));

            if (mat.HasProperty("_C2ViewportRect"))
                mat.SetVector("_C2ViewportRect", new Vector4(
                    viewportLikeOriginal.X,
                    viewportLikeOriginal.Y,
                    Mathf.Max(1, viewportLikeOriginal.W),
                    Mathf.Max(1, viewportLikeOriginal.H)));
        }

        private static void SetShaderLikeOriginal(BaseMeshLikeOriginal meshLikeOriginal, Shader shaderLikeOriginal)
        {
            if (meshLikeOriginal == null)
                return;

            meshLikeOriginal.ActiveShaderLikeOriginal = shaderLikeOriginal;
            Material mat = meshLikeOriginal.RuntimeMaterialLikeOriginal ?? meshLikeOriginal.ImmediateStreamLikeOriginal?.Material;
            if (mat != null && shaderLikeOriginal != null && mat.shader != shaderLikeOriginal)
                mat.shader = shaderLikeOriginal;
        }

        private static void SetTextureLikeOriginal(BaseMeshLikeOriginal meshLikeOriginal, int stageLikeOriginal, Texture textureLikeOriginal)
        {
            if (meshLikeOriginal == null)
                return;

            if (stageLikeOriginal <= 0)
                meshLikeOriginal.Texture0LikeOriginal = textureLikeOriginal;
            else
                meshLikeOriginal.Texture1LikeOriginal = textureLikeOriginal;
        }

        private static Texture GetTextureLikeOriginal(BaseMeshLikeOriginal meshLikeOriginal, int stageLikeOriginal)
        {
            if (meshLikeOriginal == null)
                return null;
            return stageLikeOriginal <= 0 ? meshLikeOriginal.Texture0LikeOriginal : meshLikeOriginal.Texture1LikeOriginal;
        }

        private static void ApplySurfaceTextureStagesToMaterialLikeOriginal(Material mat, Texture stage0LikeOriginal, Texture stage1LikeOriginal)
        {
            if (mat == null)
                return;

            if (mat.HasProperty("_MainTex"))
                mat.SetTexture("_MainTex", stage0LikeOriginal ?? Texture2D.whiteTexture);
            if (mat.HasProperty("_CrossTex"))
                mat.SetTexture("_CrossTex", stage1LikeOriginal ?? Texture2D.whiteTexture);
        }

        private static void ApplyGroundTextureStagesToMaterialLikeOriginal(Material mat, bool dot3LikeOriginal, Texture stage0LikeOriginal, Texture stage1LikeOriginal)
        {
            if (mat == null)
                return;

            if (dot3LikeOriginal)
            {
                if (mat.HasProperty("_NormalTex"))
                    mat.SetTexture("_NormalTex", stage0LikeOriginal ?? Texture2D.normalTexture);
                if (mat.HasProperty("_MainTex"))
                    mat.SetTexture("_MainTex", stage1LikeOriginal ?? Texture2D.whiteTexture);
            }
            else
            {
                if (mat.HasProperty("_MainTex"))
                    mat.SetTexture("_MainTex", stage0LikeOriginal ?? Texture2D.whiteTexture);
                if (mat.HasProperty("_NormalTex"))
                    mat.SetTexture("_NormalTex", Texture2D.normalTexture);
            }
        }

        private BaseMeshLikeOriginal CreateDynamicSTriangMeshLikeOriginal(
            string name,
            Shader shader,
            Texture mainTex,
            Texture crossTex,
            int renderQueue,
            StrictViewportLikeOriginal viewportLikeOriginal)
        {
            if (shader == null || mainTex == null)
                return null;

            Material mat = new Material(shader);
            mat.name = name + "_mat";
            if (mat.HasProperty("_MainTex"))
                mat.SetTexture("_MainTex", mainTex);
            if (crossTex != null && mat.HasProperty("_CrossTex"))
                mat.SetTexture("_CrossTex", crossTex);
            if (mat.HasProperty("_C2UseStrictTnL"))
                mat.SetFloat("_C2UseStrictTnL", 1.0f);
            if (mat.HasProperty("_Color"))
                mat.SetColor("_Color", Color.white);
            if (mat.HasProperty("_BaseColor"))
                mat.SetColor("_BaseColor", Color.white);
            ApplyStrictViewportToMaterialLikeOriginal(mat, viewportLikeOriginal);
            mat.renderQueue = renderQueue;
            _terrainRuntimeOwnedObjects.Add(mat);

            Mesh runtimeMesh = new Mesh();
            runtimeMesh.name = string.IsNullOrEmpty(name) ? "STriangLikeOriginal_runtime" : name + "_runtime";
            runtimeMesh.MarkDynamic();
            _terrainRuntimeOwnedObjects.Add(runtimeMesh);

            VertexTnL2LikeOriginal[] emptyVertexPtrLikeOriginal = Array.Empty<VertexTnL2LikeOriginal>();
            VertexStreamLikeOriginal stStreamLikeOriginal = new VertexStreamLikeOriginal
            {
                Material = mat,
                RuntimeMeshLikeOriginal = runtimeMesh,
                VertexPtrLikeOriginal = emptyVertexPtrLikeOriginal,
                VertexCountLikeOriginal = 0,
                SubmitFirstVertexLikeOriginal = 0,
                SubmitVertexCountLikeOriginal = 0,
                FactureIdLikeOriginal = -1,
                Dot3LikeOriginal = false
            };

            BaseMeshLikeOriginal sTriangLikeOriginal = new BaseMeshLikeOriginal
            {
                Name = "STriang",
                VertexFormatLikeOriginal = 2,
                ImmediateStreamLikeOriginal = stStreamLikeOriginal,
                UsesVertexPtrLikeOriginal = true,
                RefreshRuntimeMeshOnDrawLikeOriginal = true,
                ActiveShaderLikeOriginal = shader,
                Texture0LikeOriginal = mainTex,
                Texture1LikeOriginal = crossTex
            };
            sTriangLikeOriginal.BindImmediateStreamLikeOriginal();
            return sTriangLikeOriginal;
        }

        private Mesh CreateRuntimeMeshFromVertexPtrLikeOriginal(string name, VertexTnL2LikeOriginal[] vertices, int vertexCount)
        {
            if (vertices == null || vertexCount <= 0)
                return null;

            Mesh mesh = new Mesh();
            mesh.name = string.IsNullOrEmpty(name) ? "BaseMeshLikeOriginal_runtime" : name;
            mesh.MarkDynamic();
            UploadRuntimeMeshDataLikeOriginal(mesh, vertices, vertexCount);
            _terrainRuntimeOwnedObjects.Add(mesh);
            return mesh;
        }

        private BaseMeshLikeOriginal CreateDynamicGroundMeshLikeOriginal(
            string name,
            VertexStreamLikeOriginal[] gArrayLikeOriginal,
            int[] nInGarrLikeOriginal,
            int[] maxInGarrLikeOriginal,
            VertexTnLLikeOriginal[] gVGVertexPtrLikeOriginal,
            int nGFVertLikeOriginal,
            int[] tIdxLikeOriginal,
            GroundTextureCatalog groundCatalogLikeOriginal,
            GroundRuntimeConfig groundRuntimeConfigLikeOriginal,
            Shader lightShaderLikeOriginal,
            Shader dotShaderLikeOriginal,
            Texture defaultFactureTextureLikeOriginal,
            int renderQueue,
            StrictViewportLikeOriginal viewportLikeOriginal)
        {
            if (gArrayLikeOriginal == null || nInGarrLikeOriginal == null || maxInGarrLikeOriginal == null || gVGVertexPtrLikeOriginal == null || tIdxLikeOriginal == null || lightShaderLikeOriginal == null || defaultFactureTextureLikeOriginal == null)
                return null;

            Shader bumpShaderLikeOriginal = FindGroundBumpShaderLikeOriginal();
            Shader initShaderLikeOriginal = bumpShaderLikeOriginal ?? dotShaderLikeOriginal ?? lightShaderLikeOriginal;
            Material mat = new Material(initShaderLikeOriginal);
            mat.name = name + "_mat";
            if (mat.HasProperty("_MainTex"))
                mat.SetTexture("_MainTex", defaultFactureTextureLikeOriginal);
            if (mat.HasProperty("_NormalTex"))
                mat.SetTexture("_NormalTex", Texture2D.normalTexture);
            if (mat.HasProperty("_C2UseStrictTnL"))
                mat.SetFloat("_C2UseStrictTnL", 1.0f);
