            return new BaseMeshLikeOriginal
            {
                Name = "GroundMesh",
                VertexFormatLikeOriginal = 1,
                GArrayLikeOriginal = gArrayLikeOriginal,
                GArrayVertexPtrLikeOriginal = new VertexTnLLikeOriginal[gArrayLikeOriginal.Length][],
                NInGarrLikeOriginal = nInGarrLikeOriginal,
                MaxInGarrLikeOriginal = maxInGarrLikeOriginal,
                GVGVertexPtrLikeOriginal = gVGVertexPtrLikeOriginal,
                TIDXLikeOriginal = tIdxLikeOriginal,
                NGFVERTLikeOriginal = nGFVertLikeOriginal,
                GroundSourceVerticesLikeOriginal = null,
                GroundSourceVertexCountLikeOriginal = 0,
                GroundSourceFactureIdsLikeOriginal = null,
                GroundCatalogLikeOriginal = groundCatalogLikeOriginal,
                GroundRuntimeConfigLikeOriginal = groundRuntimeConfigLikeOriginal,
                LightShaderLikeOriginal = lightShaderLikeOriginal,
                DotShaderLikeOriginal = dotShaderLikeOriginal ?? lightShaderLikeOriginal,
                DefaultFactureTextureLikeOriginal = defaultFactureTextureLikeOriginal,
                UsesVertexPtrLikeOriginal = true,
                RefreshRuntimeMeshOnDrawLikeOriginal = true,
                RuntimeMaterialLikeOriginal = mat,
                RuntimeMeshLikeOriginal = runtimeMesh,
                ViewportLikeOriginal = new Vector2Int(Mathf.Max(1, viewportLikeOriginal.W), Mathf.Max(1, viewportLikeOriginal.H)),
                ActiveShaderLikeOriginal = initShaderLikeOriginal,
                Texture0LikeOriginal = defaultFactureTextureLikeOriginal,
                Texture1LikeOriginal = null
            };
        }

        private bool ConfigureGroundMeshSharedRuntimeLikeOriginal(BaseMeshLikeOriginal groundMeshLikeOriginal, string name)
        {
            if (groundMeshLikeOriginal == null || groundMeshLikeOriginal.GArrayLikeOriginal == null)
                return false;

            var combinedVertices = new List<VertexTnL2LikeOriginal>(4096);
            var subMeshRanges = new List<SubMeshSubmitRangeLikeOriginal>();
            bool hasAnyStream = false;

            for (int factureId = 0; factureId < groundMeshLikeOriginal.GArrayLikeOriginal.Length; factureId++)
            {
                VertexStreamLikeOriginal stream = groundMeshLikeOriginal.GArrayLikeOriginal[factureId];
                if (stream == null || stream.VertexPtrLikeOriginal == null || stream.VertexCountLikeOriginal <= 0 || stream.Material == null)
                    continue;

                int sourceCount = Mathf.Min(stream.VertexCountLikeOriginal, stream.VertexPtrLikeOriginal.Length);
                if (sourceCount <= 0)
                    continue;

                int firstVertex = combinedVertices.Count;
                var indices = new int[sourceCount];
                for (int i = 0; i < sourceCount; i++)
                {
                    combinedVertices.Add(stream.VertexPtrLikeOriginal[i]);
                    indices[i] = firstVertex + i;
                }

                stream.SubmitFirstVertexLikeOriginal = firstVertex;
                stream.SubmitVertexCountLikeOriginal = sourceCount;
                stream.SubmitSubMeshIndexLikeOriginal = subMeshRanges.Count;
                subMeshRanges.Add(new SubMeshSubmitRangeLikeOriginal
                {
                    FirstVertexLikeOriginal = firstVertex,
                    VertexCountLikeOriginal = sourceCount,
                    IndicesLikeOriginal = indices
                });
                hasAnyStream = true;
            }

            if (!hasAnyStream || combinedVertices.Count <= 0 || subMeshRanges.Count <= 0)
                return false;

            VertexTnL2LikeOriginal[] sharedVertexPtr = combinedVertices.ToArray();
            Mesh sharedMesh = new Mesh();
            sharedMesh.name = string.IsNullOrEmpty(name) ? "GroundMeshLikeOriginal_shared" : name;
            sharedMesh.MarkDynamic();
            UploadRuntimeMeshDataWithSubMeshesLikeOriginal(sharedMesh, sharedVertexPtr, sharedVertexPtr.Length, subMeshRanges);
            _terrainRuntimeOwnedObjects.Add(sharedMesh);

            groundMeshLikeOriginal.SharedRuntimeMeshLikeOriginal = sharedMesh;
            groundMeshLikeOriginal.SharedVertexPtrLikeOriginal = sharedVertexPtr;
            groundMeshLikeOriginal.SharedSubmitRangesLikeOriginal = subMeshRanges;
            groundMeshLikeOriginal.RuntimeMeshLikeOriginal = sharedMesh;
            return true;
        }

        private static void UploadRuntimeMeshDataLikeOriginal(Mesh mesh, VertexTnL2LikeOriginal[] vertices, int vertexCount)
        {
            if (mesh == null)
                return;

            if (vertices == null || vertexCount <= 0)
            {
                mesh.Clear();
                return;
            }

            vertexCount = Mathf.Min(vertexCount, vertices.Length);
            var meshDataArray = Mesh.AllocateWritableMeshData(1);
            try
            {
                Mesh.MeshData meshData = meshDataArray[0];
                var vertexLayout = new[]
                {
                    new VertexAttributeDescriptor(VertexAttribute.Position, VertexAttributeFormat.Float32, 3),
                    new VertexAttributeDescriptor(VertexAttribute.Color, VertexAttributeFormat.UNorm8, 4),
                    new VertexAttributeDescriptor(VertexAttribute.TexCoord0, VertexAttributeFormat.Float32, 2),
                    new VertexAttributeDescriptor(VertexAttribute.TexCoord1, VertexAttributeFormat.Float32, 2),
                    new VertexAttributeDescriptor(VertexAttribute.TexCoord2, VertexAttributeFormat.Float32, 4)
                };
                meshData.SetVertexBufferParams(vertexCount, vertexLayout);
                NativeArray<RuntimeSubmitVertexLikeOriginal> dstVertices = meshData.GetVertexData<RuntimeSubmitVertexLikeOriginal>();
                for (int i = 0; i < vertexCount; i++)
                    dstVertices[i] = new RuntimeSubmitVertexLikeOriginal(vertices[i]);

                bool useUInt = vertexCount > 65535;
                int totalIndexCount = vertexCount;
                meshData.SetIndexBufferParams(totalIndexCount, useUInt ? IndexFormat.UInt32 : IndexFormat.UInt16);
                if (useUInt)
                {
                    NativeArray<uint> indices = meshData.GetIndexData<uint>();
                    for (int i = 0; i < totalIndexCount; i++)
                        indices[i] = (uint)i;
                }
                else
                {
                    NativeArray<ushort> indices = meshData.GetIndexData<ushort>();
                    for (int i = 0; i < totalIndexCount; i++)
                        indices[i] = (ushort)i;
                }

                meshData.subMeshCount = 1;
                meshData.SetSubMesh(0, new SubMeshDescriptor(0, totalIndexCount, MeshTopology.Triangles)
                {
                    firstVertex = 0,
                    vertexCount = vertexCount,
                    bounds = new Bounds(Vector3.zero, new Vector3(1000000f, 1000000f, 1000000f))
                }, MeshUpdateFlags.DontRecalculateBounds | MeshUpdateFlags.DontValidateIndices | MeshUpdateFlags.DontNotifyMeshUsers);

                mesh.Clear();
                Mesh.ApplyAndDisposeWritableMeshData(meshDataArray, mesh, MeshUpdateFlags.DontRecalculateBounds | MeshUpdateFlags.DontValidateIndices | MeshUpdateFlags.DontNotifyMeshUsers);
                mesh.bounds = new Bounds(Vector3.zero, new Vector3(1000000f, 1000000f, 1000000f));
                mesh.UploadMeshData(false);
            }
            catch
            {
                meshDataArray.Dispose();
                throw;
            }
        }

        private static void UploadRuntimeMeshDataWithSubMeshesLikeOriginal(Mesh mesh, VertexTnL2LikeOriginal[] vertices, int vertexCount, List<SubMeshSubmitRangeLikeOriginal> subMeshRanges)
        {
            if (mesh == null)
                return;

            if (vertices == null || vertexCount <= 0 || subMeshRanges == null || subMeshRanges.Count <= 0)
            {
                mesh.Clear();
                return;
            }

            vertexCount = Mathf.Min(vertexCount, vertices.Length);
            int totalIndexCount = 0;
            for (int i = 0; i < subMeshRanges.Count; i++)
                totalIndexCount += subMeshRanges[i] != null && subMeshRanges[i].IndicesLikeOriginal != null ? subMeshRanges[i].IndicesLikeOriginal.Length : 0;

            var meshDataArray = Mesh.AllocateWritableMeshData(1);
            try
            {
                Mesh.MeshData meshData = meshDataArray[0];
                meshData.subMeshCount = subMeshRanges.Count;
                var vertexLayout = new[]
                {
                    new VertexAttributeDescriptor(VertexAttribute.Position, VertexAttributeFormat.Float32, 3),
                    new VertexAttributeDescriptor(VertexAttribute.Color, VertexAttributeFormat.UNorm8, 4),
                    new VertexAttributeDescriptor(VertexAttribute.TexCoord0, VertexAttributeFormat.Float32, 2),
                    new VertexAttributeDescriptor(VertexAttribute.TexCoord1, VertexAttributeFormat.Float32, 2),
                    new VertexAttributeDescriptor(VertexAttribute.TexCoord2, VertexAttributeFormat.Float32, 4)
                };
                meshData.SetVertexBufferParams(vertexCount, vertexLayout);
                NativeArray<RuntimeSubmitVertexLikeOriginal> dstVertices = meshData.GetVertexData<RuntimeSubmitVertexLikeOriginal>();
                for (int i = 0; i < vertexCount; i++)
                    dstVertices[i] = new RuntimeSubmitVertexLikeOriginal(vertices[i]);

                bool useUInt = vertexCount > 65535;
                meshData.SetIndexBufferParams(totalIndexCount, useUInt ? IndexFormat.UInt32 : IndexFormat.UInt16);

                int cursor = 0;
                for (int s = 0; s < subMeshRanges.Count; s++)
                {
                    SubMeshSubmitRangeLikeOriginal range = subMeshRanges[s];
                    int[] rangeIndices = range != null ? range.IndicesLikeOriginal : null;
                    int count = rangeIndices != null ? rangeIndices.Length : 0;

                    if (useUInt)
                    {
                        NativeArray<uint> indices = meshData.GetIndexData<uint>();
                        for (int i = 0; i < count; i++)
                            indices[cursor + i] = (uint)Mathf.Clamp(rangeIndices[i], 0, Mathf.Max(0, vertexCount - 1));
                    }
                    else
                    {
                        NativeArray<ushort> indices = meshData.GetIndexData<ushort>();
                        for (int i = 0; i < count; i++)
                            indices[cursor + i] = (ushort)Mathf.Clamp(rangeIndices[i], 0, Mathf.Max(0, vertexCount - 1));
                    }

                    meshData.SetSubMesh(s, new SubMeshDescriptor(cursor, count, MeshTopology.Triangles)
                    {
                        firstVertex = range != null ? Mathf.Max(0, range.FirstVertexLikeOriginal) : 0,
                        vertexCount = range != null ? Mathf.Max(0, range.VertexCountLikeOriginal) : 0,
                        bounds = new Bounds(Vector3.zero, new Vector3(1000000f, 1000000f, 1000000f))
                    }, MeshUpdateFlags.DontRecalculateBounds | MeshUpdateFlags.DontValidateIndices | MeshUpdateFlags.DontNotifyMeshUsers);

                    cursor += count;
                }

                mesh.Clear();
                Mesh.ApplyAndDisposeWritableMeshData(meshDataArray, mesh, MeshUpdateFlags.DontRecalculateBounds | MeshUpdateFlags.DontValidateIndices | MeshUpdateFlags.DontNotifyMeshUsers);
                mesh.bounds = new Bounds(Vector3.zero, new Vector3(1000000f, 1000000f, 1000000f));
                mesh.UploadMeshData(false);
            }
            catch
            {
                meshDataArray.Dispose();
                throw;
            }
        }

        private sealed class IRSLikeOriginalRenderer : MonoBehaviour
        {
            public C2BattleTerrainMode OwnerLikeOriginal;
            public BaseMeshLikeOriginal STriangLikeOriginal;
            public BaseMeshLikeOriginal GroundMeshLikeOriginal;
            public Camera ExpectedCameraLikeOriginal;
            private VertexTnL2LikeOriginal[] _frameGVERLikeOriginal;
            private int _frameGVERVertexCountLikeOriginal;
            private VertexTnLLikeOriginal[] _frameGVGVertexPtrLikeOriginal;
            private int[] _frameTIDXLikeOriginal;
            private int _frameNGFVERTLikeOriginal;
            private string _lastFrameBuildSignatureLikeOriginal;

            public void RebuildFromITerraGeometryCallbackLikeOriginal(Camera cam)
            {
                if (OwnerLikeOriginal == null || cam == null)
                    return;

                OwnerLikeOriginal.RebuildStrictRuntimeFrameLikeOriginal(
                    STriangLikeOriginal,
                    GroundMeshLikeOriginal,
                    cam,
                    ref _frameGVERLikeOriginal,
                    ref _frameGVERVertexCountLikeOriginal,
                    ref _frameGVGVertexPtrLikeOriginal,
                    ref _frameTIDXLikeOriginal,
                    ref _frameNGFVERTLikeOriginal);
                _lastFrameBuildSignatureLikeOriginal = OwnerLikeOriginal.GetStrictFrameBuildSignatureLikeOriginal(cam);
            }

            
            public void RebuildFromITerraBackendGlobalStateLikeOriginal(Camera cam)
            {
                if (OwnerLikeOriginal == null || cam == null)
                    return;

                RebuildFromITerraGeometryCallbackLikeOriginal(cam);
            }

            
            private bool ExecuteLiteralITerraCallbackModelLikeOriginal(Camera cam)
            {
                ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
                if (terra == null || !terra.EnabledLikeOriginal || !terra.UseLiteralCallbackModelLikeOriginal)
                    return false;

                terra.CurrentRendererLikeOriginal = this;
                terra.CurrentOwnerLikeOriginal = OwnerLikeOriginal;
                terra.CurrentCameraLikeOriginal = cam;
                if (terra.ExtentsLikeOriginal == null || terra.ExtentsLikeOriginal.W <= 0 || terra.ExtentsLikeOriginal.H <= 0)
                    terra.ExtentsLikeOriginal = BuildFullTerrainExtentsLikeOriginal(null);

                ITerraRectLikeOriginal visibleRect = CloneRectLikeOriginal(terra.ExtentsLikeOriginal);
                terra.LastVisibleRectLikeOriginal = CloneRectLikeOriginal(visibleRect);

                int forcedLod = terra.ForcedLodLikeOriginal >= 0 ? terra.ForcedLodLikeOriginal : 0;
                ITerraForceLODLikeOriginal(forcedLod);
                bool rendered = FillGroundZBufferLikeOriginal(visibleRect);

                ParsedMap runtimeMapLikeOriginal = OwnerLikeOriginal != null
                    ? OwnerLikeOriginal.ResolveLiteralITerraRuntimeMapLikeOriginal()
                    : EnsureGlobalParsedMapFacadeLikeOriginal();
                if (runtimeMapLikeOriginal != null)
                    BindParsedMapToGlobalMutableStateLikeOriginal(runtimeMapLikeOriginal);
                EnsureGlobalParsedMapFacadeLikeOriginal();
                return rendered;
            }

            
            private void OnRenderObject()
            {
                Camera cam = Camera.current;
                if (cam == null)
                    return;

                Camera expectedCameraLikeOriginal = ExpectedCameraLikeOriginal;
                if (OwnerLikeOriginal != null)
                {
                    Camera ownerCameraLikeOriginal = OwnerLikeOriginal.GetActiveBattleCameraLikeOriginal();
                    if (ownerCameraLikeOriginal != null)
                        expectedCameraLikeOriginal = ownerCameraLikeOriginal;
                }

                if (expectedCameraLikeOriginal != null && cam != expectedCameraLikeOriginal)
                {
                    if (!cam.name.Contains("Game", StringComparison.OrdinalIgnoreCase))
                        return;
                }

                StrictViewportLikeOriginal runtimeViewportLikeOriginal = default;
                if (OwnerLikeOriginal != null)
                {
                    runtimeViewportLikeOriginal = OwnerLikeOriginal.ComputeStrictViewportLikeOriginal(cam);
                    bool callbackDrivenLikeOriginal = ExecuteLiteralITerraCallbackModelLikeOriginal(cam);
                    if (!callbackDrivenLikeOriginal)
                    {
                        OwnerLikeOriginal.RebuildStrictRuntimeFrameLikeOriginal(
                            STriangLikeOriginal,
                            GroundMeshLikeOriginal,
                            cam,
                            ref _frameGVERLikeOriginal,
                            ref _frameGVERVertexCountLikeOriginal,
                            ref _frameGVGVertexPtrLikeOriginal,
                            ref _frameTIDXLikeOriginal,
                            ref _frameNGFVERTLikeOriginal);
                    }
                    _lastFrameBuildSignatureLikeOriginal = OwnerLikeOriginal.GetStrictFrameBuildSignatureLikeOriginal(cam);
                }

                if (STriangLikeOriginal != null)
                {
                    if (OwnerLikeOriginal != null)
                        OwnerLikeOriginal.ApplySurfaceMaterialStateLikeOriginal(STriangLikeOriginal, runtimeViewportLikeOriginal);
                    DrawLikeOriginal(STriangLikeOriginal, cam);
                }

                if (GroundMeshLikeOriginal == null || GroundMeshLikeOriginal.GArrayLikeOriginal == null)
                    return;

                int groundViewportWLikeOriginal = runtimeViewportLikeOriginal.W > 0 ? runtimeViewportLikeOriginal.W : Mathf.Max(1, cam.pixelWidth);
                int groundViewportHLikeOriginal = runtimeViewportLikeOriginal.H > 0 ? runtimeViewportLikeOriginal.H : Mathf.Max(1, cam.pixelHeight);
                GroundMeshLikeOriginal.ViewportLikeOriginal = new Vector2Int(groundViewportWLikeOriginal, groundViewportHLikeOriginal);

                int maxFactures = GroundMeshLikeOriginal.GArrayLikeOriginal.Length;

                for (int fid = 0; fid < maxFactures; fid++)
                {
                    if (!GroundMeshLikeOriginal.SetVertexPtrFromGArrayLikeOriginal(fid))
                        continue;
                    if (OwnerLikeOriginal != null)
                        OwnerLikeOriginal.ApplyGroundMaterialStateLikeOriginal(GroundMeshLikeOriginal, fid);
                    DrawLikeOriginal(GroundMeshLikeOriginal, cam);
                }
            }
        }

        private static void DrawLikeOriginal(BaseMeshLikeOriginal meshLikeOriginal, Camera cam)
        {
            VertexTnL2LikeOriginal[] drawVertexPtrLikeOriginal = meshLikeOriginal != null
                ? (meshLikeOriginal.UploadScratchVertexPtrLikeOriginal ?? meshLikeOriginal.VertexPtrLikeOriginal)
                : null;
            if (meshLikeOriginal == null || meshLikeOriginal.RuntimeMaterialLikeOriginal == null || meshLikeOriginal.RuntimeMeshLikeOriginal == null || drawVertexPtrLikeOriginal == null || meshLikeOriginal.NVertLikeOriginal <= 0)
                return;

            if (meshLikeOriginal.RefreshRuntimeMeshOnDrawLikeOriginal)
                UploadRuntimeMeshDataLikeOriginal(meshLikeOriginal.RuntimeMeshLikeOriginal, drawVertexPtrLikeOriginal, meshLikeOriginal.NVertLikeOriginal);

            int subMeshIndex = meshLikeOriginal.ActiveSubMeshIndexLikeOriginal >= 0 ? meshLikeOriginal.ActiveSubMeshIndexLikeOriginal : 0;
            if (meshLikeOriginal.SharedRuntimeMeshLikeOriginal != null && meshLikeOriginal.SharedSubmitRangesLikeOriginal != null && meshLikeOriginal.SharedSubmitRangesLikeOriginal.Count > 0)
            {
                int resolved = meshLikeOriginal.ResolveActiveSubMeshFromRangeLikeOriginal();
                if (resolved >= 0)
                    subMeshIndex = resolved;
            }

            if (subMeshIndex < 0 || subMeshIndex >= meshLikeOriginal.RuntimeMeshLikeOriginal.subMeshCount)
                return;

            if (!meshLikeOriginal.RuntimeMaterialLikeOriginal.SetPass(0))
                return;

            Graphics.DrawMeshNow(meshLikeOriginal.RuntimeMeshLikeOriginal, Matrix4x4.identity, subMeshIndex);
        }


private VertexStreamLikeOriginal CreateFactureVertexStreamLikeOriginal(
            string name,
            GArrayBufferLikeOriginal buffer,
            Shader shader,
            Texture mainTex,
            Texture normalTex,
            int renderQueue,
            float bumpContrast,
            float bumpBrightness,
            Func<uint, uint> remapPackedDiffuseLikeOriginal)
        {
            if (buffer == null || buffer.TriangleCount <= 0 || shader == null || mainTex == null)
                return null;

            Material mat = new Material(shader);
            mat.name = name + "_mat";
            if (mat.HasProperty("_MainTex"))
                mat.SetTexture("_MainTex", mainTex);
            if (normalTex != null && mat.HasProperty("_NormalTex"))
                mat.SetTexture("_NormalTex", normalTex);
            if (mat.HasProperty("_BumpContrast"))
                mat.SetFloat("_BumpContrast", bumpContrast);
            if (mat.HasProperty("_BumpBrightness"))
                mat.SetFloat("_BumpBrightness", bumpBrightness);
            if (mat.HasProperty("_C2UseStrictTnL"))
                mat.SetFloat("_C2UseStrictTnL", 1.0f);
            mat.renderQueue = renderQueue;
            _terrainRuntimeOwnedObjects.Add(mat);

            VertexTnL2LikeOriginal[] vertexPtr = buffer.BuildVertexArrayLikeOriginal(remapPackedDiffuseLikeOriginal);
            int vertexCount = vertexPtr != null ? vertexPtr.Length : 0;
            if (vertexCount <= 0)
                return null;

            Mesh runtimeMesh = CreateRuntimeMeshFromVertexPtrLikeOriginal(name + "_runtime", vertexPtr, vertexCount);
            if (runtimeMesh == null)
                return null;

            return new VertexStreamLikeOriginal
            {
                Material = mat,
                RuntimeMeshLikeOriginal = runtimeMesh,
                VertexPtrLikeOriginal = vertexPtr,
                VertexCountLikeOriginal = vertexCount,
                SubmitFirstVertexLikeOriginal = 0,
                SubmitVertexCountLikeOriginal = vertexCount
            };
        }

