        private static bool RebuildGroundGArrayStreamsFromGVGLikeOriginal(BaseMeshLikeOriginal groundMeshLikeOriginal)
        {
            if (groundMeshLikeOriginal == null ||
                groundMeshLikeOriginal.GArrayLikeOriginal == null ||
                groundMeshLikeOriginal.NInGarrLikeOriginal == null ||
                groundMeshLikeOriginal.MaxInGarrLikeOriginal == null ||
                groundMeshLikeOriginal.GVGVertexPtrLikeOriginal == null ||
                groundMeshLikeOriginal.TIDXLikeOriginal == null)
                return false;

            int bucketCountLikeOriginal = Math.Min(groundMeshLikeOriginal.GArrayLikeOriginal.Length, Math.Min(groundMeshLikeOriginal.NInGarrLikeOriginal.Length, groundMeshLikeOriginal.MaxInGarrLikeOriginal.Length));
            if (bucketCountLikeOriginal <= 0)
                return false;

            if (groundMeshLikeOriginal.GArrayVertexPtrLikeOriginal == null || groundMeshLikeOriginal.GArrayVertexPtrLikeOriginal.Length != groundMeshLikeOriginal.GArrayLikeOriginal.Length)
                groundMeshLikeOriginal.GArrayVertexPtrLikeOriginal = new VertexTnLLikeOriginal[groundMeshLikeOriginal.GArrayLikeOriginal.Length][];

            Array.Clear(groundMeshLikeOriginal.NInGarrLikeOriginal, 0, bucketCountLikeOriginal);

            for (int groundId = 0; groundId < bucketCountLikeOriginal; groundId++)
            {
                VertexStreamLikeOriginal stream = groundMeshLikeOriginal.GArrayLikeOriginal[groundId];
                if (stream != null)
                {
                    stream.FactureIdLikeOriginal = groundId;
                    stream.Dot3LikeOriginal = false;
                    stream.VertexCountLikeOriginal = 0;
                    stream.SubmitFirstVertexLikeOriginal = 0;
                    stream.SubmitVertexCountLikeOriginal = 0;
                    stream.SubmitSubMeshIndexLikeOriginal = 0;
                }

                if (groundMeshLikeOriginal.GArrayVertexPtrLikeOriginal[groundId] != null && groundMeshLikeOriginal.MaxInGarrLikeOriginal[groundId] > 0 && groundMeshLikeOriginal.GArrayVertexPtrLikeOriginal[groundId].Length > groundMeshLikeOriginal.MaxInGarrLikeOriginal[groundId])
                    Array.Resize(ref groundMeshLikeOriginal.GArrayVertexPtrLikeOriginal[groundId], groundMeshLikeOriginal.MaxInGarrLikeOriginal[groundId]);
            }

            int sourceVertexCountLikeOriginal = Mathf.Min(groundMeshLikeOriginal.NGFVERTLikeOriginal, groundMeshLikeOriginal.GVGVertexPtrLikeOriginal.Length);
            bool hasAnyLikeOriginal = false;

            for (int i = 0; i + 2 < sourceVertexCountLikeOriginal; i += 3)
            {
                int fid = i < groundMeshLikeOriginal.TIDXLikeOriginal.Length ? groundMeshLikeOriginal.TIDXLikeOriginal[i] : -1;
                if (fid < 0 || fid >= bucketCountLikeOriginal)
                    continue;

                int requiredVerticesLikeOriginal = groundMeshLikeOriginal.NInGarrLikeOriginal[fid] + 3;
                if (requiredVerticesLikeOriginal > groundMeshLikeOriginal.MaxInGarrLikeOriginal[fid])
                {
                    int newCapLikeOriginal = groundMeshLikeOriginal.MaxInGarrLikeOriginal[fid];
                    if (newCapLikeOriginal <= 0)
                        newCapLikeOriginal = 512 * 3;
                    while (newCapLikeOriginal < requiredVerticesLikeOriginal)
                        newCapLikeOriginal += 512 * 3;
                    groundMeshLikeOriginal.MaxInGarrLikeOriginal[fid] = newCapLikeOriginal;
                    EnsureGroundVertexArrayCapacityLikeOriginal(ref groundMeshLikeOriginal.GArrayVertexPtrLikeOriginal[fid], newCapLikeOriginal);
                }

                int dst = groundMeshLikeOriginal.NInGarrLikeOriginal[fid];
                groundMeshLikeOriginal.GArrayVertexPtrLikeOriginal[fid][dst + 0] = groundMeshLikeOriginal.GVGVertexPtrLikeOriginal[i + 0];
                groundMeshLikeOriginal.GArrayVertexPtrLikeOriginal[fid][dst + 1] = groundMeshLikeOriginal.GVGVertexPtrLikeOriginal[i + 1];
                groundMeshLikeOriginal.GArrayVertexPtrLikeOriginal[fid][dst + 2] = groundMeshLikeOriginal.GVGVertexPtrLikeOriginal[i + 2];
                groundMeshLikeOriginal.NInGarrLikeOriginal[fid] += 3;

                VertexStreamLikeOriginal stream = groundMeshLikeOriginal.GArrayLikeOriginal[fid];
                if (stream == null)
                {
                    stream = new VertexStreamLikeOriginal
                    {
                        Material = groundMeshLikeOriginal.RuntimeMaterialLikeOriginal,
                        RuntimeMeshLikeOriginal = groundMeshLikeOriginal.RuntimeMeshLikeOriginal,
                        FactureIdLikeOriginal = fid,
                        Dot3LikeOriginal = false
                    };
                    groundMeshLikeOriginal.GArrayLikeOriginal[fid] = stream;
                }
                stream.VertexCountLikeOriginal = groundMeshLikeOriginal.NInGarrLikeOriginal[fid];
                stream.SubmitFirstVertexLikeOriginal = 0;
                stream.SubmitVertexCountLikeOriginal = groundMeshLikeOriginal.NInGarrLikeOriginal[fid];
                stream.SubmitSubMeshIndexLikeOriginal = 0;
                hasAnyLikeOriginal = true;
            }

            for (int groundId = 0; groundId < bucketCountLikeOriginal; groundId++)
            {
                VertexStreamLikeOriginal stream = groundMeshLikeOriginal.GArrayLikeOriginal[groundId];
                if (stream == null)
                    continue;

                int submitCountLikeOriginal = Mathf.Max(0, groundMeshLikeOriginal.NInGarrLikeOriginal[groundId]);
                stream.VertexCountLikeOriginal = submitCountLikeOriginal;
                stream.SubmitFirstVertexLikeOriginal = 0;
                stream.SubmitVertexCountLikeOriginal = submitCountLikeOriginal;
                stream.SubmitSubMeshIndexLikeOriginal = 0;
                stream.FactureIdLikeOriginal = groundId;
            }

            return hasAnyLikeOriginal;
        }

        private static int CountGroundBucketsFromGVGLikeOriginal(int[] tidxLikeOriginal, int ngfvertLikeOriginal, int maxBucketCountLikeOriginal)
        {
            if (tidxLikeOriginal == null || ngfvertLikeOriginal <= 0 || maxBucketCountLikeOriginal <= 0)
                return 0;

            int sourceTriCountLikeOriginal = Mathf.Min(ngfvertLikeOriginal / 3, tidxLikeOriginal.Length / 3);
            var seenLikeOriginal = new bool[maxBucketCountLikeOriginal];
            int countLikeOriginal = 0;
            for (int triIndexLikeOriginal = 0; triIndexLikeOriginal < sourceTriCountLikeOriginal; triIndexLikeOriginal++)
            {
                int fid = tidxLikeOriginal[triIndexLikeOriginal * 3];
                if (fid < 0 || fid >= maxBucketCountLikeOriginal || seenLikeOriginal[fid])
                    continue;
                seenLikeOriginal[fid] = true;
                countLikeOriginal++;
            }

            return countLikeOriginal;
        }

        private void ApplyGroundMaterialStateLikeOriginal(BaseMeshLikeOriginal groundMeshLikeOriginal, int fid)
        {
            if (groundMeshLikeOriginal == null || groundMeshLikeOriginal.RuntimeMaterialLikeOriginal == null || groundMeshLikeOriginal.VertexPtrLikeOriginal == null || groundMeshLikeOriginal.NVertLikeOriginal <= 0)
                return;

            Material mat = groundMeshLikeOriginal.RuntimeMaterialLikeOriginal;
            Shader lightShaderLikeOriginal = groundMeshLikeOriginal.LightShaderLikeOriginal ?? FindGroundLightShaderLikeOriginal();
            Shader dotShaderLikeOriginal = groundMeshLikeOriginal.DotShaderLikeOriginal ?? lightShaderLikeOriginal;

            float contrastLikeOriginal;
            float brightLikeOriginal;
            Texture2D factTexLikeOriginal;
            Texture2D normalTexLikeOriginal = GetFactureBumpRuntime(groundMeshLikeOriginal.GroundCatalogLikeOriginal, groundMeshLikeOriginal.GroundRuntimeConfigLikeOriginal, fid, out contrastLikeOriginal, out brightLikeOriginal, out factTexLikeOriginal);
            if (factTexLikeOriginal == null)
                factTexLikeOriginal = groundMeshLikeOriginal.DefaultFactureTextureLikeOriginal as Texture2D ?? Texture2D.whiteTexture;

            bool useDot3LikeOriginal = normalTexLikeOriginal != null && dotShaderLikeOriginal != null;
            Shader targetShaderLikeOriginal = useDot3LikeOriginal ? dotShaderLikeOriginal : lightShaderLikeOriginal;
            SetShaderLikeOriginal(groundMeshLikeOriginal, targetShaderLikeOriginal);
            SetTextureLikeOriginal(groundMeshLikeOriginal, 0, useDot3LikeOriginal ? (Texture)(normalTexLikeOriginal ?? Texture2D.normalTexture) : factTexLikeOriginal);
            SetTextureLikeOriginal(groundMeshLikeOriginal, 1, useDot3LikeOriginal ? (Texture)factTexLikeOriginal : null);
            ApplyGroundTextureStagesToMaterialLikeOriginal(mat, useDot3LikeOriginal, GetTextureLikeOriginal(groundMeshLikeOriginal, 0), GetTextureLikeOriginal(groundMeshLikeOriginal, 1));
            mat.renderQueue = 2000;

            if (mat.HasProperty("_BumpContrast"))
                mat.SetFloat("_BumpContrast", contrastLikeOriginal);
            if (mat.HasProperty("_BumpBrightness"))
                mat.SetFloat("_BumpBrightness", brightLikeOriginal);
            if (mat.HasProperty("_C2UseStrictTnL"))
                mat.SetFloat("_C2UseStrictTnL", 1.0f);
            ApplyStrictViewportToMaterialLikeOriginal(mat, ComputeStrictViewportLikeOriginal(GetActiveBattleCameraLikeOriginal()));
            if (mat.HasProperty("_Color"))
                mat.SetColor("_Color", Color.white);
            if (mat.HasProperty("_BaseColor"))
                mat.SetColor("_BaseColor", Color.white);

            groundMeshLikeOriginal.BoundFactureIdLikeOriginal = fid;
            groundMeshLikeOriginal.BoundDot3LikeOriginal = useDot3LikeOriginal;

            if (!useDot3LikeOriginal)
            {
                groundMeshLikeOriginal.UploadScratchVertexPtrLikeOriginal = null;
                return;
            }

            int nVertLikeOriginal = Mathf.Max(0, groundMeshLikeOriginal.NVertLikeOriginal);
            if (groundMeshLikeOriginal.UploadScratchVertexPtrLikeOriginal == null || groundMeshLikeOriginal.UploadScratchVertexPtrLikeOriginal.Length < nVertLikeOriginal)
                groundMeshLikeOriginal.UploadScratchVertexPtrLikeOriginal = new VertexTnL2LikeOriginal[nVertLikeOriginal];

            for (int j = 0; j < nVertLikeOriginal; j++)
            {
                VertexTnL2LikeOriginal srcVertexLikeOriginal = groundMeshLikeOriginal.VertexPtrLikeOriginal[j];
                srcVertexLikeOriginal = WithStrictDiffuseLikeOriginal(srcVertexLikeOriginal, RemapFacturePackedDiffuseToDot3LikeOriginal(srcVertexLikeOriginal.Diffuse, contrastLikeOriginal, brightLikeOriginal));
                groundMeshLikeOriginal.UploadScratchVertexPtrLikeOriginal[j] = srcVertexLikeOriginal;
            }
        }


