        private Material CreateStrictRuntimeMeshSurfaceBatchMaterialLikeOriginal(int factureLikeOriginal, GroundTextureCatalog catalog, GroundRuntimeConfig runtimeCfg, out bool useDot3LikeOriginal, out Texture2D stage0LikeOriginal, out Texture2D stage1LikeOriginal)
        {
            float contrastLikeOriginal;
            float brightLikeOriginal;
            Texture2D factTexLikeOriginal;
            Texture2D bumpTexLikeOriginal = GetFactureBumpRuntime(catalog, runtimeCfg, factureLikeOriginal, out contrastLikeOriginal, out brightLikeOriginal, out factTexLikeOriginal);

            if (factTexLikeOriginal == null)
                factTexLikeOriginal = Texture2D.whiteTexture;

            // Original OneMapVertex::GetShader() uses terra_shadowed for plain and dot3specular for bump.
            // In Unity we bind the nearest available strict facture shaders while preserving the same stage semantics:
            //   stage0 = bump/normal or facture
            //   stage1 = facture
            Shader lightShaderLikeOriginal = FindGroundLightShaderLikeOriginal() ?? FindBestStrictRuntimeFlatMeshShaderLikeOriginal();
            Shader dotShaderLikeOriginal = FindGroundDotShaderLikeOriginal()
                ?? Shader.Find("Cossacks2Bridge/TerrainRuntimeFacture4SurfacePass")
                ?? lightShaderLikeOriginal;

            useDot3LikeOriginal = bumpTexLikeOriginal != null && dotShaderLikeOriginal != null;
            Shader shaderLikeOriginal = useDot3LikeOriginal ? dotShaderLikeOriginal : lightShaderLikeOriginal;
            stage0LikeOriginal = useDot3LikeOriginal ? (bumpTexLikeOriginal ?? Texture2D.normalTexture) : factTexLikeOriginal;
            stage1LikeOriginal = factTexLikeOriginal;

            var materialLikeOriginal = new Material(shaderLikeOriginal ?? FindBestStrictRuntimeFlatMeshShaderLikeOriginal());
            materialLikeOriginal.name = $"C2_HSEMBatch_F{factureLikeOriginal:D3}_{(useDot3LikeOriginal ? "dot3specular" : "terra_shadowed")}";
            ApplyGroundTextureStagesToMaterialLikeOriginal(materialLikeOriginal, useDot3LikeOriginal, stage0LikeOriginal, stage1LikeOriginal);

            if (materialLikeOriginal.HasProperty("_BumpContrast"))
                materialLikeOriginal.SetFloat("_BumpContrast", contrastLikeOriginal);
            if (materialLikeOriginal.HasProperty("_BumpBrightness"))
                materialLikeOriginal.SetFloat("_BumpBrightness", brightLikeOriginal);
            if (materialLikeOriginal.HasProperty("_Color"))
                materialLikeOriginal.SetColor("_Color", Color.white);
            if (materialLikeOriginal.HasProperty("_BaseColor"))
                materialLikeOriginal.SetColor("_BaseColor", Color.white);
            if (materialLikeOriginal.HasProperty("_SpecColor"))
                materialLikeOriginal.SetColor("_SpecColor", useDot3LikeOriginal ? Color.white : new Color(0.5f, 0.5f, 0.5f, 1.0f));
            if (materialLikeOriginal.HasProperty("_Glossiness"))
                materialLikeOriginal.SetFloat("_Glossiness", useDot3LikeOriginal ? 0.5f : 0.0f);
            if (materialLikeOriginal.HasProperty("_Shininess"))
                materialLikeOriginal.SetFloat("_Shininess", useDot3LikeOriginal ? 0.5f : 0.0f);
            if (materialLikeOriginal.HasProperty("_C2UseStrictTnL"))
                materialLikeOriginal.SetFloat("_C2UseStrictTnL", 0.0f);
            if (materialLikeOriginal.HasProperty("_C2UseMeshSpecularPayload"))
                materialLikeOriginal.SetFloat("_C2UseMeshSpecularPayload", useDot3LikeOriginal ? 1.0f : 0.0f);
            materialLikeOriginal.renderQueue = 2000;
            _terrainRuntimeOwnedObjects.Add(materialLikeOriginal);
            return materialLikeOriginal;
        }

        private bool TryCreateStrictRuntimeMeshSurfaceLikeOriginal(string selectedId, Transform parent, out Material firstMaterial, out string info)
        {
            firstMaterial = null;
            info = "";

            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            if (runtimeMapLikeOriginal == null || !runtimeMapLikeOriginal.IsMeshSurface)
            {
                info = "strictRuntime meshSurface map missing";
                return false;
            }

            EnsureMeshSurfaceSupportLikeOriginal(runtimeMapLikeOriginal);
            GroundTextureCatalog catalog = GetOrCreateGroundCatalog(out _);
            GroundRuntimeConfig runtimeCfg = GetOrCreateGroundRuntimeConfig(out _);
            EnsureGroundTextureTable(runtimeCfg, catalog);

            MeshQuadRenderBatchLikeOriginal[] renderBatchesLikeOriginal = BuildMeshSurfaceQuadFactureSplitRenderBatchesLikeOriginal(
                runtimeMapLikeOriginal,
                catalog,
                runtimeCfg,
                out int batchCountLikeOriginal,
                out int batchTriangleCountLikeOriginal);

            if (renderBatchesLikeOriginal != null && batchCountLikeOriginal > 0)
            {
                var rootGo = new GameObject("HSEMSurfaceLikeOriginal");
                rootGo.transform.SetParent(parent, false);

                var materialByFactureLikeOriginal = new Dictionary<int, Material>();
                int bumpFactureCountLikeOriginal = 0;
                int plainFactureCountLikeOriginal = 0;
                MeshQuadSystemLikeOriginal quadSystem = runtimeMapLikeOriginal.MeshQuadSystem;

                foreach (MeshQuadRenderBatchLikeOriginal batchLikeOriginal in renderBatchesLikeOriginal)
                {
                    if (batchLikeOriginal == null || batchLikeOriginal.Mesh == null)
                        continue;

                    if (!materialByFactureLikeOriginal.TryGetValue(batchLikeOriginal.Facture, out Material batchMaterialLikeOriginal) || batchMaterialLikeOriginal == null)
                    {
                        batchMaterialLikeOriginal = CreateStrictRuntimeMeshSurfaceBatchMaterialLikeOriginal(
                            batchLikeOriginal.Facture,
                            catalog,
                            runtimeCfg,
                            out bool useDot3LikeOriginal,
                            out _,
                            out _);

                        materialByFactureLikeOriginal[batchLikeOriginal.Facture] = batchMaterialLikeOriginal;
                        if (useDot3LikeOriginal)
                            bumpFactureCountLikeOriginal++;
                        else
                            plainFactureCountLikeOriginal++;
                    }

                    int qx = quadSystem != null && quadSystem.QuadsNx > 0 ? batchLikeOriginal.QuadIndex % quadSystem.QuadsNx : batchLikeOriginal.QuadIndex;
                    int qy = quadSystem != null && quadSystem.QuadsNx > 0 ? batchLikeOriginal.QuadIndex / quadSystem.QuadsNx : 0;
                    CreateStrictRuntimeChild(rootGo.transform, $"HSEMBatch_Q{qx:D3}_{qy:D3}_F{batchLikeOriginal.Facture:D3}", batchLikeOriginal.Mesh, batchMaterialLikeOriginal);

                    if (firstMaterial == null)
                        firstMaterial = batchMaterialLikeOriginal;
                }

                int quadCount = runtimeMapLikeOriginal.MeshQuadSystem != null ? runtimeMapLikeOriginal.MeshQuadSystem.QuadsNx * runtimeMapLikeOriginal.MeshQuadSystem.QuadsNy : 0;
                int heightCount = runtimeMapLikeOriginal.Heights != null ? runtimeMapLikeOriginal.Heights.Length : 0;
                info = $"terrainTextureInfo=renderPath=strict-runtime-hsem-speedysplit-like; surfaceBackend=mesh-quad-facture-batches-like-itcreategeometry; constructionOrder=loadnewsurface-then-quadsystem-init-then-fillmapofheights-supplementrect-like-original-then-vbmref-merge-speedysplit-like-batches; geometrySource=hsem-native-vertices-indices-colors-normals-split-by-quads-and-facture-like-original; heightsSource=mesh-fillmapofheights-and-supplementrect-like-original; quads={(runtimeMapLikeOriginal.MeshQuadSystem != null ? runtimeMapLikeOriginal.MeshQuadSystem.QuadsNx + "x" + runtimeMapLikeOriginal.MeshQuadSystem.QuadsNy : "none")}; quadCount={quadCount}; renderedBatches={batchCountLikeOriginal}; renderedTris={batchTriangleCountLikeOriginal}; meshVerts={(runtimeMapLikeOriginal.MeshVertices != null ? runtimeMapLikeOriginal.MeshVertices.Length : 0)}; meshIdx={(runtimeMapLikeOriginal.MeshIndices != null ? runtimeMapLikeOriginal.MeshIndices.Length : 0)}; heights={heightCount}; surfaceInit=vertex-colors-shadow-diffuse-and-original-normals-like; materialState=per-facture-getfactureid-getfactureid2-getshader-like-original; mappingState=per-facture-getmapper-getmappingcode-uvpair-like-original; vertexPayload=diffuse-specular-tangent-uv-like-basemesh; plainFactures={plainFactureCountLikeOriginal}; bumpFactures={bumpFactureCountLikeOriginal}; viewport=quad-merge-speedysplit-like; water=deleted; roads=deleted; bounds=direct-mesh-map-like-original";
                return true;
            }

            Shader shader = FindBestStrictRuntimeFlatMeshShaderLikeOriginal();
            var material = new Material(shader);
            material.name = "C2_HSEMSurfaceLikeOriginal";
            if (material.HasProperty("_MainTex"))
                material.SetTexture("_MainTex", Texture2D.whiteTexture);
            material.color = Color.white;
            _terrainRuntimeOwnedObjects.Add(material);

            Mesh[] quadMeshesLikeOriginal = BuildMeshSurfaceQuadChunkMeshesLikeOriginal(runtimeMapLikeOriginal, out int quadRenderCountLikeOriginal, out int quadRenderTriangleCountLikeOriginal);
            if (quadMeshesLikeOriginal != null && quadRenderCountLikeOriginal > 0)
            {
                var rootGo = new GameObject("HSEMSurfaceLikeOriginal");
                rootGo.transform.SetParent(parent, false);

                MeshQuadSystemLikeOriginal quadSystem = runtimeMapLikeOriginal.MeshQuadSystem;
                for (int quadIndex = 0; quadIndex < quadMeshesLikeOriginal.Length; quadIndex++)
                {
                    Mesh chunkMeshLikeOriginal = quadMeshesLikeOriginal[quadIndex];
                    if (chunkMeshLikeOriginal == null)
                        continue;

                    int qx = quadSystem != null && quadSystem.QuadsNx > 0 ? quadIndex % quadSystem.QuadsNx : quadIndex;
                    int qy = quadSystem != null && quadSystem.QuadsNx > 0 ? quadIndex / quadSystem.QuadsNx : 0;
                    CreateStrictRuntimeChild(rootGo.transform, $"HSEMQuad_{qx:D3}_{qy:D3}", chunkMeshLikeOriginal, material);
                }

                firstMaterial = material;
                int quadCount = runtimeMapLikeOriginal.MeshQuadSystem != null ? runtimeMapLikeOriginal.MeshQuadSystem.QuadsNx * runtimeMapLikeOriginal.MeshQuadSystem.QuadsNy : 0;
                int heightCount = runtimeMapLikeOriginal.Heights != null ? runtimeMapLikeOriginal.Heights.Length : 0;
                info = $"terrainTextureInfo=renderPath=strict-runtime-hsem-quads; surfaceBackend=mesh-quad-chunks-like-universalmap; constructionOrder=loadnewsurface-then-quadsystem-init-then-fillmapofheights-supplementrect-like-original-then-quad-render-chunks; geometrySource=hsem-native-vertices-indices-colors-normals-split-by-quads-like-original; heightsSource=mesh-fillmapofheights-and-supplementrect-like-original; quads={(runtimeMapLikeOriginal.MeshQuadSystem != null ? runtimeMapLikeOriginal.MeshQuadSystem.QuadsNx + "x" + runtimeMapLikeOriginal.MeshQuadSystem.QuadsNy : "none")}; quadCount={quadCount}; renderedQuads={quadRenderCountLikeOriginal}; renderedTris={quadRenderTriangleCountLikeOriginal}; meshVerts={(runtimeMapLikeOriginal.MeshVertices != null ? runtimeMapLikeOriginal.MeshVertices.Length : 0)}; meshIdx={(runtimeMapLikeOriginal.MeshIndices != null ? runtimeMapLikeOriginal.MeshIndices.Length : 0)}; heights={heightCount}; surfaceInit=vertex-colors-and-original-normals-like; viewport=quad-mesh-native-like-universalmap; water=deleted; roads=deleted; bounds=direct-mesh-map-like-original";
