            info = $"terrainTextureInfo=renderPath=strict-runtime-hsem-fallback-native; surfaceBackend=mesh-native-direct-fallback; constructionOrder=loadnewsurface-then-quadsystem-init-then-fillmapofheights-supplementrect-like-original-then-single-fallback-mesh; geometrySource=hsem-native-vertices-indices-colors-normals-like-original; heightsSource=mesh-fillmapofheights-and-supplementrect-like-original; quads={(runtimeMapLikeOriginal.MeshQuadSystem != null ? runtimeMapLikeOriginal.MeshQuadSystem.QuadsNx + "x" + runtimeMapLikeOriginal.MeshQuadSystem.QuadsNy : "none")}; meshVerts={(runtimeMapLikeOriginal.MeshVertices != null ? runtimeMapLikeOriginal.MeshVertices.Length : 0)}; meshIdx={(runtimeMapLikeOriginal.MeshIndices != null ? runtimeMapLikeOriginal.MeshIndices.Length : 0)}; heights={fallbackHeightCountLikeOriginal}; surfaceInit=vertex-colors-and-original-normals-like; viewport=native-mesh-surface-fallback; water=deleted; roads=deleted; bounds=direct-mesh-map-like-original";
            return true;
        }

        private bool TryCreateStrictRuntimeTerrain(string selectedId, Transform parent, out Material firstMaterial, out string info)
