                activeCamera = _camera != null ? _camera : Camera.main;

            bool includeSecondary = true;
            bool includeFacture = true;
            bool emitSurfaceGroundBucketsLikeOriginal = false;
            string renderPath = "strict-runtime-literal-irs";
            string groundArrayInfo = "groundArray=deleted";
            string factureArrayInfo = "facture=gvg-tidx-groundmesh-like-original";
            Dictionary<int, int> groundLayerById = BuildStrictSurfaceGroundLayerMapIfNeededLikeOriginal(emitSurfaceGroundBucketsLikeOriginal, catalog, runtimeCfg, out string groundLayerInfo);

            VertexTnL2LikeOriginal[] gVERLikeOriginal = Array.Empty<VertexTnL2LikeOriginal>();
