            int nGFVertLikeOriginal = 0;
            VertexStreamLikeOriginal[] gArrayLikeOriginal = new VertexStreamLikeOriginal[256];
            int[] nInGarrLikeOriginal = new int[256];
            int[] maxInGarrLikeOriginal = new int[256];

            GArrayBufferLikeOriginal[] factPlainById = new GArrayBufferLikeOriginal[256];
            GArrayBufferLikeOriginal[] factBumpById = new GArrayBufferLikeOriginal[256];
            int baseTriCount = 0;
            int secTriCount = 0;
            int factTriCount = 0;
            int factPlainTriCount = 0;
            int factBumpTriCount = 0;

            BuildStrictRuntimeFrameSourcesLikeOriginal(
                activeCamera,
                catalog,
                runtimeCfg,
                groundLayerById,
                randoma,
                includeSecondary,
                includeFacture,
                ref gVERLikeOriginal,
                ref gVERVertexCountLikeOriginal,
                ref gVGVertexPtrLikeOriginal,
                ref tIdxLikeOriginal,
                ref nGFVertLikeOriginal,
                ref gArrayLikeOriginal,
                ref nInGarrLikeOriginal,
                ref maxInGarrLikeOriginal,
                ref factPlainById,
                ref factBumpById,
                ref baseTriCount,
                ref secTriCount,
                ref factTriCount,
                ref factPlainTriCount,
                ref factBumpTriCount);

            if (gVERVertexCountLikeOriginal <= 0 && nGFVertLikeOriginal <= 0)
            {
