            Texture2D surfaceCrossTexLikeOriginal = ResolveSurfaceCrossTextureLikeOriginal();
            Texture2D defaultFactureTexLikeOriginal = surfaceGroundTexLikeOriginal ?? Texture2D.whiteTexture;
            if (surfaceShader == null || groundLightShaderLikeOriginal == null || defaultFactureTexLikeOriginal == null || surfaceCrossTexLikeOriginal == null)
            {
                info = $"strictRuntime stripped shader/resources missing surface={(surfaceShader != null ? 1 : 0)} groundLight={(groundLightShaderLikeOriginal != null ? 1 : 0)} surfaceTex={(surfaceGroundTexLikeOriginal != null ? 1 : 0)} crossTex={(surfaceCrossTexLikeOriginal != null ? 1 : 0)}";
