                        STriangLikeOriginal.GVERLikeOriginal = gVERLikeOriginal;
                        STriangLikeOriginal.GVERVertexCountLikeOriginal = gVERVertexCountLikeOriginal;
                        STriangLikeOriginal.SetVertexPtrLikeOriginal(gVERLikeOriginal);
                        STriangLikeOriginal.SetNVertLikeOriginal(gVERVertexCountLikeOriginal);
                        STriangLikeOriginal.SetNIndLikeOriginal(gVERVertexCountLikeOriginal);
                        STriangLikeOriginal.SetNPriLikeOriginal(gVERVertexCountLikeOriginal / 3);
                        ApplySurfaceMaterialStateLikeOriginal(STriangLikeOriginal, runtimeViewportLikeOriginal);
                    }

                    Material stMaterialLikeOriginal = STriangLikeOriginal.RuntimeMaterialLikeOriginal ?? STriangLikeOriginal.ImmediateStreamLikeOriginal?.Material;
                    if (stMaterialLikeOriginal != null)
                    {
                        if (stMaterialLikeOriginal.HasProperty("_Color"))
