                    }
                }
            }

            BaseMeshLikeOriginal GroundMeshLikeOriginal = null;
            if (nGFVertLikeOriginal > 0)
            {
                GroundMeshLikeOriginal = CreateDynamicGroundMeshLikeOriginal(
                    selectedId + "_strict_ground_dynamic",
                    gArrayLikeOriginal,
                    nInGarrLikeOriginal,
                    maxInGarrLikeOriginal,
                    gVGVertexPtrLikeOriginal,
                    nGFVertLikeOriginal,
                    tIdxLikeOriginal,
                    catalog,
                    runtimeCfg,
                    groundLightShaderLikeOriginal,
                    groundDotShaderLikeOriginal,
                    defaultFactureTexLikeOriginal,
                    2000,
                    runtimeViewportLikeOriginal);

                if (GroundMeshLikeOriginal != null)
                {
