                        firstMaterial = GroundMeshLikeOriginal.RuntimeMaterialLikeOriginal;

                    GroundMeshLikeOriginal.GArrayLikeOriginal = gArrayLikeOriginal;
                    GroundMeshLikeOriginal.NInGarrLikeOriginal = nInGarrLikeOriginal;
                    GroundMeshLikeOriginal.MaxInGarrLikeOriginal = maxInGarrLikeOriginal;
                    GroundMeshLikeOriginal.GVGVertexPtrLikeOriginal = gVGVertexPtrLikeOriginal;
                    GroundMeshLikeOriginal.TIDXLikeOriginal = tIdxLikeOriginal;
                    GroundMeshLikeOriginal.NGFVERTLikeOriginal = nGFVertLikeOriginal;
                    GroundMeshLikeOriginal.GVERLikeOriginal = gVERLikeOriginal;
                    GroundMeshLikeOriginal.GVERVertexCountLikeOriginal = gVERVertexCountLikeOriginal;
                    GroundMeshLikeOriginal.ViewportLikeOriginal = new Vector2Int(Mathf.Max(1, runtimeViewportLikeOriginal.W), Mathf.Max(1, runtimeViewportLikeOriginal.H));
                    RebuildGroundGArrayStreamsFromGVGLikeOriginal(GroundMeshLikeOriginal);
                }
            }

            int groundBatchCount = CountActiveFactureBucketsLikeOriginal(
                tIdxLikeOriginal,
                nGFVertLikeOriginal,
                gArrayLikeOriginal != null ? gArrayLikeOriginal.Length : 0);
            groundArrayInfo = GroundMeshLikeOriginal != null
                ? $"groundArray=regrouped-post-sttriang-from-facture-gvg-tidx-like-original; garrayStorage=raw-facture-vertex-buckets-like-original; finalize=runtime-frame-rebuild-from-gvg-tidx-like-original; buckets={groundBatchCount}"
                : "groundArray=deleted";

            if (STriangLikeOriginal == null && GroundMeshLikeOriginal == null)
            {
                info = $"strictRuntime no-runtime-meshes-created surfaceVerts={gVERVertexCountLikeOriginal} factureVerts={nGFVertLikeOriginal}; {catalogInfo}; {runtimeInfo}";
                return false;
            }

            GameObject factureHost = new GameObject("IRSLikeOriginal");
            factureHost.transform.SetParent(parent, false);
            var immediateRenderer = factureHost.AddComponent<IRSLikeOriginalRenderer>();
            immediateRenderer.OwnerLikeOriginal = this;
            immediateRenderer.STriangLikeOriginal = STriangLikeOriginal;
            immediateRenderer.GroundMeshLikeOriginal = GroundMeshLikeOriginal;
            immediateRenderer.ExpectedCameraLikeOriginal = activeCamera;

            info = $"terrainTextureInfo=renderPath={renderPath}; surfaceBackend=irs-draw-basemesh-setvertexptr-like; surfaceInit=Surface-GroundTex-BoundNew128-like-original; factureBackend=gvg-tidx-groundmesh-like-original; factureInit=Facture4-like-then-Facture3-dot3-like-original; factureState=setShader-setTexture0-setTexture1-like-original; drawOrder=STriang-GroundMesh; constructionOrder=live-view-frame-build-thmap-cell-geometry-halves-then-triangle-screen-geometry-then-surface-stage1-stage2-then-facture-gvg-tidx-then-post-regroup-garray-like-original; geometrySource=emitstrictgeometrycell-halves-plus-triangle-screen-geometry-like-original-catalog-independent; oldSurfaceHelperMesh=deleted-in-strict-exact; textures=facture-loop-per-fid-light-dot3-like; viewport=software-vp-coarse-cell-reject-like-original; water=deleted; roads=deleted; bounds=direct-map-like-original; overlay=deleted; stonePath=deleted; groundSharedRuntime=0; groundSubmitMode={(GroundMeshLikeOriginal != null ? "vertexptr-direct-dynamic-upload" : "deleted")}; surfaceTris={(gVERVertexCountLikeOriginal / 3)} stage1Tris={baseTriCount} stage2Tris={secTriCount} groundBatches={groundBatchCount} stoneQuads=0 factureTris={factTriCount} facturePlainTris={factPlainTriCount} factureDot3Tris={factBumpTriCount} facturePlainBatches=0 factureDot3Batches=0; {factureArrayInfo}; {groundArrayInfo}; {groundLayerInfo}; {catalogInfo}; {runtimeInfo}";
            return true;
        }


        private static int CountActiveFactureBucketsLikeOriginal(int[] tidxLikeOriginal, int ngfvertLikeOriginal, int bucketCountLikeOriginal)
        {
            if (tidxLikeOriginal == null || ngfvertLikeOriginal <= 0 || bucketCountLikeOriginal <= 0)
                return 0;

            bool[] seenLikeOriginal = new bool[bucketCountLikeOriginal];
            int countLikeOriginal = 0;
            int limitLikeOriginal = Math.Min(ngfvertLikeOriginal, tidxLikeOriginal.Length);
            for (int i = 0; i < limitLikeOriginal; i += 3)
            {
                int fidLikeOriginal = tidxLikeOriginal[i];
                if (fidLikeOriginal < 0 || fidLikeOriginal >= bucketCountLikeOriginal || seenLikeOriginal[fidLikeOriginal])
                    continue;

                seenLikeOriginal[fidLikeOriginal] = true;
                countLikeOriginal++;
            }

            return countLikeOriginal;
        }

        private static byte GetArrayByteSafe(byte[] data, int index, byte fallback)
        {
            if (data == null || index < 0 || index >= data.Length)
                return fallback;
            return data[index];
        }

        private static byte GetArrayByteSafe(byte[] data, int index, int fallback)
        {
            byte safe = (byte)Mathf.Clamp(fallback, 0, 255);
            if (data == null || index < 0 || index >= data.Length)
                return safe;
            return data[index];
        }

        private static Color32 MakeWeightColor(float w0, float w1, float w2)
        {
            return new Color(Mathf.Clamp01(w0), Mathf.Clamp01(w1), Mathf.Clamp01(w2), 1.0f);
        }

        private void CreateStrictRuntimeChild(Transform parent, string name, Mesh mesh, Material mat)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var mf = go.AddComponent<MeshFilter>();
            var mr = go.AddComponent<MeshRenderer>();
            mf.sharedMesh = mesh;
            mr.sharedMaterial = mat;
            mr.shadowCastingMode = ShadowCastingMode.Off;
            mr.receiveShadows = false;
            mr.lightProbeUsage = UnityEngine.Rendering.LightProbeUsage.Off;
            mr.reflectionProbeUsage = UnityEngine.Rendering.ReflectionProbeUsage.Off;
        }

        private static void CollapseSortedUnique(int t0, int t1, int t2, out int l0, out int l1, out int l2)
        {
            l0 = t0;
            l1 = t1;
            l2 = t2;
            if (l1 == l0) l1 = -1;
            if (l2 == l0 || l2 == l1) l2 = -1;
        }

        private ParsedMap ResolveLiteralITerraRuntimeMapLikeOriginal()
        {
            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            if (terra != null && terra.EnabledLikeOriginal && terra.UseLiteralCallbackModelLikeOriginal)
            {
                ParsedMap facadeLikeOriginal = EnsureGlobalParsedMapFacadeLikeOriginal();
                if (facadeLikeOriginal != null)
                    return facadeLikeOriginal;
            }
            return _map;
        }

        private ParsedMap ResolveAuxRuntimeMapLikeOriginal()
        {
            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            return runtimeMapLikeOriginal ?? _map;
        }

        private string GetStrictFrameBuildSignatureLikeOriginal(Camera cam)
        {
            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            StrictViewportLikeOriginal viewportLikeOriginal = ComputeStrictViewportLikeOriginal(cam);
            return $"strict-frame|{_strictMapX:0.###}|{_strictMapY:0.###}|{_strictZoom:0.###}|mode={_strictZoomModeIndex}|vp={viewportLikeOriginal.X},{viewportLikeOriginal.Y},{viewportLikeOriginal.W},{viewportLikeOriginal.H}|surf={viewportLikeOriginal.SurfaceW},{viewportLikeOriginal.SurfaceH}|mx={viewportLikeOriginal.Mx}|mlx={viewportLikeOriginal.MLx}|gy={viewportLikeOriginal.Gy}|gy1={viewportLikeOriginal.Gy1}|limit={viewportLikeOriginal.ScLimit}|shift={viewportLikeOriginal.ScShift}|step={GetEffectiveStrictOldSurfaceStepLikeOriginal(runtimeMapLikeOriginal)}";
        }

        private void RebuildStrictRuntimeFrameLikeOriginal(
            BaseMeshLikeOriginal sTriangLikeOriginal,
            BaseMeshLikeOriginal groundMeshLikeOriginal,
            Camera activeCamera,
            ref VertexTnL2LikeOriginal[] gVERLikeOriginal,
            ref int gVERVertexCountLikeOriginal,
            ref VertexTnLLikeOriginal[] gVGVertexPtrLikeOriginal,
            ref int[] tIdxLikeOriginal,
            ref int nGFVertLikeOriginal)
        {
            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            if (runtimeMapLikeOriginal == null || runtimeMapLikeOriginal.IsMeshSurface)
                return;

            {
                GroundTextureCatalog catalog = GetOrCreateGroundCatalog(out _);
            GroundRuntimeConfig runtimeCfg = GetOrCreateGroundRuntimeConfig(out _);
            EnsureGroundTextureTable(runtimeCfg, catalog);
            short[] randoma = GetRandomTableLikeOriginal(runtimeCfg);
            SeedStrictCRandLikeOriginal(1);
            bool emitSurfaceGroundBucketsLikeOriginal = false;
            Dictionary<int, int> groundLayerById = BuildStrictSurfaceGroundLayerMapIfNeededLikeOriginal(emitSurfaceGroundBucketsLikeOriginal, catalog, runtimeCfg, out _);

            VertexStreamLikeOriginal[] gArrayLikeOriginal = groundMeshLikeOriginal != null ? groundMeshLikeOriginal.GArrayLikeOriginal : null;
            int[] nInGarrLikeOriginal = groundMeshLikeOriginal != null ? groundMeshLikeOriginal.NInGarrLikeOriginal : null;
            int[] maxInGarrLikeOriginal = groundMeshLikeOriginal != null ? groundMeshLikeOriginal.MaxInGarrLikeOriginal : null;
            GArrayBufferLikeOriginal[] factPlainById = new GArrayBufferLikeOriginal[256];
            GArrayBufferLikeOriginal[] factBumpById = new GArrayBufferLikeOriginal[256];
            int baseTriCount = 0;
            int secTriCount = 0;
            int factTriCount = 0;
            int factPlainTriCount = 0;
            int factBumpTriCount = 0;

            BuildStrictRuntimeFrameSourcesLikeOriginal(
                activeCamera,
                catalog,
                runtimeCfg,
                groundLayerById,
                randoma,
                includeSecondary: true,
                includeFacture: true,
                ref gVERLikeOriginal,
                ref gVERVertexCountLikeOriginal,
                ref gVGVertexPtrLikeOriginal,
                ref tIdxLikeOriginal,
                ref nGFVertLikeOriginal,
                ref gArrayLikeOriginal,
                ref nInGarrLikeOriginal,
                ref maxInGarrLikeOriginal,
                ref factPlainById,
                ref factBumpById,
                ref baseTriCount,
                ref secTriCount,
                ref factTriCount,
                ref factPlainTriCount,
                ref factBumpTriCount);

            StrictViewportLikeOriginal strictViewportLikeOriginal = ComputeStrictViewportLikeOriginal(activeCamera);

            if (sTriangLikeOriginal != null)
            {
                sTriangLikeOriginal.ViewportLikeOriginal = new Vector2Int(Mathf.Max(1, strictViewportLikeOriginal.W), Mathf.Max(1, strictViewportLikeOriginal.H));

                VertexStreamLikeOriginal stStreamLikeOriginal = sTriangLikeOriginal.ImmediateStreamLikeOriginal;
                if (stStreamLikeOriginal != null)
                {
                    stStreamLikeOriginal.VertexPtrLikeOriginal = gVERLikeOriginal;
                    stStreamLikeOriginal.VertexCountLikeOriginal = gVERVertexCountLikeOriginal;
                    stStreamLikeOriginal.SubmitFirstVertexLikeOriginal = 0;
                    stStreamLikeOriginal.SubmitVertexCountLikeOriginal = gVERVertexCountLikeOriginal;
                    sTriangLikeOriginal.GVERLikeOriginal = gVERLikeOriginal;
                    sTriangLikeOriginal.GVERVertexCountLikeOriginal = gVERVertexCountLikeOriginal;
                    sTriangLikeOriginal.SetVertexPtrLikeOriginal(gVERLikeOriginal);
                    sTriangLikeOriginal.SetNVertLikeOriginal(gVERVertexCountLikeOriginal);
                    sTriangLikeOriginal.SetNIndLikeOriginal(gVERVertexCountLikeOriginal);
                    sTriangLikeOriginal.SetNPriLikeOriginal(gVERVertexCountLikeOriginal / 3);
                    ApplySurfaceMaterialStateLikeOriginal(sTriangLikeOriginal, strictViewportLikeOriginal);
                }
            }

            if (groundMeshLikeOriginal != null)
            {
                groundMeshLikeOriginal.ViewportLikeOriginal = new Vector2Int(Mathf.Max(1, strictViewportLikeOriginal.W), Mathf.Max(1, strictViewportLikeOriginal.H));
                groundMeshLikeOriginal.GArrayLikeOriginal = gArrayLikeOriginal;
                if (groundMeshLikeOriginal.GArrayVertexPtrLikeOriginal == null || groundMeshLikeOriginal.GArrayVertexPtrLikeOriginal.Length != gArrayLikeOriginal.Length)
                    groundMeshLikeOriginal.GArrayVertexPtrLikeOriginal = new VertexTnLLikeOriginal[gArrayLikeOriginal.Length][];
                groundMeshLikeOriginal.NInGarrLikeOriginal = nInGarrLikeOriginal;
                groundMeshLikeOriginal.MaxInGarrLikeOriginal = maxInGarrLikeOriginal;
                groundMeshLikeOriginal.GVERLikeOriginal = gVERLikeOriginal;
                groundMeshLikeOriginal.GVERVertexCountLikeOriginal = gVERVertexCountLikeOriginal;
                groundMeshLikeOriginal.GVGVertexPtrLikeOriginal = gVGVertexPtrLikeOriginal;
                groundMeshLikeOriginal.TIDXLikeOriginal = tIdxLikeOriginal;
                groundMeshLikeOriginal.NGFVERTLikeOriginal = nGFVertLikeOriginal;
                groundMeshLikeOriginal.GroundSourceVerticesLikeOriginal = null;
                groundMeshLikeOriginal.GroundSourceVertexCountLikeOriginal = 0;
                groundMeshLikeOriginal.GroundSourceFactureIdsLikeOriginal = null;
                RebuildGroundGArrayStreamsFromGVGLikeOriginal(groundMeshLikeOriginal);
            }
            }
        }

        private void BuildStrictRuntimeFrameSourcesLikeOriginal(
            Camera activeCamera,
            GroundTextureCatalog catalog,
            GroundRuntimeConfig runtimeCfg,
            Dictionary<int, int> groundLayerById,
            short[] randoma,
            bool includeSecondary,
            bool includeFacture,
            ref VertexTnL2LikeOriginal[] gVERLikeOriginal,
            ref int gVERVertexCountLikeOriginal,
            ref VertexTnLLikeOriginal[] gVGVertexPtrLikeOriginal,
            ref int[] tIdxLikeOriginal,
            ref int nGFVertLikeOriginal,
            ref VertexStreamLikeOriginal[] gArrayLikeOriginal,
            ref int[] nInGarrLikeOriginal,
            ref int[] maxInGarrLikeOriginal,
            ref GArrayBufferLikeOriginal[] factPlainById,
            ref GArrayBufferLikeOriginal[] factBumpById,
            ref int baseTriCount,
            ref int secTriCount,
            ref int factTriCount,
            ref int factPlainTriCount,
            ref int factBumpTriCount)
        {
            gVERVertexCountLikeOriginal = 0;
            nGFVertLikeOriginal = 0;
            baseTriCount = 0;
            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            if (runtimeMapLikeOriginal == null || runtimeMapLikeOriginal.Heights == null || runtimeMapLikeOriginal.Heights.Length == 0 || runtimeMapLikeOriginal.VertInLine <= 1 || runtimeMapLikeOriginal.MaxTH <= 1)
                return;
            secTriCount = 0;
            factTriCount = 0;
            factPlainTriCount = 0;
            factBumpTriCount = 0;

            // Original DrawTriStrip() old-surface path has no sampled fallback here.
            // Strict exact mode always traverses the full THMap grid directly.

            StrictViewportLikeOriginal viewportLikeOriginal = ComputeStrictViewportLikeOriginal(activeCamera);
            int tQuantLikeOriginal = viewportLikeOriginal.TQuant;
            int hQuantLikeOriginal = viewportLikeOriginal.HQuant;
            int sQuantLikeOriginal = viewportLikeOriginal.SQuant;
            int gyLikeOriginal = viewportLikeOriginal.Gy;
            int glYLikeOriginal = viewportLikeOriginal.H;
            int gy1LikeOriginal = viewportLikeOriginal.Gy1;
            int scLimitLikeOriginal = viewportLikeOriginal.ScLimit;
            int mxLikeOriginal = viewportLikeOriginal.Mx;
            int mLxLikeOriginal = viewportLikeOriginal.MLx;

            for (int ix = 0; ix < mLxLikeOriginal; ix++)
            {
                int mapCol = mxLikeOriginal + ix;
                if (mapCol < 0 || mapCol >= runtimeMapLikeOriginal.VertInLine - 1)
                    break;

                int yp0 = Mathf.FloorToInt((float)gyLikeOriginal / tQuantLikeOriginal) * 2;
                if (yp0 < 0)
                    yp0 = 0;
                if (yp0 > runtimeMapLikeOriginal.MaxTH - 2)
                    yp0 = Mathf.Max(0, runtimeMapLikeOriginal.MaxTH - 2);
                int p0 = mapCol + yp0 * runtimeMapLikeOriginal.VertInLine;

                while (yp0 > 0)
                {
                    int cgyLikeOriginal = yp0 * hQuantLikeOriginal - GetStrictShiftedHeightLikeOriginal(p0, viewportLikeOriginal.ScShift);
                    if (cgyLikeOriginal > scLimitLikeOriginal)
                    {
                        yp0--;
                        p0 -= runtimeMapLikeOriginal.VertInLine;
                    }
                    else
                    {
                        break;
                    }
                }

                int yaLikeOriginal = int.MinValue;
                do
                {
                    if (mapCol < 0 || mapCol >= runtimeMapLikeOriginal.VertInLine - 1 || yp0 < 0 || yp0 >= runtimeMapLikeOriginal.MaxTH - 1)
                        break;

                    int yLikeOriginal = yp0 * hQuantLikeOriginal;
                    int s0LikeOriginal;
                    int s1LikeOriginal;
                    int s2LikeOriginal;
                    int s3LikeOriginal;
                    if ((mapCol & 1) != 0)
                    {
                        s0LikeOriginal = yLikeOriginal - sQuantLikeOriginal;
                        s1LikeOriginal = yLikeOriginal;
                        s2LikeOriginal = yLikeOriginal + sQuantLikeOriginal;
                        s3LikeOriginal = yLikeOriginal + hQuantLikeOriginal;
                    }
                    else
                    {
                        s0LikeOriginal = yLikeOriginal;
                        s1LikeOriginal = yLikeOriginal - sQuantLikeOriginal;
                        s2LikeOriginal = yLikeOriginal + hQuantLikeOriginal;
                        s3LikeOriginal = yLikeOriginal + sQuantLikeOriginal;
                    }

                    int v00 = p0;
                    int v10 = p0 + 1;
                    int v01 = p0 + runtimeMapLikeOriginal.VertInLine;
                    int v11 = p0 + runtimeMapLikeOriginal.VertInLine + 1;
                    if (v11 < 0 || runtimeMapLikeOriginal.Heights == null || v11 >= runtimeMapLikeOriginal.Heights.Length)
                        break;

                    int y0LikeOriginal = s0LikeOriginal - GetStrictShiftedHeightLikeOriginal(v00, viewportLikeOriginal.ScShift);
                    int y1LikeOriginal = s1LikeOriginal - GetStrictShiftedHeightLikeOriginal(v10, viewportLikeOriginal.ScShift);
                    int y2LikeOriginal = s2LikeOriginal - GetStrictShiftedHeightLikeOriginal(v01, viewportLikeOriginal.ScShift);
                    int y3LikeOriginal = s3LikeOriginal - GetStrictShiftedHeightLikeOriginal(v11, viewportLikeOriginal.ScShift);
                    yaLikeOriginal = y0LikeOriginal;

                    bool allBelowLikeOriginal = y0LikeOriginal < gyLikeOriginal && y1LikeOriginal < gyLikeOriginal && y2LikeOriginal < gyLikeOriginal && y3LikeOriginal < gyLikeOriginal;
                    bool allAboveLikeOriginal = y0LikeOriginal > gy1LikeOriginal && y1LikeOriginal > gy1LikeOriginal && y2LikeOriginal > gy1LikeOriginal && y3LikeOriginal > gy1LikeOriginal;
                    // Match DrawTriStrip(): only this coarse cell-level Y reject is applied before triangle emission.
                    if (!allBelowLikeOriginal && !allAboveLikeOriginal)
                    {
                        EmitStrictGeometryCellLikeOriginal(
                            viewportLikeOriginal,
                            ref gVERLikeOriginal,
                            ref gVERVertexCountLikeOriginal,
                            ref gVGVertexPtrLikeOriginal,
                            ref tIdxLikeOriginal,
                            ref nGFVertLikeOriginal,
                            runtimeCfg,
                            groundLayerById,
                            randoma,
                            mapCol,
                            v00, v10, v01, v11,
                            includeSecondary,
                            !includeFacture,
                            ref baseTriCount,
                            ref secTriCount);

                        if (includeFacture)
                        {
                            if ((mapCol & 1) != 0)
                            {
                                factTriCount += AddStrictFactureTrianglesBatched(viewportLikeOriginal, ref gVGVertexPtrLikeOriginal, ref nGFVertLikeOriginal, ref tIdxLikeOriginal, runtimeCfg, catalog, v00, v10, v01, out int addedPlain0, out int addedBump0);
                                factPlainTriCount += addedPlain0;
                                factBumpTriCount += addedBump0;
                                factTriCount += AddStrictFactureTrianglesBatched(viewportLikeOriginal, ref gVGVertexPtrLikeOriginal, ref nGFVertLikeOriginal, ref tIdxLikeOriginal, runtimeCfg, catalog, v01, v10, v11, out int addedPlain1, out int addedBump1);
                                factPlainTriCount += addedPlain1;
                                factBumpTriCount += addedBump1;
                            }
                            else
                            {
                                factTriCount += AddStrictFactureTrianglesBatched(viewportLikeOriginal, ref gVGVertexPtrLikeOriginal, ref nGFVertLikeOriginal, ref tIdxLikeOriginal, runtimeCfg, catalog, v00, v10, v11, out int addedPlain2, out int addedBump2);
                                factPlainTriCount += addedPlain2;
                                factBumpTriCount += addedBump2;
                                factTriCount += AddStrictFactureTrianglesBatched(viewportLikeOriginal, ref gVGVertexPtrLikeOriginal, ref nGFVertLikeOriginal, ref tIdxLikeOriginal, runtimeCfg, catalog, v00, v11, v01, out int addedPlain3, out int addedBump3);
                                factPlainTriCount += addedPlain3;
                                factBumpTriCount += addedBump3;
                            }
                        }
                    }

                    yp0++;
                    p0 += runtimeMapLikeOriginal.VertInLine;
                }
                while (yp0 < runtimeMapLikeOriginal.MaxTH - 1 && yaLikeOriginal < gy1LikeOriginal + 1000);
            }
        }

        // Helper-only sampled fallback retained for non-original debug/perf experimentation.
        // Active strict old-surface path does not call this path.
        private void BuildStrictRuntimeFrameSourcesSampledFallbackLikeOriginal(
            Mesh terrainMesh,
            GroundTextureCatalog catalog,
            GroundRuntimeConfig runtimeCfg,
            Dictionary<int, int> groundLayerById,
            short[] randoma,
            bool includeSecondary,
            bool includeFacture,
            ref VertexTnL2LikeOriginal[] gVERLikeOriginal,
            ref int gVERVertexCountLikeOriginal,
            ref VertexTnLLikeOriginal[] gVGVertexPtrLikeOriginal,
            ref int[] tIdxLikeOriginal,
            ref int nGFVertLikeOriginal,
            ref VertexStreamLikeOriginal[] gArrayLikeOriginal,
            ref int[] nInGarrLikeOriginal,
            ref int[] maxInGarrLikeOriginal,
            ref GArrayBufferLikeOriginal[] factPlainById,
            ref GArrayBufferLikeOriginal[] factBumpById,
            ref int baseTriCount,
            ref int secTriCount,
            ref int factTriCount,
            ref int factPlainTriCount,
            ref int factBumpTriCount)
        {
            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            if (runtimeMapLikeOriginal == null || runtimeMapLikeOriginal.VertInLine <= 1 || runtimeMapLikeOriginal.MaxTH <= 1)
                return;

            List<int> cols = BuildSampledIndices(runtimeMapLikeOriginal.VertInLine, Math.Max(1, OldSurfaceStep));
            List<int> rows = BuildSampledIndices(runtimeMapLikeOriginal.MaxTH, Math.Max(1, OldSurfaceStep));
            int sampledCols = cols.Count;
            int sampledRows = rows.Count;
            Vector3[] terrainVerts = terrainMesh != null ? terrainMesh.vertices : null;
            if (terrainVerts == null || terrainVerts.Length != sampledCols * sampledRows)
                return;

            StrictViewportLikeOriginal viewportLikeOriginal = ComputeStrictViewportLikeOriginal(GetActiveBattleCameraLikeOriginal());

            for (int ry = 0; ry < sampledRows - 1; ry++)
            {
                for (int cx = 0; cx < sampledCols - 1; cx++)
                {
                    int mapCol = cols[cx];
                    int v00 = rows[ry] * runtimeMapLikeOriginal.VertInLine + cols[cx];
                    int v10 = rows[ry] * runtimeMapLikeOriginal.VertInLine + cols[cx + 1];
                    int v01 = rows[ry + 1] * runtimeMapLikeOriginal.VertInLine + cols[cx];
                    int v11 = rows[ry + 1] * runtimeMapLikeOriginal.VertInLine + cols[cx + 1];

                    int d00 = ry * sampledCols + cx;
                    int d10 = ry * sampledCols + (cx + 1);
                    int d01 = (ry + 1) * sampledCols + cx;
                    int d11 = (ry + 1) * sampledCols + (cx + 1);

                    Vector3 p00 = terrainVerts[d00];
                    Vector3 p10 = terrainVerts[d10];
                    Vector3 p01 = terrainVerts[d01];
                    Vector3 p11 = terrainVerts[d11];

                    EmitStrictGeometryCellLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, runtimeCfg, groundLayerById, randoma,
                        mapCol, v00, v10, v01, v11,
                        includeSecondary,
                        !includeFacture,
                        ref baseTriCount,
                        ref secTriCount);

                    if (includeFacture)
                    {
                        if ((mapCol & 1) != 0)
                        {
                            factTriCount += AddStrictFactureTrianglesBatched(viewportLikeOriginal, ref gVGVertexPtrLikeOriginal, ref nGFVertLikeOriginal, ref tIdxLikeOriginal, runtimeCfg, catalog, v00, v10, v01, out int addedPlain0, out int addedBump0);
                            factPlainTriCount += addedPlain0;
                            factBumpTriCount += addedBump0;
                            factTriCount += AddStrictFactureTrianglesBatched(viewportLikeOriginal, ref gVGVertexPtrLikeOriginal, ref nGFVertLikeOriginal, ref tIdxLikeOriginal, runtimeCfg, catalog, v01, v10, v11, out int addedPlain1, out int addedBump1);
                            factPlainTriCount += addedPlain1;
                            factBumpTriCount += addedBump1;
                        }
                        else
                        {
                            factTriCount += AddStrictFactureTrianglesBatched(viewportLikeOriginal, ref gVGVertexPtrLikeOriginal, ref nGFVertLikeOriginal, ref tIdxLikeOriginal, runtimeCfg, catalog, v00, v10, v11, out int addedPlain2, out int addedBump2);
                            factPlainTriCount += addedPlain2;
                            factBumpTriCount += addedBump2;
                            factTriCount += AddStrictFactureTrianglesBatched(viewportLikeOriginal, ref gVGVertexPtrLikeOriginal, ref nGFVertLikeOriginal, ref tIdxLikeOriginal, runtimeCfg, catalog, v00, v11, v01, out int addedPlain3, out int addedBump3);
                            factPlainTriCount += addedPlain3;
                            factBumpTriCount += addedBump3;
                        }
                    }
                }
            }
        }

        
        private Vector3 BuildStrictWorldVertexLikeOriginal(int vertexId)
        {
            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            if (runtimeMapLikeOriginal == null || runtimeMapLikeOriginal.Heights == null || vertexId < 0 || vertexId >= runtimeMapLikeOriginal.Heights.Length || runtimeMapLikeOriginal.VertInLine <= 0)
                return Vector3.zero;

            int vx = vertexId % runtimeMapLikeOriginal.VertInLine;
            int vy = vertexId / runtimeMapLikeOriginal.VertInLine;
            float x = vx * 32.0f * HorizontalScale;
            float z = (vy * 32.0f + (((vx & 1) != 0) ? -16.0f : 0.0f)) * HorizontalScale * WorldZSign;
            float y = runtimeMapLikeOriginal.Heights[vertexId] * VerticalScale;
            return new Vector3(x, y, z);
        }

        private int EmitStrictPrimaryGeometryHalfLikeOriginal(StrictViewportLikeOriginal viewportLikeOriginal, ref VertexTnL2LikeOriginal[] gVERLikeOriginal, ref int gVERVertexCountLikeOriginal, ref VertexTnLLikeOriginal[] gVGVertexPtrLikeOriginal, ref int[] tIdxLikeOriginal, ref int nGFVertLikeOriginal, bool emitSurfaceGroundBucketsLikeOriginal, GroundRuntimeConfig runtimeCfg, Dictionary<int, int> groundLayerById, short[] randoma,
            int triKind,
            int v00, int v10, int v01, int v11,
            int tA, int tB, int tC,
            bool stage1PlainMode)
        {
            int tMin = tA, tAve = tB, tMax = tC;
            Sort3LikeOriginal(ref tMin, ref tAve, ref tMax);

            int triCount = 0;
            triCount += EmitStrictSurfacePassLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, emitSurfaceGroundBucketsLikeOriginal, runtimeCfg, groundLayerById, randoma, triKind, 0,
                v00, v10, v01, v11,
                tA, tB, tC, tMin,
                255, 255, 255,
                stage1PlainMode);

            if (tAve != tMin)
            {
                int fa = tA == tAve ? 255 : 0;
                int fb = tB == tAve ? 255 : 0;
                int fc = tC == tAve ? 255 : 0;
                triCount += EmitStrictSurfacePassLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, emitSurfaceGroundBucketsLikeOriginal, runtimeCfg, groundLayerById, randoma, triKind, 1,
                    v00, v10, v01, v11,
                    tA, tB, tC, tAve,
                    fa, fb, fc,
                    stage1PlainMode);
            }
            if (tMax != tMin && tMax != tAve)
            {
                int fa = tA == tMax ? 255 : 0;
                int fb = tB == tMax ? 255 : 0;
                int fc = tC == tMax ? 255 : 0;
                triCount += EmitStrictSurfacePassLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, emitSurfaceGroundBucketsLikeOriginal, runtimeCfg, groundLayerById, randoma, triKind, 2,
                    v00, v10, v01, v11,
                    tA, tB, tC, tMax,
                    fa, fb, fc,
                    stage1PlainMode);
            }

            return triCount;
        }

        private int EmitStrictSecondaryGeometryHalfLikeOriginal(StrictViewportLikeOriginal viewportLikeOriginal, ref VertexTnL2LikeOriginal[] gVERLikeOriginal, ref int gVERVertexCountLikeOriginal, ref VertexTnLLikeOriginal[] gVGVertexPtrLikeOriginal, ref int[] tIdxLikeOriginal, ref int nGFVertLikeOriginal, bool emitSurfaceGroundBucketsLikeOriginal, GroundRuntimeConfig runtimeCfg, Dictionary<int, int> groundLayerById, short[] randoma,
            int triKind,
            int v00, int v10, int v01, int v11,
            int sA, int sB, int sC,
            int wA, int wB, int wC)
        {
            int sMin = sA, sAve = sB, sMax = sC;
            Sort3LikeOriginal(ref sMin, ref sAve, ref sMax);

            int triCount = 0;
            triCount += EmitStrictSurfacePassLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, emitSurfaceGroundBucketsLikeOriginal, runtimeCfg, groundLayerById, randoma, triKind, 0,
                v00, v10, v01, v11,
                sA, sB, sC, sMin,
                sA == sMin ? wA : 0, sB == sMin ? wB : 0, sC == sMin ? wC : 0,
                true);

            if (sAve != sMin)
            {
                int fa = sA == sAve ? wA : 0;
                int fb = sB == sAve ? wB : 0;
                int fc = sC == sAve ? wC : 0;
                triCount += EmitStrictSurfacePassLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, emitSurfaceGroundBucketsLikeOriginal, runtimeCfg, groundLayerById, randoma, triKind, 1,
                    v00, v10, v01, v11,
                    sA, sB, sC, sAve,
                    fa, fb, fc,
                    true);
            }
            if (sMax != sMin && sMax != sAve)
            {
                int fa = sA == sMax ? wA : 0;
                int fb = sB == sMax ? wB : 0;
                int fc = sC == sMax ? wC : 0;
                triCount += EmitStrictSurfacePassLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, emitSurfaceGroundBucketsLikeOriginal, runtimeCfg, groundLayerById, randoma, triKind, 2,
                    v00, v10, v01, v11,
                    sA, sB, sC, sMax,
                    fa, fb, fc,
                    true);
            }

            return triCount;
        }

        private void EmitStrictGeometryCellLikeOriginal(StrictViewportLikeOriginal viewportLikeOriginal, ref VertexTnL2LikeOriginal[] gVERLikeOriginal, ref int gVERVertexCountLikeOriginal, ref VertexTnLLikeOriginal[] gVGVertexPtrLikeOriginal, ref int[] tIdxLikeOriginal, ref int nGFVertLikeOriginal, GroundRuntimeConfig runtimeCfg, Dictionary<int, int> groundLayerById, short[] randoma,
            int mapCol,
            int v00, int v10, int v01, int v11,
            bool includeSecondary,
            bool emitSurfaceGroundBucketsLikeOriginal,
            ref int baseTriCount,
            ref int secTriCount)
        {
            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            if (runtimeMapLikeOriginal == null || runtimeMapLikeOriginal.TilePrimary == null)
                return;

            // Geometry cell stage: split the old diamond cell into its two original triangle halves first,
            // then run stage1/stage2 surface passes on top of those halves.
            bool stage1PlainMode = IsStrictSurfaceStage1PlainModeLikeOriginal(v00, v10, v01, v11);

            int t1 = runtimeMapLikeOriginal.TilePrimary[v00] & 0xFF;
            int t2 = runtimeMapLikeOriginal.TilePrimary[v10] & 0xFF;
            int t3 = runtimeMapLikeOriginal.TilePrimary[v01] & 0xFF;
            int t4 = runtimeMapLikeOriginal.TilePrimary[v11] & 0xFF;

            if ((mapCol & 1) != 0)
            {
                baseTriCount += EmitStrictPrimaryGeometryHalfLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, emitSurfaceGroundBucketsLikeOriginal, runtimeCfg, groundLayerById, randoma,
                    0, v00, v10, v01, v11, t1, t2, t3, stage1PlainMode);
                baseTriCount += EmitStrictPrimaryGeometryHalfLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, emitSurfaceGroundBucketsLikeOriginal, runtimeCfg, groundLayerById, randoma,
                    1, v00, v10, v01, v11, t3, t2, t4, stage1PlainMode);

                if (includeSecondary)
                {
                    int s1 = GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondary, v00, runtimeMapLikeOriginal.TilePrimary[v00]) & 0xFF;
                    int s2 = GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondary, v10, runtimeMapLikeOriginal.TilePrimary[v10]) & 0xFF;
                    int s3 = GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondary, v01, runtimeMapLikeOriginal.TilePrimary[v01]) & 0xFF;
                    int s4 = GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondary, v11, runtimeMapLikeOriginal.TilePrimary[v11]) & 0xFF;
                    int w1 = ScaleSecondaryWeightLikeOriginal(GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondaryWeight, v00, 0));
                    int w2 = ScaleSecondaryWeightLikeOriginal(GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondaryWeight, v10, 0));
                    int w3 = ScaleSecondaryWeightLikeOriginal(GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondaryWeight, v01, 0));
                    int w4 = ScaleSecondaryWeightLikeOriginal(GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondaryWeight, v11, 0));

                    secTriCount += EmitStrictSecondaryGeometryHalfLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, emitSurfaceGroundBucketsLikeOriginal, runtimeCfg, groundLayerById, randoma,
                        0, v00, v10, v01, v11, s1, s2, s3, w1, w2, w3);
                    secTriCount += EmitStrictSecondaryGeometryHalfLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, emitSurfaceGroundBucketsLikeOriginal, runtimeCfg, groundLayerById, randoma,
                        1, v00, v10, v01, v11, s3, s2, s4, w3, w2, w4);
                }
            }
            else
            {
                baseTriCount += EmitStrictPrimaryGeometryHalfLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, emitSurfaceGroundBucketsLikeOriginal, runtimeCfg, groundLayerById, randoma,
                    2, v00, v10, v01, v11, t1, t2, t4, stage1PlainMode);
                baseTriCount += EmitStrictPrimaryGeometryHalfLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, emitSurfaceGroundBucketsLikeOriginal, runtimeCfg, groundLayerById, randoma,
                    3, v00, v10, v01, v11, t1, t4, t3, stage1PlainMode);

                if (includeSecondary)
                {
                    int s1 = GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondary, v00, runtimeMapLikeOriginal.TilePrimary[v00]) & 0xFF;
                    int s2 = GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondary, v10, runtimeMapLikeOriginal.TilePrimary[v10]) & 0xFF;
                    int s3 = GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondary, v01, runtimeMapLikeOriginal.TilePrimary[v01]) & 0xFF;
                    int s4 = GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondary, v11, runtimeMapLikeOriginal.TilePrimary[v11]) & 0xFF;
                    int w1 = ScaleSecondaryWeightLikeOriginal(GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondaryWeight, v00, 0));
                    int w2 = ScaleSecondaryWeightLikeOriginal(GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondaryWeight, v10, 0));
                    int w3 = ScaleSecondaryWeightLikeOriginal(GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondaryWeight, v01, 0));
                    int w4 = ScaleSecondaryWeightLikeOriginal(GetArrayByteSafe(runtimeMapLikeOriginal.TileSecondaryWeight, v11, 0));

                    secTriCount += EmitStrictSecondaryGeometryHalfLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, emitSurfaceGroundBucketsLikeOriginal, runtimeCfg, groundLayerById, randoma,
                        2, v00, v10, v01, v11, s1, s2, s4, w1, w2, w4);
                    secTriCount += EmitStrictSecondaryGeometryHalfLikeOriginal(viewportLikeOriginal, ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, ref gVGVertexPtrLikeOriginal, ref tIdxLikeOriginal, ref nGFVertLikeOriginal, emitSurfaceGroundBucketsLikeOriginal, runtimeCfg, groundLayerById, randoma,
                        3, v00, v10, v01, v11, s1, s4, s3, w1, w4, w3);
                }
            }
        }

        
        private bool IsStrictSurfaceStage1PlainModeLikeOriginal(int v00, int v10, int v01, int v11)
        {
            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            byte[] secondaryWeightLikeOriginal = runtimeMapLikeOriginal != null ? runtimeMapLikeOriginal.TileSecondaryWeight : null;
            byte w1 = GetArrayByteSafe(secondaryWeightLikeOriginal, v00, 0);
            byte w2 = GetArrayByteSafe(secondaryWeightLikeOriginal, v10, 0);
            byte w3 = GetArrayByteSafe(secondaryWeightLikeOriginal, v01, 0);
            byte w4 = GetArrayByteSafe(secondaryWeightLikeOriginal, v11, 0);
            return w1 > 80 || w2 > 80 || w3 > 80 || w4 > 80;
        }

        private int EmitStrictSurfacePassLikeOriginal(StrictViewportLikeOriginal viewportLikeOriginal, ref VertexTnL2LikeOriginal[] gVERLikeOriginal, ref int gVERVertexCountLikeOriginal, ref VertexTnLLikeOriginal[] gVGVertexPtrLikeOriginal, ref int[] tIdxLikeOriginal, ref int nGFVertLikeOriginal, bool emitSurfaceGroundBucketsLikeOriginal, GroundRuntimeConfig runtimeCfg, Dictionary<int, int> groundLayerById, short[] randoma, int triKind, int passRank,
            int v00, int v10, int v01, int v11,
            int ta, int tb, int tc, int candidateId,
            int finalA, int finalB, int finalC,
            bool plainMode)
        {
            // Old DrawTriStrip() geometry is driven by THMap + cell topology first.
            // Texture catalog/layer lookup only participates in the optional regroup/bucket overlay.
            if (!TryBuildStrictSurfacePassGeometryLikeOriginal(
                    viewportLikeOriginal,
                    runtimeCfg,
                    randoma,
                    triKind,
                    passRank,
                    v00, v10, v01, v11,
                    ta, tb, tc, candidateId,
                    finalA, finalB, finalC,
                    plainMode,
                    out VertexTnL2LikeOriginal sv0,
                    out VertexTnL2LikeOriginal sv1,
                    out VertexTnL2LikeOriginal sv2))
            {
                return 0;
            }

            AddSTriangTriangleLikeOriginal(ref gVERLikeOriginal, ref gVERVertexCountLikeOriginal, sv0, sv1, sv2);
            TryEmitStrictSurfaceGroundBucketLikeOriginal(
                ref gVGVertexPtrLikeOriginal,
                ref tIdxLikeOriginal,
                ref nGFVertLikeOriginal,
                emitSurfaceGroundBucketsLikeOriginal,
                groundLayerById,
                candidateId,
                sv0, sv1, sv2);
            return 1;
        }

        private bool TryBuildStrictTriangleScreenGeometryLikeOriginal(
            StrictViewportLikeOriginal viewportLikeOriginal,
            int triKind,
            int v00, int v10, int v01, int v11,
            out int triA,
            out int triB,
            out int triC,
            out Vector3 screenPos0,
            out Vector3 screenPos1,
            out Vector3 screenPos2)
        {
            triA = triB = triC = 0;
            screenPos0 = screenPos1 = screenPos2 = default;

            GetStrictSurfaceTriangleVertexIdsLikeOriginal(triKind, v00, v10, v01, v11, out triA, out triB, out triC);
            screenPos0 = GetStrictSurfaceScreenPosLikeOriginal(viewportLikeOriginal, triA);
            screenPos1 = GetStrictSurfaceScreenPosLikeOriginal(viewportLikeOriginal, triB);
            screenPos2 = GetStrictSurfaceScreenPosLikeOriginal(viewportLikeOriginal, triC);
            return true;
        }

        private bool TryBuildStrictSurfacePassGeometryLikeOriginal(
            StrictViewportLikeOriginal viewportLikeOriginal,
            GroundRuntimeConfig runtimeCfg,
            short[] randoma,
            int triKind,
            int passRank,
            int v00, int v10, int v01, int v11,
            int ta, int tb, int tc, int candidateId,
            int finalA, int finalB, int finalC,
            bool plainMode,
            out VertexTnL2LikeOriginal sv0,
            out VertexTnL2LikeOriginal sv1,
            out VertexTnL2LikeOriginal sv2)
        {
            sv0 = default;
            sv1 = default;
            sv2 = default;

            if (finalA <= 0 && finalB <= 0 && finalC <= 0)
                return false;

            if (!TryBuildStrictTriangleScreenGeometryLikeOriginal(
                    viewportLikeOriginal,
                    triKind,
                    v00, v10, v01, v11,
                    out int triA,
                    out int triB,
                    out int triC,
                    out Vector3 screenPos0,
                    out Vector3 screenPos1,
                    out Vector3 screenPos2))
            {
                return false;
            }

            // Geometry/topology comes first; surface-pass UV/decorate state is applied on top.
            GetTriPassAtlasUvLikeOriginal(candidateId, triKind, passRank, randoma, v00, v10, v01, v11, out Vector2 uv0, out Vector2 uv1, out Vector2 uv2);

            sv0 = BuildStrictSurfaceVertexLikeOriginal(screenPos0, triA, finalA, uv0, Vector2.zero);
            sv1 = BuildStrictSurfaceVertexLikeOriginal(screenPos1, triB, finalB, uv1, Vector2.zero);
            sv2 = BuildStrictSurfaceVertexLikeOriginal(screenPos2, triC, finalC, uv2, Vector2.zero);

            if (passRank > 0)
            {
                if (ta != candidateId) sv0 = WithStrictDiffuseLikeOriginal(sv0, ApplyStrictDwLMinLikeOriginal(sv0.Diffuse, triA));
                if (tb != candidateId) sv1 = WithStrictDiffuseLikeOriginal(sv1, ApplyStrictDwLMinLikeOriginal(sv1.Diffuse, triB));
                if (tc != candidateId) sv2 = WithStrictDiffuseLikeOriginal(sv2, ApplyStrictDwLMinLikeOriginal(sv2.Diffuse, triC));
            }

            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            int tMinLikeOriginal = ta;
            int tAveLikeOriginal = tb;
            int tMaxLikeOriginal = tc;
            Sort3LikeOriginal(ref tMinLikeOriginal, ref tAveLikeOriginal, ref tMaxLikeOriginal);

            bool prevPlainModeLikeOriginal = PLAINMODELikeOriginal;
            PLAINMODELikeOriginal = plainMode;
            switch (triKind)
            {
                case 0:
                    if (passRank == 0)
                        NormalizeVertexTexLLikeOriginal(runtimeMapLikeOriginal, runtimeCfg, randoma, ref sv0, ref sv1, ref sv2, tMinLikeOriginal, tMinLikeOriginal, plainMode, v00);
                    else if (passRank == 1)
                        NormalizeVertexTexLLikeOriginal(runtimeMapLikeOriginal, runtimeCfg, randoma, ref sv0, ref sv1, ref sv2, tMinLikeOriginal, tAveLikeOriginal, plainMode, v01);
                    else
                        NormalizeVertexTexLLikeOriginal(runtimeMapLikeOriginal, runtimeCfg, randoma, ref sv0, ref sv1, ref sv2, tMaxLikeOriginal, tAveLikeOriginal, plainMode, v11);
                    break;

                case 1:
                    if (passRank == 0)
                        NormalizeVertexTexRLikeOriginal(runtimeMapLikeOriginal, runtimeCfg, randoma, ref sv0, ref sv1, ref sv2, tMinLikeOriginal, tMinLikeOriginal, plainMode, v10);
                    else if (passRank == 1)
                        NormalizeVertexTexRLikeOriginal(runtimeMapLikeOriginal, runtimeCfg, randoma, ref sv0, ref sv1, ref sv2, tMinLikeOriginal, tAveLikeOriginal, plainMode, v10);
                    else
                        NormalizeVertexTexRLikeOriginal(runtimeMapLikeOriginal, runtimeCfg, randoma, ref sv0, ref sv1, ref sv2, tAveLikeOriginal, tMaxLikeOriginal, plainMode, v01);
                    break;

                case 2:
                    if (passRank == 0)
                        NormalizeVertexTexRLikeOriginal(runtimeMapLikeOriginal, runtimeCfg, randoma, ref sv0, ref sv1, ref sv2, tMinLikeOriginal, tMinLikeOriginal, plainMode, v10);
                    else if (passRank == 1)
                        NormalizeVertexTexRLikeOriginal(runtimeMapLikeOriginal, runtimeCfg, randoma, ref sv0, ref sv1, ref sv2, tMinLikeOriginal, tAveLikeOriginal, plainMode, v11);
                    else
                        NormalizeVertexTexRLikeOriginal(runtimeMapLikeOriginal, runtimeCfg, randoma, ref sv0, ref sv1, ref sv2, tAveLikeOriginal, tMaxLikeOriginal, plainMode, v10);
                    break;

                default:
                    if (passRank == 0)
                        NormalizeVertexTexLLikeOriginal(runtimeMapLikeOriginal, runtimeCfg, randoma, ref sv0, ref sv1, ref sv2, tMinLikeOriginal, tMinLikeOriginal, plainMode, v11);
                    else if (passRank == 1)
                        NormalizeVertexTexLLikeOriginal(runtimeMapLikeOriginal, runtimeCfg, randoma, ref sv0, ref sv1, ref sv2, tMinLikeOriginal, tAveLikeOriginal, plainMode, v10);
                    else
                        NormalizeVertexTexLLikeOriginal(runtimeMapLikeOriginal, runtimeCfg, randoma, ref sv0, ref sv1, ref sv2, tAveLikeOriginal, tMaxLikeOriginal, plainMode, v01);
                    break;
            }
            PLAINMODELikeOriginal = prevPlainModeLikeOriginal;
            return true;
        }

        private static void TryEmitStrictSurfaceGroundBucketLikeOriginal(
            ref VertexTnLLikeOriginal[] gVGVertexPtrLikeOriginal,
            ref int[] tIdxLikeOriginal,
