        private Vector3 GetStrictSurfaceScreenPosLikeOriginal(StrictViewportLikeOriginal viewportLikeOriginal, int vertexId)
        {
            Vector3 screenPos = ProjectStrictVertexIdToSurfaceScreenLikeOriginal(viewportLikeOriginal, vertexId);
            screenPos.x += GetXShiftLikeOriginal(vertexId);
            screenPos.y += GetYShiftLikeOriginal(vertexId);
            return screenPos;
        }

        
        private float GetStrictHeightRasterLikeOriginal(int vertexId, StrictViewportLikeOriginal viewportLikeOriginal)
        {
            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            if (runtimeMapLikeOriginal == null || runtimeMapLikeOriginal.Heights == null || vertexId < 0 || vertexId >= runtimeMapLikeOriginal.Heights.Length)
                return 0.0f;

            int heightLikeOriginal = runtimeMapLikeOriginal.Heights[vertexId];
            int shiftLikeOriginal = Mathf.Clamp(viewportLikeOriginal.ScShift, 0, 8);
            if (shiftLikeOriginal > 0)
                heightLikeOriginal >>= shiftLikeOriginal;
            return heightLikeOriginal;
        }

        
        private int GetStrictShiftedHeightLikeOriginal(int vertexId, int scShiftLikeOriginal)
        {
            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            if (runtimeMapLikeOriginal == null || runtimeMapLikeOriginal.Heights == null || vertexId < 0 || vertexId >= runtimeMapLikeOriginal.Heights.Length)
                return 0;

            int heightLikeOriginal = runtimeMapLikeOriginal.Heights[vertexId];
            int shiftLikeOriginal = Mathf.Clamp(scShiftLikeOriginal, 0, 8);
            if (shiftLikeOriginal > 0)
                heightLikeOriginal >>= shiftLikeOriginal;
            return heightLikeOriginal;
        }

        
        private Vector3 ProjectStrictVertexIdToSurfaceScreenLikeOriginal(StrictViewportLikeOriginal viewportLikeOriginal, int vertexId)
        {
            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            if (runtimeMapLikeOriginal == null || runtimeMapLikeOriginal.VertInLine <= 0 || vertexId < 0)
                return Vector3.zero;

            int vx = vertexId % runtimeMapLikeOriginal.VertInLine;
            int vy = vertexId / runtimeMapLikeOriginal.VertInLine;
            float baseX = viewportLikeOriginal.X + (vx - viewportLikeOriginal.Mx) * viewportLikeOriginal.TQuant;
            float baseY = viewportLikeOriginal.Y + vy * viewportLikeOriginal.HQuant + (((vx & 1) != 0) ? -viewportLikeOriginal.SQuant : 0.0f);
            float heightRaster = GetStrictHeightRasterLikeOriginal(vertexId, viewportLikeOriginal);
            float screenX = baseX;
            float screenY = baseY - viewportLikeOriginal.Gy - heightRaster;
            return new Vector3(screenX, screenY, heightRaster);
        }

        // Legacy helper kept for non-strict experiments; active strict old-surface path does not use it.

        
        private Vector3 ProjectWorldToSurfaceScreenLikeOriginal(Camera activeCamera, StrictViewportLikeOriginal viewportLikeOriginal, Vector3 worldPos, int vertexId)
        {
            float hScale = Mathf.Abs(HorizontalScale) > 0.0001f ? Mathf.Abs(HorizontalScale) : 1.0f;
            float vScale = Mathf.Abs(VerticalScale) > 0.0001f ? Mathf.Abs(VerticalScale) : 1.0f;

            ParsedMap runtimeMapLikeOriginal = ResolveLiteralITerraRuntimeMapLikeOriginal();
            if (runtimeMapLikeOriginal == null || runtimeMapLikeOriginal.VertInLine <= 0 || vertexId < 0)
            {
                float fallbackHeight = worldPos.y / vScale;
                return new Vector3(worldPos.x / hScale, worldPos.z / hScale - fallbackHeight, fallbackHeight);
            }

            int vx = vertexId % runtimeMapLikeOriginal.VertInLine;
            int vy = vertexId / runtimeMapLikeOriginal.VertInLine;

            float baseX = viewportLikeOriginal.X + (vx - viewportLikeOriginal.Mx) * viewportLikeOriginal.TQuant;
            float baseY = viewportLikeOriginal.Y + vy * viewportLikeOriginal.HQuant + (((vx & 1) != 0) ? -viewportLikeOriginal.SQuant : 0.0f);
            float heightRaster = worldPos.y / vScale;

            float screenX = baseX;
            float screenY = baseY - viewportLikeOriginal.Gy - heightRaster;

            return new Vector3(screenX, screenY, heightRaster);
        }

        private static float GetStrictSurfaceRhwLikeOriginal(int vertexId)
        {
            // Factures3D.cpp in this source archive routes w through GetRHW(V), and GetRHW(V) currently returns 1.0f.
            return 1.0f;
        }

        private static float GetStrictSurfaceZLikeOriginal(float screenYLikeOriginal)
        {
            return 0.5f - screenYLikeOriginal / 3000.0f;
        }

        private static int GetMaxPointIndexLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return 0;

            if (map.MaxPointIndex > 0)
                return map.MaxPointIndex;

            // Original engine uses MaxPointIndex == (MaxTH + 1) * MaxTH for THMap / XYShift / texture maps.
            if (map.MaxTH > 0)
                return checked((map.MaxTH + 1) * map.MaxTH);

            if (map.VertInLine > 0 && map.MaxTH > 0)
                return checked(map.VertInLine * map.MaxTH);

            if (map.Heights != null && map.Heights.Length > 0)
                return map.Heights.Length;

            return 0;
        }

        private static void EnsureMapXyShiftLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            int expected = GetMaxPointIndexLikeOriginal(map);
            if (expected <= 0)
                return;

            if (map.XYShift != null && map.XYShift.Length >= expected)
                return;

            // Original retail path does not read XYShift from SURF/TILE/FMAPP chunks.
            // LoadSave.cpp calls SetupXYShift(), and SetupXYShift() allocates (MaxTH + 1) * MaxTH bytes
            // and clears them to 0x88. With GETXSHIFT/GETYSHIFT this decodes to zero shift everywhere
            // until some later editor/gameplay path mutates XYShift in memory.
            map.XYShift = Enumerable.Repeat((byte)0x88, expected).ToArray();
        }

        
        private int GetXShiftLikeOriginal(int vertex)
        {
            return GetXShiftLikeOriginal(ResolveLiteralITerraRuntimeMapLikeOriginal(), vertex);
        }

        
        private int GetYShiftLikeOriginal(int vertex)
        {
            return GetYShiftLikeOriginal(ResolveLiteralITerraRuntimeMapLikeOriginal(), vertex);
        }

        private static int GetXShiftLikeOriginal(ParsedMap map, int vertex)
        {
            EnsureMapXyShiftLikeOriginal(map);
            if (map == null || map.XYShift == null || vertex < 0 || vertex >= map.XYShift.Length)
                return 0;
            return (map.XYShift[vertex] & 0x0F) - 8;
        }

        private static int GetYShiftLikeOriginal(ParsedMap map, int vertex)
        {
            EnsureMapXyShiftLikeOriginal(map);
            if (map == null || map.XYShift == null || vertex < 0 || vertex >= map.XYShift.Length)
                return 0;
            return ((map.XYShift[vertex] >> 4) & 0x0F) - 8;
        }

        private static uint SetStrictPackedAlphaLikeOriginal(uint diffuse, int alpha)
