        {
            public int QuadLx;
            public int QuadLy;
            public int QuadX0;
            public int QuadY0;
            public int QuadsNx;
            public int QuadsNy;
            public int UmlX;
            public int UmlY;
            public List<int>[] TrianglesByQuad;
        }

