            public int TriangleCount;
        }

        private static Vector3 GetMeshVertexPlanarHeightLikeOriginal(ParsedMap map, int index)
        {
            if (map == null)
                return Vector3.zero;
            if (map.MeshVerticesOriginal != null && index >= 0 && index < map.MeshVerticesOriginal.Length)
                return map.MeshVerticesOriginal[index];
            if (map.MeshVertices == null || index < 0 || index >= map.MeshVertices.Length)
                return Vector3.zero;

            Vector3 v = map.MeshVertices[index];
            return new Vector3(v.x, v.z, v.y);
        }

        private static byte GetMeshVertexFactureLikeOriginal(ParsedMap map, int index)
        {
            if (map == null || map.MeshFacture == null || index < 0 || index >= map.MeshFacture.Length)
                return 0;
            return map.MeshFacture[index];
        }

        private static Vector3 GetMeshVertexOriginalNormalLikeOriginal(ParsedMap map, int index)
        {
            if (map == null)
                return new Vector3(0.0f, 1.0f, 0.0f);
            if (map.MeshNormalsOriginal != null && index >= 0 && index < map.MeshNormalsOriginal.Length)
            {
                Vector3 n0 = map.MeshNormalsOriginal[index];
                if (n0.sqrMagnitude <= 1e-12f)
                    return new Vector3(0.0f, 1.0f, 0.0f);
                return n0.normalized;
            }
            if (map.MeshNormals == null || index < 0 || index >= map.MeshNormals.Length)
                return new Vector3(0.0f, 1.0f, 0.0f);

            Vector3 n = map.MeshNormals[index];
            Vector3 originalLike = new Vector3(n.x, n.z, n.y);
            if (originalLike.sqrMagnitude <= 1e-12f)
                return new Vector3(0.0f, 1.0f, 0.0f);
            return originalLike.normalized;
        }

        private sealed class MeshMapperStateLikeOriginal
        {
            public int Facture;
            public int MapperKind;
            public float SU = 1.0f;
            public float SV = 1.0f;
            public int Lx = 256;
            public int Ly = 256;
        }

        private static MeshMapperStateLikeOriginal BuildMeshMapperStateLikeOriginal(GroundTextureCatalog catalog, GroundRuntimeConfig runtimeCfg, int factureLikeOriginal)
        {
            var stateLikeOriginal = new MeshMapperStateLikeOriginal
            {
                Facture = factureLikeOriginal,
                MapperKind = GetFactureUsageLikeOriginal(runtimeCfg, factureLikeOriginal) == 0 ? 0 : 1
            };

            if (runtimeCfg != null && runtimeCfg.Factures != null && factureLikeOriginal >= 0 && factureLikeOriginal < runtimeCfg.Factures.Length)
            {
                FactureInfoEntry fe = runtimeCfg.Factures[factureLikeOriginal];
                if (fe != null)
                {
                    if (fe.Mapping == 0 || fe.Mapping == 1)
                        stateLikeOriginal.MapperKind = fe.Mapping;
                    else if (fe.Mapping == 2)
                        stateLikeOriginal.MapperKind = 1;

                    if (!Mathf.Approximately(fe.UScale, 0.0f))
                        stateLikeOriginal.SU = fe.UScale;
                    if (!Mathf.Approximately(fe.VScale, 0.0f))
                        stateLikeOriginal.SV = fe.VScale;

                    Texture2D tex = ResolveTextureByFlexibleKeys(catalog, fe.TexturePathKey, fe.TextureNameKey);
                    if (tex != null)
                    {
                        stateLikeOriginal.Lx = Mathf.Max(1, tex.width);
                        stateLikeOriginal.Ly = Mathf.Max(1, tex.height);
                    }
                }
            }

            return stateLikeOriginal;
        }

        private static uint GetMeshMappingCodeLikeOriginal(MeshMapperStateLikeOriginal mapperLikeOriginal, Vector3 originalPosLikeOriginal, Vector3 originalNormalLikeOriginal)
        {
            if (mapperLikeOriginal == null || mapperLikeOriginal.MapperKind == 0)
            {
                int px = (int)(originalPosLikeOriginal.x / 350.0f + originalPosLikeOriginal.y / 470.0f);
                int py = (int)(originalPosLikeOriginal.x / 520.0f + originalPosLikeOriginal.y / 430.0f);
                return (uint)(px + (py << 16));
            }

            float nx = originalNormalLikeOriginal.x;
            float ny = originalNormalLikeOriginal.y;
            float L = Mathf.Sqrt(Mathf.Max(1e-6f, nx * nx + ny * ny));
            nx /= L;
            ny /= L;

            if (nx >= 0.0f && ny >= 0.0f)
            {
                if (nx > 2.4f * ny) return 6;
                if (ny > 2.4f * nx) return 0;
                return 7;
            }
            if (nx < 0.0f && ny >= 0.0f)
            {
                nx = -nx;
                if (nx > 2.4f * ny) return 2;
                if (ny > 2.4f * nx) return 0;
                return 1;
            }
            if (nx < 0.0f && ny < 0.0f)
            {
                nx = -nx;
                ny = -ny;
                if (nx > 2.4f * ny) return 2;
                if (ny > 2.4f * nx) return 4;
                return 3;
            }

            ny = -ny;
            if (nx > 2.4f * ny) return 6;
            if (ny > 2.4f * nx) return 4;
            return 5;
        }

        private static Vector2 GetMeshMappingUvLikeOriginal(MeshMapperStateLikeOriginal mapperLikeOriginal, Vector3 originalPosLikeOriginal, Vector3 originalNormalLikeOriginal, uint mappingCodeLikeOriginal)
        {
            if (mapperLikeOriginal == null || mapperLikeOriginal.MapperKind == 0)
            {
                float ushift = (mappingCodeLikeOriginal & 0xFFFF) / 10.0f;
                float vshift = (mappingCodeLikeOriginal >> 16) / 10.0f;
                ushift -= Mathf.Floor(ushift);
                vshift -= Mathf.Floor(vshift);
                return new Vector2(
                    originalPosLikeOriginal.x / 256.0f + ushift,
                    originalPosLikeOriginal.y / 512.0f + vshift);
            }

            float denomU = Mathf.Max(1e-6f, mapperLikeOriginal.SU * mapperLikeOriginal.Lx);
            float denomV = Mathf.Max(1e-6f, mapperLikeOriginal.SV * mapperLikeOriginal.Ly);
            float X = originalPosLikeOriginal.x / denomU;
            float Y = originalPosLikeOriginal.y / denomU;
            float Z = originalPosLikeOriginal.z / denomV;
            float u;
            switch ((int)mappingCodeLikeOriginal)
            {
                case 0:
                case 4:
                    u = -X;
                    break;
                case 2:
                case 6:
                    u = Y;
                    break;
                case 7:
                case 3:
                    u = -(X - Y) / 1.4142f;
                    break;
                case 1:
                case 5:
                    u = -(X + Y) / 1.4142f;
                    break;
                default:
                    u = -X;
                    break;
            }

            return new Vector2(u, -Z);
        }

        private static Color32 BuildMeshFactureDiffuseColorLikeOriginal(ParsedMap map, int originalIndexLikeOriginal, bool alphaLikeOriginal)
        {
            Color32 baseColor = map != null && map.MeshColors != null && originalIndexLikeOriginal >= 0 && originalIndexLikeOriginal < map.MeshColors.Length
                ? map.MeshColors[originalIndexLikeOriginal]
                : new Color32(255, 255, 255, 255);

            byte shadowLikeOriginal = map != null && map.MeshShadow != null && originalIndexLikeOriginal >= 0 && originalIndexLikeOriginal < map.MeshShadow.Length
                ? map.MeshShadow[originalIndexLikeOriginal]
                : (byte)128;

            int factorLikeOriginal = Mathf.Clamp(shadowLikeOriginal * 2, 0, 255);
            byte a = alphaLikeOriginal ? (byte)0 : (byte)255;
            return new Color32(
                (byte)((baseColor.r * factorLikeOriginal) >> 8),
                (byte)((baseColor.g * factorLikeOriginal) >> 8),
                (byte)((baseColor.b * factorLikeOriginal) >> 8),
                a);
        }

        private static Vector3 GetMeshSpecularLightDirLikeOriginal()
        {
            Light sunLikeOriginal = RenderSettings.sun;
            if (sunLikeOriginal != null)
            {
                Vector3 fromSurfaceToLightLikeOriginal = -sunLikeOriginal.transform.forward;
                if (fromSurfaceToLightLikeOriginal.sqrMagnitude > 1e-8f)
                    return fromSurfaceToLightLikeOriginal.normalized;
            }

            Vector3 fallbackLikeOriginal = new Vector3(0.35f, 0.85f, 0.25f);
            return fallbackLikeOriginal.normalized;
        }

        private static Vector3 GetWorldNormalFromOriginalLikeOriginal(Vector3 originalNormalLikeOriginal)
        {
            Vector3 worldNormalLikeOriginal = new Vector3(
                originalNormalLikeOriginal.x,
                originalNormalLikeOriginal.y,
                originalNormalLikeOriginal.z * WorldZSign);

            if (worldNormalLikeOriginal.sqrMagnitude <= 1e-12f)
                return Vector3.up;
            return worldNormalLikeOriginal.normalized;
        }

        private static Vector4 BuildMeshTangentLikeOriginal(Vector3 originalNormalLikeOriginal)
        {
            Vector3 worldNormalLikeOriginal = GetWorldNormalFromOriginalLikeOriginal(originalNormalLikeOriginal);
            Vector3 tangentSeedLikeOriginal = Vector3.right;
            Vector3 tangentLikeOriginal = tangentSeedLikeOriginal - Vector3.Dot(tangentSeedLikeOriginal, worldNormalLikeOriginal) * worldNormalLikeOriginal;
            if (tangentLikeOriginal.sqrMagnitude <= 1e-8f)
            {
                tangentSeedLikeOriginal = Vector3.forward;
                tangentLikeOriginal = tangentSeedLikeOriginal - Vector3.Dot(tangentSeedLikeOriginal, worldNormalLikeOriginal) * worldNormalLikeOriginal;
            }

            if (tangentLikeOriginal.sqrMagnitude <= 1e-8f)
                tangentLikeOriginal = Vector3.Cross(worldNormalLikeOriginal, Vector3.up);

            tangentLikeOriginal.Normalize();
            Vector3 bitangentLikeOriginal = Vector3.Cross(worldNormalLikeOriginal, tangentLikeOriginal).normalized;
            float handednessLikeOriginal = Vector3.Dot(Vector3.Cross(worldNormalLikeOriginal, tangentLikeOriginal), bitangentLikeOriginal) < 0.0f ? -1.0f : 1.0f;
            return new Vector4(tangentLikeOriginal.x, tangentLikeOriginal.y, tangentLikeOriginal.z, handednessLikeOriginal);
        }

        private static Color32 VectorToColorLikeOriginal(Vector3 tangentSpaceVectorLikeOriginal, byte alphaLikeOriginal)
        {
            byte Pack(float c)
            {
                int v = Mathf.RoundToInt((Mathf.Clamp(c, -1.0f, 1.0f) * 0.5f + 0.5f) * 255.0f);
                return (byte)Mathf.Clamp(v, 0, 255);
            }

            return new Color32(
                Pack(tangentSpaceVectorLikeOriginal.x),
                Pack(tangentSpaceVectorLikeOriginal.y),
                Pack(tangentSpaceVectorLikeOriginal.z),
                alphaLikeOriginal);
        }

        private static Vector4 BuildMeshFactureSpecularPayloadLikeOriginal(ParsedMap map, int originalIndexLikeOriginal, bool alphaLikeOriginal)
        {
            Vector3 originalNormalLikeOriginal = GetMeshVertexOriginalNormalLikeOriginal(map, originalIndexLikeOriginal);
            Vector3 nLikeOriginal = GetWorldNormalFromOriginalLikeOriginal(originalNormalLikeOriginal);
            Vector3 lLikeOriginal = GetMeshSpecularLightDirLikeOriginal();
            float dotpLikeOriginal = Vector3.Dot(lLikeOriginal, nLikeOriginal);
            float bLikeOriginal = 0.5f;
            if (dotpLikeOriginal < 0.0f)
                bLikeOriginal += dotpLikeOriginal;
            if (bLikeOriginal < 0.0f)
                bLikeOriginal = 0.0f;
            float aLikeOriginal = 0.5f - bLikeOriginal * dotpLikeOriginal;
            Vector3 vlLikeOriginal = aLikeOriginal * nLikeOriginal + bLikeOriginal * lLikeOriginal;
            Vector3 tangentSpaceVectorLikeOriginal = ToTangentSpaceLikeOriginal(vlLikeOriginal, nLikeOriginal, Vector3.right);
            Color32 packedLikeOriginal = VectorToColorLikeOriginal(tangentSpaceVectorLikeOriginal, alphaLikeOriginal ? (byte)0 : (byte)255);
            return new Vector4(
                packedLikeOriginal.r / 255.0f,
                packedLikeOriginal.g / 255.0f,
                packedLikeOriginal.b / 255.0f,
                packedLikeOriginal.a / 255.0f);
        }

        private static uint[] BuildMeshVertexMappingCodesLikeOriginal(ParsedMap map, GroundTextureCatalog catalog, GroundRuntimeConfig runtimeCfg)
        {
            if (map == null || map.MeshVertices == null || map.MeshVertices.Length == 0)
                return null;

            uint[] codesLikeOriginal = new uint[map.MeshVertices.Length];
            for (int i = 0; i < map.MeshVertices.Length; i++)
            {
                int vertexFactureLikeOriginal = GetMeshVertexFactureLikeOriginal(map, i);
                MeshMapperStateLikeOriginal mapperLikeOriginal = BuildMeshMapperStateLikeOriginal(catalog, runtimeCfg, vertexFactureLikeOriginal);
                Vector3 originalPosLikeOriginal = GetMeshVertexPlanarHeightLikeOriginal(map, i);
                Vector3 originalNormalLikeOriginal = GetMeshVertexOriginalNormalLikeOriginal(map, i);
                codesLikeOriginal[i] = GetMeshMappingCodeLikeOriginal(mapperLikeOriginal, originalPosLikeOriginal, originalNormalLikeOriginal);
            }

            return codesLikeOriginal;
        }

        private static MeshQuadSystemLikeOriginal BuildMeshQuadSystemLikeOriginal(ParsedMap map)
        {
            if (map == null || map.MeshVertices == null || map.MeshVertices.Length == 0 || map.MeshIndices == null || map.MeshIndices.Length < 3)
                return null;

            const int D = 128;
            Vector3 v0Planar = GetMeshVertexPlanarHeightLikeOriginal(map, 0);
            int minX = (int)v0Planar.x;
            int maxX = (int)v0Planar.x;
            int minY = (int)v0Planar.y;
            int maxY = (int)v0Planar.y;
            for (int i = 1; i < map.MeshVertices.Length; i++)
            {
                Vector3 v = GetMeshVertexPlanarHeightLikeOriginal(map, i);
                int vx = (int)v.x;
                int vy = (int)v.y;
                if (vx < minX) minX = vx;
                if (vx > maxX) maxX = vx;
                if (vy < minY) minY = vy;
                if (vy > maxY) maxY = vy;
            }

            int dx = maxX - minX + 1;
            int dy = maxY - minY + 1;
            int quadsNx = dx / D;
            int quadsNy = dy / D;
            if (quadsNx * D < dx) quadsNx++;
            if (quadsNy * D < dy) quadsNy++;
            quadsNx = Mathf.Max(1, quadsNx);
            quadsNy = Mathf.Max(1, quadsNy);

            var quadSystem = new MeshQuadSystemLikeOriginal
            {
                QuadLx = D,
                QuadLy = D,
                QuadX0 = minX,
                QuadY0 = minY,
                QuadsNx = quadsNx,
                QuadsNy = quadsNy,
                UmlX = quadsNx * D,
                UmlY = quadsNy * D,
                TrianglesByQuad = new List<int>[quadsNx * quadsNy]
            };
            for (int i = 0; i < quadSystem.TrianglesByQuad.Length; i++)
                quadSystem.TrianglesByQuad[i] = new List<int>();

            int triCount = map.MeshIndices.Length / 3;
            for (int tri = 0; tri < triCount; tri++)
            {
                int i0 = map.MeshIndices[tri * 3 + 0];
                int i1 = map.MeshIndices[tri * 3 + 1];
                int i2 = map.MeshIndices[tri * 3 + 2];
                if (i0 < 0 || i1 < 0 || i2 < 0 || i0 >= map.MeshVertices.Length || i1 >= map.MeshVertices.Length || i2 >= map.MeshVertices.Length)
                    continue;

                Vector3 v0 = GetMeshVertexPlanarHeightLikeOriginal(map, i0);
                Vector3 v1 = GetMeshVertexPlanarHeightLikeOriginal(map, i1);
                Vector3 v2 = GetMeshVertexPlanarHeightLikeOriginal(map, i2);
                int cx = ((int)v0.x + (int)v1.x + (int)v2.x) / 3;
                int cy = ((int)v0.y + (int)v1.y + (int)v2.y) / 3;
                int qx = (cx - quadSystem.QuadX0) / quadSystem.QuadLx;
                int qy = (cy - quadSystem.QuadY0) / quadSystem.QuadLy;
                if (qx < 0 || qx >= quadSystem.QuadsNx || qy < 0 || qy >= quadSystem.QuadsNy)
                    continue;
                quadSystem.TrianglesByQuad[quadSystem.QuadsNx * qy + qx].Add(tri);
            }

            return quadSystem;
        }

        private static bool TryZXTriLikeOriginal(out float z, Vector3 triA, Vector3 triB, Vector3 triC)
        {
            z = 0.0f;
            Vector3[] v = { triA, triB, triC };
            int xmin = (int)v[0].x;
            int xmax = (int)v[0].x;
            int ymin = (int)v[0].y;
            int ymax = (int)v[0].y;
            for (int i = 1; i < 3; i++)
            {
                int vx = (int)v[i].x;
                int vy = (int)v[i].y;
                if (xmin > vx) xmin = vx;
                if (ymin > vy) ymin = vy;
                if (xmax < vx) xmax = vx;
                if (ymax < vy) ymax = vy;
            }

            if (xmin == 0) { v[0].x--; v[1].x--; v[2].x--; xmin--; xmax--; }
            if (ymin == 0) { v[0].y--; v[1].y--; v[2].y--; ymin--; ymax--; }
            if (xmax == 0) { v[0].x++; v[1].x++; v[2].x++; xmax++; xmin++; }
            if (ymax == 0) { v[0].y++; v[1].y++; v[2].y++; ymax++; ymin++; }
            if (xmin > 0 || xmax < 0 || ymin > 0 || ymax < 0)
                return false;

            int nhor = 0;
            float[] xs = new float[4];
            float[] zs = new float[4];
            for (int i = 0; i < 3; i++)
            {
                int next = i + 1;
                if (next >= 3) next = 0;
                float y1 = v[i].y;
                float y2 = v[next].y;
                if (((0.0f >= y1) && (0.0f < y2)) || ((0.0f <= y1) && (0.0f > y2)))
                {
                    xs[nhor] = v[i].x - (v[next].x - v[i].x) * y1 / (y2 - y1);
                    zs[nhor] = v[i].z - (v[next].z - v[i].z) * y1 / (y2 - y1);
                    nhor++;
                }
            }

            if (nhor != 2)
                return false;
            if (xs[1] == xs[0])
            {
                if (xs[1] == 0.0f)
                {
                    z = 0.5f * (zs[0] + zs[1]);
                    return true;
                }
                return false;
            }
            if (((xs[0] <= 0.0f) && (xs[1] >= 0.0f)) || ((xs[0] >= 0.0f) && (xs[1] <= 0.0f)))
            {
                z = zs[0] - xs[0] * (zs[1] - zs[0]) / (xs[1] - xs[0]);
                return true;
            }
            return false;
        }

        private static void SupplementMeshSurfaceHeightMapInRectLikeOriginal(short[] heights, ParsedMap map, MeshQuadSystemLikeOriginal quadSystem, int x0, int y0, int x1, int y1)
        {
            if (heights == null || map == null || quadSystem == null)
                return;

            const float notIntersected = -9999.99f;
            List<int>[] quads = quadSystem.TrianglesByQuad;
            for (int ny = 0; ny < map.MaxTH; ny++)
            {
                for (int nx = 0; nx < map.VertInLine; nx++)
                {
                    int x = nx << 5;
                    int y = ny << 5;
                    int t = (nx >> 1) << 1;
                    if (t != nx)
                        y -= 16;
                    if (x < x0 || x > x1 || y < y0 || y > y1)
                        continue;
                    if (x < quadSystem.QuadX0 || x >= quadSystem.QuadX0 + quadSystem.UmlX || y < quadSystem.QuadY0 || y >= quadSystem.QuadY0 + quadSystem.UmlY)
                        continue;

                    int nqx = (x - quadSystem.QuadX0) / quadSystem.QuadLx;
                    int nqy = (y - quadSystem.QuadY0) / quadSystem.QuadLy;
                    List<int>[] candidateQuads = { null, null, null, null };
                    candidateQuads[0] = quads[nqx + quadSystem.QuadsNx * nqy];

                    int X = nqx * quadSystem.QuadLx + quadSystem.QuadX0;
                    int Y = nqy * quadSystem.QuadLy + quadSystem.QuadY0;
                    int dx = x - X;
                    int dy = y - Y;
                    bool right = dx >= (quadSystem.QuadLx >> 1);
                    bool top = dy < (quadSystem.QuadLy >> 1);
                    int subQuad = 0;
                    if (!right && top) subQuad = 0;
                    if (!right && !top) subQuad = 2;
                    if (right && top) subQuad = 1;
                    if (right && !top) subQuad = 3;

                    if (!right)
                    {
                        if (nqx >= 1) candidateQuads[1] = quads[(nqx - 1) + quadSystem.QuadsNx * nqy];
                    }
                    else
                    {
                        if (nqx < quadSystem.QuadsNx - 1) candidateQuads[1] = quads[(nqx + 1) + quadSystem.QuadsNx * nqy];
                    }
                    if (top)
                    {
                        if (nqy >= 1) candidateQuads[2] = quads[nqx + quadSystem.QuadsNx * (nqy - 1)];
                    }
                    else
                    {
                        if (nqy < quadSystem.QuadsNy - 1) candidateQuads[2] = quads[nqx + quadSystem.QuadsNx * (nqy + 1)];
                    }
                    if (candidateQuads[1] != null && candidateQuads[2] != null)
                    {
                        switch (subQuad)
                        {
                            case 0:
                                if (nqx >= 1 && nqy >= 1) candidateQuads[3] = quads[(nqx - 1) + quadSystem.QuadsNx * (nqy - 1)];
                                break;
                            case 1:
                                if (nqx < quadSystem.QuadsNx - 1 && nqy >= 1) candidateQuads[3] = quads[(nqx + 1) + quadSystem.QuadsNx * (nqy - 1)];
                                break;
                            case 2:
                                if (nqx >= 1 && nqy < quadSystem.QuadsNy - 1) candidateQuads[3] = quads[(nqx - 1) + quadSystem.QuadsNx * (nqy + 1)];
                                break;
                            case 3:
                                if (nqx < quadSystem.QuadsNx - 1 && nqy < quadSystem.QuadsNy - 1) candidateQuads[3] = quads[(nqx + 1) + quadSystem.QuadsNx * (nqy + 1)];
                                break;
                        }
                    }

                    for (int qi = 0; qi < 4; qi++)
                    {
                        List<int> triList = candidateQuads[qi];
                        if (triList == null)
                            continue;

                        float bestZ = notIntersected;
                        for (int n = 0; n < triList.Count; n++)
                        {
                            int tri = triList[n];
                            int i0 = map.MeshIndices[tri * 3 + 0];
                            int i1 = map.MeshIndices[tri * 3 + 1];
                            int i2 = map.MeshIndices[tri * 3 + 2];
                            if (i0 < 0 || i1 < 0 || i2 < 0 || i0 >= map.MeshVertices.Length || i1 >= map.MeshVertices.Length || i2 >= map.MeshVertices.Length)
                                continue;

                            Vector3 v0 = GetMeshVertexPlanarHeightLikeOriginal(map, i0);
                            Vector3 v1 = GetMeshVertexPlanarHeightLikeOriginal(map, i1);
                            Vector3 v2 = GetMeshVertexPlanarHeightLikeOriginal(map, i2);
                            if (TryZXTriLikeOriginal(out float z, new Vector3(v0.x - x, v0.y - y, v0.z), new Vector3(v1.x - x, v1.y - y, v1.z), new Vector3(v2.x - x, v2.y - y, v2.z)) && z > bestZ)
                                bestZ = z;
                        }

                        if (bestZ > notIntersected)
                        {
                            heights[nx + map.VertInLine * ny] = (short)bestZ;
                            break;
                        }
                    }
                }
            }
        }

        private static short[] BuildMeshSurfaceHeightMapLikeOriginal(ParsedMap map, MeshQuadSystemLikeOriginal quadSystem)
        {
            if (map == null || quadSystem == null || map.VertInLine <= 0 || map.MaxTH <= 0)
                return null;

            short[] heights = new short[map.VertInLine * map.MaxTH];
            SupplementMeshSurfaceHeightMapInRectLikeOriginal(
                heights,
                map,
                quadSystem,
                quadSystem.QuadX0,
                quadSystem.QuadY0,
                quadSystem.QuadX0 + quadSystem.UmlX - 1,
                quadSystem.QuadY0 + quadSystem.UmlY - 1);
            return heights;
        }

        private static void EnsureMeshSurfaceSupportLikeOriginal(ParsedMap map)
        {
            if (map == null || !map.IsMeshSurface || map.MeshVertices == null || map.MeshVertices.Length == 0 || map.MeshIndices == null || map.MeshIndices.Length < 3)
                return;

            map.MeshQuadSystem ??= BuildMeshQuadSystemLikeOriginal(map);
            if (map.Heights == null || map.Heights.Length == 0)
                map.Heights = BuildMeshSurfaceHeightMapLikeOriginal(map, map.MeshQuadSystem);
            if (map.Heights != null && map.Heights.Length > 0)
                map.Options = BuildOriginalGroundOptions(map);
            EnsureMapXyShiftLikeOriginal(map);
        }

        private static Vector3 ConvertOriginalMeshVertexToWorldLikeOriginal(Vector3 originalPosLikeOriginal)
        {
            return new Vector3(originalPosLikeOriginal.x * HorizontalScale, originalPosLikeOriginal.y * VerticalScale, originalPosLikeOriginal.z * HorizontalScale * WorldZSign);
        }

        private static Vector3 GetMeshVertexWorldPosLikeOriginal(ParsedMap map, int index)
        {
            return ConvertOriginalMeshVertexToWorldLikeOriginal(GetMeshVertexPlanarHeightLikeOriginal(map, index));
        }

        private static void GetMeshSurfaceUvRectLikeOriginal(ParsedMap map, out float minX, out float maxX, out float minZ, out float maxZ)
        {
            minX = 0.0f;
            maxX = 1.0f;
            minZ = 0.0f;
            maxZ = 1.0f;
            if (map == null || map.MeshVertices == null || map.MeshVertices.Length == 0)
                return;

            minX = map.MeshVertices.Min(v => v.x);
            maxX = map.MeshVertices.Max(v => v.x);
            minZ = map.MeshVertices.Min(v => v.z);
            maxZ = map.MeshVertices.Max(v => v.z);
            if (Math.Abs(maxX - minX) < 0.001f) maxX = minX + 1.0f;
            if (Math.Abs(maxZ - minZ) < 0.001f) maxZ = minZ + 1.0f;
        }


        private static Mesh BuildMeshSurfaceFactureSplitMeshLikeOriginal(ParsedMap map, GroundTextureCatalog catalog, GroundRuntimeConfig runtimeCfg, int quadIndex, int factureLikeOriginal, List<MeshTriangleBatchRefLikeOriginal> triangleRefsLikeOriginal, float minX, float maxX, float minZ, float maxZ, out int emittedTriCountLikeOriginal)
        {
            emittedTriCountLikeOriginal = 0;
            if (map == null || map.MeshVertices == null || map.MeshVertices.Length == 0 || map.MeshIndices == null || map.MeshIndices.Length < 3 || triangleRefsLikeOriginal == null || triangleRefsLikeOriginal.Count == 0)
                return null;

            MeshMapperStateLikeOriginal batchMapperLikeOriginal = BuildMeshMapperStateLikeOriginal(catalog, runtimeCfg, factureLikeOriginal);
            uint[] mappingCodesLikeOriginal = BuildMeshVertexMappingCodesLikeOriginal(map, catalog, runtimeCfg);

            var remapLikeOriginal = new Dictionary<ulong, int>();
            var verticesLikeOriginal = new List<Vector3>(triangleRefsLikeOriginal.Count * 3);
            var uvLikeOriginal = new List<Vector2>(triangleRefsLikeOriginal.Count * 3);
            List<Color32> colorsLikeOriginal = new List<Color32>(triangleRefsLikeOriginal.Count * 3);
            List<Vector3> normalsLikeOriginal = new List<Vector3>(triangleRefsLikeOriginal.Count * 3);
            List<Vector4> tangentsLikeOriginal = new List<Vector4>(triangleRefsLikeOriginal.Count * 3);
            List<Vector4> specularPayloadLikeOriginal = new List<Vector4>(triangleRefsLikeOriginal.Count * 3);
            var indicesLikeOriginal = new List<int>(triangleRefsLikeOriginal.Count * 3);

            int GetOrAddVertex(int originalIndexLikeOriginal, uint mappingCodeLikeOriginal, bool alphaLikeOriginal)
            {
                ulong keyLikeOriginal = ((ulong)mappingCodeLikeOriginal << 32) ^ ((ulong)(uint)originalIndexLikeOriginal << 1) ^ (alphaLikeOriginal ? 1UL : 0UL);
                if (remapLikeOriginal.TryGetValue(keyLikeOriginal, out int localIndexLikeOriginal))
                    return localIndexLikeOriginal;

                localIndexLikeOriginal = verticesLikeOriginal.Count;
                remapLikeOriginal.Add(keyLikeOriginal, localIndexLikeOriginal);

                Vector3 originalPosLikeOriginal = GetMeshVertexPlanarHeightLikeOriginal(map, originalIndexLikeOriginal);
                Vector3 originalNormalLikeOriginal = GetMeshVertexOriginalNormalLikeOriginal(map, originalIndexLikeOriginal);

                verticesLikeOriginal.Add(GetMeshVertexWorldPosLikeOriginal(map, originalIndexLikeOriginal));
                uvLikeOriginal.Add(GetMeshMappingUvLikeOriginal(batchMapperLikeOriginal, originalPosLikeOriginal, originalNormalLikeOriginal, mappingCodeLikeOriginal));
                colorsLikeOriginal.Add(BuildMeshFactureDiffuseColorLikeOriginal(map, originalIndexLikeOriginal, alphaLikeOriginal));
                normalsLikeOriginal.Add(GetWorldNormalFromOriginalLikeOriginal(originalNormalLikeOriginal));
                tangentsLikeOriginal.Add(BuildMeshTangentLikeOriginal(originalNormalLikeOriginal));
                specularPayloadLikeOriginal.Add(BuildMeshFactureSpecularPayloadLikeOriginal(map, originalIndexLikeOriginal, alphaLikeOriginal));

                return localIndexLikeOriginal;
            }

            for (int i = 0; i < triangleRefsLikeOriginal.Count; i++)
            {
                MeshTriangleBatchRefLikeOriginal triRefLikeOriginal = triangleRefsLikeOriginal[i];
                if (triRefLikeOriginal == null)
                    continue;

                int src = triRefLikeOriginal.TriangleIndex * 3;
                if (src < 0 || src + 2 >= map.MeshIndices.Length)
                    continue;

                int i0 = map.MeshIndices[src + 0];
                int i1 = map.MeshIndices[src + 1];
                int i2 = map.MeshIndices[src + 2];
                if (i0 < 0 || i1 < 0 || i2 < 0 || i0 >= map.MeshVertices.Length || i1 >= map.MeshVertices.Length || i2 >= map.MeshVertices.Length)
                    continue;

                bool a0 = triRefLikeOriginal.Transitive && GetMeshVertexFactureLikeOriginal(map, i0) != factureLikeOriginal;
                bool a1 = triRefLikeOriginal.Transitive && GetMeshVertexFactureLikeOriginal(map, i1) != factureLikeOriginal;
                bool a2 = triRefLikeOriginal.Transitive && GetMeshVertexFactureLikeOriginal(map, i2) != factureLikeOriginal;

                uint mappingCodeLikeOriginal = mappingCodesLikeOriginal != null && i0 >= 0 && i0 < mappingCodesLikeOriginal.Length
                    ? mappingCodesLikeOriginal[i0]
                    : 0u;

                int l0 = GetOrAddVertex(i0, mappingCodeLikeOriginal, a0);
                int l1 = GetOrAddVertex(i1, mappingCodeLikeOriginal, a1);
                int l2 = GetOrAddVertex(i2, mappingCodeLikeOriginal, a2);

                indicesLikeOriginal.Add(l0);
                indicesLikeOriginal.Add(l2);
                indicesLikeOriginal.Add(l1);
                emittedTriCountLikeOriginal++;
            }

            if (emittedTriCountLikeOriginal <= 0 || verticesLikeOriginal.Count == 0)
                return null;

            var meshLikeOriginal = new Mesh();
            meshLikeOriginal.name = $"C2_HSEMQuadFactureChunk_{quadIndex:D4}_F{factureLikeOriginal:D3}";
            meshLikeOriginal.indexFormat = IndexFormat.UInt32;
            meshLikeOriginal.SetVertices(verticesLikeOriginal);
            meshLikeOriginal.SetTriangles(indicesLikeOriginal, 0, true);
            meshLikeOriginal.SetUVs(0, uvLikeOriginal);
            if (specularPayloadLikeOriginal.Count == verticesLikeOriginal.Count)
                meshLikeOriginal.SetUVs(1, specularPayloadLikeOriginal);
            if (colorsLikeOriginal.Count == verticesLikeOriginal.Count)
                meshLikeOriginal.SetColors(colorsLikeOriginal);
            if (normalsLikeOriginal.Count == verticesLikeOriginal.Count)
                meshLikeOriginal.SetNormals(normalsLikeOriginal);
            else
                meshLikeOriginal.RecalculateNormals();
            if (tangentsLikeOriginal.Count == verticesLikeOriginal.Count)
                meshLikeOriginal.SetTangents(tangentsLikeOriginal);
            meshLikeOriginal.RecalculateBounds();
            return meshLikeOriginal;
        }

        private static MeshQuadRenderBatchLikeOriginal[] BuildMeshSurfaceQuadFactureSplitRenderBatchesLikeOriginal(ParsedMap map, GroundTextureCatalog catalog, GroundRuntimeConfig runtimeCfg, out int batchRenderCountLikeOriginal, out int batchRenderTriangleCountLikeOriginal)
        {
            batchRenderCountLikeOriginal = 0;
            batchRenderTriangleCountLikeOriginal = 0;
            if (map == null || !map.IsMeshSurface)
                return null;

            EnsureMeshSurfaceSupportLikeOriginal(map);
            if (map.MeshQuadRenderBatches != null && map.MeshQuadRenderBatches.Length > 0)
            {
                batchRenderCountLikeOriginal = map.MeshQuadRenderBatchCount;
                batchRenderTriangleCountLikeOriginal = map.MeshQuadRenderBatchTriangleCount;
                return map.MeshQuadRenderBatches;
            }

            MeshQuadSystemLikeOriginal quadSystem = map.MeshQuadSystem;
            if (quadSystem == null || quadSystem.TrianglesByQuad == null || quadSystem.TrianglesByQuad.Length == 0)
                return null;

            GetMeshSurfaceUvRectLikeOriginal(map, out float minX, out float maxX, out float minZ, out float maxZ);
            var batchesLikeOriginal = new List<MeshQuadRenderBatchLikeOriginal>();

            for (int quadIndex = 0; quadIndex < quadSystem.TrianglesByQuad.Length; quadIndex++)
            {
                List<int> quadTrianglesLikeOriginal = quadSystem.TrianglesByQuad[quadIndex];
                if (quadTrianglesLikeOriginal == null || quadTrianglesLikeOriginal.Count == 0)
                    continue;

                var factureTrianglesLikeOriginal = new Dictionary<int, List<MeshTriangleBatchRefLikeOriginal>>();

                void AddFactureTriangle(int factureLikeOriginal, int triangleIndexLikeOriginal, bool transitiveLikeOriginal)
                {
                    if (!factureTrianglesLikeOriginal.TryGetValue(factureLikeOriginal, out List<MeshTriangleBatchRefLikeOriginal> listLikeOriginal))
                    {
                        listLikeOriginal = new List<MeshTriangleBatchRefLikeOriginal>();
                        factureTrianglesLikeOriginal.Add(factureLikeOriginal, listLikeOriginal);
                    }

                    listLikeOriginal.Add(new MeshTriangleBatchRefLikeOriginal
                    {
                        TriangleIndex = triangleIndexLikeOriginal,
                        Transitive = transitiveLikeOriginal
                    });
                }

                for (int i = 0; i < quadTrianglesLikeOriginal.Count; i++)
                {
                    int triLikeOriginal = quadTrianglesLikeOriginal[i];
                    int src = triLikeOriginal * 3;
                    if (src < 0 || src + 2 >= map.MeshIndices.Length)
                        continue;

                    int i0 = map.MeshIndices[src + 0];
                    int i1 = map.MeshIndices[src + 1];
                    int i2 = map.MeshIndices[src + 2];
                    if (i0 < 0 || i1 < 0 || i2 < 0 || i0 >= map.MeshVertices.Length || i1 >= map.MeshVertices.Length || i2 >= map.MeshVertices.Length)
                        continue;

                    int n0 = GetMeshVertexFactureLikeOriginal(map, i0);
                    int n1 = GetMeshVertexFactureLikeOriginal(map, i1);
                    int n2 = GetMeshVertexFactureLikeOriginal(map, i2);

                    if (n0 == n1 && n0 == n2)
                    {
                        AddFactureTriangle(n0, triLikeOriginal, false);
                    }
                    else
                    {
                        int nmin = Math.Min(n0, Math.Min(n1, n2));
                        int nmax = Math.Max(n0, Math.Max(n1, n2));
                        AddFactureTriangle(nmin, triLikeOriginal, false);
                        AddFactureTriangle(nmax, triLikeOriginal, true);

                        int nmed = nmin;
                        if (n0 != nmin && n0 != nmax) nmed = n0;
                        if (n1 != nmin && n1 != nmax) nmed = n1;
                        if (n2 != nmin && n2 != nmax) nmed = n2;
                        if (nmed != nmin)
                            AddFactureTriangle(nmed, triLikeOriginal, true);
                    }
                }

                foreach (KeyValuePair<int, List<MeshTriangleBatchRefLikeOriginal>> kv in factureTrianglesLikeOriginal.OrderBy(k => k.Key))
                {
                    Mesh splitMeshLikeOriginal = BuildMeshSurfaceFactureSplitMeshLikeOriginal(
                        map,
                        catalog,
                        runtimeCfg,
                        quadIndex,
                        kv.Key,
                        kv.Value,
                        minX,
                        maxX,
                        minZ,
                        maxZ,
                        out int emittedTriCountLikeOriginal);

                    if (splitMeshLikeOriginal == null || emittedTriCountLikeOriginal <= 0)
                        continue;

                    batchesLikeOriginal.Add(new MeshQuadRenderBatchLikeOriginal
                    {
                        Mesh = splitMeshLikeOriginal,
                        QuadIndex = quadIndex,
                        Facture = kv.Key,
                        TriangleCount = emittedTriCountLikeOriginal
                    });

                    batchRenderCountLikeOriginal++;
                    batchRenderTriangleCountLikeOriginal += emittedTriCountLikeOriginal;
                }
            }

            if (batchesLikeOriginal.Count == 0)
                return null;

            map.MeshQuadRenderBatches = batchesLikeOriginal.ToArray();
            map.MeshQuadRenderBatchCount = batchRenderCountLikeOriginal;
            map.MeshQuadRenderBatchTriangleCount = batchRenderTriangleCountLikeOriginal;
            return map.MeshQuadRenderBatches;
        }

        private static Mesh BuildMeshSurfaceQuadChunkMeshLikeOriginal(ParsedMap map, int quadIndex, List<int> triangleRefsLikeOriginal, float minX, float maxX, float minZ, float maxZ, out int emittedTriCountLikeOriginal)
        {
            emittedTriCountLikeOriginal = 0;
            if (map == null || map.MeshVertices == null || map.MeshVertices.Length == 0 || map.MeshIndices == null || map.MeshIndices.Length < 3 || triangleRefsLikeOriginal == null || triangleRefsLikeOriginal.Count == 0)
                return null;

            var remapLikeOriginal = new Dictionary<int, int>();
            var verticesLikeOriginal = new List<Vector3>(triangleRefsLikeOriginal.Count * 3);
            var uvLikeOriginal = new List<Vector2>(triangleRefsLikeOriginal.Count * 3);
            List<Color32> colorsLikeOriginal = map.MeshColors != null && map.MeshColors.Length == map.MeshVertices.Length
                ? new List<Color32>(triangleRefsLikeOriginal.Count * 3)
                : null;
            List<Vector3> normalsLikeOriginal = map.MeshNormals != null && map.MeshNormals.Length == map.MeshVertices.Length
                ? new List<Vector3>(triangleRefsLikeOriginal.Count * 3)
                : null;
            var indicesLikeOriginal = new List<int>(triangleRefsLikeOriginal.Count * 3);

            int GetOrAddVertex(int originalIndexLikeOriginal)
            {
                if (remapLikeOriginal.TryGetValue(originalIndexLikeOriginal, out int localIndexLikeOriginal))
                    return localIndexLikeOriginal;

                localIndexLikeOriginal = verticesLikeOriginal.Count;
                remapLikeOriginal.Add(originalIndexLikeOriginal, localIndexLikeOriginal);

                Vector3 v = map.MeshVertices[originalIndexLikeOriginal];
                verticesLikeOriginal.Add(GetMeshVertexWorldPosLikeOriginal(map, originalIndexLikeOriginal));
                uvLikeOriginal.Add(new Vector2((v.x - minX) / (maxX - minX), (v.z - minZ) / (maxZ - minZ)));
                if (colorsLikeOriginal != null)
                    colorsLikeOriginal.Add(map.MeshColors[originalIndexLikeOriginal]);
                if (normalsLikeOriginal != null)
                {
                    Vector3 n = map.MeshNormals[originalIndexLikeOriginal];
                    normalsLikeOriginal.Add(new Vector3(n.x, n.y, n.z * WorldZSign).normalized);
                }

                return localIndexLikeOriginal;
            }

            for (int i = 0; i < triangleRefsLikeOriginal.Count; i++)
            {
                int triLikeOriginal = triangleRefsLikeOriginal[i];
                int src = triLikeOriginal * 3;
                if (src < 0 || src + 2 >= map.MeshIndices.Length)
                    continue;

                int i0 = map.MeshIndices[src + 0];
                int i1 = map.MeshIndices[src + 1];
                int i2 = map.MeshIndices[src + 2];
                if (i0 < 0 || i1 < 0 || i2 < 0 || i0 >= map.MeshVertices.Length || i1 >= map.MeshVertices.Length || i2 >= map.MeshVertices.Length)
                    continue;

                int l0 = GetOrAddVertex(i0);
                int l1 = GetOrAddVertex(i1);
                int l2 = GetOrAddVertex(i2);

                // Keep the same mirrored winding used by the whole-mesh fallback path.
                indicesLikeOriginal.Add(l0);
                indicesLikeOriginal.Add(l2);
                indicesLikeOriginal.Add(l1);
                emittedTriCountLikeOriginal++;
            }

            if (emittedTriCountLikeOriginal <= 0 || verticesLikeOriginal.Count == 0)
                return null;

            var meshLikeOriginal = new Mesh();
            meshLikeOriginal.name = $"C2_HSEMQuadChunk_{quadIndex:D4}";
            meshLikeOriginal.indexFormat = IndexFormat.UInt32;
            meshLikeOriginal.SetVertices(verticesLikeOriginal);
            meshLikeOriginal.SetTriangles(indicesLikeOriginal, 0, true);
            meshLikeOriginal.SetUVs(0, uvLikeOriginal);
            if (colorsLikeOriginal != null && colorsLikeOriginal.Count == verticesLikeOriginal.Count)
                meshLikeOriginal.SetColors(colorsLikeOriginal);
            if (normalsLikeOriginal != null && normalsLikeOriginal.Count == verticesLikeOriginal.Count)
                meshLikeOriginal.SetNormals(normalsLikeOriginal);
            else
                meshLikeOriginal.RecalculateNormals();
            meshLikeOriginal.RecalculateBounds();
            return meshLikeOriginal;
        }

        private static Mesh[] BuildMeshSurfaceQuadChunkMeshesLikeOriginal(ParsedMap map, out int quadRenderCountLikeOriginal, out int quadRenderTriangleCountLikeOriginal)
        {
            quadRenderCountLikeOriginal = 0;
            quadRenderTriangleCountLikeOriginal = 0;
            if (map == null || !map.IsMeshSurface)
                return null;

            EnsureMeshSurfaceSupportLikeOriginal(map);
            if (map.MeshQuadRenderMeshes != null && map.MeshQuadRenderMeshes.Length > 0)
            {
                quadRenderCountLikeOriginal = map.MeshQuadRenderCount;
                quadRenderTriangleCountLikeOriginal = map.MeshQuadRenderTriangleCount;
                return map.MeshQuadRenderMeshes;
            }

            MeshQuadSystemLikeOriginal quadSystem = map.MeshQuadSystem;
            if (quadSystem == null || quadSystem.TrianglesByQuad == null || quadSystem.TrianglesByQuad.Length == 0)
                return null;

            GetMeshSurfaceUvRectLikeOriginal(map, out float minX, out float maxX, out float minZ, out float maxZ);
            var meshesLikeOriginal = new Mesh[quadSystem.TrianglesByQuad.Length];
            int emittedChunksLikeOriginal = 0;
            int emittedTrianglesLikeOriginal = 0;

            for (int quadIndex = 0; quadIndex < quadSystem.TrianglesByQuad.Length; quadIndex++)
            {
                Mesh chunkMeshLikeOriginal = BuildMeshSurfaceQuadChunkMeshLikeOriginal(
                    map,
                    quadIndex,
                    quadSystem.TrianglesByQuad[quadIndex],
                    minX,
                    maxX,
                    minZ,
                    maxZ,
                    out int triCountLikeOriginal);

                meshesLikeOriginal[quadIndex] = chunkMeshLikeOriginal;
                if (chunkMeshLikeOriginal != null)
                {
                    emittedChunksLikeOriginal++;
                    emittedTrianglesLikeOriginal += triCountLikeOriginal;
                }
            }

            map.MeshQuadRenderMeshes = meshesLikeOriginal;
            map.MeshQuadRenderCount = emittedChunksLikeOriginal;
            map.MeshQuadRenderTriangleCount = emittedTrianglesLikeOriginal;

            quadRenderCountLikeOriginal = emittedChunksLikeOriginal;
            quadRenderTriangleCountLikeOriginal = emittedTrianglesLikeOriginal;
            return meshesLikeOriginal;
        }

        private static Mesh BuildMeshSurface(ParsedMap map)
        {
            var vertices = new Vector3[map.MeshVertices.Length];
            var uv = new Vector2[map.MeshVertices.Length];

            GetMeshSurfaceUvRectLikeOriginal(map, out float minX, out float maxX, out float minZ, out float maxZ);

            var normals = ((map.MeshNormalsOriginal != null && map.MeshNormalsOriginal.Length == map.MeshVertices.Length) || (map.MeshNormals != null && map.MeshNormals.Length == map.MeshVertices.Length)) ? new Vector3[map.MeshVertices.Length] : null;
            for (int i = 0; i < map.MeshVertices.Length; i++)
            {
                Vector3 v = map.MeshVertices[i];
                vertices[i] = GetMeshVertexWorldPosLikeOriginal(map, i);
                uv[i] = new Vector2((v.x - minX) / (maxX - minX), (v.z - minZ) / (maxZ - minZ));
                if (normals != null)
                    normals[i] = GetWorldNormalFromOriginalLikeOriginal(GetMeshVertexOriginalNormalLikeOriginal(map, i));
            }

            int[] sourceIndicesLikeOriginal = map.MeshIndicesOriginal != null && map.MeshIndicesOriginal.Length == map.MeshIndices.Length ? map.MeshIndicesOriginal : map.MeshIndices;
            int[] mirroredIndices = new int[sourceIndicesLikeOriginal.Length];
            for (int i = 0; i + 2 < sourceIndicesLikeOriginal.Length; i += 3)
            {
                mirroredIndices[i + 0] = sourceIndicesLikeOriginal[i + 0];
                mirroredIndices[i + 1] = sourceIndicesLikeOriginal[i + 2];
                mirroredIndices[i + 2] = sourceIndicesLikeOriginal[i + 1];
            }

            var mesh = new Mesh();
            mesh.name = "C2_NewTerrainMeshLikeOriginal";
            mesh.indexFormat = IndexFormat.UInt32;
            mesh.vertices = vertices;
            mesh.triangles = mirroredIndices;
            mesh.uv = uv;
            if (map.MeshColors != null && map.MeshColors.Length == map.MeshVertices.Length)
                mesh.colors32 = map.MeshColors;
            if (normals != null)
                mesh.normals = normals;
            else
                mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static void AddTri(List<int> tris, int a, int b, int c)
        {
            tris.Add(a); tris.Add(c); tris.Add(b);
        }

        private static bool TryParseMap(Cossacks2Bridge.Core.CoreFileSystem fs, string relativePath, out ParsedMap map, out string error)
        {
            map = null;
            error = "";
            string mapId = Path.GetFileNameWithoutExtension(relativePath ?? string.Empty);

            if (fs == null)
            {
                error = "CoreFileSystem == null";
                return false;
            }

            if (string.IsNullOrWhiteSpace(relativePath))
            {
                error = "relativePath is empty";
                return false;
            }

            if (!fs.Exists(relativePath))
            {
                error = "Файл не найден: " + relativePath;
                return false;
            }

            byte[] raw = fs.ReadAllBytes(relativePath);
            if (raw == null || raw.Length == 0)
            {
                error = "Файл пустой: " + relativePath;
                return false;
            }

            byte[] data = MaybeDecompressM3d(raw, out bool wasCompressed, out string decompressError);
            if (data == null || data.Length < 12)
            {
                error = "Не удалось распаковать .m3d: " + decompressError;
                return false;
            }

            using (var ms = new MemoryStream(data))
            using (var br = new BinaryReader(ms))
            {
                string magic = ReadTag(br);
                if (!IsSupportedMapMagic(magic))
                {
                    error = "Неожиданный magic: " + magic + (wasCompressed ? " (после распаковки)" : "");
                    return false;
                }

                if (!TryGetAddshFromMapMagic(magic, out int addsh))
                {
                    error = "Не удалось определить ADDSH из заголовка карты: " + magic;
                    return false;
                }

                int storedVertInLine = br.ReadInt32();
                int storedMaxTH = br.ReadInt32();

                map = new ParsedMap
                {
                    SourcePath = relativePath,
                    HeaderMagic = magic,
                    HeaderStoredVertInLine = storedVertInLine,
                    HeaderStoredMaxTH = storedMaxTH,
                    Addsh = addsh
                };
                EnsureRoadRuntimeDescriptorsLikeOriginal(fs, map);
                ResetGlobalTerrainRuntimeStateLikeOriginal();
                ApplyOriginalHeaderSetupArraysLikeOriginal(map);
                EnsureMapXyShiftLikeOriginal(map);

                if (map.HeaderStoredVertInLine != map.VertInLine || map.HeaderStoredMaxTH != map.MaxTH)
                {
                    Debug.LogWarning("[C2:MAP] header/setupArrays mismatch " + BuildHeaderSetupArraysDiagnostics(map));
                }
                else
                {
                    Debug.Log("[C2:MAP] header/setupArrays " + BuildHeaderSetupArraysDiagnostics(map));
                }

                var chunkCounts = new Dictionary<string, int>(StringComparer.Ordinal);
                var chunkPayloadBytes = new Dictionary<string, int>(StringComparer.Ordinal);

                while (ms.Position + 8 <= ms.Length)
                {
                    string tag = ReadTag(br);
                    if (string.Equals(tag, "ENDM", StringComparison.Ordinal))
                    {
                        Debug.Log($"[C2:MAP] chunk ENDM at {ms.Position - 4}");
                        break;
                    }

                    int sizeField = br.ReadInt32();
                    int payloadLen = Math.Max(0, sizeField - 4);
                    long payloadStart = ms.Position;
                    long payloadEnd = payloadStart + payloadLen;

                    if (IsTplTag(tag))
                    {
                        if (TryResolveTplChunkPayloadEnd(
                            data,
                            payloadStart,
                            payloadEnd,
                            map.MaxTH,
                            out long fixedPayloadEnd,
                            out int legacyPayloadLen,
                            out bool claimedMatchesLegacy,
                            out bool claimedMatchesActual,
                            out string tplInfo))
                        {
                            payloadEnd = fixedPayloadEnd;
                            payloadLen = checked((int)(payloadEnd - payloadStart));

                            if (claimedMatchesActual)
                            {
                                Debug.Log($"[C2:MAP] {tag} payload verified: {tplInfo}");
                            }
                            else if (claimedMatchesLegacy)
                            {
                                Debug.Log($"[C2:MAP] {tag} legacy sizeField accepted: {tplInfo}");
                            }
                            else
                            {
                                Debug.LogWarning($"[C2:MAP] {tag} size mismatch: claimedPayload={sizeField - 4} legacyPayload={legacyPayloadLen} actualPayload={payloadLen}; {tplInfo}");
                            }
                        }
                        else
                        {
                            Debug.LogWarning($"[C2:MAP] {tag} topology parse failed, using sizeField path");
                        }
                    }

                    Debug.Log($"[C2:MAP] chunk {tag} sizeField={sizeField} payloadLen={payloadLen} pos={ms.Position - 8}");
                    if (chunkCounts.TryGetValue(tag, out int seenCount)) chunkCounts[tag] = seenCount + 1; else chunkCounts[tag] = 1;
                    if (chunkPayloadBytes.TryGetValue(tag, out int seenBytes)) chunkPayloadBytes[tag] = seenBytes + payloadLen; else chunkPayloadBytes[tag] = payloadLen;

                    if (payloadEnd > ms.Length)
                    {
                        error = $"Чанк {tag} выходит за пределы файла ({payloadEnd} > {ms.Length})";
                        return false;
                    }

                    switch (tag)
                    {
                        case "ZSPM":
                            if (payloadLen >= 16)
                            {
                                map.MinMapX = br.ReadInt32();
                                map.MinMapY = br.ReadInt32();
                                map.MaxMapX = br.ReadInt32();
                                map.MaxMapY = br.ReadInt32();
                                map.TileWidth = map.VertInLine;
                                map.TileHeight = map.MaxTH;
                            }
                            break;

                        case "SURF":
                            ApplySurfaceChunkLikeOriginal(map, br, payloadLen);
                            break;

                        case "TILE":
                            {
                                int expected = Math.Max(0, map.VertInLine * map.MaxTH);
                                ReadPrimaryTiles(br, payloadLen, expected, out map.TilePrimary, out map.TilePrimaryOpt);
                                map.TileWidth = map.VertInLine;
                                map.TileHeight = map.MaxTH;
                                CopyPrimaryTilesIntoOriginalStateLikeOriginal(map);
                            }
                            break;

                        case "TIL2":
                            {
                                int expected = Math.Max(0, map.VertInLine * map.MaxTH);
                                ReadSecondaryTiles(br, payloadLen, expected, out map.TileSecondary, out map.TileSecondaryOpt, out map.TileSecondaryWeight);
                            }
                            break;

                        case "FMAP":
                            {
                                int expected = Math.Max(0, map.VertInLine * map.MaxTH);
                                if (expected > 0 && payloadLen >= expected * 2)
                                {
                                    map.FactureMap = br.ReadBytes(expected);
                                    map.FactureWeight = br.ReadBytes(expected);
                                    if (payloadLen > expected * 2)
                                        br.ReadBytes(payloadLen - expected * 2);
                                }
                                else
                                {
                                    map.FactureMap = br.ReadBytes(payloadLen);
                                }

                                CopyFacturesIntoOriginalStateLikeOriginal(map);
                            }
                            break;

                        case "SEA2":
                            {
                                byte[] seaPayload = br.ReadBytes(payloadLen);
                                map.Water ??= new C2WaterData();
                                C2WaterBuilder.TryParseSea2Payload(seaPayload, map.Water, out string waterInfo);
                                map.Sea2PayloadBytes = payloadLen;
                                map.Sea2NonZeroCount = map.Water.SeaDeepNonZeroCount;
                                Debug.Log($"[C2:WATER] chunk=SEA2 selected={mapId} payload={payloadLen} " + waterInfo);
                            }
                            break;

                        case "RGBW":
                            {
                                byte[] rgbwPayload = br.ReadBytes(payloadLen);
                                map.Water ??= new C2WaterData();
                                C2WaterBuilder.TryParseRgbwPayload(rgbwPayload, map.Water, out string waterInfo);
                                Debug.Log($"[C2:WATER] chunk=RGBW selected={mapId} payload={payloadLen} " + waterInfo);
                            }
                            break;

                        case "RIV1":
                            {
                                byte[] rivPayload = br.ReadBytes(payloadLen);
                                map.Water ??= new C2WaterData();
                                C2WaterBuilder.TryParseRiv1Payload(rivPayload, map.Water, out string waterInfo);
                                Debug.Log($"[C2:WATER] chunk=RIV1 selected={mapId} payload={payloadLen} " + waterInfo);
                            }
                            break;

                        case "TRE2":
                            map.ChunkTRE2 = br.ReadBytes(payloadLen);
                            map.Tre2DecodedLikeOriginal = false;
                            map.DecodedSpritesLikeOriginal = Array.Empty<DecodedSpriteLikeOriginal>();
                            map.SpRefListsLikeOriginal = Array.Empty<int[]>();
                            break;

                        case "UNI3":
                            map.ChunkUNI3 = br.ReadBytes(payloadLen);
                            map.Uni3DecodedLikeOriginal = false;
                            map.DecodedUnitsLikeOriginal = Array.Empty<DecodedUnitLikeOriginal>();
                            break;

                        case "GSPR":
                            map.ChunkGSPR = br.ReadBytes(payloadLen);
                            break;

                        case "ZON2":
                            map.ChunkZON2 = br.ReadBytes(payloadLen);
                            break;

                        case "MOPT":
                            map.ChunkMOPT = br.ReadBytes(payloadLen);
                            break;

                        case "RNE2":
                            ApplyRoadNetChunkLikeOriginal(map, br, payloadLen);
                            break;

                        case "FOR2":
                            map.ChunkFOR2 = br.ReadBytes(payloadLen);
                            break;

                        case "LOC2":
                            map.ChunkLOC2 = br.ReadBytes(payloadLen);
                            break;

                        case "0TPL":
                            ApplyTopologyChunkLikeOriginal(map, br, payloadLen, 0, "0TPL");
                            break;

                        case "1TPL":
                            ApplyTopologyChunkLikeOriginal(map, br, payloadLen, 1, "1TPL");
                            break;

                        case "2TPL":
                            ApplyTopologyChunkLikeOriginal(map, br, payloadLen, 2, "2TPL");
                            break;

                        case "HSEM":
                        case "MESH":
                            if (!TryApplyNewSurfaceChunkLikeOriginal(map, br, payloadLen, out error))
                                return false;
                            break;
                    }

                    ms.Position = payloadEnd;
                }

                if (!map.IsMeshSurface)
                {
                    if (map.Heights == null || map.Heights.Length == 0)
                    {
                        error = "Не найден SURF heightmap.";
                        return false;
                    }

                    int expected = (map.MaxTH + 1) * map.MaxTH;
                    if (expected > 0 && map.Heights.Length < expected)
                    {
                        error = $"SURF слишком короткий: {map.Heights.Length} < {expected}";
                        return false;
                    }
                }
                else
                {
                    if (map.MeshVertices == null || map.MeshVertices.Length == 0 || map.MeshIndices == null || map.MeshIndices.Length == 0)
                    {
                        error = "Чанк HSEM найден, но геометрия пуста.";
                        return false;
                    }

                    EnsureMeshSurfaceSupportLikeOriginal(map);
                    if (map.Heights == null || map.Heights.Length == 0)
                    {
                        error = "Чанк HSEM найден, но FillMapOfHeights-like support не построен.";
                        return false;
                    }
                }

                if (!map.IsMeshSurface && map.Heights != null && map.Heights.Length > 0)
                    map.Options = BuildOriginalGroundOptions(map);

                int tileOptNonZero = map.TilePrimaryOpt != null ? map.TilePrimaryOpt.Count(v => v != 0) : 0;
                int tile2OptNonZero = map.TileSecondaryOpt != null ? map.TileSecondaryOpt.Count(v => v != 0) : 0;
                Debug.Log($"[C2:MAP] parse summary heights={(map.Heights != null ? map.Heights.Length : 0)} tile={(map.TilePrimary != null ? map.TilePrimary.Length : 0)} tileOpt={(map.TilePrimaryOpt != null ? map.TilePrimaryOpt.Length : 0)} tileOptNZ={tileOptNonZero} tile2={(map.TileSecondary != null ? map.TileSecondary.Length : 0)} tile2Opt={(map.TileSecondaryOpt != null ? map.TileSecondaryOpt.Length : 0)} tile2OptNZ={tile2OptNonZero} tile2w={(map.TileSecondaryWeight != null ? map.TileSecondaryWeight.Length : 0)} fmap={(map.FactureMap != null ? map.FactureMap.Length : 0)} fmapw={(map.FactureWeight != null ? map.FactureWeight.Length : 0)} sea2Bytes={map.Sea2PayloadBytes} sea2NonZero={map.Sea2NonZeroCount} meshVerts={(map.MeshVertices != null ? map.MeshVertices.Length : 0)} meshIdx={(map.MeshIndices != null ? map.MeshIndices.Length : 0)} meshColors={(map.MeshColors != null ? map.MeshColors.Length : 0)} meshShadow={(map.MeshShadow != null ? map.MeshShadow.Length : 0)} meshFacture={(map.MeshFacture != null ? map.MeshFacture.Length : 0)} meshNormals={(map.MeshNormals != null ? map.MeshNormals.Length : 0)} meshQuads={(map.MeshQuadSystem != null ? map.MeshQuadSystem.QuadsNx + "x" + map.MeshQuadSystem.QuadsNy : "none")} options={(map.Options != null ? map.Options.Length : 0)}");
                EnsureMapXyShiftLikeOriginal(map);
                Debug.Log($"[C2:MAP] terrain summary tile={(map.TilePrimary != null && map.TilePrimary.Length > 0 ? "ok" : "missing")} tile2={(map.TileSecondary != null && map.TileSecondary.Length > 0 ? "ok" : "missing")} fmap={(map.FactureMap != null && map.FactureMap.Length > 0 ? "ok" : "missing")} sea2Count={map.Sea2NonZeroCount} modeDefault={Mathf.Clamp(InitialTerrainDebugMode, 1, 7)}");
                Debug.Log($"[C2:MAP] chunk inventory VIE2={GetChunkInventory(chunkCounts, chunkPayloadBytes, "VIE2")} SURF={GetChunkInventory(chunkCounts, chunkPayloadBytes, "SURF")} TILE={GetChunkInventory(chunkCounts, chunkPayloadBytes, "TILE")} TIL2={GetChunkInventory(chunkCounts, chunkPayloadBytes, "TIL2")} FMAP={GetChunkInventory(chunkCounts, chunkPayloadBytes, "FMAP")} SEA2={GetChunkInventory(chunkCounts, chunkPayloadBytes, "SEA2")} RGBW={GetChunkInventory(chunkCounts, chunkPayloadBytes, "RGBW")} RIV1={GetChunkInventory(chunkCounts, chunkPayloadBytes, "RIV1")} TRE2={GetChunkInventory(chunkCounts, chunkPayloadBytes, "TRE2")} UNI3={GetChunkInventory(chunkCounts, chunkPayloadBytes, "UNI3")} GSPR={GetChunkInventory(chunkCounts, chunkPayloadBytes, "GSPR")} ZON2={GetChunkInventory(chunkCounts, chunkPayloadBytes, "ZON2")} MOPT={GetChunkInventory(chunkCounts, chunkPayloadBytes, "MOPT")} RNE2={GetChunkInventory(chunkCounts, chunkPayloadBytes, "RNE2")} 0TPL={GetChunkInventory(chunkCounts, chunkPayloadBytes, "0TPL")} 1TPL={GetChunkInventory(chunkCounts, chunkPayloadBytes, "1TPL")} 2TPL={GetChunkInventory(chunkCounts, chunkPayloadBytes, "2TPL")} HSEM={GetChunkInventory(chunkCounts, chunkPayloadBytes, "HSEM")} MESH={GetChunkInventory(chunkCounts, chunkPayloadBytes, "MESH")} ");
                Debug.Log($"[C2:MAP] tpl detail 0TPL={BuildTplChunkDetail(map.Chunk0TPL, map.MaxTH)} 1TPL={BuildTplChunkDetail(map.Chunk1TPL, map.MaxTH)} 2TPL={BuildTplChunkDetail(map.Chunk2TPL, map.MaxTH)}");
                Debug.Log($"[C2:MAP] adjacent chunks TRE2={BuildChunkProbe(map.ChunkTRE2)} UNI3={BuildChunkProbe(map.ChunkUNI3)} ZON2={BuildChunkProbe(map.ChunkZON2)} RNE2={BuildChunkProbe(map.ChunkRNE2)} MOPT={BuildChunkProbe(map.ChunkMOPT)} LOC2={BuildChunkProbe(map.ChunkLOC2)} GSPR={BuildScalarChunkProbe(map.ChunkGSPR)} FOR2={BuildScalarChunkProbe(map.ChunkFOR2)}");
                Debug.Log($"[C2:MAP] stage6 candidates fields=FOR2+0TPL+1TPL+2TPL trees=TRE2+GSPR units=UNI3 zones=ZON2 routes=RNE2+LOC2 mopt={BuildScalarChunkProbe(map.ChunkMOPT)}");
                Debug.Log($"[C2:MAP] stage7 tpl samples 0TPL={BuildTplAreaSample(map.Chunk0TPL, map.MaxTH)} 1TPL={BuildTplAreaSample(map.Chunk1TPL, map.MaxTH)} 2TPL={BuildTplAreaSample(map.Chunk2TPL, map.MaxTH)}");
                Debug.Log($"[C2:MAP] stage7 count guesses TRE2={BuildCountGuessProbe(map.ChunkTRE2)} UNI3={BuildCountGuessProbe(map.ChunkUNI3)} ZON2={BuildCountGuessProbe(map.ChunkZON2)} RNE2={BuildCountGuessProbe(map.ChunkRNE2)} LOC2={BuildCountGuessProbe(map.ChunkLOC2)}");
                Debug.Log($"[C2:MAP] stage7 viability fields={(IsScalarZeroChunk(map.ChunkFOR2) ? "absent-on-this-map" : "present-or-unknown")} trees={(IsScalarZeroChunk(map.ChunkGSPR) ? "no-gspr-table" : "gspr-present")} tpl={(HasResolvableTplPayload(map.Chunk0TPL, map.MaxTH) && HasResolvableTplPayload(map.Chunk1TPL, map.MaxTH) && HasResolvableTplPayload(map.Chunk2TPL, map.MaxTH) ? "usable" : "partial")}");
                Debug.Log($"[C2:MAP] stage8 topref 0TPL={BuildTplTopRefProbe(map.Chunk0TPL, map.MaxTH)} 1TPL={BuildTplTopRefProbe(map.Chunk1TPL, map.MaxTH)} 2TPL={BuildTplTopRefProbe(map.Chunk2TPL, map.MaxTH)}");
                Debug.Log($"[C2:MAP] stage8 area refs 0TPL={BuildTplAreaRefProbe(map.Chunk0TPL, map.MaxTH)} 1TPL={BuildTplAreaRefProbe(map.Chunk1TPL, map.MaxTH)} 2TPL={BuildTplAreaRefProbe(map.Chunk2TPL, map.MaxTH)}");
                Debug.Log($"[C2:MAP] stage9 normalized topref 0TPL={BuildTplNormalizedTopRefProbe(map.Chunk0TPL, map.MaxTH)} 1TPL={BuildTplNormalizedTopRefProbe(map.Chunk1TPL, map.MaxTH)} 2TPL={BuildTplNormalizedTopRefProbe(map.Chunk2TPL, map.MaxTH)}");
                Debug.Log($"[C2:MAP] stage9 area coverage 0TPL={BuildTplAreaCoverageProbe(map.Chunk0TPL, map.MaxTH)} 1TPL={BuildTplAreaCoverageProbe(map.Chunk1TPL, map.MaxTH)} 2TPL={BuildTplAreaCoverageProbe(map.Chunk2TPL, map.MaxTH)}");
                Debug.Log($"[C2:MAP] stage10 area anchors 0TPL={BuildTplAreaAnchorProbe(map.Chunk0TPL, map.MaxTH)} 1TPL={BuildTplAreaAnchorProbe(map.Chunk1TPL, map.MaxTH)} 2TPL={BuildTplAreaAnchorProbe(map.Chunk2TPL, map.MaxTH)}");
                Debug.Log($"[C2:MAP] stage10 link quads 0TPL={BuildTplLinkQuadProbe(map.Chunk0TPL, map.MaxTH)} 1TPL={BuildTplLinkQuadProbe(map.Chunk1TPL, map.MaxTH)} 2TPL={BuildTplLinkQuadProbe(map.Chunk2TPL, map.MaxTH)}");
                Debug.Log($"[C2:MAP] stage11 normalized graph 0TPL={BuildTplNormalizedGraphProbe(map.Chunk0TPL, map.MaxTH)} 1TPL={BuildTplNormalizedGraphProbe(map.Chunk1TPL, map.MaxTH)} 2TPL={BuildTplNormalizedGraphProbe(map.Chunk2TPL, map.MaxTH)}");
                Debug.Log($"[C2:MAP] stage11 edge samples 0TPL={BuildTplEdgeSampleProbe(map.Chunk0TPL, map.MaxTH)} 1TPL={BuildTplEdgeSampleProbe(map.Chunk1TPL, map.MaxTH)} 2TPL={BuildTplEdgeSampleProbe(map.Chunk2TPL, map.MaxTH)}");
                Debug.Log($"[C2:TOPO] base map={mapId} surface={(map.IsMeshSurface ? "mesh" : "surf")} size={map.VertInLine}x{map.MaxTH} heights={(map.Heights != null ? map.Heights.Length : 0)} tile={(map.TilePrimary != null ? map.TilePrimary.Length : 0)} tile2={(map.TileSecondary != null ? map.TileSecondary.Length : 0)} fmap={(map.FactureMap != null ? map.FactureMap.Length : 0)}");
                Debug.Log($"[C2:TOPO] chunks RNE2={(map.ChunkRNE2 != null ? map.ChunkRNE2.Length : 0)} LOC2={(map.ChunkLOC2 != null ? map.ChunkLOC2.Length : 0)} ZON2={(map.ChunkZON2 != null ? map.ChunkZON2.Length : 0)} MOPT={(map.ChunkMOPT != null ? map.ChunkMOPT.Length : 0)} UNI3={(map.ChunkUNI3 != null ? map.ChunkUNI3.Length : 0)} TRE2={(map.ChunkTRE2 != null ? map.ChunkTRE2.Length : 0)} GSPR={(map.ChunkGSPR != null ? map.ChunkGSPR.Length : 0)} 0TPL={(map.Chunk0TPL != null ? map.Chunk0TPL.Length : 0)} 1TPL={(map.Chunk1TPL != null ? map.Chunk1TPL.Length : 0)} 2TPL={(map.Chunk2TPL != null ? map.Chunk2TPL.Length : 0)}");
                EnsureTopologyRuntimeStateLikeOriginal(map);
                Debug.Log($"[C2:TOPO] runtime {BuildTopologyRuntimeSummaryLikeOriginal(map)}");
                Debug.Log($"[C2:TOPO] hints zoneSpace=road-knots-plus-top-areas tplTarget=q2-candidate-not-final next=decode-rne2");
                DecodedRoadNet decodedRne2 = map.DecodedRne2;
                string rneSummary = decodedRne2 != null ? BuildRne2Summary(decodedRne2) : "";
                string rneSamples = decodedRne2 != null ? BuildRne2Samples(decodedRne2) : "";
                if (decodedRne2 != null || TryDecodeRne2(map.ChunkRNE2, out decodedRne2, out rneSummary, out rneSamples))
                {
                    map.DecodedRne2 = decodedRne2;
                    Debug.Log($"[C2:RNE2] decoded {rneSummary}");
                    Debug.Log($"[C2:RNE2] samples {rneSamples}");
                    Debug.Log($"[C2:RNE2] integrity {BuildRne2IntegritySummary(decodedRne2)}");
                    Debug.Log($"[C2:RNE2] integrity-samples {BuildRne2IntegritySamples(decodedRne2)}");
                    Debug.Log($"[C2:ZONE] split {BuildZoneSplitSummary(map)}");
                    Debug.Log($"[C2:ZONE] samples {BuildZoneSplitSamples(map)}");
                    Debug.Log($"[C2:TPL] target-space compare 0TPL={BuildTplTargetSpaceCompare(map.Chunk0TPL, map.DecodedRne2 != null ? map.DecodedRne2.NodeCount : 0)} 1TPL={BuildTplTargetSpaceCompare(map.Chunk1TPL, map.DecodedRne2 != null ? map.DecodedRne2.NodeCount : 0)} 2TPL={BuildTplTargetSpaceCompare(map.Chunk2TPL, map.DecodedRne2 != null ? map.DecodedRne2.NodeCount : 0)}");
                    Debug.Log($"[C2:TPL] target-space samples 0TPL={BuildTplTargetSpaceSamples(map.Chunk0TPL, map.DecodedRne2 != null ? map.DecodedRne2.NodeCount : 0)} 1TPL={BuildTplTargetSpaceSamples(map.Chunk1TPL, map.DecodedRne2 != null ? map.DecodedRne2.NodeCount : 0)} 2TPL={BuildTplTargetSpaceSamples(map.Chunk2TPL, map.DecodedRne2 != null ? map.DecodedRne2.NodeCount : 0)}");
                    Debug.Log($"[C2:TPL] semantic compare 0TPL={BuildTplSemanticCompare(map.Chunk0TPL, map.DecodedRne2)} 1TPL={BuildTplSemanticCompare(map.Chunk1TPL, map.DecodedRne2)} 2TPL={BuildTplSemanticCompare(map.Chunk2TPL, map.DecodedRne2)}");
                    Debug.Log($"[C2:TPL] semantic samples 0TPL={BuildTplSemanticSamples(map.Chunk0TPL, map.DecodedRne2)} 1TPL={BuildTplSemanticSamples(map.Chunk1TPL, map.DecodedRne2)} 2TPL={BuildTplSemanticSamples(map.Chunk2TPL, map.DecodedRne2)}");
                    Debug.Log($"[C2:ZON2] params {BuildTextChunkSummary(map.ChunkZON2, "ZON2")}");
                    Debug.Log($"[C2:MOPT] params {BuildTextChunkSummary(map.ChunkMOPT, "MOPT")}");
                    Debug.Log($"[C2:LOC2] decode {BuildLoc2DecodeSummary(map.ChunkLOC2, map.DecodedRne2)}");
                    Debug.Log($"[C2:LOC2] waypoint relation {BuildLoc2WaypointRelation(map.ChunkLOC2, map.DecodedRne2)}");
                    Debug.Log($"[C2:ROAD] graph summary {BuildRoadGraphSummary(map)}");
                    Debug.Log($"[C2:ROAD] overlay {BuildRoadOverlaySummary(map)}");
                }
                else
                {
                    Debug.LogWarning($"[C2:RNE2] decode failed len={(map.ChunkRNE2 != null ? map.ChunkRNE2.Length : 0)}");
                }
                if (map.IsMeshSurface && map.MeshVertices != null && map.MeshVertices.Length > 0)
                {
                    int shadowNonZero = 0;
                    int factureNonZero = 0;
                    int normalNonZero = 0;
                    byte minShadow = 255;
                    byte maxShadow = 0;
                    byte minFacture = 255;
                    byte maxFacture = 0;
                    for (int i = 0; i < map.MeshVertices.Length; i++)
                    {
                        byte shadow = map.MeshShadow != null && i < map.MeshShadow.Length ? map.MeshShadow[i] : (byte)0;
                        byte facture = map.MeshFacture != null && i < map.MeshFacture.Length ? map.MeshFacture[i] : (byte)0;
                        if (shadow != 0) shadowNonZero++;
                        if (facture != 0) factureNonZero++;
                        if (shadow < minShadow) minShadow = shadow;
                        if (shadow > maxShadow) maxShadow = shadow;
                        if (facture < minFacture) minFacture = facture;
                        if (facture > maxFacture) maxFacture = facture;
                        Vector3 n = map.MeshNormals != null && i < map.MeshNormals.Length ? map.MeshNormals[i] : Vector3.zero;
                        if (n.sqrMagnitude > 0.0001f) normalNonZero++;
                    }

                    Color32 c0 = map.MeshColors != null && map.MeshColors.Length > 0 ? map.MeshColors[0] : new Color32(0, 0, 0, 0);
                    Vector3 n0 = map.MeshNormals != null && map.MeshNormals.Length > 0 ? map.MeshNormals[0] : Vector3.zero;
                    Debug.Log($"[C2:MAP] mesh extras colors={(map.MeshColors != null ? map.MeshColors.Length : 0)} firstColor={c0.r},{c0.g},{c0.b},{c0.a} shadowNZ={shadowNonZero} shadowMin={minShadow} shadowMax={maxShadow} factureNZ={factureNonZero} factureMin={minFacture} factureMax={maxFacture} normalNZ={normalNonZero} firstNormal={n0.x:F3},{n0.y:F3},{n0.z:F3}");
                }

                // Defer heavy road runtime build until the first real topology/path request.
                // Eager construction here noticeably slows initial map opening.
                if (map.Water != null)
                {
                    Debug.Log("[C2:WATER] summary " + map.Water.BuildSummary());
                    Debug.Log($"[C2:WATER] chunks selected={mapId} sea2Present={map.Water.HasSea2Payload} rgbwPresent={map.Water.HasRgbwPayload} riv1Present={map.Water.HasRiv1Payload} sea2Bytes={map.Sea2PayloadBytes} rgbwBytes={map.Water.RgbPayloadBytes} riv1Bytes={map.Water.RivPayloadBytes}");
                }
                else
                {
                    Debug.Log($"[C2:WATER] chunks selected={mapId} sea2Present=false rgbwPresent=false riv1Present=false");
                }
                InstallGlobalMutableStateLikeOriginal(map, "TryParseMap-final");
                Debug.Log("[C2:GLOBAL] " + BuildGlobalMutableStateSummaryLikeOriginal());
                Debug.Log($"[C2:ITERRA] enabled={(EnsureITerraBackendLikeOriginal().EnabledLikeOriginal ? 1 : 0)} new={(EnsureITerraBackendLikeOriginal().SurfaceTypeNewLikeOriginal ? 1 : 0)} texCb={EnsureITerraBackendLikeOriginal().TextureCallbackNameLikeOriginal} geoCb={EnsureITerraBackendLikeOriginal().GeometryCallbackNameLikeOriginal} hCb={EnsureITerraBackendLikeOriginal().HeightCallbackNameLikeOriginal} aabbCb={EnsureITerraBackendLikeOriginal().AabbCallbackNameLikeOriginal} ext={EnsureITerraBackendLikeOriginal().ExtentsLikeOriginal.X},{EnsureITerraBackendLikeOriginal().ExtentsLikeOriginal.Y},{EnsureITerraBackendLikeOriginal().ExtentsLikeOriginal.W},{EnsureITerraBackendLikeOriginal().ExtentsLikeOriginal.H}");
                return true;
            }
        }


        private static string BuildTopologyRuntimeSummaryLikeOriginal(ParsedMap map)
        {
            if (map == null || map.TopologyFieldsLikeOriginal == null)
                return "fields=0";

            var parts = new List<string>();
            for (int i = 0; i < map.TopologyFieldsLikeOriginal.Length; i++)
            {
                TopologyHashTableLikeOriginal field = map.TopologyFieldsLikeOriginal[i];
                if (field == null)
                {
                    parts.Add($"{i}:null");
                    continue;
                }

                parts.Add($"{i}:areas={field.NAreas}/create={(field.CreateAreasAppliedLikeOriginal ? 1 : 0)}/rebuild={(field.ReCreateAreasAppliedLikeOriginal ? 1 : 0)}/src={field.LastCreateAreasSourceLikeOriginal}/roads={field.RoadRelinkCountLikeOriginal}/gates={field.GateRelinkCountLikeOriginal}/islands={field.IslandCountLikeOriginal}/largest={field.LargestIslandLikeOriginal}/singled={field.SingledCellsLikeOriginal}/hits={field.LastCalculateWayHitCountLikeOriginal}/miss={field.LastCalculateWayMissCountLikeOriginal}/wayCost={field.LastPathCostLikeOriginal}/wayPts={(field.FullWayLikeOriginal != null ? field.FullWayLikeOriginal.Length : 0)}");
            }

            return string.Join(" | ", parts);
        }

        private static string ReadTag(BinaryReader br)
        {
            byte[] tag = br.ReadBytes(4);
            if (tag == null || tag.Length < 4) return "";
            return System.Text.Encoding.ASCII.GetString(tag);
        }

        private static bool IsTplTag(string tag)
        {
            return string.Equals(tag, "0TPL", StringComparison.Ordinal)
                || string.Equals(tag, "1TPL", StringComparison.Ordinal)
                || string.Equals(tag, "2TPL", StringComparison.Ordinal)
                || string.Equals(tag, "3TPL", StringComparison.Ordinal);
        }

        private static bool TryResolveTplChunkPayloadEnd(
            byte[] raw,
            long payloadStart,
            long claimedPayloadEnd,
            int maxTH,
            out long actualPayloadEnd,
            out int legacyPayloadLen,
            out bool claimedMatchesLegacy,
            out bool claimedMatchesActual,
            out string info)
        {
            actualPayloadEnd = claimedPayloadEnd;
            legacyPayloadLen = 0;
            claimedMatchesLegacy = false;
            claimedMatchesActual = false;
            info = "";

            if (raw == null)
            {
                info = "raw=null";
                return false;
            }

            if (payloadStart < 0 || payloadStart + 4 > raw.LongLength)
            {
                info = "payloadStart out of range";
                return false;
            }

            int cursor = checked((int)payloadStart);
            int areaCount = ReadInt32LE(raw, cursor);
            cursor += 4;
            if (areaCount < 0)
            {
                info = "negative areaCount";
                return false;
            }

            long sumLinks = 0;
            long actualLinkBytes = 0;
            long legacyLinkBytes = 0;

            for (int i = 0; i < areaCount; i++)
            {
                if (cursor + 6 > raw.Length)
                {
                    info = $"area header overflow at {i}";
                    return false;
                }

                ushort linkCount = ReadUInt16LE(raw, cursor + 4);
                cursor += 6;

                // Original engine writes AR->Link as sizeof(OneLinkInfo) == 8 bytes,
                // but stores sizeField as if every link consumed only 4 bytes.
                long linkBytes = (long)linkCount * 8L;
                long legacyBytes = (long)linkCount * 4L;

                if (cursor + linkBytes > raw.LongLength)
                {
                    info = $"link array overflow at area={i} links={linkCount}";
                    return false;
                }

                cursor += checked((int)linkBytes);
                sumLinks += linkCount;
                actualLinkBytes += linkBytes;
                legacyLinkBytes += legacyBytes;
            }

            int topLx = maxTH > 1 ? (maxTH >> 1) : 0;
            if (topLx <= 0)
            {
                info = "invalid topLx";
                return false;
            }

            long topRefBytes = (long)topLx * (long)topLx * 2L;
            actualPayloadEnd = cursor + topRefBytes;

            long actualPayloadLen64 = 4L + (long)areaCount * 6L + actualLinkBytes + topRefBytes;
            long legacyPayloadLen64 = 4L + (long)areaCount * 6L + legacyLinkBytes + topRefBytes;
            if (actualPayloadLen64 > int.MaxValue || legacyPayloadLen64 > int.MaxValue)
            {
                info = "payload length overflow";
                return false;
            }

            legacyPayloadLen = checked((int)legacyPayloadLen64);
            int claimedPayloadLen = checked((int)(claimedPayloadEnd - payloadStart));
            int actualPayloadLen = checked((int)actualPayloadLen64);

            claimedMatchesLegacy = claimedPayloadLen == legacyPayloadLen;
            claimedMatchesActual = claimedPayloadLen == actualPayloadLen;

            info =
                $"areas={areaCount} sumLinks={sumLinks} topLx={topLx} topRefBytes={topRefBytes} " +
                $"legacyLinkBytes={legacyLinkBytes} actualLinkBytes={actualLinkBytes} " +
                $"claimedPayload={claimedPayloadLen} legacyPayload={legacyPayloadLen} actualPayload={actualPayloadLen}";

            return actualPayloadEnd >= payloadStart && actualPayloadEnd <= raw.LongLength;
        }

        private static ushort ReadUInt16LE(byte[] raw, int offset)
        {
            return (ushort)(raw[offset] | (raw[offset + 1] << 8));
        }

        private static int ReadInt32LE(byte[] raw, int offset)
        {
            return raw[offset]
                | (raw[offset + 1] << 8)
                | (raw[offset + 2] << 16)
                | (raw[offset + 3] << 24);
        }


private const int Rne2MaxLink = 8;

private static bool TryDecodeRne2(byte[] raw, out DecodedRoadNet net, out string summary, out string samples)
{
    net = null;
    summary = "unavailable";
    samples = "none";

    if (raw == null || raw.Length < 8)
    {
        summary = $"len={(raw != null ? raw.Length : 0)}";
        return false;
    }

    int count = ReadInt32LE(raw, 0);
    if (count <= 0 || count > 100000)
    {
        summary = $"badCount={count} len={raw.Length}";
        return false;
    }

    int payload = raw.Length - 4;
    int[] preferredStrides = { 77, 80, 53, 56 };
    int stride = 0;
    foreach (int candidate in preferredStrides)
    {
        if (payload == count * candidate)
        {
            stride = candidate;
            break;
        }
    }

    if (stride == 0 && count > 0 && payload % count == 0)
    {
        int dynamicStride = payload / count;
        if (dynamicStride >= 40 && dynamicStride <= 96)
            stride = dynamicStride;
    }

    if (stride == 0)
    {
        summary = $"count={count} payload={payload} stride=unresolved";
        return false;
    }

    var decoded = new DecodedRoadNet
    {
        NodeCount = count,
        Stride = stride,
        Layout = GetRne2LayoutName(stride)
    };

    int minX = int.MaxValue;
    int maxX = int.MinValue;
    int minY = int.MaxValue;
    int maxY = int.MinValue;
    int minRoadX = int.MaxValue;
    int maxRoadX = int.MinValue;
    int minRoadY = int.MaxValue;
    int maxRoadY = int.MinValue;
    int activeSources = 0;
    int zeroDegree = 0;
    int linkTypeMin = 255;
    int linkTypeMax = 0;
    int roadIdNonZero = 0;
    int waypointNonZero = 0;

    for (int i = 0; i < count; i++)
    {
        int offset = 4 + i * stride;
        if (!TryReadRne2Node(raw, offset, stride, out RoadKnot node))
        {
            summary = $"count={count} stride={stride} badNode={i}";
            return false;
        }

        decoded.Nodes.Add(node);

        minX = Math.Min(minX, node.X);
        maxX = Math.Max(maxX, node.X);
        minY = Math.Min(minY, node.Y);
        maxY = Math.Max(maxY, node.Y);

        if (node.HasOnRoad)
        {
            minRoadX = Math.Min(minRoadX, node.XOnRoad);
            maxRoadX = Math.Max(maxRoadX, node.XOnRoad);
            minRoadY = Math.Min(minRoadY, node.YOnRoad);
            maxRoadY = Math.Max(maxRoadY, node.YOnRoad);
        }

        int degree = Math.Clamp(node.NLinks, 0, Rne2MaxLink);
        decoded.MaxDegree = Math.Max(decoded.MaxDegree, degree);
        if (degree > 0) activeSources++; else zeroDegree++;
        if (node.Hidden != 0) decoded.HiddenCount++;

        for (int q = 0; q < degree; q++)
        {
            ushort target = node.Links[q];
            if (target < count) decoded.ValidLinkRefs++; else decoded.InvalidLinkRefs++;
            if (node.RoadID[q] != 0xFFFF) roadIdNonZero++;
            if (node.WayPointToPointIndex[q] != 0xFFFF) waypointNonZero++;
            linkTypeMin = Math.Min(linkTypeMin, node.LinkType[q]);
            linkTypeMax = Math.Max(linkTypeMax, node.LinkType[q]);
        }
    }

    decoded.ActiveSources = activeSources;
    decoded.ZeroDegree = zeroDegree;

    for (int i = 0; i < decoded.Nodes.Count; i++)
    {
        var node = decoded.Nodes[i];
        int degree = Math.Clamp(node.NLinks, 0, Rne2MaxLink);
        for (int q = 0; q < degree; q++)
        {
            int target = node.Links[q];
            if (target < 0 || target >= decoded.Nodes.Count) continue;
            if (HasRne2BackLink(decoded.Nodes[target], i)) decoded.ReciprocalDirected++;
        }
    }

    string linkTypeInfo = linkTypeMin <= linkTypeMax ? $"{linkTypeMin}-{linkTypeMax}" : "n/a";
    string roadInfo = minRoadX <= maxRoadX && minRoadY <= maxRoadY
        ? $"{minRoadX},{minRoadY}-{maxRoadX},{maxRoadY}"
        : "absent";
    summary =
        $"nodes={count} stride={stride} layout={decoded.Layout} active={activeSources} zeroDegree={zeroDegree} hidden={decoded.HiddenCount} " +
        $"validLinks={decoded.ValidLinkRefs} invalidLinks={decoded.InvalidLinkRefs} reciprocalDirected={decoded.ReciprocalDirected} " +
        $"xy={minX},{minY}-{maxX},{maxY} onRoad={roadInfo} roadIdsNonZero={roadIdNonZero} waypointsNonZero={waypointNonZero} linkTypeRange={linkTypeInfo}";

    var sampleParts = new List<string>();
    for (int i = 0; i < decoded.Nodes.Count && sampleParts.Count < 3; i++)
    {
        RoadKnot node = decoded.Nodes[i];
        int degree = Math.Clamp(node.NLinks, 0, Rne2MaxLink);
        if (degree <= 0 && i + 1 < decoded.Nodes.Count) continue;
        string links = degree > 0 ? string.Join(",", node.Links.Take(degree)) : "-";
        string roads = degree > 0 ? string.Join(",", node.RoadID.Take(degree)) : "-";
        string types = degree > 0 ? string.Join(",", node.LinkType.Take(degree)) : "-";
        string way = degree > 0 ? string.Join(",", node.WayPointToPointIndex.Take(degree)) : "-";
        string onRoad = node.HasOnRoad ? $"{node.XOnRoad},{node.YOnRoad}" : "n/a";
        sampleParts.Add($"{i}@{node.X},{node.Y} nl={node.NLinks} hidden={node.Hidden} links={links} road={roads} type={types} wp={way} onRoad={onRoad}");
    }

    if (sampleParts.Count == 0)
        sampleParts.Add("none");

    samples = string.Join(" | ", sampleParts);
    net = decoded;
    return true;
}

private static void EnsureRoadRuntimeDescriptorsLikeOriginal(Cossacks2Bridge.Core.CoreFileSystem fs, ParsedMap map)
{
    if (map == null)
        return;
    if (map.RoadPhysByTypeLikeOriginal != null && map.RoadPhysByTypeLikeOriginal.Count > 0 &&
        map.RoadPrioryByTypeLikeOriginal != null && map.RoadPrioryByTypeLikeOriginal.Count > 0)
        return;

    var physByType = new Dictionary<int, RoadPhysLikeOriginal>();
    bool loadedFromFile = false;
    string path = fs != null ? fs.ResolvePath("Roads.dat") : "";
    if (!string.IsNullOrWhiteSpace(path) && File.Exists(path))
    {
        try
        {
            ParseRoadPhysByTypeLikeOriginal(path, physByType);
            loadedFromFile = physByType.Count > 0;
        }
        catch (Exception ex)
        {
            Debug.LogWarning("[C2:ROAD] phys parse failed: " + ex.Message);
            physByType.Clear();
            loadedFromFile = false;
        }
    }

    if ((physByType == null || physByType.Count == 0) && map.DecodedRne2 != null && map.DecodedRne2.Nodes != null)
        BuildFallbackRoadPhysByTypeLikeOriginal(map.DecodedRne2, physByType);

    var prioryByType = new Dictionary<int, short>();
    foreach (var kv in physByType)
        prioryByType[kv.Key] = kv.Value != null && kv.Value.Priory > 0 ? kv.Value.Priory : (short)256;

    map.RoadPhysByTypeLikeOriginal = physByType;
    map.RoadPrioryByTypeLikeOriginal = prioryByType;
    map.RoadDescriptorsLoadedFromFileLikeOriginal = loadedFromFile;
}

private static void ParseRoadPhysByTypeLikeOriginal(string path, Dictionary<int, RoadPhysLikeOriginal> dest)
{
    if (dest == null)
        return;

    var entries = new List<RoadPhysLikeOriginal>();
    foreach (string rawLine in File.ReadAllLines(path, Encoding.GetEncoding(1251)))
    {
        string line = rawLine;
        int commentPos = line.IndexOf(';');
        if (commentPos >= 0)
            line = line.Substring(0, commentPos);
        line = line.Trim();
        if (string.IsNullOrWhiteSpace(line))
            continue;

        string[] tokens = line.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
        if (tokens.Length == 0)
            continue;

        string head = tokens[0];
        if (string.Equals(head, "$PHYS", StringComparison.OrdinalIgnoreCase))
        {
            if (entries.Count > 0 && tokens.Length >= 4)
            {
                int speed;
                int tiring;
                int priory;
                if (!int.TryParse(tokens[1], NumberStyles.Integer, CultureInfo.InvariantCulture, out speed))
                    speed = 256;
                if (!int.TryParse(tokens[2], NumberStyles.Integer, CultureInfo.InvariantCulture, out tiring))
                    tiring = 256;
                if (!int.TryParse(tokens[3], NumberStyles.Integer, CultureInfo.InvariantCulture, out priory))
                    priory = 656;

                RoadPhysLikeOriginal last = entries[entries.Count - 1];
                last.Speed = (short)Mathf.Clamp(speed, 1, 32767);
                last.Tiring = (short)Mathf.Clamp(tiring, 1, 32767);
                last.Priory = (short)Mathf.Clamp(priory, 1, 32767);
            }
            continue;
        }

        if (string.Equals(head, "$EX", StringComparison.OrdinalIgnoreCase))
        {
            RoadPhysLikeOriginal clone = entries.Count > 0 ? entries[entries.Count - 1].Clone() : new RoadPhysLikeOriginal();
            entries.Add(clone);
            continue;
        }

        if (string.Equals(head, "$BUMP", StringComparison.OrdinalIgnoreCase) || string.Equals(head, "$PREVIEW", StringComparison.OrdinalIgnoreCase))
            continue;

        if (tokens.Length < 16)
            continue;

        short rwidth = 64;
        int parsedWidth;
        if (int.TryParse(tokens[8], NumberStyles.Integer, CultureInfo.InvariantCulture, out parsedWidth))
            rwidth = (short)Mathf.Clamp(parsedWidth, 1, 32767);

        entries.Add(new RoadPhysLikeOriginal
        {
            RWidth = rwidth,
            RoadName = head
        });
    }

    for (int i = 0; i < entries.Count; i++)
        dest[i] = entries[i];
}

private static void BuildFallbackRoadPhysByTypeLikeOriginal(DecodedRoadNet net, Dictionary<int, RoadPhysLikeOriginal> dest)
{
    if (dest == null)
        return;
    var types = new HashSet<int>();
    if (net != null && net.Nodes != null)
    {
        foreach (RoadKnot node in net.Nodes)
        {
            if (node == null || node.LinkType == null)
                continue;
            int degree = Math.Min(Math.Max(node.NLinks, 0), Math.Min(Rne2MaxLink, node.LinkType.Length));
            for (int i = 0; i < degree; i++)
                types.Add(node.LinkType[i]);
        }
    }
    if (types.Count == 0)
        types.Add(0);
    foreach (int type in types)
    {
        int priory = 656 - Math.Max(0, type) * 48;
        if (priory < 64)
            priory = 64;
        dest[type] = new RoadPhysLikeOriginal
        {
            Speed = 256,
            Tiring = 256,
            Priory = (short)priory,
            RWidth = 64,
            RoadName = $"type_{type}"
        };
    }
}

private static void EnsureRoadNetRuntimeLikeOriginal(ParsedMap map)
{
    if (map == null || map.DecodedRne2 == null || map.DecodedRne2.Nodes == null)
        return;
    if (map.RoadNetParamsByNodeLikeOriginal != null && map.RoadWayPointToPointLikeOriginal != null)
        return;

    EnsureRoadRuntimeDescriptorsLikeOriginal(null, map);

    int nodeCount = map.DecodedRne2.Nodes.Count;
    var netParams = new RoadNetParamsLikeOriginal[nodeCount];

    for (int i = 0; i < nodeCount; i++)
    {
        RoadKnot nk = map.DecodedRne2.Nodes[i];
        if (nk == null)
            continue;

        int degree = Math.Min(Math.Max(nk.NLinks, 0), nk.Links != null ? nk.Links.Length : 0);
        if (degree == 2)
        {
            int k0 = nk.Links[0];
            int k1 = nk.Links[1];
            if (k0 >= 0 && k0 < nodeCount && k1 >= 0 && k1 < nodeCount)
            {
                nk.XOnRoad = (nk.X * 6 + map.DecodedRne2.Nodes[k0].X + map.DecodedRne2.Nodes[k1].X) / 8;
                nk.YOnRoad = (nk.Y * 6 + map.DecodedRne2.Nodes[k0].Y + map.DecodedRne2.Nodes[k1].Y) / 8;
            }
            else
            {
                nk.XOnRoad = nk.X;
                nk.YOnRoad = nk.Y;
            }
        }
        else
        {
            nk.XOnRoad = nk.X;
            nk.YOnRoad = nk.Y;
        }
        nk.HasOnRoad = true;

        if (nk.WayPointToPointIndex == null || nk.WayPointToPointIndex.Length < Rne2MaxLink)
            nk.WayPointToPointIndex = new ushort[Rne2MaxLink];
        for (int j = 0; j < nk.WayPointToPointIndex.Length; j++)
            nk.WayPointToPointIndex[j] = 0xFFFF;

        int ss = 0;
        int st = 0;
        int sp = 0;
        int degree2 = Math.Min(Math.Max(nk.NLinks, 0), nk.LinkType != null ? nk.LinkType.Length : 0);

        for (int j = 0; j < degree2; j++)
        {
            int type = nk.LinkType[j];
            RoadPhysLikeOriginal phys = null;
            if (map.RoadPhysByTypeLikeOriginal != null)
                map.RoadPhysByTypeLikeOriginal.TryGetValue(type, out phys);
            if (phys == null)
                phys = new RoadPhysLikeOriginal();

            ss += phys.Speed;
            st += phys.Tiring;
            sp += phys.Priory;
        }

        if (degree2 > 0)
        {
            ss /= degree2;
            st /= degree2;
            sp /= degree2;
        }
        else
        {
            ss = 256;
            st = 256;
            sp = 256;
        }

        netParams[i] = new RoadNetParamsLikeOriginal
        {
            Speed = (short)Mathf.Clamp(ss, 1, 32767),
            Tiring = (short)Mathf.Clamp(st, 1, 32767),
            Priory = (short)Mathf.Clamp(sp, 1, 32767)
        };
    }

    var runtime = new List<RoadWayPointToPointLikeOriginal>(Math.Max(4, nodeCount * 2));
    for (int i = 0; i < nodeCount; i++)
    {
        RoadKnot nk = map.DecodedRne2.Nodes[i];
        if (nk == null || nk.Hidden != 0 || nk.Links == null || nk.WayPointToPointIndex == null)
            continue;

        int degree = Math.Min(Math.Max(nk.NLinks, 0), Math.Min(nk.Links.Length, nk.WayPointToPointIndex.Length));
        for (int j = 0; j < degree; j++)
        {
            if (nk.WayPointToPointIndex[j] != 0xFFFF)
                continue;

            int dest = nk.Links[j];
            if (dest < 0 || dest >= nodeCount)
                continue;

            RoadKnot dnk = map.DecodedRne2.Nodes[dest];
            if (dnk == null || dnk.Hidden != 0 || dnk.Links == null || dnk.WayPointToPointIndex == null)
                continue;

            ushort shared = 0xFFFF;
            int backIndex = -1;
            int backDegree = Math.Min(Math.Max(dnk.NLinks, 0), Math.Min(dnk.Links.Length, dnk.WayPointToPointIndex.Length));
            for (int k = 0; k < backDegree; k++)
            {
                if (dnk.Links[k] == i)
                {
                    backIndex = k;
                    if (dnk.WayPointToPointIndex[k] != 0xFFFF)
                    {
                        shared = dnk.WayPointToPointIndex[k];
                        break;
                    }
                }
            }

            if (shared == 0xFFFF)
            {
                shared = (ushort)runtime.Count;
                runtime.Add(new RoadWayPointToPointLikeOriginal
                {
                    StartKnot = i,
                    EndKnot = dest,
                    Samples = null,
                    SamplesReady = false,
                    Owner = 0xFFFFFFFFu,
                    PreLockRequestor = 0xFFFFFFFFu
                });
            }

            nk.WayPointToPointIndex[j] = shared;
            if (backIndex >= 0 && backIndex < dnk.WayPointToPointIndex.Length)
                dnk.WayPointToPointIndex[backIndex] = shared;
        }
    }

    map.RoadNetParamsByNodeLikeOriginal = netParams;
    map.RoadWayPointToPointLikeOriginal = runtime.ToArray();
}

private static RoadWayPointToPointLikeOriginal EnsureRoadWayPointObjectBuiltLikeOriginal(ParsedMap map, RoadWayPointToPointLikeOriginal wp)
{
    if (wp == null)
        return null;
    if (wp.SamplesReady && wp.Samples != null)
        return wp;

    RoadWayPointToPointLikeOriginal built = BuildRoadWayPointToPointLikeOriginal(map, wp.StartKnot, wp.EndKnot);
    if (built == null)
    {
        wp.Samples = Array.Empty<RoadWayPointSampleLikeOriginal>();
        wp.SamplesReady = true;
        return wp;
    }

    wp.Samples = built.Samples ?? Array.Empty<RoadWayPointSampleLikeOriginal>();
    wp.SamplesReady = true;
    return wp;
}

private static int NormalizeRoadDirLikeOriginal(float dx, float dy)
{
    float ang = Mathf.Atan2(dx, dy) * (128f / Mathf.PI);
    int dir = Mathf.RoundToInt(ang);
    dir %= 256;
    if (dir < 0)
        dir += 256;
    return dir;
}

private static void Calk2RoadWayPointLikeOriginal(int x1, int y1, int x2, int y2, int n, int p, out int nx, out int ny)
{
    if (n <= 0)
    {
        nx = x2;
        ny = y2;
        return;
    }
    nx = (x1 * (n - p) + x2 * p) / n;
    ny = (y1 * (n - p) + y2 * p) / n;
}

private static void Calk3RoadWayPointLikeOriginal(int x1, int y1, int x2, int y2, int x3, int y3, int n, int p, out int nx, out int ny)
{
    if (n <= 0)
    {
        nx = x2;
        ny = y2;
        return;
    }
    nx = (x1 * (n - p) + x3 * p) / n + ((4 * x2 - 2 * (x1 + x3)) * p * (n - p)) / (n * n);
    ny = (y1 * (n - p) + y3 * p) / n + ((4 * y2 - 2 * (y1 + y3)) * p * (n - p)) / (n * n);
}

private static int CalcNormaLikeOriginal(int dx, int dy)
{
    dx = Math.Abs(dx);
    dy = Math.Abs(dy);
    int m = Math.Max(dx, dy);
    return (m + dx + dy) >> 1;
}

private static void AddRoadWayPointSampleLikeOriginal(List<RoadWayPointSampleLikeOriginal> samples, int xx, int yy)
{
    if (samples == null)
        return;
    if (samples.Count == 0)
    {
        samples.Add(new RoadWayPointSampleLikeOriginal { X = xx, Y = yy, Dir = 0 });
        return;
    }

    RoadWayPointSampleLikeOriginal prev = samples[samples.Count - 1];
    int dist = CalcNormaLikeOriginal(prev.X - xx, prev.Y - yy);
    if (dist > RoadWayPointToPointLikeOriginal.Step)
        samples.Add(new RoadWayPointSampleLikeOriginal { X = xx, Y = yy, Dir = 0 });
}

private static RoadWayPointToPointLikeOriginal BuildRoadWayPointToPointLikeOriginal(ParsedMap map, int startKnot, int endKnot)
{
    DecodedRoadNet net = map != null ? map.DecodedRne2 : null;
    if (net == null || net.Nodes == null || startKnot < 0 || endKnot < 0 || startKnot >= net.Nodes.Count || endKnot >= net.Nodes.Count)
        return null;

    RoadKnot st = net.Nodes[startKnot];
    RoadKnot en = net.Nodes[endKnot];
    if (st == null || en == null)
        return null;

    int startXOnRoad = st.HasOnRoad ? st.XOnRoad : st.X;
    int startYOnRoad = st.HasOnRoad ? st.YOnRoad : st.Y;
    int endXOnRoad = en.HasOnRoad ? en.XOnRoad : en.X;
    int endYOnRoad = en.HasOnRoad ? en.YOnRoad : en.Y;

    int dst = CalcNormaLikeOriginal(startXOnRoad - endXOnRoad, startYOnRoad - endYOnRoad);
    int piMax = dst / RoadWayPointToPointLikeOriginal.Step + 100;
    var samples = new List<RoadWayPointSampleLikeOriginal>(Math.Max(4, piMax));

    int mpx = (st.X + en.X) / 2;
    int mpy = (st.Y + en.Y) / 2;
    int dst1 = CalcNormaLikeOriginal(startXOnRoad - mpx, startYOnRoad - mpy);
    int dst2 = CalcNormaLikeOriginal(endXOnRoad - mpx, endYOnRoad - mpy);
    int xx, yy;

    if (st.NLinks == 2 && st.Links != null && st.Links.Length >= 2)
    {
        int prevNode = st.Links[0] == endKnot ? st.Links[1] : st.Links[0];
        if (prevNode >= 0 && prevNode < net.Nodes.Count)
        {
            int prx = net.Nodes[prevNode].X;
            int pry = net.Nodes[prevNode].Y;
            int mpprx = (st.X + prx) / 2;
            int mppry = (st.Y + pry) / 2;
            int dst1pr = CalcNormaLikeOriginal(mpx - mpprx, mpy - mppry);
            if (dst1pr == 0) dst1pr = 1;
            int npp = dst1pr / RoadWayPointToPointLikeOriginal.Step;
            int sP = (npp * dst1) / dst1pr;
            for (int p = sP; p < npp; p++)
            {
                Calk3RoadWayPointLikeOriginal(mpprx, mppry, startXOnRoad, startYOnRoad, mpx, mpy, npp, p, out xx, out yy);
                AddRoadWayPointSampleLikeOriginal(samples, xx, yy);
            }
        }
    }
    else
    {
        int npp = dst1 / RoadWayPointToPointLikeOriginal.Step;
        for (int p = 0; p < npp; p++)
        {
            Calk2RoadWayPointLikeOriginal(startXOnRoad, startYOnRoad, mpx, mpy, npp, p, out xx, out yy);
            AddRoadWayPointSampleLikeOriginal(samples, xx, yy);
        }
    }

    AddRoadWayPointSampleLikeOriginal(samples, mpx, mpy);

    if (en.NLinks == 2 && en.Links != null && en.Links.Length >= 2)
    {
        int nextNode = en.Links[0] == startKnot ? en.Links[1] : en.Links[0];
        if (nextNode >= 0 && nextNode < net.Nodes.Count)
        {
            int nnx = net.Nodes[nextNode].X;
            int nny = net.Nodes[nextNode].Y;
            int mpprx = (en.X + nnx) / 2;
            int mppry = (en.Y + nny) / 2;
            int dst2pr = CalcNormaLikeOriginal(mpx - mpprx, mpy - mppry);
            if (dst2pr == 0) dst2pr = 1;
            int npp = dst2pr / RoadWayPointToPointLikeOriginal.Step;
            int sP = (npp * dst2) / dst2pr;
            for (int p = 1; p < sP + 1; p++)
            {
                Calk3RoadWayPointLikeOriginal(mpx, mpy, endXOnRoad, endYOnRoad, mpprx, mppry, npp, p, out xx, out yy);
                AddRoadWayPointSampleLikeOriginal(samples, xx, yy);
            }
        }
    }
    else
    {
        int npp = dst2 / RoadWayPointToPointLikeOriginal.Step;
        for (int p = 1; p < npp + 1; p++)
        {
            Calk2RoadWayPointLikeOriginal(mpx, mpy, endXOnRoad, endYOnRoad, npp, p, out xx, out yy);
            AddRoadWayPointSampleLikeOriginal(samples, xx, yy);
        }
    }

    if (samples.Count == 0)
        AddRoadWayPointSampleLikeOriginal(samples, startXOnRoad, startYOnRoad);
    if (samples.Count == 1)
        AddRoadWayPointSampleLikeOriginal(samples, endXOnRoad, endYOnRoad);

    for (int i = 0; i < samples.Count - 2; i++)
    {
        RoadWayPointSampleLikeOriginal s0 = samples[i];
        RoadWayPointSampleLikeOriginal s2 = samples[i + 2];
        samples[i].Dir = (byte)NormalizeRoadDirLikeOriginal(s2.X - s0.X, s2.Y - s0.Y);
    }
    if (samples.Count >= 2)
    {
        byte tailDir = samples.Count >= 3 ? samples[samples.Count - 3].Dir : (byte)NormalizeRoadDirLikeOriginal(endXOnRoad - startXOnRoad, endYOnRoad - startYOnRoad);
        samples[samples.Count - 2].Dir = tailDir;
        samples[samples.Count - 1].Dir = tailDir;
    }

    return new RoadWayPointToPointLikeOriginal
    {
        StartKnot = startKnot,
        EndKnot = endKnot,
        Samples = samples.ToArray(),
        SamplesReady = true,
        Owner = 0xFFFFFFFFu,
        PreLockRequestor = 0xFFFFFFFFu
    };
}

private static int GetRoadWayPointsCoreLikeOriginal(ParsedMap map, RoadWayPointToPointLikeOriginal wp, int fromNode, int destNode, bool nearMode, byte turn)
{
    wp = EnsureRoadWayPointObjectBuiltLikeOriginal(map, wp);
    if (wp == null || wp.Samples == null || wp.Samples.Length <= 1)
        return 0;

    bool asc = fromNode == wp.StartKnot && destNode == wp.EndKnot;
    bool desc = fromNode == wp.EndKnot && destNode == wp.StartKnot;
    if (!asc && !desc)
        return 0;

    if (!nearMode)
        return wp.Samples.Length - 1;

    int rez = 0;
    int shift = 90;
    int bShift;
    int shiftStep = wp.Samples.Length > 0 ? shift / wp.Samples.Length : 0;
    if (turn == 0)
    {
        bShift = shift;
        shiftStep = 0;
    }
    else if (turn == 1)
    {
        bShift = shiftStep;
    }
    else
    {
        bShift = shift - shiftStep;
        shiftStep = -shiftStep;
    }

    int prevX = int.MinValue;
    int prevY = int.MinValue;
    if (asc)
    {
        for (int i = 0; i < wp.Samples.Length - 1; i++)
        {
            RoadWayPointSampleLikeOriginal s0 = wp.Samples[i + 1];
            float ang = s0.Dir * (Mathf.PI * 2f / 256f);
            int xx = s0.X - Mathf.RoundToInt((bShift + shiftStep * (i + 1)) * Mathf.Sin(ang));
            int yy = s0.Y + Mathf.RoundToInt((bShift + shiftStep * (i + 1)) * Mathf.Cos(ang));
            if (rez == 0 || CalcNormaLikeOriginal(prevX - xx, prevY - yy) > RoadWayPointToPointLikeOriginal.Step)
            {
                prevX = xx;
                prevY = yy;
                rez++;
            }
        }
    }
    else
    {
        for (int i = 1; i < wp.Samples.Length; i++)
        {
            RoadWayPointSampleLikeOriginal s0 = wp.Samples[wp.Samples.Length - i - 1];
            int dir = (s0.Dir + 128) & 255;
            float ang = dir * (Mathf.PI * 2f / 256f);
            int xx = s0.X - Mathf.RoundToInt((bShift + shiftStep * i) * Mathf.Sin(ang));
            int yy = s0.Y + Mathf.RoundToInt((bShift + shiftStep * i) * Mathf.Cos(ang));
            if (rez == 0 || CalcNormaLikeOriginal(prevX - xx, prevY - yy) > RoadWayPointToPointLikeOriginal.Step)
            {
                prevX = xx;
                prevY = yy;
                rez++;
            }
        }
    }

    return rez;
}

private static int GetRoadWayPointCountLikeOriginal(ParsedMap map, int fromNode, int destNode, ushort waypointIndex)
{
    EnsureRoadNetRuntimeLikeOriginal(map);
    if (map == null || map.RoadWayPointToPointLikeOriginal == null || waypointIndex == 0xFFFF || waypointIndex >= map.RoadWayPointToPointLikeOriginal.Length)
        return 0;

    RoadWayPointToPointLikeOriginal wp = map.RoadWayPointToPointLikeOriginal[waypointIndex];
    return GetRoadWayPointsCoreLikeOriginal(map, wp, fromNode, destNode, false, 0);
}

private static bool IsRoadWayPointOwnerActiveLikeOriginal(RoadWayPointToPointLikeOriginal wp)
{
    if (wp == null)
        return false;
    if ((uint)wp.Owner == 0xFFFFFFFFu)
        return false;
    if (wp.LockTime + (100 << 8) > GetRoadRuntimeTicksLikeOriginal())
        return true;
    wp.Owner = 0xFFFFFFFFu;
    wp.OwnerDirection = false;
    return false;
}

private static int GetRoadWayPointsLikeOriginal(ParsedMap map, int fromNode, int destNode, ushort waypointIndex, ref ushort flag, uint requestor)
{
    EnsureRoadNetRuntimeLikeOriginal(map);
    if (map == null || map.RoadWayPointToPointLikeOriginal == null || waypointIndex == 0xFFFF || waypointIndex >= map.RoadWayPointToPointLikeOriginal.Length)
        return 0;

    RoadWayPointToPointLikeOriginal wp = map.RoadWayPointToPointLikeOriginal[waypointIndex];
    if (wp == null)
        return 0;

    bool ascDir = fromNode == wp.StartKnot && destNode == wp.EndKnot;
    if ((uint)wp.Owner == 0xFFFFFFFFu && GetRoadWayPointPreLockLikeOriginal(wp) == 0)
    {
        wp.Owner = requestor;
        wp.OwnerDirection = ascDir;
        wp.LockTime = GetRoadRuntimeTicksLikeOriginal();
        flag = 0;
        return GetRoadWayPointsCoreLikeOriginal(map, wp, fromNode, destNode, false, 0);
    }

    if (GetRoadWayPointPreLockLikeOriginal(wp) > 1 && wp.PreLockRequestor != requestor)
    {
        byte turn = 0;
        if (flag == 0)
            turn = 1;
        flag = 2;
        if (wp.OwnerDirection == ascDir)
        {
            flag = 1;
            return 0;
        }
        return GetRoadWayPointsCoreLikeOriginal(map, wp, fromNode, destNode, true, turn);
    }

    if (requestor == wp.Owner || !IsRoadWayPointOwnerActiveLikeOriginal(wp))
    {
        wp.Owner = requestor;
        wp.OwnerDirection = ascDir;
        wp.LockTime = GetRoadRuntimeTicksLikeOriginal();
        if (flag == 2)
        {
            flag = 0;
            return GetRoadWayPointsCoreLikeOriginal(map, wp, fromNode, destNode, true, 2);
        }
        flag = 0;
        return GetRoadWayPointsCoreLikeOriginal(map, wp, fromNode, destNode, false, 0);
    }

    if (wp.OwnerDirection == ascDir)
    {
        flag = 1;
        return 0;
    }
    else
    {
        byte turn = 0;
        if (flag == 0)
            turn = 1;
        flag = 2;
        return GetRoadWayPointsCoreLikeOriginal(map, wp, fromNode, destNode, true, turn);
    }
}

private static int GetRoadRuntimeNextWayPointsLikeOriginal(ParsedMap map, int fromNode, int destNode)
{
    EnsureRoadNetRuntimeLikeOriginal(map);
    if (map == null || map.DecodedRne2 == null || map.DecodedRne2.Nodes == null || fromNode < 0 || fromNode >= map.DecodedRne2.Nodes.Count)
        return 0;

    RoadKnot node = map.DecodedRne2.Nodes[fromNode];
    if (node == null || node.Links == null || node.WayPointToPointIndex == null)
        return 0;

    int degree = Math.Min(Math.Max(node.NLinks, 0), Math.Min(node.Links.Length, node.WayPointToPointIndex.Length));
    for (int i = 0; i < degree; i++)
    {
        if (node.Links[i] != destNode)
            continue;
        return GetRoadWayPointCountLikeOriginal(map, fromNode, destNode, node.WayPointToPointIndex[i]);
    }
    return 0;
}

private static int GetRoadRuntimeNextWayPointsLikeOriginal(ParsedMap map, int fromNode, int destNode, ref ushort flag, uint requestor)
{
    EnsureRoadNetRuntimeLikeOriginal(map);
    if (map == null || map.DecodedRne2 == null || map.DecodedRne2.Nodes == null || fromNode < 0 || fromNode >= map.DecodedRne2.Nodes.Count)
        return 0;

    RoadKnot node = map.DecodedRne2.Nodes[fromNode];
    if (node == null || node.Links == null || node.WayPointToPointIndex == null)
        return 0;

    int degree = Math.Min(Math.Max(node.NLinks, 0), Math.Min(node.Links.Length, node.WayPointToPointIndex.Length));
    for (int i = 0; i < degree; i++)
    {
        if (node.Links[i] != destNode)
            continue;
        return GetRoadWayPointsLikeOriginal(map, fromNode, destNode, node.WayPointToPointIndex[i], ref flag, requestor);
    }
    return 0;
}

private static int SetRoadRuntimePreLockLikeOriginal(ParsedMap map, int fromNode, int destNode)
{
    return SetRoadRuntimePreLockLikeOriginal(map, fromNode, destNode, 0xFFFFFFFFu);
}

private static int SetRoadRuntimePreLockLikeOriginal(ParsedMap map, int fromNode, int destNode, uint requestor)
{
    EnsureRoadNetRuntimeLikeOriginal(map);
    if (map == null || map.DecodedRne2 == null || map.DecodedRne2.Nodes == null || fromNode < 0 || fromNode >= map.DecodedRne2.Nodes.Count)
        return 0;

    RoadKnot node = map.DecodedRne2.Nodes[fromNode];
    if (node == null || node.Links == null || node.WayPointToPointIndex == null)
        return 0;

    int degree = Math.Min(Math.Max(node.NLinks, 0), Math.Min(node.Links.Length, node.WayPointToPointIndex.Length));
    for (int i = 0; i < degree; i++)
    {
        if (node.Links[i] != destNode)
            continue;
        ushort wpIndex = node.WayPointToPointIndex[i];
        if (wpIndex == 0xFFFF || map.RoadWayPointToPointLikeOriginal == null || wpIndex >= map.RoadWayPointToPointLikeOriginal.Length)
            return 0;
        return SetRoadWayPointPreLockLikeOriginal(map.RoadWayPointToPointLikeOriginal[wpIndex], requestor);
    }
    return 0;
}

private static int GetRoadRuntimeTicksLikeOriginal()
{
    return Environment.TickCount & int.MaxValue;
}

private static int GetRoadWayPointPreLockLikeOriginal(RoadWayPointToPointLikeOriginal wp)
{
    if (wp == null)
        return 0;
    if (wp.PreLock != 0 && wp.PreLockTime + (64 << 8) < GetRoadRuntimeTicksLikeOriginal())
        wp.PreLock = 0;
    return wp.PreLock;
}

private static int SetRoadWayPointPreLockLikeOriginal(RoadWayPointToPointLikeOriginal wp, uint requestor)
{
    if (wp == null)
        return 0;
    GetRoadWayPointPreLockLikeOriginal(wp);
    if (wp.PreLock < ushort.MaxValue)
        wp.PreLock++;
    wp.PreLockTime = GetRoadRuntimeTicksLikeOriginal();
    wp.PreLockRequestor = requestor;
    return wp.PreLock;
}
private static bool TryReadRne2Node(byte[] raw, int offset, int stride, out RoadKnot node)
{
    node = new RoadKnot
    {
        Links = new ushort[Rne2MaxLink],
        RoadID = new ushort[Rne2MaxLink],
        LinkType = new byte[Rne2MaxLink],
        WayPointToPointIndex = new ushort[Rne2MaxLink]
    };
    for (int i = 0; i < Rne2MaxLink; i++)
    {
        node.Links[i] = 0xFFFF;
        node.RoadID[i] = 0xFFFF;
        node.WayPointToPointIndex[i] = 0xFFFF;
    }

    if (offset < 0 || offset + stride > raw.Length) return false;
    if (stride < 53) return false;

    node.X = ReadInt32LE(raw, offset + 0);
    node.Y = ReadInt32LE(raw, offset + 4);
    node.NLinks = ReadInt32LE(raw, offset + 8);
    node.Hidden = raw[offset + 12];

    int cursor;
    int xOnRoadOffset = -1;
    int yOnRoadOffset = -1;
    bool hasWaypoints = false;

    switch (stride)
    {
        case 77:
            cursor = offset + 13;
            hasWaypoints = true;
            xOnRoadOffset = offset + 69;
            yOnRoadOffset = offset + 73;
            break;
        case 80:
            cursor = offset + 14;
            hasWaypoints = true;
            xOnRoadOffset = offset + 72;
            yOnRoadOffset = offset + 76;
            break;
        case 53:
            cursor = offset + 13;
            break;
        case 56:
            cursor = offset + 14;
            break;
        default:
            if (stride >= 77)
            {
                cursor = offset + 13;
                hasWaypoints = true;
                xOnRoadOffset = offset + stride - 8;
                yOnRoadOffset = offset + stride - 4;
            }
            else
            {
                cursor = offset + 13;
            }
            break;
    }

    for (int i = 0; i < Rne2MaxLink; i++, cursor += 2)
        node.Links[i] = ReadUInt16LE(raw, cursor);

    for (int i = 0; i < Rne2MaxLink; i++, cursor += 2)
        node.RoadID[i] = ReadUInt16LE(raw, cursor);

    for (int i = 0; i < Rne2MaxLink; i++, cursor++)
        node.LinkType[i] = raw[cursor];

    if (hasWaypoints)
    {
        for (int i = 0; i < Rne2MaxLink; i++, cursor += 2)
            node.WayPointToPointIndex[i] = ReadUInt16LE(raw, cursor);
    }

    if (xOnRoadOffset >= 0 && yOnRoadOffset >= 0 && yOnRoadOffset + 4 <= offset + stride)
    {
        node.XOnRoad = ReadInt32LE(raw, xOnRoadOffset);
        node.YOnRoad = ReadInt32LE(raw, yOnRoadOffset);
        node.HasOnRoad = true;
    }

    return true;
}

private static bool HasRne2BackLink(RoadKnot node, int source)
{
    int degree = Math.Clamp(node.NLinks, 0, Rne2MaxLink);
    for (int i = 0; i < degree; i++)
    {
        if (node.Links[i] == source) return true;
    }
    return false;
}

private static string BuildRne2IntegritySummary(DecodedRoadNet net)
{
    if (net == null || net.Nodes == null || net.Nodes.Count == 0)
        return "missing";

    int nodes = net.Nodes.Count;
    int selfLinks = 0;
    int duplicateTargets = 0;
    int oneWayDirected = 0;
    int hiddenSources = 0;
    int hiddenDirected = 0;
    int isolated = 0;
    int maxDegree = 0;
    int minDegree = int.MaxValue;
    long degreeSum = 0;
    int multiRoadIdDirected = 0;
    int typeNon16Directed = 0;
    int roadDirected = 0;
    int waypointDirected = 0;
    int weakComponents = 0;

    var undirected = new List<int>[nodes];
    for (int i = 0; i < nodes; i++) undirected[i] = new List<int>();

    for (int i = 0; i < nodes; i++)
    {
        var node = net.Nodes[i];
        int degree = Math.Clamp(node.NLinks, 0, Rne2MaxLink);
        if (node.Hidden != 0) hiddenSources++;
        if (degree == 0) isolated++;
        minDegree = Math.Min(minDegree, degree);
        maxDegree = Math.Max(maxDegree, degree);
        degreeSum += degree;

        var seenTargets = new HashSet<int>();
        var roadIdsHere = new HashSet<int>();
        for (int q = 0; q < degree; q++)
        {
            int target = node.Links[q];
            if (target < 0 || target >= nodes) continue;
            if (target == i) selfLinks++;
            if (!seenTargets.Add(target)) duplicateTargets++;
            if (!HasRne2BackLink(net.Nodes[target], i)) oneWayDirected++;
            if (node.Hidden != 0) hiddenDirected++;
            if (node.RoadID[q] != 0xFFFF)
            {
                roadDirected++;
                roadIdsHere.Add(node.RoadID[q]);
            }
            if (node.WayPointToPointIndex[q] != 0xFFFF) waypointDirected++;
            if (node.LinkType[q] != 16) typeNon16Directed++;
            if (!undirected[i].Contains(target)) undirected[i].Add(target);
            if (!undirected[target].Contains(i)) undirected[target].Add(i);
        }
        if (roadIdsHere.Count > 1)
            multiRoadIdDirected += degree;
    }

    var visited = new bool[nodes];
    var queue = new Queue<int>();
    for (int i = 0; i < nodes; i++)
    {
        if (visited[i]) continue;
        weakComponents++;
        visited[i] = true;
        queue.Enqueue(i);
        while (queue.Count > 0)
        {
            int cur = queue.Dequeue();
            foreach (int nxt in undirected[cur])
            {
                if ((uint)nxt >= (uint)nodes || visited[nxt]) continue;
                visited[nxt] = true;
                queue.Enqueue(nxt);
            }
        }
    }

    if (minDegree == int.MaxValue) minDegree = 0;
    float avgDegree = nodes > 0 ? (float)degreeSum / nodes : 0f;

    return $"nodes={nodes} weakComponents={weakComponents} isolated={isolated} minDegree={minDegree} maxDegree={maxDegree} avgDegree={avgDegree:0.00} selfLinks={selfLinks} duplicateTargets={duplicateTargets} oneWayDirected={oneWayDirected} hiddenSources={hiddenSources} hiddenDirected={hiddenDirected} roadDirected={roadDirected} waypointDirected={waypointDirected} typeNon16Directed={typeNon16Directed} multiRoadIdDirected={multiRoadIdDirected}";
}

private static string BuildRne2IntegritySamples(DecodedRoadNet net)
{
    if (net == null || net.Nodes == null || net.Nodes.Count == 0)
        return "none";

    var parts = new List<string>();
    for (int i = 0; i < net.Nodes.Count && parts.Count < 3; i++)
    {
        var node = net.Nodes[i];
        int degree = Math.Clamp(node.NLinks, 0, Rne2MaxLink);
        if (degree <= 0) continue;

        int oneWay = 0;
        int dup = 0;
        int self = 0;
        var seenTargets = new HashSet<int>();
        var edgeParts = new List<string>();
        for (int q = 0; q < degree; q++)
        {
            int target = node.Links[q];
            bool back = target >= 0 && target < net.Nodes.Count && HasRne2BackLink(net.Nodes[target], i);
            if (!back) oneWay++;
            if (target == i) self++;
            if (!seenTargets.Add(target)) dup++;
            if (q < 3)
                edgeParts.Add($"{target}/r{node.RoadID[q]}/t{node.LinkType[q]}/w{node.WayPointToPointIndex[q]}/back={(back ? 1 : 0)}");
        }

        if (oneWay > 0 || dup > 0 || self > 0 || i < 3)
            parts.Add($"{i}@{node.X},{node.Y} deg={degree} oneWay={oneWay} dup={dup} self={self} edges={string.Join(",", edgeParts)}");
    }

    if (parts.Count == 0)
    {
        for (int i = 0; i < net.Nodes.Count && parts.Count < 3; i++)
        {
            var node = net.Nodes[i];
            int degree = Math.Clamp(node.NLinks, 0, Rne2MaxLink);
            if (degree <= 0) continue;
            var edgeParts = new List<string>();
            for (int q = 0; q < degree && q < 3; q++)
            {
                int target = node.Links[q];
                bool back = target >= 0 && target < net.Nodes.Count && HasRne2BackLink(net.Nodes[target], i);
                edgeParts.Add($"{target}/r{node.RoadID[q]}/t{node.LinkType[q]}/w{node.WayPointToPointIndex[q]}/back={(back ? 1 : 0)}");
            }
            parts.Add($"{i}@{node.X},{node.Y} deg={degree} edges={string.Join(",", edgeParts)}");
        }
    }

    return parts.Count > 0 ? string.Join(" | ", parts) : "none";
}


private static string BuildZoneSplitSummary(ParsedMap map)
{
    if (map == null) return "missing-map";
    int roadKnots = map.DecodedRne2 != null ? map.DecodedRne2.NodeCount : 0;
    return $"roadKnots={roadKnots} 0TPL={BuildZoneSpaceForTpl(map.Chunk0TPL, map.MaxTH, roadKnots)} 1TPL={BuildZoneSpaceForTpl(map.Chunk1TPL, map.MaxTH, roadKnots)} 2TPL={BuildZoneSpaceForTpl(map.Chunk2TPL, map.MaxTH, roadKnots)}";
}

private static string BuildZoneSplitSamples(ParsedMap map)
{
    if (map == null) return "missing-map";
    int roadKnots = map.DecodedRne2 != null ? map.DecodedRne2.NodeCount : 0;

    var parts = new List<string>();
    if (map.DecodedRne2 != null && map.DecodedRne2.Nodes.Count > 0)
    {
        RoadKnot first = map.DecodedRne2.Nodes[0];
        RoadKnot last = map.DecodedRne2.Nodes[map.DecodedRne2.Nodes.Count - 1];
        parts.Add($"road[0]={first.X},{first.Y}/deg={Math.Clamp(first.NLinks, 0, Rne2MaxLink)}");
        parts.Add($"road[{map.DecodedRne2.Nodes.Count - 1}]={last.X},{last.Y}/deg={Math.Clamp(last.NLinks, 0, Rne2MaxLink)}");
    }

    parts.Add($"0TPL={BuildZoneSampleForTpl(map.Chunk0TPL, roadKnots)}");
    parts.Add($"1TPL={BuildZoneSampleForTpl(map.Chunk1TPL, roadKnots)}");
    parts.Add($"2TPL={BuildZoneSampleForTpl(map.Chunk2TPL, roadKnots)}");
    return string.Join(" ", parts);
}

private static string BuildZoneSpaceForTpl(byte[] payload, int maxTH, int roadKnots)
{
    if (payload == null || payload.Length == 0) return "missing";
    if (!TryReadTplTopRef(payload, maxTH, out int areaCount, out _, out _, out string error))
        return error;

    int topFirst = roadKnots;
    int topLast = areaCount > 0 ? roadKnots + areaCount - 1 : roadKnots - 1;
    int totalSpan = areaCount > 0 ? roadKnots + areaCount : roadKnots;
    return $"areas={areaCount}; roadRange=0-{Math.Max(-1, roadKnots - 1)}; topRange={topFirst}-{topLast}; totalZoneSpan={totalSpan}";
}

private static string BuildZoneSampleForTpl(byte[] payload, int roadKnots)
{
    if (payload == null || payload.Length == 0) return "missing";
    if (!TryReadTplAreaHeaders(payload, out ushort[] ax, out ushort[] ay, out ushort[] linkCounts, out ushort[] firstQ0, out ushort[] firstQ1, out ushort[] firstQ2, out ushort[] firstQ3, out string error))
        return error;

    int areaCount = ax != null ? ax.Length : 0;
    if (areaCount <= 0) return "areas=0";

    int areaA = 0;
    int areaB = Math.Max(0, areaCount - 1);
    int areaTop = 0;
    int bestLinks = -1;
    for (int i = 0; i < areaCount; i++)
    {
        int lc = linkCounts[i];
        if (lc > bestLinks)
        {
            bestLinks = lc;
            areaTop = i;
        }
    }

    string fmt(int area)
    {
        int zone = roadKnots + area;
        return $"z{zone}=a{area}@{ax[area]},{ay[area]}/lc={linkCounts[area]}/q={firstQ0[area]},{firstQ1[area]},{firstQ2[area]},{firstQ3[area]}";
    }

    if (areaTop == areaA || areaTop == areaB)
        return $"{fmt(areaA)} | {fmt(areaB)}";
    return $"{fmt(areaA)} | {fmt(areaTop)} | {fmt(areaB)}";
}


private static string BuildTplTargetSpaceCompare(byte[] payload, int roadKnots)
{
    if (payload == null || payload.Length == 0) return "missing";
    if (!TryReadTplAreaLinks(payload, out ushort[] ax, out _, out _, out ushort[][] q0, out ushort[][] q1, out ushort[][] q2, out ushort[][] q3, out string error))
        return error;

    int areaCount = ax != null ? ax.Length : 0;
    int topStart = roadKnots;
    int topEndExclusive = roadKnots + areaCount;

    string f0 = BuildTplFieldSpaceSummary(q0, roadKnots, topStart, topEndExclusive, areaCount);
    string f1 = BuildTplFieldSpaceSummary(q1, roadKnots, topStart, topEndExclusive, areaCount);
    string f2 = BuildTplFieldSpaceSummary(q2, roadKnots, topStart, topEndExclusive, areaCount);
    string f3 = BuildTplFieldSpaceSummary(q3, roadKnots, topStart, topEndExclusive, areaCount);
    return $"areas={areaCount}; roadKnots={roadKnots}; q0={f0} q1={f1} q2={f2} q3={f3}";
}

private static string BuildTplFieldSpaceSummary(ushort[][] fields, int roadKnots, int topStart, int topEndExclusive, int areaCount)
{
    long total = 0;
    long sentinel = 0;
    long zero = 0;
    long roadDirect = 0;
    long topOffset = 0;
    long areaZeroBased = 0;
    int max = 0;

    if (fields != null)
    {
        foreach (ushort[] arr in fields)
        {
            if (arr == null) continue;
            foreach (ushort v in arr)
            {
                total++;
                if (v == 0xFFFF) { sentinel++; continue; }
                if (v == 0) zero++;
                if (v < roadKnots) roadDirect++;
                if (v >= topStart && v < topEndExclusive) topOffset++;
                if (v < areaCount) areaZeroBased++;
                if (v > max) max = v;
            }
        }
    }

    long nonSent = total - sentinel;
    string guess = GuessTplFieldTargetMode(nonSent, zero, roadDirect, topOffset, areaZeroBased, max);
    return $"tot={total},sent={sentinel},zero={zero},road={roadDirect},topOfs={topOffset},area0={areaZeroBased},max={max},guess={guess}";
}

private static string GuessTplFieldTargetMode(long nonSent, long zero, long roadDirect, long topOffset, long areaZeroBased, int max)
{
    if (nonSent <= 0) return "empty";
    if (zero == nonSent) return "all-zero";

    long best = Math.Max(roadDirect, Math.Max(topOffset, areaZeroBased));
    bool decisive = best * 4 >= nonSent * 3;

    if (decisive)
    {
        if (best == topOffset) return "top-offset";
        if (best == roadDirect) return "road-direct";
        if (best == areaZeroBased) return "area-zero-based";
    }

    if (max <= 32) return "small-enum-or-type";
    if (max <= 256) return "small-id-space";
    if (roadDirect > 0 && topOffset == 0 && areaZeroBased == 0) return "road-direct-weak";
    if (topOffset > 0 && roadDirect == 0) return "top-offset-weak";
    if (areaZeroBased > 0 && roadDirect == 0 && topOffset == 0) return "area-zero-based-weak";
    return "mixed";
}

private static string BuildTplTargetSpaceSamples(byte[] payload, int roadKnots)
{
    if (payload == null || payload.Length == 0) return "missing";
    if (!TryReadTplAreaLinks(payload, out ushort[] ax, out ushort[] ay, out ushort[] linkCounts, out ushort[][] q0, out ushort[][] q1, out ushort[][] q2, out ushort[][] q3, out string error))
        return error;

    int areaCount = ax != null ? ax.Length : 0;
    if (areaCount <= 0) return "areas=0";

    var areas = Enumerable.Range(0, areaCount)
        .Where(i => linkCounts[i] > 0)
        .OrderByDescending(i => linkCounts[i])
        .ThenBy(i => i)
        .Take(3)
        .ToArray();

    if (areas.Length == 0) return $"areas={areaCount}; samples=<none>";

    int topStart = roadKnots;
    int topEndExclusive = roadKnots + areaCount;
    string FormatVal(int value)
    {
        if (value == 0xFFFF) return "empty";
        if (value >= 0 && value < roadKnots) return $"road:{value}";
        if (value >= topStart && value < topEndExclusive) return $"top:{value - roadKnots}";
        if (value >= 0 && value < areaCount) return $"area0:{value}";
        return value.ToString();
    }

    var parts = new List<string>();
    foreach (int area in areas)
    {
        int idx = q0[area] != null && q0[area].Length > 0 ? 0 : -1;
        if (idx < 0)
        {
            parts.Add($"a{area}@{ax[area]},{ay[area]} lc={linkCounts[area]} <no-links>");
            continue;
        }

        parts.Add($"a{area}@{ax[area]},{ay[area]} lc={linkCounts[area]} q0={q0[area][idx]}[{FormatVal(q0[area][idx])}] q1={q1[area][idx]}[{FormatVal(q1[area][idx])}] q2={q2[area][idx]}[{FormatVal(q2[area][idx])}] q3={q3[area][idx]}[{FormatVal(q3[area][idx])}]");
    }

    return $"areas={areaCount}; roadKnots={roadKnots}; samples={string.Join(" | ", parts)}";
}

private static string GetRne2LayoutName(int stride)
{
    return stride switch
    {
        77 => "packed77",
        80 => "padded80",
        53 => "packed53-old",
        56 => "padded56-old",
        _ => $"stride{stride}"
    };
}

        private static byte[] MaybeDecompressM3d(byte[] raw, out bool wasCompressed, out string error)
        {
            wasCompressed = false;
            error = "";

            if (raw == null || raw.Length == 0)
            {
                error = "raw is empty";
                return null;
            }

            string rawMagic = ReadMagic4(raw);
            if (IsSupportedMapMagic(rawMagic))
            {
                Debug.Log($"[C2:MAP] GetTrueMapName1 exact raw path len={raw.Length} magic={rawMagic} head={ToHexHead(raw, 16)}");
                return raw;
            }

            if (!TryReadFCompressorHeader(raw, out byte compType, out int inLen, out int outLen))
            {
                error = "Неизвестный контейнер карты (ожидался FCompressor/3DMP/4DMP/5DMP).";
                return null;
            }

            int packedLen = Math.Min(raw.Length, 9 + inLen);
            byte[] fcompBlock = SliceBytes(raw, 0, packedLen);
            byte[] payload = SliceBytes(raw, 9, inLen);
            bool originalBzipProbe = StartsWithBzipMagic(payload);

            Debug.Log($"[C2:MAP] FCOMP type={compType} inLen={inLen} outLen={outLen} rawLen={raw.Length} blockLen={fcompBlock.Length} payloadLen={payload.Length} originalBzipProbe={originalBzipProbe}");
            Debug.Log($"[C2:MAP] FCOMP rawHead={ToHexHead(raw, 16)} payloadMagic={ReadMagic4(payload)} payloadHead={ToHexHead(payload, 16)}");

            if (originalBzipProbe)
            {
                if (!TryDecompressFCompressorBlockLikeOriginal(fcompBlock, payload, compType, inLen, outLen, out byte[] decodedExact, out string exactInfo))
                {
                    error = "GetTrueMapName1 exact BZh9 path failed: " + exactInfo;
                    return null;
                }

                wasCompressed = true;
                if (TryAcceptDecodedMapPayload(decodedExact, out byte[] acceptedExact, out string acceptedExactInfo))
                {
                    Debug.Log($"[C2:MAP] GetTrueMapName1 exact BZh9 path ok via {exactInfo}; accepted={acceptedExactInfo}; len={acceptedExact.Length} magic={ReadMagic4(acceptedExact)} head={ToHexHead(acceptedExact, 16)}");
                    return acceptedExact;
                }

                error = "GetTrueMapName1 exact BZh9 path produced unsupported stream: " + acceptedExactInfo;
                return null;
            }

            if (TryDecompressFCompressorBlockLikeOriginal(fcompBlock, payload, compType, inLen, outLen, out byte[] decodedCompat, out string compatInfo))
            {
                wasCompressed = compType == 1 || compType == 3 || compType == 4;
                if (TryAcceptDecodedMapPayload(decodedCompat, out byte[] acceptedCompat, out string acceptedCompatInfo))
                {
                    Debug.Log($"[C2:MAP] Compatibility FCOMP path ok via {compatInfo}; accepted={acceptedCompatInfo}; len={acceptedCompat.Length} magic={ReadMagic4(acceptedCompat)} head={ToHexHead(acceptedCompat, 16)}");
                    return acceptedCompat;
                }

                error = "FCOMP decoded but payload is not a supported map stream: " + acceptedCompatInfo;
                return null;
            }

            error = "FCOMP decode failed: " + compatInfo;
            return null;
        }

        private static bool TryDecompressFCompressorBlockLikeOriginal(byte[] fcompBlock, byte[] payload, byte compType, int inLen, int outLen, out byte[] decoded, out string info)
        {
            decoded = null;
            info = "";

            if (fcompBlock == null || fcompBlock.Length < 9)
            {
                info = "block too short";
                return false;
            }

            switch (compType)
            {
                case 0:
                {
                    int copyLen = Math.Min(Math.Min(inLen, outLen), payload != null ? payload.Length : 0);
                    if (copyLen <= 0)
                    {
                        info = "STORE payload empty";
                        return false;
                    }

                    decoded = new byte[copyLen];
                    Buffer.BlockCopy(payload, 0, decoded, 0, copyLen);
                    info = $"STORE copyLen={copyLen} payloadMagic={ReadMagic4(decoded)}";
                    return true;
                }

                case 1:
                {
                    if (!TryDecodeBzipPayload(payload, outLen, out decoded, out string bzInfo))
                    {
                        info = "BZ2 " + bzInfo;
                        return false;
                    }

                    info = "BZ2 " + bzInfo;
                    return true;
                }

                case 2:
                    info = "PPMd is not supported in original FCompressor.cpp either";
                    return false;

                case 3:
                case 4:
                {
                    if (!TryInvokeManagedDecompress(fcompBlock, payload, outLen, out decoded, out string managedInfo))
                    {
                        info = ((compType == 3) ? "LZO " : "FLZ ") + managedInfo;
                        return false;
                    }

                    info = ((compType == 3) ? "LZO " : "FLZ ") + managedInfo;
                    return true;
                }

                default:
                    info = "Unknown FCompressor type: " + compType;
                    return false;
            }
        }

        private static bool TryAcceptDecodedMapPayload(byte[] decoded, out byte[] accepted, out string info)
        {
            accepted = null;
            info = "";

            if (decoded == null || decoded.Length == 0)
            {
                info = "decoded empty";
                return false;
            }

            string magic = ReadMagic4(decoded);
            if (IsSupportedMapMagic(magic))
            {
                accepted = decoded;
                info = "direct map stream";
                return true;
            }

            accepted = NormalizeDecodedMapPayload(decoded, out string normalizeInfo);
            if (accepted != null)
            {
                info = normalizeInfo;
                return true;
            }

            info = "magic=" + magic + " head=" + ToHexHead(decoded, 16) + " normalize=" + normalizeInfo;
            return false;
        }

        private static string ReadMagic4(byte[] raw)
        {
            if (raw == null || raw.Length < 4) return "<short>";
            return System.Text.Encoding.ASCII.GetString(raw, 0, 4);
        }

        private static bool StartsWithTag(byte[] raw, string tag)
        {
            if (raw == null || raw.Length < 4 || string.IsNullOrEmpty(tag) || tag.Length != 4)
                return false;
            return raw[0] == (byte)tag[0] && raw[1] == (byte)tag[1] && raw[2] == (byte)tag[2] && raw[3] == (byte)tag[3];
        }

        private static bool StartsWithBzipMagic(byte[] raw)
        {
            if (raw == null || raw.Length < 4)
                return false;

            return raw[0] == (byte)'B'
                && raw[1] == (byte)'Z'
                && raw[2] == (byte)'h'
                && raw[3] >= (byte)'1'
                && raw[3] <= (byte)'9';
        }

        private static bool IsSupportedMapMagic(string magic)
        {
            return string.Equals(magic, "3DMP", StringComparison.Ordinal)
                || string.Equals(magic, "4DMP", StringComparison.Ordinal)
                || string.Equals(magic, "5DMP", StringComparison.Ordinal)
                || string.Equals(magic, "PMD3", StringComparison.Ordinal)
                || string.Equals(magic, "PMD4", StringComparison.Ordinal)
                || string.Equals(magic, "PMD5", StringComparison.Ordinal);
        }

        private static bool TryGetAddshFromMapMagic(string magic, out int addsh)
        {
            addsh = 0;
            if (string.IsNullOrEmpty(magic) || magic.Length != 4)
                return false;

            if ((magic[0] == '3' || magic[0] == '4' || magic[0] == '5')
                && magic[1] == 'D'
                && magic[2] == 'M'
                && magic[3] == 'P')
            {
                addsh = (magic[0] - '3') + 1;
                return addsh >= 1 && addsh <= 3;
            }

            if (magic[0] == 'P'
                && magic[1] == 'M'
                && magic[2] == 'D'
                && (magic[3] == '3' || magic[3] == '4' || magic[3] == '5'))
            {
                addsh = (magic[3] - '3') + 1;
                return addsh >= 1 && addsh <= 3;
            }

            return false;
        }

        private static void ApplyOriginalHeaderSetupArraysLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            int addsh = Mathf.Clamp(map.Addsh, 1, 3);
            map.Addsh = addsh;
            map.MaxSector = 128 << addsh;
            map.MaxTH = map.MaxSector * 2;
            map.MTHShift = 8 + addsh;
            map.VertInLine = map.MaxSector + map.MaxSector + 1;
            map.SectInLine = map.MaxSector * 6;
            map.MaxPointIndex = checked((map.MaxTH + 1) * map.MaxTH);
            map.MaxLineIndex = checked(map.MaxSector * map.MaxTH * 6);
            map.MapShift = 9 + addsh;

            map.MAPSX = 512 << addsh;
            map.MAPSY = map.MAPSX;
            map.WLX = 128 << (1 + addsh);
            map.MaxWX = map.MAPSX >> 1;
            map.MaxWY = map.MAPSY >> 1;
            map.MAPSHF = 6 + addsh;
            map.BMSX = 64 << addsh;
            map.B3SX = map.MAPSX >> (B3SHIFTLikeOriginal - 4);
            map.B3SY = map.MAPSY >> (B3SHIFTLikeOriginal - 4);
            map.B3SZ = checked(map.B3SX * map.B3SY);
            map.TopLx = map.MAPSX >> 2;
            map.TopLy = map.MAPSY >> 2;
            map.MaxTop = checked(map.TopLx * map.TopLy);
            map.TopSH = 7 + addsh;
            map.StratLx = (64 << addsh) >> 1;
            map.StratLy = map.StratLx;
            map.MAXCIOFS = checked((64 << addsh) * (64 << addsh));
            map.TSX = map.TopLx >> 2;
            map.SafeMLx = map.TopLx >> 4;
            map.SafeMSH = map.TopSH - 4;
            map.TSH = map.TopSH - 2;
            map.VertLx = map.TopLx >> 3;
            map.MaxLI = checked((64 << addsh) * (64 << addsh) * 4);
            map.MaxLIX = (64 << addsh) + (64 << addsh);
            map.MaxLIY = map.MaxLIX;
            map.StratSH = 5 + addsh;
            map.DangLx = map.TopLx >> 1;
            map.DangSH = map.TopSH - 1;
            map.RivNX = 64 << addsh;
            map.RivSH = 6 + addsh;
            map.SqMaxX = (480 << (addsh - 1)) * 32;
            map.SqMaxY = map.SqMaxX;
            map.SqDX = map.SqMaxX / 256;
            map.SqDY = map.SqMaxY / 256;
            map.ScrollMsxLikeOriginal = 240 << addsh;
            map.ScrollMsyLikeOriginal = 240 << addsh;

            map.TileWidth = map.VertInLine;
            map.TileHeight = map.MaxTH;

            ApplySetupArraysImmediateStateLikeOriginal(map);
        }

        private static string BuildHeaderSetupArraysDiagnostics(ParsedMap map)
        {
            if (map == null)
                return "map=null";

            return
                $"magic={map.HeaderMagic}; addsh={map.Addsh}; storedVertInLine={map.HeaderStoredVertInLine}; storedMaxTH={map.HeaderStoredMaxTH}; " +
                $"setupArraysVertInLine={map.VertInLine}; setupArraysMaxTH={map.MaxTH}; maxSector={map.MaxSector}; maxPointIndex={map.MaxPointIndex}; mapShift={map.MapShift}; mthShift={map.MTHShift}; sectInLine={map.SectInLine}; " +
                $"maps={map.MAPSX}x{map.MAPSY}; top={map.TopLx}x{map.TopLy}; dang={map.DangLx}; wlx={map.WLX}; bmsx={map.BMSX}; topo={(map.SetupTopologyApplied ? "yes" : "no")}; init3d={(map.Init3DMapSystemApplied ? "yes" : "no")}";
        }

