        private static string GetMethodNameLikeOriginal(Delegate d)
        {
            return d != null ? d.Method.Name : "<null>";
        }

        private static ITerraRectLikeOriginal CloneRectLikeOriginal(ITerraRectLikeOriginal src)
        {
            return src != null
                ? new ITerraRectLikeOriginal(src.X, src.Y, src.W, src.H)
                : new ITerraRectLikeOriginal();
        }

        private static void UnionRectLikeOriginal(ITerraRectLikeOriginal dst, ITerraRectLikeOriginal src)
        {
            if (dst == null || src == null)
                return;

            if (dst.W <= 0 || dst.H <= 0)
            {
                dst.X = src.X;
                dst.Y = src.Y;
                dst.W = src.W;
                dst.H = src.H;
                return;
            }

            int minX = Math.Min(dst.X, src.X);
            int minY = Math.Min(dst.Y, src.Y);
            int maxX = Math.Max(dst.X + dst.W, src.X + src.W);
            int maxY = Math.Max(dst.Y + dst.H, src.Y + src.H);
            dst.X = minX;
            dst.Y = minY;
            dst.W = Math.Max(0, maxX - minX);
            dst.H = Math.Max(0, maxY - minY);
        }

        private static void BindParsedMapToGlobalMutableStateLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            CopyGlobalMutableStateToParsedMapLikeOriginal(map);
        }

