        private static bool FillGroundZBufferLikeOriginal(ITerraRectLikeOriginal visibleRectLikeOriginal)
        {
            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            if (!terra.EnabledLikeOriginal || !terra.UseLiteralCallbackModelLikeOriginal)
                return false;

            terra.FillGroundZBufferInvocationsLikeOriginal++;
            string prevPhaseLikeOriginal = terra.ActiveHeightPhaseLikeOriginal ?? "cache";
            bool prevUseRenderHeightLikeOriginal = terra.UseRenderHeightCallbackLikeOriginal;
            terra.ActiveHeightPhaseLikeOriginal = "render";
            terra.UseRenderHeightCallbackLikeOriginal = true;
            try
            {
                UpdateVisiblePvsLikeOriginal(visibleRectLikeOriginal);
                return ITerraRenderLikeOriginal(visibleRectLikeOriginal);
            }
            finally
            {
                terra.UseRenderHeightCallbackLikeOriginal = prevUseRenderHeightLikeOriginal;
                terra.ActiveHeightPhaseLikeOriginal = prevPhaseLikeOriginal;
            }
        }

        private static void InvalidateTerrainPatchLikeOriginal(ITerraRectLikeOriginal rect)
        {
            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            ITerraRectLikeOriginal useRect = rect ?? terra.ExtentsLikeOriginal ?? new ITerraRectLikeOriginal();
            if (!terra.NeedUpdateTerrainCacheLikeOriginal)
            {
                terra.NeedUpdateTerrainCacheLikeOriginal = true;
                terra.DirtyTerrainRectLikeOriginal = CloneRectLikeOriginal(useRect);
            }
            else
            {
                UnionRectLikeOriginal(terra.DirtyTerrainRectLikeOriginal, useRect);
            }
            terra.LastInvalidatedRectLikeOriginal = CloneRectLikeOriginal(terra.DirtyTerrainRectLikeOriginal);
        }

        private static void ClearPvsLikeOriginal(ITerraRectLikeOriginal rect)
        {
            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            terra.ClearPvsCallsLikeOriginal++;
            terra.NeedClearPvsLikeOriginal = false;
            terra.LastPvsRectLikeOriginal = CloneRectLikeOriginal(rect ?? terra.ExtentsLikeOriginal);
            terra.PvsRevisionLikeOriginal++;
        }

        private static void UpdateVisiblePvsLikeOriginal(ITerraRectLikeOriginal visibleRectLikeOriginal)
        {
            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            ITerraRectLikeOriginal rect = CloneRectLikeOriginal(visibleRectLikeOriginal ?? terra.ExtentsLikeOriginal);
            if (terra.NeedClearPvsLikeOriginal || terra.LastPvsRectLikeOriginal == null || !RectEqualsLikeOriginal(terra.LastPvsRectLikeOriginal, rect))
                ClearPvsLikeOriginal(rect);
            terra.LastPvsVisibleCellsLikeOriginal = Math.Max(0, Mathf.RoundToInt((rect != null ? rect.W : 0f) / 32.0f) * Mathf.RoundToInt((rect != null ? rect.H : 0f) / 32.0f));
        }

        private static bool RectEqualsLikeOriginal(ITerraRectLikeOriginal a, ITerraRectLikeOriginal b)
        {
            if (ReferenceEquals(a, b))
                return true;
            if (a == null || b == null)
                return false;
            return Mathf.Approximately(a.X, b.X) && Mathf.Approximately(a.Y, b.Y) && Mathf.Approximately(a.W, b.W) && Mathf.Approximately(a.H, b.H);
        }

        private static void ITerraInvalidateAABBLikeOriginal(ITerraRectLikeOriginal rect)
        {
            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            terra.InvalidatedAabbCallsLikeOriginal++;
            terra.DirtyAabbLikeOriginal = false;
            terra.LastInvalidatedRectLikeOriginal = CloneRectLikeOriginal(rect);
        }

