        }

        private static int SampleHeightFromGlobalStateLikeOriginal(int x, int y, bool clampNegative)
        {
            GlobalTerrainRuntimeStateLikeOriginal global = EnsureGlobalTerrainRuntimeStateLikeOriginal();
            if (!global.Mode3DLikeOriginal || global.THMapLikeOriginal == null || global.VertInLine <= 0 || global.MaxTH <= 0)
                return 0;

            int col = Mathf.Clamp(Mathf.RoundToInt(x / 32.0f), 0, global.VertInLine - 1);
            int row = Mathf.Clamp(Mathf.RoundToInt(y / 64.0f), 0, global.MaxTH - 1);
            int idx = row * global.VertInLine + col;
            if (idx < 0 || idx >= global.THMapLikeOriginal.Length)
                return 0;

            int z = global.THMapLikeOriginal[idx];
            return clampNegative && z < 0 ? 0 : z;
        }

        private static bool ITerraRenderLikeOriginal(ITerraRectLikeOriginal visibleRectLikeOriginal)
        {
            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            if (!terra.EnabledLikeOriginal || !terra.UseLiteralCallbackModelLikeOriginal)
                return false;

            bool prevUseRenderHeightLikeOriginal = terra.UseRenderHeightCallbackLikeOriginal;
            string prevHeightPhaseLikeOriginal = terra.ActiveHeightPhaseLikeOriginal ?? "cache";
            terra.ActiveHeightPhaseLikeOriginal = "render";

            ITerraRectLikeOriginal renderRectLikeOriginal = CloneRectLikeOriginal(visibleRectLikeOriginal ?? terra.ExtentsLikeOriginal);
            if (renderRectLikeOriginal == null || renderRectLikeOriginal.W <= 0 || renderRectLikeOriginal.H <= 0)
                renderRectLikeOriginal = CloneRectLikeOriginal(terra.ExtentsLikeOriginal);

            terra.RenderInvocationsLikeOriginal++;
            terra.LastVisibleRectLikeOriginal = CloneRectLikeOriginal(renderRectLikeOriginal);

            if (terra.GetAabbCallbackLikeOriginal != null)
                terra.GetAabbCallbackLikeOriginal(renderRectLikeOriginal, terra.LastAabbLikeOriginal);

            if (terra.NeedUpdateTerrainCacheLikeOriginal)
            {
                ITerraRectLikeOriginal dirty = CloneRectLikeOriginal(terra.DirtyTerrainRectLikeOriginal != null && terra.DirtyTerrainRectLikeOriginal.W > 0 && terra.DirtyTerrainRectLikeOriginal.H > 0
                    ? terra.DirtyTerrainRectLikeOriginal
                    : renderRectLikeOriginal);
                ITerraInvalidateAABBLikeOriginal(dirty);
                ITerraInvalidateTextureLikeOriginal(dirty);
                ITerraInvalidateGeometryLikeOriginal(dirty);
                terra.NeedUpdateTerrainCacheLikeOriginal = false;
                terra.DirtyTerrainRectLikeOriginal = new ITerraRectLikeOriginal();
                terra.CacheRevisionLikeOriginal++;
                terra.NeedClearPvsLikeOriginal = true;
            }

            try
            {
                if (!terra.SurfaceTypeNewLikeOriginal && terra.TextureCallbackLikeOriginal != null)
                    terra.TextureCallbackLikeOriginal(0, renderRectLikeOriginal);
                if (terra.GeometryCallbackLikeOriginal != null)
                    terra.GeometryCallbackLikeOriginal(renderRectLikeOriginal, terra.ForcedLodLikeOriginal >= 0 ? terra.ForcedLodLikeOriginal : 0);
            }
            finally
            {
                terra.UseRenderHeightCallbackLikeOriginal = prevUseRenderHeightLikeOriginal;
                terra.ActiveHeightPhaseLikeOriginal = prevHeightPhaseLikeOriginal;
            }

            return true;
        }

        private static ITerraRectLikeOriginal BuildFullTerrainExtentsLikeOriginal(ParsedMap map)
        {
            int addsh = map != null ? Mathf.Clamp(map.Addsh, 1, 3) : Mathf.Clamp(EnsureGlobalTerrainRuntimeStateLikeOriginal().Addsh, 1, 3);
            if (addsh <= 0)
                return new ITerraRectLikeOriginal();

            int mapSideX = (256 << addsh) * 32;
            int mapSideY = (256 << addsh) * 64;
            return new ITerraRectLikeOriginal(0, 0, mapSideX, mapSideY);
        }

        private static void InitGroundZBufferLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            terra.EnabledLikeOriginal = true;
            terra.UseLiteralCallbackModelLikeOriginal = true;
            ITerraSetHeightCallbacksLikeOriginal(GetHeightCBLikeOriginal, GetHeightRenderLikeOriginal);
            ITerraSetAabbCallbackLikeOriginal(GetAABBCallbackLikeOriginal);
            SelectSurfaceTypeLikeOriginal(map, map.IsMeshSurface || map.SurfaceTypeNewLikeOriginal);
            ITerraSetLODBiasLikeOriginal(5000.0f);
            ITerraEnableVertexLightingLikeOriginal(false);
            ITerraSetBorderConfigFileLikeOriginal("Models\\Scripts\\mapborders.xml");
            ITerraSetHeightmapPowLikeOriginal((256 << map.Addsh) >> 3);
            ITerraSetExtentsLikeOriginal(BuildFullTerrainExtentsLikeOriginal(map));
            terra.LastVisibleRectLikeOriginal = CloneRectLikeOriginal(terra.ExtentsLikeOriginal);
            InvalidateTerrainPatchLikeOriginal(terra.ExtentsLikeOriginal);
            InstallGlobalMutableStateLikeOriginal(map, "InitGroundZBufferLikeOriginal");
        }

        private static void CopyRectLikeOriginal(ITerraRectLikeOriginal src, ITerraRectLikeOriginal dst)
        {
            if (src == null || dst == null)
                return;
            dst.X = src.X;
            dst.Y = src.Y;
            dst.W = src.W;
            dst.H = src.H;
        }

        private static void InvalidateITerraLikeOriginal(ParsedMap map, bool invalidateAabb, bool invalidateTexture, bool invalidateGeometry)
        {
            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            if (map != null && (terra.ExtentsLikeOriginal == null || terra.ExtentsLikeOriginal.W <= 0 || terra.ExtentsLikeOriginal.H <= 0))
                terra.ExtentsLikeOriginal = BuildFullTerrainExtentsLikeOriginal(map);

            ITerraRectLikeOriginal dirtyRect = CloneRectLikeOriginal(terra.ExtentsLikeOriginal);
            if (dirtyRect.W <= 0 || dirtyRect.H <= 0)
                dirtyRect = BuildFullTerrainExtentsLikeOriginal(map);

            if (invalidateAabb)
                terra.DirtyAabbLikeOriginal = true;
            if (invalidateTexture)
                terra.DirtyTextureLikeOriginal = true;
            if (invalidateGeometry)
                terra.DirtyGeometryLikeOriginal = true;

            if (invalidateAabb || invalidateTexture || invalidateGeometry)
                InvalidateTerrainPatchLikeOriginal(dirtyRect);
        }

        private static int GetHeightCBLikeOriginal(int x, int y)
        {
            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            terra.GetHeightInvocationsLikeOriginal++;
            return SampleHeightFromGlobalStateLikeOriginal(x, y, true);
        }

        private static int GetHeightRenderLikeOriginal(int x, int y)
        {
            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            terra.RenderHeightInvocationsLikeOriginal++;
            return SampleHeightFromGlobalStateLikeOriginal(x, y, true);
        }

        private static void GetAABBCallbackLikeOriginal(ITerraRectLikeOriginal mapExt, ITerraAabbLikeOriginal aabb)
        {
            if (aabb == null)
                return;

            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            terra.GetAabbInvocationsLikeOriginal++;

            ITerraRectLikeOriginal rc = mapExt ?? terra.ExtentsLikeOriginal ?? new ITerraRectLikeOriginal();
            aabb.MinX = rc.X;
            aabb.MinY = rc.Y;
            aabb.MaxX = rc.X + rc.W;
            aabb.MaxY = rc.Y + rc.H;
            aabb.MinZ = 1000000.0f;
            aabb.MaxZ = -1000000.0f;

            float yborder = rc.H * 4.0f;
            float bx = rc.X;
            float by = rc.Y - yborder;
            float ex = rc.X + rc.W;
            float ey = rc.Y + rc.H + yborder;

            float dx = (ex - bx) / 32.0f;
            float dy = (ey - by) / 32.0f;
            if (dx < 0.0001f) dx = 0.0001f;
            if (dy < 0.0001f) dy = 0.0001f;

            for (float fx = bx; fx <= ex; fx += dx)
            {
                for (float fy = by; fy <= ey; fy += dy)
                {
                    float h = terra.UseRenderHeightCallbackLikeOriginal && terra.RenderHeightCallbackLikeOriginal != null
                        ? terra.RenderHeightCallbackLikeOriginal(Mathf.RoundToInt(fx), Mathf.RoundToInt(fy))
                        : (terra.GetHeightCallbackLikeOriginal != null ? terra.GetHeightCallbackLikeOriginal(Mathf.RoundToInt(fx), Mathf.RoundToInt(fy)) : 0);
                    if (h < aabb.MinZ) aabb.MinZ = h;
                    if (h > aabb.MaxZ) aabb.MaxZ = h;
                }
            }

            if (aabb.MinZ > aabb.MaxZ)
            {
                aabb.MinZ = 0.0f;
                aabb.MaxZ = 0.0f;
            }
        }

        private static bool CreateGroundTextureCallbackLikeOriginal(int texId, ITerraRectLikeOriginal mapExt)
        {
            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            terra.TextureCallbackInvocationsLikeOriginal++;
            terra.LastTextureTexIdLikeOriginal = texId;
            terra.TextureCallbackNameLikeOriginal = nameof(CreateGroundTextureCallbackLikeOriginal);
            if (mapExt != null)
                CopyRectLikeOriginal(mapExt, terra.LastTextureRectLikeOriginal);
            terra.DirtyTextureLikeOriginal = false;
            return true;
        }

        private static bool CreateGroundGeometryCallbackLikeOriginal(ITerraRectLikeOriginal mapExt, int lod)
        {
            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            terra.GeometryCallbackInvocationsLikeOriginal++;
            terra.LastLodLikeOriginal = lod;
            terra.GeometryCallbackNameLikeOriginal = nameof(CreateGroundGeometryCallbackLikeOriginal);
            if (mapExt != null)
                CopyRectLikeOriginal(mapExt, terra.LastGeometryRectLikeOriginal);
            terra.DirtyGeometryLikeOriginal = false;

            if (terra.CurrentRendererLikeOriginal != null && terra.CurrentCameraLikeOriginal != null)
                terra.CurrentRendererLikeOriginal.RebuildFromITerraBackendGlobalStateLikeOriginal(terra.CurrentCameraLikeOriginal);

            return true;
        }

        private static bool ITCreateGeometryCallbackLikeOriginal(ITerraRectLikeOriginal mapExt, int lod)
        {
            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            terra.GeometryCallbackInvocationsLikeOriginal++;
            terra.LastLodLikeOriginal = lod;
