            if (mapExt != null)
                CopyRectLikeOriginal(mapExt, terra.LastGeometryRectLikeOriginal);
            terra.DirtyGeometryLikeOriginal = false;
            if (terra.CurrentRendererLikeOriginal != null && terra.CurrentCameraLikeOriginal != null)
                terra.CurrentRendererLikeOriginal.RebuildFromITerraBackendGlobalStateLikeOriginal(terra.CurrentCameraLikeOriginal);
            return true;
        }

