private static string BuildGlobalMutableStateSummaryLikeOriginal()
        {
            GlobalTerrainRuntimeStateLikeOriginal global = s_GlobalTerrainRuntimeStateLikeOriginal;
            if (global == null)
                return "global=null";

            int topFields = global.TopologyFieldsLikeOriginal != null ? global.TopologyFieldsLikeOriginal.Length : 0;
            int roadNodes = global.DecodedRne2 != null ? global.DecodedRne2.NodeCount : 0;
            return
                $"rev={global.Revision}; reason={global.LastReason}; source={Path.GetFileName(global.SourcePath ?? string.Empty)}; " +
                $"surface={global.SurfaceTypeLikeOriginal}; mode3d={(global.Mode3DLikeOriginal ? 1 : 0)}; mesh={(global.IsMeshSurface ? 1 : 0)}; " +
                $"grid={global.VertInLine}x{global.MaxTH}; points={global.MaxPointIndex}; maps={global.MAPSX}x{global.MAPSY}; top={global.TopLx}x{global.TopLy}; " +
                $"th={(global.THMapLikeOriginal != null ? global.THMapLikeOriginal.Length : 0)}; tex={(global.TexMapLikeOriginal != null ? global.TexMapLikeOriginal.Length : 0)}; fmap={(global.FactureMapStorageLikeOriginal != null ? global.FactureMapStorageLikeOriginal.Length : 0)}; " +
                $"motion={(global.MotionFieldMapsLikeOriginal != null ? global.MotionFieldMapsLikeOriginal.Length : 0)}; topFields={topFields}; activeTopType={global.ActiveTopTypeLikeOriginal}; roadNodes={roadNodes}; " +
                $"iterra={(global.ITerraEnabledLikeOriginal ? 1 : 0)} cbModel={(global.ITerraUseLiteralCallbackModelLikeOriginal ? 1 : 0)} new={(global.ITerraSurfaceTypeNewLikeOriginal ? 1 : 0)} " +
                $"texCb={global.ITerraTextureCallbackNameLikeOriginal} geoCb={global.ITerraGeometryCallbackNameLikeOriginal} hCb={global.ITerraHeightCallbackNameLikeOriginal} rhCb={global.ITerraRenderHeightCallbackNameLikeOriginal} aabbCb={global.ITerraAabbCallbackNameLikeOriginal} " +
                $"texCall={global.ITerraTextureCallbackInvocationsLikeOriginal} geoCall={global.ITerraGeometryCallbackInvocationsLikeOriginal} renderCall={global.ITerraRenderInvocationsLikeOriginal} fillZ={global.ITerraFillGroundZBufferInvocationsLikeOriginal} getH={global.ITerraGetHeightInvocationsLikeOriginal} renderH={global.ITerraRenderHeightInvocationsLikeOriginal} getAabb={global.ITerraGetAabbInvocationsLikeOriginal} phase={global.ITerraActiveHeightPhaseLikeOriginal} " +
                $"inv={global.ITerraInvalidatedAabbCallsLikeOriginal}/{global.ITerraInvalidatedTextureCallsLikeOriginal}/{global.ITerraInvalidatedGeometryCallsLikeOriginal} dirty={(global.ITerraNeedUpdateTerrainCacheLikeOriginal ? 1 : 0)} lod={global.ITerraLastLodLikeOriginal} cacheRev={global.ITerraCacheRevisionLikeOriginal} pvsClr={global.ITerraClearPvsCallsLikeOriginal} pvsRev={global.ITerraPvsRevisionLikeOriginal} pvsCells={global.ITerraLastPvsVisibleCellsLikeOriginal}";
        }

        private static void ApplySetupArraysImmediateStateLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            int pointCount = GetMaxPointIndexLikeOriginal(map);
            if (pointCount <= 0)
                return;

            EnsureMapXyShiftLikeOriginal(map);

            if (map.THMapLikeOriginal == null || map.THMapLikeOriginal.Length != pointCount)
                map.THMapLikeOriginal = new short[pointCount];

            if (map.TexMapLikeOriginal == null || map.TexMapLikeOriginal.Length != pointCount)
                map.TexMapLikeOriginal = new byte[pointCount];

            if (map.FactureMapStorageLikeOriginal == null || map.FactureMapStorageLikeOriginal.Length != pointCount)
                map.FactureMapStorageLikeOriginal = new byte[pointCount];

            if (map.FactureWeightStorageLikeOriginal == null || map.FactureWeightStorageLikeOriginal.Length != pointCount)
                map.FactureWeightStorageLikeOriginal = new byte[pointCount];

            if (map.FactureShiftLikeOriginal == null || map.FactureShiftLikeOriginal.Length != pointCount)
                map.FactureShiftLikeOriginal = new byte[pointCount];

            int riverCount = Math.Max(0, map.RivNX * map.RivNX);
            if (map.RivDirLikeOriginal == null || map.RivDirLikeOriginal.Length != riverCount)
                map.RivDirLikeOriginal = new byte[riverCount];
            if (map.RivVolLikeOriginal == null || map.RivVolLikeOriginal.Length != riverCount)
                map.RivVolLikeOriginal = new byte[riverCount];

            if (map.Addsh == 1)
            {
                int sectCount = Mathf.Max(0, map.MaxSector * map.MaxTH * 6);
                if (map.SectMapLikeOriginal == null || map.SectMapLikeOriginal.Length != sectCount)
                    map.SectMapLikeOriginal = new byte[sectCount];
            }
            else
            {
                map.SectMapLikeOriginal = null;
            }

            int maxCiofs = Math.Max(0, map.MAXCIOFS);
            if (map.MCountLikeOriginal == null || map.MCountLikeOriginal.Length != maxCiofs)
                map.MCountLikeOriginal = new byte[maxCiofs];
            if (map.MRefLikeOriginal == null || map.MRefLikeOriginal.Length != maxCiofs)
            {
                map.MRefLikeOriginal = new ushort[maxCiofs];
                FillUShortArrayLikeOriginal(map.MRefLikeOriginal, 0xFFFF);
            }
            if (map.BldListLikeOriginal == null || map.BldListLikeOriginal.Length != maxCiofs)
                map.BldListLikeOriginal = new int[maxCiofs];
            if (map.NPresenceLikeOriginal == null || map.NPresenceLikeOriginal.Length != maxCiofs)
                map.NPresenceLikeOriginal = new byte[maxCiofs];
            if (map.TmpMCLikeOriginal == null || map.TmpMCLikeOriginal.Length != maxCiofs)
                map.TmpMCLikeOriginal = new byte[maxCiofs];

            int spriteSize = Math.Max(0, (64 << Mathf.Clamp(map.Addsh, 1, 3)) * (64 << Mathf.Clamp(map.Addsh, 1, 3)));
            if (map.NSpriLikeOriginal == null || map.NSpriLikeOriginal.Length != spriteSize)
                map.NSpriLikeOriginal = new byte[spriteSize];
            if (map.SpRefsLikeOriginal == null || map.SpRefsLikeOriginal.Length != spriteSize)
                map.SpRefsLikeOriginal = new int[spriteSize];
            if (map.InfoMapLikeOriginal == null || map.InfoMapLikeOriginal.Length != spriteSize)
                map.InfoMapLikeOriginal = new byte[spriteSize];
            if (map.CantBuildLikeOriginal == null || map.CantBuildLikeOriginal.Length != spriteSize)
                map.CantBuildLikeOriginal = new byte[spriteSize];

            int waterQuarter = Math.Max(0, (map.MAPSX * map.MAPSY) >> 2);
            if (map.WaterDeepLikeOriginal == null || map.WaterDeepLikeOriginal.Length != waterQuarter)
                map.WaterDeepLikeOriginal = new byte[waterQuarter];
            if (map.WaterBrightLikeOriginal == null || map.WaterBrightLikeOriginal.Length != waterQuarter)
                map.WaterBrightLikeOriginal = new byte[waterQuarter];

            int motionMapSize = Math.Max(0, map.MAPSY * map.BMSX);
            if (map.MotionFieldMapsLikeOriginal == null || map.MotionFieldMapsLikeOriginal.Length != TopologyFieldCountLikeOriginal)
                map.MotionFieldMapsLikeOriginal = new byte[TopologyFieldCountLikeOriginal][];
            for (int i = 0; i < TopologyFieldCountLikeOriginal; i++)
            {
                if (map.MotionFieldMapsLikeOriginal[i] == null || map.MotionFieldMapsLikeOriginal[i].Length != motionMapSize)
                    map.MotionFieldMapsLikeOriginal[i] = new byte[motionMapSize];
            }
            if (map.TempMFMapLikeOriginal == null || map.TempMFMapLikeOriginal.Length != motionMapSize)
                map.TempMFMapLikeOriginal = new byte[motionMapSize];
            if (map.UnitsFieldMapLikeOriginal == null || map.UnitsFieldMapLikeOriginal.Length != motionMapSize)
                map.UnitsFieldMapLikeOriginal = new byte[motionMapSize];

            int b3Size = Math.Max(0, map.B3SZ);
            if (map.NObj3LikeOriginal == null || map.NObj3LikeOriginal.Length != b3Size)
                map.NObj3LikeOriginal = new ushort[b3Size];

            int dangCount = Mathf.Max(0, map.DangLx * map.DangLx);
            if (map.DangMapLikeOriginal == null || map.DangMapLikeOriginal.Length != dangCount)
                map.DangMapLikeOriginal = new byte[dangCount];
            if (map.DchTimeLikeOriginal == null || map.DchTimeLikeOriginal.Length != dangCount)
                map.DchTimeLikeOriginal = new ushort[dangCount];

            if (!map.SetupTopologyApplied)
                SetupTopologyLikeOriginal(map);
            if (!map.Init3DMapSystemApplied)
                Init3DMapSystemLikeOriginal(map);
            if (!map.FogSetupAppliedLikeOriginal)
                SetupFogLikeOriginal(map);
            if (!map.GpMapInitializedLikeOriginal)
                InitGPMAPLikeOriginal(map);
            if (!map.PointTexInitializedLikeOriginal)
                SetupPointTexsLikeOriginal(map);

            InstallGlobalMutableStateLikeOriginal(map, "ApplySetupArraysImmediateStateLikeOriginal");
        }

        private static void SetupTopologyLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            int topCellCount = Math.Max(0, map.TopLx * map.TopLx);
            map.SetupTopologyApplied = true;
            map.TopologyHashFieldCount = TopologyFieldCountLikeOriginal;
            map.TopologyFieldKindsLikeOriginal = new[] { 0, 1, 2, 3 };

            if (map.TopologyFieldsLikeOriginal == null || map.TopologyFieldsLikeOriginal.Length != TopologyFieldCountLikeOriginal)
                map.TopologyFieldsLikeOriginal = new TopologyHashTableLikeOriginal[TopologyFieldCountLikeOriginal];

            for (int i = 0; i < TopologyFieldCountLikeOriginal; i++)
            {
                TopologyHashTableLikeOriginal field = map.TopologyFieldsLikeOriginal[i];
                if (field == null)
                {
                    field = new TopologyHashTableLikeOriginal();
                    map.TopologyFieldsLikeOriginal[i] = field;
                }

                field.TopType = (byte)i;
                field.EnsureHashStorageLikeOriginal(TopologyHashKeyCountLikeOriginal);

                if (field.TopRef == null || field.TopRef.Length != topCellCount)
                {
                    field.TopRef = new ushort[topCellCount];
                    FillUShortArrayLikeOriginal(field.TopRef, 0xFFFF);
                }

                if (field.TopMap == null)
                    field.TopMap = Array.Empty<TopologyAreaLikeOriginal>();
                field.NAreas = Math.Max(0, field.NAreas);
                field.MaxArea = Math.Max(field.MaxArea, field.NAreas);
            }

            if (map.ActiveTopTypeLikeOriginal < 0 || map.ActiveTopTypeLikeOriginal >= TopologyFieldCountLikeOriginal)
                map.ActiveTopTypeLikeOriginal = 0;
            map.ActiveTopRefLikeOriginal = map.TopologyFieldsLikeOriginal[map.ActiveTopTypeLikeOriginal].TopRef;
            InstallGlobalMutableStateLikeOriginal(map, "SetupTopologyLikeOriginal");
        }

        private static void Init3DMapSystemLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            map.Init3DMapSystemApplied = true;
            map.Mode3DLikeOriginal = true;

            if (map.THMapLikeOriginal != null)
                Array.Clear(map.THMapLikeOriginal, 0, map.THMapLikeOriginal.Length);

            if (map.TexMapLikeOriginal != null)
                Array.Clear(map.TexMapLikeOriginal, 0, map.TexMapLikeOriginal.Length);
            if (map.FactureMapStorageLikeOriginal != null)
                Array.Clear(map.FactureMapStorageLikeOriginal, 0, map.FactureMapStorageLikeOriginal.Length);
            if (map.FactureWeightStorageLikeOriginal != null)
                Array.Clear(map.FactureWeightStorageLikeOriginal, 0, map.FactureWeightStorageLikeOriginal.Length);
            if (map.FactureShiftLikeOriginal != null)
                Array.Clear(map.FactureShiftLikeOriginal, 0, map.FactureShiftLikeOriginal.Length);

            if (map.RivDirLikeOriginal != null)
                Array.Clear(map.RivDirLikeOriginal, 0, map.RivDirLikeOriginal.Length);
            if (map.RivVolLikeOriginal != null)
                Array.Clear(map.RivVolLikeOriginal, 0, map.RivVolLikeOriginal.Length);

            if (map.MCountLikeOriginal != null)
                Array.Clear(map.MCountLikeOriginal, 0, map.MCountLikeOriginal.Length);
            if (map.MRefLikeOriginal != null)
                FillUShortArrayLikeOriginal(map.MRefLikeOriginal, 0xFFFF);
            if (map.BldListLikeOriginal != null)
                Array.Clear(map.BldListLikeOriginal, 0, map.BldListLikeOriginal.Length);
            if (map.NPresenceLikeOriginal != null)
                Array.Clear(map.NPresenceLikeOriginal, 0, map.NPresenceLikeOriginal.Length);
            if (map.TmpMCLikeOriginal != null)
                Array.Clear(map.TmpMCLikeOriginal, 0, map.TmpMCLikeOriginal.Length);

            if (map.NSpriLikeOriginal != null)
                Array.Clear(map.NSpriLikeOriginal, 0, map.NSpriLikeOriginal.Length);
            if (map.SpRefsLikeOriginal != null)
                Array.Clear(map.SpRefsLikeOriginal, 0, map.SpRefsLikeOriginal.Length);
            if (map.WaterDeepLikeOriginal != null)
                Array.Clear(map.WaterDeepLikeOriginal, 0, map.WaterDeepLikeOriginal.Length);
            if (map.WaterBrightLikeOriginal != null)
                Array.Clear(map.WaterBrightLikeOriginal, 0, map.WaterBrightLikeOriginal.Length);

            if (map.MotionFieldMapsLikeOriginal != null)
            {
                for (int i = 0; i < map.MotionFieldMapsLikeOriginal.Length; i++)
                {
                    if (map.MotionFieldMapsLikeOriginal[i] != null)
                        Array.Clear(map.MotionFieldMapsLikeOriginal[i], 0, map.MotionFieldMapsLikeOriginal[i].Length);
                }
            }
            if (map.TempMFMapLikeOriginal != null)
                Array.Clear(map.TempMFMapLikeOriginal, 0, map.TempMFMapLikeOriginal.Length);
            if (map.UnitsFieldMapLikeOriginal != null)
                Array.Clear(map.UnitsFieldMapLikeOriginal, 0, map.UnitsFieldMapLikeOriginal.Length);
            if (map.NObj3LikeOriginal != null)
                Array.Clear(map.NObj3LikeOriginal, 0, map.NObj3LikeOriginal.Length);
            if (map.InfoMapLikeOriginal != null)
                Array.Clear(map.InfoMapLikeOriginal, 0, map.InfoMapLikeOriginal.Length);
            if (map.CantBuildLikeOriginal != null)
                Array.Clear(map.CantBuildLikeOriginal, 0, map.CantBuildLikeOriginal.Length);
            map.FishLxLikeOriginal = 0;
            map.FishMapLikeOriginal = Array.Empty<byte>();
            FreeFogLikeOriginal(map);
            FreeGPMAPLikeOriginal(map);
            FreePointsTexLikeOriginal(map);

            if (map.SectMapLikeOriginal != null)
                InitializeSectMapLikeOriginal(map);

            if (map.DangMapLikeOriginal != null)
                Array.Clear(map.DangMapLikeOriginal, 0, map.DangMapLikeOriginal.Length);
            if (map.DchTimeLikeOriginal != null)
                Array.Clear(map.DchTimeLikeOriginal, 0, map.DchTimeLikeOriginal.Length);

            if (map.TopologyFieldsLikeOriginal != null)
            {
                for (int i = 0; i < map.TopologyFieldsLikeOriginal.Length; i++)
                {
                    TopologyHashTableLikeOriginal field = map.TopologyFieldsLikeOriginal[i];
                    if (field == null)
                        continue;
                    field.ClearHashLikeOriginal();
                    if (field.TopRef != null)
                        FillUShortArrayLikeOriginal(field.TopRef, 0xFFFF);
                    field.TopMap = Array.Empty<TopologyAreaLikeOriginal>();
                    field.NAreas = 0;
                    field.MaxArea = 0;
                    field.SourceChunkTag = "";
                }
            }
            map.ActiveTopTypeLikeOriginal = 0;
            map.ActiveTopRefLikeOriginal = map.TopologyFieldsLikeOriginal != null && map.TopologyFieldsLikeOriginal.Length > 0
                ? map.TopologyFieldsLikeOriginal[0].TopRef
                : null;
            map.TopologyRuntimeReadyLikeOriginal = false;

            if (string.IsNullOrEmpty(map.SurfaceTypeLikeOriginal))
                map.SurfaceTypeLikeOriginal = "unknown";

            InitGroundZBufferLikeOriginal(map);
            InstallGlobalMutableStateLikeOriginal(map, "Init3DMapSystemLikeOriginal");
        }


        private static void SetupFogLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            int shift = Math.Max(0, map.Addsh - 1);
            map.FmsxLikeOriginal = 134 << shift;
            map.Fmsx2LikeOriginal = map.FmsxLikeOriginal << 1;

            int fogSide = Math.Max(1, map.FmsxLikeOriginal);
            int fogCellCount = checked(fogSide * fogSide);
            if (map.FogMapLikeOriginal == null || map.FogMapLikeOriginal.Length != fogCellCount)
                map.FogMapLikeOriginal = new ushort[fogCellCount];
            else
                Array.Clear(map.FogMapLikeOriginal, 0, map.FogMapLikeOriginal.Length);

            if (map.FogMap1LikeOriginal == null || map.FogMap1LikeOriginal.Length != fogCellCount)
                map.FogMap1LikeOriginal = new ushort[fogCellCount];
            else
                Array.Clear(map.FogMap1LikeOriginal, 0, map.FogMap1LikeOriginal.Length);

            if (map.FogOffsetsLikeOriginal == null || map.FogOffsetsLikeOriginal.Length != 1024)
                map.FogOffsetsLikeOriginal = new int[1024];

            for (int i = 0; i < map.FogOffsetsLikeOriginal.Length; i++)
                map.FogOffsetsLikeOriginal[i] = i * map.FmsxLikeOriginal;

            ClearFogLikeOriginal(map);
            map.FogSetupAppliedLikeOriginal = true;
        }


        private static void ClearFogLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;
            if (map.FogMapLikeOriginal != null)
                Array.Clear(map.FogMapLikeOriginal, 0, map.FogMapLikeOriginal.Length);
            if (map.FogMap1LikeOriginal != null)
                Array.Clear(map.FogMap1LikeOriginal, 0, map.FogMap1LikeOriginal.Length);
            if (map.ScreenFogTileLikeOriginal != null)
                Array.Clear(map.ScreenFogTileLikeOriginal, 0, map.ScreenFogTileLikeOriginal.Length);
            map.ScreenFogWidthLikeOriginal = 0;
            map.ScreenFogHeightLikeOriginal = 0;
        }

        private static void FreeFogLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;
            map.FogOffsetsLikeOriginal = Array.Empty<int>();
            map.FogMapLikeOriginal = Array.Empty<ushort>();
            map.FogMap1LikeOriginal = Array.Empty<ushort>();
            map.ScreenFogTileLikeOriginal = Array.Empty<byte>();
            map.ScreenFogWidthLikeOriginal = 0;
            map.ScreenFogHeightLikeOriginal = 0;
            map.FmsxLikeOriginal = 0;
            map.Fmsx2LikeOriginal = 0;
            map.FogSetupAppliedLikeOriginal = false;
        }

        private static void EnsureScreenFogTileLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;
            int count = ScreenFogSideLikeOriginal * ScreenFogSideLikeOriginal;
            if (map.ScreenFogTileLikeOriginal == null || map.ScreenFogTileLikeOriginal.Length != count)
                map.ScreenFogTileLikeOriginal = new byte[count];
        }

        private static void ProcessFog1_1LikeOriginal(ParsedMap map)
        {
            if (map == null || map.FogMapLikeOriginal == null || map.FogMap1LikeOriginal == null)
                return;

            int side = map.FmsxLikeOriginal;
            if (side <= 2 || map.FogMapLikeOriginal.Length < side * side || map.FogMap1LikeOriginal.Length < side * side)
                return;

            Array.Copy(map.FogMapLikeOriginal, map.FogMap1LikeOriginal, side * side);
            for (int y = 1; y < side - 1; y++)
            {
                int row = y * side;
                for (int x = 1; x < side - 1; x++)
                {
                    int ofs = row + x;
                    int sum = map.FogMap1LikeOriginal[ofs - side]
                            + map.FogMap1LikeOriginal[ofs + side]
                            + map.FogMap1LikeOriginal[ofs - 1]
                            + map.FogMap1LikeOriginal[ofs + 1];
                    int ax = sum >> 2;
                    ax -= (sum >> 8);
                    if (ax > FogMinLikeOriginal && ax > map.FogMapLikeOriginal[ofs])
                        map.FogMapLikeOriginal[ofs] = (ushort)Mathf.Clamp(ax, 0, 0xFFFF);
                }
            }
        }


        private static void SetScreenFog16x16LikeOriginal(ParsedMap map, int mapX, int mapY, int smaplx, int smaply, int maxShad)
        {
            if (map == null || map.FogMapLikeOriginal == null || map.FmsxLikeOriginal <= 0)
                return;

            EnsureScreenFogTileLikeOriginal(map);

            int srcLx = Mathf.Max(0, smaplx + 1);
            int srcLy = Mathf.Max(0, smaply + 1);
            int lx2 = Mathf.Clamp(srcLx << 1, 0, ScreenFogSideLikeOriginal - 2);
            int ly2 = Mathf.Clamp(srcLy << 1, 0, ScreenFogSideLikeOriginal - 2);
            map.ScreenFogWidthLikeOriginal = Mathf.Max(0, lx2);
            map.ScreenFogHeightLikeOriginal = Mathf.Max(0, ly2);

            Array.Clear(map.ScreenFogTileLikeOriginal, 0, map.ScreenFogTileLikeOriginal.Length);

            int side = map.FmsxLikeOriginal;
            int startX = Mathf.Clamp(mapX - 1, 0, side - 1);
            int startY = Mathf.Clamp(mapY - 1, 0, side - 1);
            int minShad = maxShad - (32 << FogShiftLikeOriginal);

            for (int y = 0; y < srcLy && (startY + y) < side; y++)
            {
                int dstRow0 = (y << 1) + 1;
                int dstRow1 = dstRow0 + 1;
                for (int x = 0; x < srcLx && (startX + x) < side; x++)
                {
                    ushort src = map.FogMapLikeOriginal[(startY + y) * side + (startX + x)];
                    int fog;
                    if (src >= maxShad)
                        fog = 0;
                    else if (src <= minShad)
                        fog = 32;
                    else
                        fog = (maxShad - src) >> FogShiftLikeOriginal;

                    fog = Mathf.Clamp(fog, 0, 32);
                    int dstCol0 = (x << 1) + 1;
                    int dstCol1 = dstCol0 + 1;

                    int ofs00 = dstRow0 * ScreenFogSideLikeOriginal + dstCol0;
                    int ofs01 = ofs00 + 1;
                    int ofs10 = dstRow1 * ScreenFogSideLikeOriginal + dstCol0;
                    int ofs11 = ofs10 + 1;

                    if ((uint)ofs00 < (uint)map.ScreenFogTileLikeOriginal.Length) map.ScreenFogTileLikeOriginal[ofs00] = (byte)fog;
                    if ((uint)ofs01 < (uint)map.ScreenFogTileLikeOriginal.Length) map.ScreenFogTileLikeOriginal[ofs01] = (byte)fog;
                    if ((uint)ofs10 < (uint)map.ScreenFogTileLikeOriginal.Length) map.ScreenFogTileLikeOriginal[ofs10] = (byte)fog;
                    if ((uint)ofs11 < (uint)map.ScreenFogTileLikeOriginal.Length) map.ScreenFogTileLikeOriginal[ofs11] = (byte)fog;
                }
            }
        }



        private static void ProcessScreenFog16x16LikeOriginal(ParsedMap map, int smaplx, int smaply)
        {
            if (map == null || map.ScreenFogTileLikeOriginal == null || map.ScreenFogTileLikeOriginal.Length != ScreenFogSideLikeOriginal * ScreenFogSideLikeOriginal)
                return;

            int lx2 = Mathf.Clamp((Mathf.Max(0, smaplx + 1)) << 1, 0, ScreenFogSideLikeOriginal - 2);
            int ly2 = Mathf.Clamp((Mathf.Max(0, smaply + 1)) << 1, 0, ScreenFogSideLikeOriginal - 2);
            if (lx2 <= 0 || ly2 <= 0)
                return;

            byte[] src = (byte[])map.ScreenFogTileLikeOriginal.Clone();
            for (int y = 1; y <= ly2; y++)
            {
                for (int x = 1; x <= lx2; x++)
                {
                    int ofs = y * ScreenFogSideLikeOriginal + x;
                    int ax = src[ofs - 1] + src[ofs + 1] + src[ofs - ScreenFogSideLikeOriginal] + src[ofs + ScreenFogSideLikeOriginal];
                    ax >>= 2;
                    map.ScreenFogTileLikeOriginal[ofs] = (byte)Mathf.Clamp(ax, 0, 31);
                }
            }
        }


        private static void InitGPMAPLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            InitSFPICTLikeOriginal(map);

            int valMaxCx = 64 << map.Addsh;
            int cellCount = checked(valMaxCx * valMaxCx);
            map.GpMapCellCountLikeOriginal = cellCount;

            if (map.GpMapLikeOriginal == null || map.GpMapLikeOriginal.Length != cellCount)
                map.GpMapLikeOriginal = new OneGPieceLikeOriginal[cellCount][];
            else
                Array.Clear(map.GpMapLikeOriginal, 0, map.GpMapLikeOriginal.Length);

            if (map.NInGpMapLikeOriginal == null || map.NInGpMapLikeOriginal.Length != cellCount)
                map.NInGpMapLikeOriginal = new ushort[cellCount];
            else
                Array.Clear(map.NInGpMapLikeOriginal, 0, map.NInGpMapLikeOriginal.Length);

            if (map.DirtyGpCellsLikeOriginal == null || map.DirtyGpCellsLikeOriginal.Length != MaxDirtyGpCellsLikeOriginal)
                map.DirtyGpCellsLikeOriginal = new int[MaxDirtyGpCellsLikeOriginal];
            else
                Array.Clear(map.DirtyGpCellsLikeOriginal, 0, map.DirtyGpCellsLikeOriginal.Length);

            map.DirtyGpCellCountLikeOriginal = 0;
            map.GpMapInitializedLikeOriginal = true;
        }


        private static void InitFlowTexLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            if (map.FlowTexLikeOriginal == null || map.FlowTexLikeOriginal.Length != 256 * (256 + 24))
                map.FlowTexLikeOriginal = new byte[256 * (256 + 24)];
            else
                Array.Clear(map.FlowTexLikeOriginal, 0, map.FlowTexLikeOriginal.Length);

            map.FlowTexNamesLikeOriginal = new string[TextureCoverSlotsLikeOriginal];
            for (int i = 0; i < map.FlowTexNamesLikeOriginal.Length; i++)
                map.FlowTexNamesLikeOriginal[i] = $"Ground\\tex{i}.bmp";

            map.WaveTexLikeOriginal =
                TryLoadTextureByExactResourcePathLikeOriginal("Wave0.bmp")
                ?? TryLoadTextureByExactResourcePathLikeOriginal("textures/Wave0.bmp")
                ?? TryLoadTextureByExactResourcePathLikeOriginal("Wave0");

            InitializeTextureCoverageLikeOriginal(map);
            TryPreloadPenaLikeOriginal(map);
            map.FlowTexInitializedLikeOriginal = true;
        }



        private static void InitializeTextureCoverageLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            var cover = map.TCoverLikeOriginal ?? new TextureCoverageLikeOriginal();
            int totalSlots = TextureCoverSlotsLikeOriginal << 6;
            if (cover.TxCash == null || cover.TxCash.Length != totalSlots)
                cover.TxCash = new OneCashedTextureLikeOriginal[totalSlots];
            if (cover.SourceNames == null || cover.SourceNames.Length != TextureCoverSlotsLikeOriginal)
                cover.SourceNames = new string[TextureCoverSlotsLikeOriginal];

            int loaded = 0;
            for (int i = 0; i < TextureCoverSlotsLikeOriginal; i++)
            {
                string name = $"Ground\tex{i}.bmp";
                cover.SourceNames[i] = name;
                Texture2D tex =
                    TryLoadTextureByExactResourcePathLikeOriginal(name)
                    ?? TryLoadTextureByExactResourcePathLikeOriginal($"textures/{name}")
                    ?? TryLoadTextureByExactResourcePathLikeOriginal($"Ground/tex{i}.bmp")
                    ?? TryLoadTextureByExactResourcePathLikeOriginal($"textures/Ground/tex{i}.bmp")
                    ?? TryLoadTextureByExactResourcePathLikeOriginal($"Ground/tex{i}")
                    ?? TryLoadTextureByExactResourcePathLikeOriginal($"textures/Ground/tex{i}");
                OneCashedTextureLikeOriginal[] group = BuildTextureCoverageGroupLikeOriginal(tex);
                int baseIdx = i << 6;
                for (int j = 0; j < 64; j++)
                    cover.TxCash[baseIdx + j] = group[j];
                if (tex != null)
                    loaded = baseIdx + 64;
            }

            cover.NCTex = loaded;
            cover.LoadedLikeOriginal = loaded > 0;
            map.TCoverLikeOriginal = cover;
        }

        private static OneCashedTextureLikeOriginal[] BuildTextureCoverageGroupLikeOriginal(Texture2D tex)
        {
            var group = new OneCashedTextureLikeOriginal[64];
            Texture2D readable = GetReadableTexture(tex, null);
            for (int i = 0; i < 64; i++)
                group[i] = new OneCashedTextureLikeOriginal { SourceTexture = tex, TexPix = new byte[512] };
            if (readable == null || readable.width <= 0 || readable.height <= 0)
                return group;

            for (int ty = 0; ty < 8; ty++)
            {
                for (int tx = 0; tx < 8; tx++)
                {
                    int idx = tx + (ty << 3);
                    byte[] packed = group[idx].TexPix;
                    int d = 0;
                    for (int y = 0; y < 32; y++)
                    {
                        int sy = Mathf.Clamp(((ty * 32 + y) * readable.height) >> 8, 0, readable.height - 1);
                        for (int x = 0; x < 32; x += 2)
                        {
                            int sx0 = Mathf.Clamp(((tx * 32 + x) * readable.width) >> 8, 0, readable.width - 1);
                            int sx1 = Mathf.Clamp(((tx * 32 + x + 1) * readable.width) >> 8, 0, readable.width - 1);
                            int a = Mathf.Clamp(Mathf.RoundToInt(readable.GetPixel(sx0, sy).grayscale * 15f), 0, 15);
                            int b = Mathf.Clamp(Mathf.RoundToInt(readable.GetPixel(sx1, sy).grayscale * 15f), 0, 15);
                            packed[d++] = (byte)((a & 0x0F) | ((b & 0x0F) << 4));
                        }
                    }
                }
            }
            return group;
        }

        private static void TryPreloadPenaLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            map.PenaTextureLikeOriginal =
                TryLoadTextureByExactResourcePathLikeOriginal(PenaGpNameLikeOriginal)
                ?? TryLoadTextureByExactResourcePathLikeOriginal("textures/" + PenaGpNameLikeOriginal)
                ?? TryLoadTextureByExactResourcePathLikeOriginal("Ground/" + PenaGpNameLikeOriginal);

            map.PenaGpNameLikeOriginal = PenaGpNameLikeOriginal;
            map.PenaGpLikeOriginal = PreLoadGpImageLikeOriginal(PenaGpNameLikeOriginal);
        }

        private static int PreLoadGpImageLikeOriginal(string name)
        {
            if (string.IsNullOrWhiteSpace(name))
                return 0;
            if (s_gpImageIdsLikeOriginal.TryGetValue(name, out int id))
                return id;
            id = s_nextGpImageIdLikeOriginal++;
            s_gpImageIdsLikeOriginal[name] = id;
            return id;
        }

        private static void EnsureInvBrFogLikeOriginal()
        {
            if (s_invBrFogLikeOriginal.Length == 32 * 256)
                return;
            s_invBrFogLikeOriginal = new byte[32 * 256];
            for (int fog = 0; fog < 32; fog++)
                for (int c = 0; c < 256; c++)
                    s_invBrFogLikeOriginal[(fog << 8) | c] = (byte)Mathf.Clamp(c - fog, 0, 255);
        }

        private static void LoadCurPixTextureLikeOriginal(ParsedMap map, string name)
        {
            if (map == null)
                return;

            map.CurPixTextureResourceLikeOriginal =
                TryLoadTextureByExactResourcePathLikeOriginal(name)
                ?? TryLoadTextureByExactResourcePathLikeOriginal("textures/" + name)
                ?? TryLoadTextureByExactResourcePathLikeOriginal("Ground/" + name)
                ?? TryLoadTextureByExactResourcePathLikeOriginal("textures/Ground/" + name);

            map.CurPixTextureLikeOriginal = ConvertTextureToSignedCoverageLikeOriginal(map.CurPixTextureResourceLikeOriginal);
            map.NTexPagesLikeOriginal = map.CurPixTextureLikeOriginal != null && map.CurPixTextureLikeOriginal.Length >= (256 * 256 * 3) ? 3 : 1;
        }

        private static byte[] ConvertTextureToSignedCoverageLikeOriginal(Texture2D tex)
        {
            if (tex == null)
                return Array.Empty<byte>();
            Texture2D readable = GetReadableTexture(tex, null);
            if (readable == null || readable.width <= 0 || readable.height <= 0)
                return Array.Empty<byte>();

            int pages = Math.Max(1, readable.width / 256);
            int width = Math.Max(256, readable.width);
            int height = Math.Max(256, readable.height);
            byte[] dst = new byte[pages * 256 * 256];
            for (int p = 0; p < pages; p++)
            {
                int xBase = Math.Min(readable.width - 256, p * 256);
                xBase = Math.Max(0, xBase);
                for (int y = 0; y < 256; y++)
                {
                    int sy = Mathf.Clamp((y * readable.height) >> 8, 0, readable.height - 1);
                    for (int x = 0; x < 256; x++)
                    {
                        int sx = Mathf.Clamp(xBase + x, 0, readable.width - 1);
                        Color c = readable.GetPixel(sx, sy);
                        int v = Mathf.Clamp(Mathf.RoundToInt((c.grayscale - 0.5f) * 254f), -127, 127);
                        dst[p * 256 * 256 + x + (y << 8)] = unchecked((byte)(sbyte)v);
                    }
                }
            }
            return dst;
        }

        private static int GetTexStartOfsLikeOriginal(ParsedMap map, int x, int ys)
        {
            if (map == null || map.CurPixTextureLikeOriginal == null || map.NTexPagesLikeOriginal < 3)
                return 0;

            int hr = SampleHeightFromMapLikeOriginal(map, x + 32, ys);
            int hl = SampleHeightFromMapLikeOriginal(map, x - 32, ys);
            int hu = SampleHeightFromMapLikeOriginal(map, x, ys - 32);
            int hd = SampleHeightFromMapLikeOriginal(map, x, ys + 32);
            if (hr == hl && hu == hd)
                return 0;

            int nx = hl - hr;
            int ny = Math.Abs(hd - hu);
            float ang = Mathf.Atan2(nx, Math.Max(1, ny));
            int n = map.NTexPagesLikeOriginal >> 1;
            float ang0 = Mathf.PI / map.NTexPagesLikeOriginal / 2.0f;
            int page;
            if (ang > 0)
            {
                page = Mathf.Clamp(Mathf.RoundToInt((ang + ang0) / (2 * ang0)), 0, n);
                return page != 0 ? page << 16 : 0;
            }
            page = Mathf.Clamp(Mathf.RoundToInt((-ang + ang0) / (2 * ang0)), 0, n);
            return page != 0 ? (n + page) << 16 : 0;
        }

        private static void CheckPixPrecompLikeOriginal(int radius)
        {
            radius = Mathf.Clamp(radius, 0, 63);
            if (radius == s_curPixRadiusLikeOriginal)
                return;

            Array.Clear(s_pixFuncPrecompLikeOriginal, 0, s_pixFuncPrecompLikeOriginal.Length);
            int rr = radius << 4;
            if (rr <= 0)
            {
                s_curPixRadiusLikeOriginal = radius;
                return;
            }

            for (int i = 0; i < rr && i < s_pixFuncPrecompLikeOriginal.Length; i++)
            {
                int c = (255 * (rr - i)) / rr;
                s_pixFuncPrecompLikeOriginal[i] = (byte)Mathf.Clamp(c, 0, 255);
            }

            s_curPixRadiusLikeOriginal = radius;
        }

        private static void ClearPixUndoStackLikeOriginal(ParsedMap map)
        {
            if (map == null || map.PixUndoBufLikeOriginal == null)
                return;
            Array.Clear(map.PixUndoBufLikeOriginal, 0, map.PixUndoBufLikeOriginal.Length);
            map.NPixUndoSegmentsLikeOriginal = 0;
            map.UndoSizeLikeOriginal = 0;
        }

        private static void AddPixUndoSegmentLikeOriginal(ParsedMap map, int x, int y, bool first)
        {
            if (map == null)
                return;
            if (map.PixUndoBufLikeOriginal == null || map.MaxPixUndoSegmentsLikeOriginal <= 0)
            {
                map.MaxPixUndoSegmentsLikeOriginal = 64;
                map.PixUndoBufLikeOriginal = new OnePixUndoSegmentLikeOriginal[map.MaxPixUndoSegmentsLikeOriginal];
            }
            if (map.NPixUndoSegmentsLikeOriginal >= map.MaxPixUndoSegmentsLikeOriginal)
            {
                map.MaxPixUndoSegmentsLikeOriginal += 64;
                Array.Resize(ref map.PixUndoBufLikeOriginal, map.MaxPixUndoSegmentsLikeOriginal);
            }
            byte[] packed = new byte[1200];
            int size = GetPackPixSquareLikeOriginal(map, x, y, packed);
            byte[] data = new byte[size];
            Buffer.BlockCopy(packed, 0, data, 0, size);
            map.PixUndoBufLikeOriginal[map.NPixUndoSegmentsLikeOriginal++] = new OnePixUndoSegmentLikeOriginal { cx = x, cy = y, First = first, size = size, data = data };
            map.UndoSizeLikeOriginal += size;
        }

        private static void PerformPixUndoLikeOriginal(ParsedMap map)
        {
            if (map == null || map.PixUndoBufLikeOriginal == null)
                return;
            bool doit = true;
            while (map.NPixUndoSegmentsLikeOriginal > 0 && doit)
            {
                OnePixUndoSegmentLikeOriginal seg = map.PixUndoBufLikeOriginal[map.NPixUndoSegmentsLikeOriginal - 1];
                if (seg != null)
                {
                    SetPackPixSquareLikeOriginal(map, seg.cx, seg.cy, seg.data, seg.size);
                    map.UndoSizeLikeOriginal -= seg.size;
                    MakeDirtyPieceLikeOriginal(map, (seg.cx << 5) + 16, (seg.cy << 5) + 16);
                    doit = !seg.First;
                }
                map.PixUndoBufLikeOriginal[--map.NPixUndoSegmentsLikeOriginal] = null;
            }
        }

        private static void UnpackFromBufLikeOriginal(byte[] dst, byte[] src, int offset, int size)
        {
            if (dst == null || src == null)
                return;

            Array.Clear(dst, 0, dst.Length);
            int ofs = 0;
            int end = Mathf.Min(src.Length, offset + size);
            bool freeMode = true;
            int ptr = offset;

            while (ofs < 1024 && ptr < end)
            {
                int len = src[ptr++];
                if (freeMode)
                {
                    int run = Mathf.Min(len, 1024 - ofs);
                    if (run > 0)
                        Array.Clear(dst, ofs, run);
                    ofs += run;
                    freeMode = false;
                }
                else
                {
                    int pairs = Mathf.Min(len, end - ptr);
                    for (int i = 0; i < pairs && ofs < 1024; i++)
                    {
                        byte b = src[ptr++];
                        dst[ofs++] = (byte)((b & 0x0F) << 4);
                        if (ofs < 1024)
                            dst[ofs++] = (byte)(b & 0xF0);
                    }
                    freeMode = true;
                }
            }
        }

        private static int PackIntoBufLikeOriginal(byte[] src, byte[] dst)
        {
            if (src == null || dst == null)
                return 0;

            bool mod = false;
            int ofs = 0;
            int dofs = 0;
            bool nonEmpty = false;

            while (ofs < 1024 && dofs < dst.Length)
            {
                if (mod)
                {
                    int len = 0;
                    while (ofs + len < 1024 && src[ofs + len] != 0 && len < 254)
                    {
                        nonEmpty = true;
                        len++;
                    }

                    if ((len & 1) != 0)
                        len++;

                    int pairs = len >> 1;
                    if (dofs >= dst.Length)
                        break;
                    dst[dofs++] = (byte)pairs;
                    for (int i = 0; i < pairs && dofs < dst.Length; i++)
                    {
                        byte a = ofs < 1024 ? src[ofs] : (byte)0;
                        byte b = (ofs + 1) < 1024 ? src[ofs + 1] : (byte)0;
                        dst[dofs++] = (byte)((a >> 4) | (b & 0xF0));
                        ofs += 2;
                    }
                    mod = false;
                }
                else
                {
                    int len = 0;
                    while (ofs + len < 1024 && src[ofs + len] == 0 && len < 254)
                        len++;
                    ofs += len;
                    if (dofs >= dst.Length)
                        break;
                    dst[dofs++] = (byte)len;
                    mod = true;
                }
            }

            return nonEmpty ? dofs : 0;
        }

        private static bool GetPixSquareLikeOriginal(ParsedMap map, int cx, int cy, byte[] pix)
        {
            if (map?.SfPictLikeOriginal == null || pix == null || pix.Length < 1024)
                return false;

            int sx = cx >> 2;
            int sy = cy >> 1;
            int valMaxCx = GetValMaxCxLikeOriginal(map);
            if (sx < 0 || sy < 0 || sx >= valMaxCx || sy >= valMaxCx)
            {
                Array.Clear(pix, 0, Mathf.Min(pix.Length, 1024));
                return false;
            }

            int cell = sx + (sy << GetValShfCxLikeOriginal(map));
            if ((uint)cell >= (uint)map.SfPictLikeOriginal.Length)
            {
                Array.Clear(pix, 0, Mathf.Min(pix.Length, 1024));
                return false;
            }

            OneSurfPictureLikeOriginal osp = map.SfPictLikeOriginal[cell];
            if (osp == null)
            {
                Array.Clear(pix, 0, Mathf.Min(pix.Length, 1024));
                return false;
            }

            int intCell = (cx & 3) + ((cy & 1) << 2);
            ushort ofs = osp.OFFS[intCell];
            ushort size = osp.SIZE[intCell];
            if (ofs == 0 || size == 0 || osp.points == null || osp.points.Length == 0)
            {
                Array.Clear(pix, 0, Mathf.Min(pix.Length, 1024));
                return false;
            }

            int start = ofs - 32;
            if (start < 0 || start >= osp.points.Length)
            {
                Array.Clear(pix, 0, Mathf.Min(pix.Length, 1024));
                return false;
            }

            UnpackFromBufLikeOriginal(pix, osp.points, start, size);
            return true;
        }

        private static int GetPackPixSquareLikeOriginal(ParsedMap map, int cx, int cy, byte[] packed)
        {
            if (map?.SfPictLikeOriginal == null)
                return 0;

            int sx = cx >> 2;
            int sy = cy >> 1;
            int valMaxCx = GetValMaxCxLikeOriginal(map);
            if (sx < 0 || sy < 0 || sx >= valMaxCx || sy >= valMaxCx)
                return 0;

            int cell = sx + (sy << GetValShfCxLikeOriginal(map));
            if ((uint)cell >= (uint)map.SfPictLikeOriginal.Length)
                return 0;

            OneSurfPictureLikeOriginal osp = map.SfPictLikeOriginal[cell];
            if (osp == null || osp.points == null)
                return 0;

            int intCell = (cx & 3) + ((cy & 1) << 2);
            ushort ofs = osp.OFFS[intCell];
            ushort size = osp.SIZE[intCell];
            if (ofs == 0 || size == 0)
                return 0;

            int start = ofs - 32;
            if (start < 0 || start + size > osp.points.Length)
                return 0;

            if (packed != null && packed.Length >= size)
                Buffer.BlockCopy(osp.points, start, packed, 0, size);
            return size;
        }

        private static void SetPackPixSquareLikeOriginal(ParsedMap map, int cx, int cy, byte[] packed, int size)
        {
            if (map?.SfPictLikeOriginal == null)
                return;

            int sx = cx >> 2;
            int sy = cy >> 1;
            int valMaxCx = GetValMaxCxLikeOriginal(map);
            if (sx < 0 || sy < 0 || sx >= valMaxCx || sy >= valMaxCx)
                return;

            int cell = sx + (sy << GetValShfCxLikeOriginal(map));
            if ((uint)cell >= (uint)map.SfPictLikeOriginal.Length)
                return;

            OneSurfPictureLikeOriginal osp = map.SfPictLikeOriginal[cell] ?? new OneSurfPictureLikeOriginal();
            int intCell = (cx & 3) + ((cy & 1) << 2);

            byte[][] chunks = new byte[8][];
            int total = 0;
            for (int i = 0; i < 8; i++)
            {
                if (i == intCell)
                {
                    if (packed != null && size > 0)
                    {
                        chunks[i] = new byte[size];
                        Buffer.BlockCopy(packed, 0, chunks[i], 0, size);
                        total += size;
                    }
                }
                else if (osp.OFFS[i] != 0 && osp.SIZE[i] != 0 && osp.points != null)
                {
                    int start = osp.OFFS[i] - 32;
                    int len = osp.SIZE[i];
                    if (start >= 0 && start + len <= osp.points.Length)
                    {
                        chunks[i] = new byte[len];
                        Buffer.BlockCopy(osp.points, start, chunks[i], 0, len);
                        total += len;
                    }
                }
            }

            if (total == 0)
            {
                map.SfPictLikeOriginal[cell] = null;
                return;
            }

            osp = new OneSurfPictureLikeOriginal();
            osp.points = new byte[total];
            int pos = 0;
            for (int i = 0; i < 8; i++)
            {
                byte[] chunk = chunks[i];
                if (chunk == null || chunk.Length == 0)
                {
                    osp.OFFS[i] = 0;
                    osp.SIZE[i] = 0;
                    continue;
                }

                osp.OFFS[i] = (ushort)(32 + pos);
                osp.SIZE[i] = (ushort)chunk.Length;
                Buffer.BlockCopy(chunk, 0, osp.points, pos, chunk.Length);
                pos += chunk.Length;
            }

            map.SfPictLikeOriginal[cell] = osp;
        }

        private static void SetPixSquareLikeOriginal(ParsedMap map, int cx, int cy, byte[] pix)
        {
            if (pix == null || pix.Length < 1024)
                return;

            byte[] packed = new byte[8192];
            int size = PackIntoBufLikeOriginal(pix, packed);
            SetPackPixSquareLikeOriginal(map, cx, cy, packed, size);
        }

        private static void SetPixSpotLikeOriginal(ParsedMap map, int x, int y, int radius, int h0, int h1)
        {
            if (map == null)
                return;

            radius = Mathf.Clamp(radius, 0, 63);
            CheckPixPrecompLikeOriginal(radius);

            int cx0 = (x - radius) >> 5;
            int cy0 = (y - radius) >> 5;
            int cx1 = (x + radius + 1) >> 5;
            int cy1 = (y + radius + 1) >> 5;

            byte[] buf = new byte[1024];
            bool first = true;
            int stofs = GetTexStartOfsLikeOriginal(map, x, y);
            for (int vx = cx0; vx <= cx1; vx++)
            {
                for (int vy = cy0; vy <= cy1; vy++)
                {
                    int pixx0 = (((vx + map.TexStartDXLikeOriginal) << 5) & 255);
                    int pixy0 = (((vy + map.TexStartDYLikeOriginal) << 5) & 255);
                    GetPixSquareLikeOriginal(map, vx, vy, buf);
                    byte[] before = (byte[])buf.Clone();
                    int x0 = vx << 5;
                    int y0 = vy << 5;
                    bool changed = false;
                    int ofs = 0;

                    for (int iy = 0; iy < 32; iy++)
                    {
                        for (int ix = 0; ix < 32; ix++, ofs++)
                        {
                            int dx = x - x0 - ix;
                            int dy = y - y0 - iy;
                            int r = (int)Mathf.Sqrt(dx * dx + dy * dy);
                            if (r >= radius)
                                continue;

                            int fp = Mathf.Clamp(r << 4, 0, s_pixFuncPrecompLikeOriginal.Length - 1);
                            int c = h1 - (((h1 - h0) * s_pixFuncPrecompLikeOriginal[fp]) >> 8);
                            c >>= 1;
                            c = Mathf.Clamp(c, 0, 127);

                            int cur = (sbyte)buf[ofs];
                            int target = c;
                            if (map.CurPixTextureLikeOriginal != null && map.CurPixTextureLikeOriginal.Length > 0 && h1 != 255)
                            {
                                int pageOfs = stofs & ~0xFFFF;
                                int texOfs = pageOfs + (((pixy0 + iy) & 255) << 8) + ((pixx0 + ix) & 255);
                                if ((uint)texOfs < (uint)map.CurPixTextureLikeOriginal.Length)
                                {
                                    int cpx = (((sbyte)map.CurPixTextureLikeOriginal[texOfs]) * c) >> 7;
                                    target = cpx;
                                }
                            }

                            if (h1 == 255)
                            {
                                if (cur < 0 && cur < -c)
                                {
                                    buf[ofs] = c < 16 ? (byte)0 : unchecked((byte)(-c));
                                    changed = true;
                                }
                                else if (cur > 0 && cur > c)
                                {
                                    buf[ofs] = (byte)c;
                                    changed = true;
                                }
                            }
                            else
                            {
                                if (target < 0 && cur > target)
                                {
                                    buf[ofs] = unchecked((byte)(sbyte)Mathf.Clamp(target, -127, 127));
                                    changed = true;
                                }
                                else if (target > 0 && cur < target)
                                {
                                    buf[ofs] = (byte)Mathf.Clamp(target, 0, 127);
                                    changed = true;
                                }
                            }
                        }
                    }

                    if (changed)
                    {
                        AddPixUndoSegmentLikeOriginal(map, vx, vy, first);
                        first = false;
                        SetPixSquareLikeOriginal(map, vx, vy, buf);
                        MakeDirtyPieceLikeOriginal(map, (vx << 5) + 16, (vy << 5) + 16);
                    }
                }
            }
        }

        private static void SetPixLineLikeOriginal(ParsedMap map, int x0, int y0, int x1, int y1, int radius, int h0, int h1)
        {
            if (map == null)
                return;
            int dx = x1 - x0;
            int dy = y1 - y0;
            int steps = Math.Max(Math.Abs(dx), Math.Abs(dy));
            if (steps <= 0)
            {
                SetPixSpotLikeOriginal(map, x0, y0, radius, h0, h1);
                return;
            }
            for (int i = 0; i <= steps; i++)
            {
                int px = x0 + (dx * i) / steps;
                int py = y0 + (dy * i) / steps;
                int hh = h0 + ((h1 - h0) * i) / steps;
                SetPixSpotLikeOriginal(map, px, py, radius, hh, h1);
            }
        }

        private static void SetPixLineLikeOriginal(ParsedMap map, int x0, int y0, int x1, int y1, int radius0, int radius1, int h0, int h1, int h01)
        {
            if (map == null)
                return;
            int dx = x1 - x0;
            int dy = y1 - y0;
            int steps = Math.Max(Math.Abs(dx), Math.Abs(dy));
            if (steps <= 0)
            {
                SetPixSpotLikeOriginal(map, x0, y0, radius0, h0, h01);
                return;
            }
            for (int i = 0; i <= steps; i++)
            {
                int px = x0 + (dx * i) / steps;
                int py = y0 + (dy * i) / steps;
                int rr = radius0 + ((radius1 - radius0) * i) / steps;
                int hh = h0 + ((h1 - h0) * i) / steps;
                int hh1 = h01 + ((h1 - h01) * i) / steps;
                SetPixSpotLikeOriginal(map, px, py, rr, hh, hh1);
            }
        }

        private static int ClampWeightLikeOriginal(int value, bool clampTo15)
        {
            if (clampTo15 && value > 15)
                return 15;
            return Mathf.Clamp(value, 0, 127);
        }

        private static void PutWeightToTextureLikeOriginal(byte[] srcTex, byte[] dstTex, int w1, int w2, int w3, int w4)
        {
            if (srcTex == null || dstTex == null || srcTex.Length < 512 || dstTex.Length < 1024)
                return;
            if (w1 <= 0 && w2 <= 0 && w3 <= 0 && w4 <= 0)
                return;

            for (int y = 0; y < 32; y++)
            {
                float fy = y / 31.0f;
                float wy1 = Mathf.Lerp(w1, w3, fy);
                float wy2 = Mathf.Lerp(w2, w4, fy);
                for (int x = 0; x < 32; x++)
                {
                    float fx = x / 31.0f;
                    float w = Mathf.Lerp(wy1, wy2, fx) / 15.0f;
                    w = Mathf.Clamp01(w);
                    int si = (x >> 1) + (y << 4);
                    byte packed = srcTex[si];
                    int pix = (x & 1) == 0 ? (packed & 0x0F) : ((packed >> 4) & 0x0F);
                    int v = Mathf.Clamp(Mathf.RoundToInt(pix * w), 0, 15);
                    int di = x + (y << 5);
                    if (v < dstTex[di])
                        dstTex[di] = (byte)v;
                }
            }
        }

        private static void BuildPointTextureMaskSquareLikeOriginal(ParsedMap map, int cx, int cy, byte[] dst)
        {
            if (dst == null || dst.Length < 1024)
                return;

            Array.Fill(dst, (byte)15);
            if (map == null || map.TCoverLikeOriginal == null || map.TCoverLikeOriginal.TxCash == null || map.PointTexWeightLikeOriginal == null || map.PointTexIndexLikeOriginal == null)
                return;

            int w1 = GetTWeightLikeOriginal(map, cx, cy);
            int w2 = GetTWeightLikeOriginal(map, cx + 1, cy);
            int w3 = GetTWeightLikeOriginal(map, cx, cy + 1);
            int w4 = GetTWeightLikeOriginal(map, cx + 1, cy + 1);
            if (!(w1 != 0 || w2 != 0 || w3 != 0 || w4 != 0))
                return;

            byte[] tmp = new byte[1024];
            Array.Fill(tmp, (byte)15);
            int tex1 = GetPTextureLikeOriginal(map, cx, cy);
            int tex2 = GetPTextureLikeOriginal(map, cx + 1, cy);
            int tex3 = GetPTextureLikeOriginal(map, cx, cy + 1);
            int tex4 = GetPTextureLikeOriginal(map, cx + 1, cy + 1);
            bool uniTex = tex1 == tex2 && tex1 == tex3 && tex1 == tex4;

            void BlendTex(int tex, int a, int b, int c, int d)
            {
                if (tex < 0 || tex >= map.TCoverLikeOriginal.NCTex || tex >= map.TCoverLikeOriginal.TxCash.Length)
                    return;
                int tx = (cx + (tex & 7)) & 7;
                int ty = (cy + ((tex >> 3) & 7)) & 7;
                int idx = (tex & ~63) + tx + (ty << 3);
                if (idx < 0 || idx >= map.TCoverLikeOriginal.TxCash.Length)
                    return;
                OneCashedTextureLikeOriginal entry = map.TCoverLikeOriginal.TxCash[idx];
                if (entry == null || entry.TexPix == null || entry.TexPix.Length < 512)
                    return;
                PutWeightToTextureLikeOriginal(entry.TexPix, tmp, ClampWeightLikeOriginal(a, uniTex), ClampWeightLikeOriginal(b, uniTex), ClampWeightLikeOriginal(c, uniTex), ClampWeightLikeOriginal(d, uniTex));
            }

            BlendTex(tex1, w1, tex1 == tex2 ? w2 : 0, tex1 == tex3 ? w3 : 0, tex1 == tex4 ? w4 : 0);
            if (tex2 != tex1) BlendTex(tex2, tex2 == tex1 ? w1 : 0, w2, tex2 == tex3 ? w3 : 0, tex2 == tex4 ? w4 : 0);
            if (tex3 != tex2 && tex3 != tex1) BlendTex(tex3, tex3 == tex1 ? w1 : 0, tex3 == tex2 ? w2 : 0, w3, tex3 == tex4 ? w4 : 0);
            if (tex4 != tex3 && tex4 != tex2 && tex4 != tex1) BlendTex(tex4, tex4 == tex1 ? w1 : 0, tex4 == tex2 ? w2 : 0, tex4 == tex3 ? w3 : 0, w4);
            Buffer.BlockCopy(tmp, 0, dst, 0, 1024);
        }

        private static void ApplyScreenFogToIndexedBufferLikeOriginal(ParsedMap map, byte[] dst, int dstWidth, int dstHeight, int dstX, int dstY)
        {
            if (map == null || map.ScreenFogTileLikeOriginal == null || dst == null || dstWidth <= 0 || dstHeight <= 0)
                return;

            EnsureInvBrFogLikeOriginal();
            int width = Mathf.Min(map.ScreenFogWidthLikeOriginal + 2, ScreenFogSideLikeOriginal);
            int height = Mathf.Min(map.ScreenFogHeightLikeOriginal + 2, ScreenFogSideLikeOriginal);
            for (int y = 0; y < height; y++)
            {
                int py = dstY + y;
                if ((uint)py >= (uint)dstHeight)
                    continue;

                for (int x = 0; x < width; x++)
                {
                    int px = dstX + x;
                    if ((uint)px >= (uint)dstWidth)
                        continue;

                    int fog = Mathf.Clamp(map.ScreenFogTileLikeOriginal[y * ScreenFogSideLikeOriginal + x], 0, 31);
                    int ofs = px + py * dstWidth;
                    int idx = (fog << 8) | dst[ofs];
                    dst[ofs] = s_invBrFogLikeOriginal[idx];
                }
            }
        }

        private static void ApplyPointTextureMaskToIndexedBufferLikeOriginal(ParsedMap map, byte[] dst, int dstWidth, int dstHeight, int dstX, int dstY, int cx, int cy)
        {
            if (dst == null || dstWidth <= 0 || dstHeight <= 0)
                return;

            byte[] mask = new byte[1024];
            BuildPointTextureMaskSquareLikeOriginal(map, cx, cy, mask);
            for (int iy = 0; iy < 32; iy++)
            {
                int py = dstY + iy;
                if ((uint)py >= (uint)dstHeight)
                    continue;

                for (int ix = 0; ix < 32; ix++)
                {
                    int px = dstX + ix;
                    if ((uint)px >= (uint)dstWidth)
                        continue;

                    int ofs = px + py * dstWidth;
                    int v = dst[ofs] - mask[ix + (iy << 5)];
                    dst[ofs] = (byte)Mathf.Clamp(v, 0, 255);
                }
            }
        }


        private static void SetupPointTexsLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            InitFlowTexLikeOriginal(map);

            map.PT_LxLikeOriginal = 256 << map.Addsh;
            map.PT_LyLikeOriginal = 128 << map.Addsh;
            map.PT_SHWLikeOriginal = 8 + map.Addsh;
            map.PT_SHILikeOriginal = 8 + map.Addsh;

            int weightCount = checked(map.PT_LxLikeOriginal * map.PT_LyLikeOriginal);
            int indexCount = checked(map.PT_LxLikeOriginal * map.PT_LxLikeOriginal);

            if (map.PointTexWeightLikeOriginal == null || map.PointTexWeightLikeOriginal.Length != weightCount)
                map.PointTexWeightLikeOriginal = new sbyte[weightCount];
            if (map.PointTexIndexLikeOriginal == null || map.PointTexIndexLikeOriginal.Length != indexCount)
                map.PointTexIndexLikeOriginal = new ushort[indexCount];

            for (int i = 0; i < map.PointTexWeightLikeOriginal.Length; i++)
                map.PointTexWeightLikeOriginal[i] = unchecked((sbyte)0x81);
            FillUShortArrayLikeOriginal(map.PointTexIndexLikeOriginal, 0xFFFF);

            TryPreloadPenaLikeOriginal(map);
            Array.Clear(map.PointTexIndexLikeOriginal, 0, map.PointTexIndexLikeOriginal.Length);
            map.PointTexInitializedLikeOriginal = true;
        }

        private static int GetTWeightLikeOriginal(ParsedMap map, int cx, int cy)
        {
            if (map == null || map.PointTexWeightLikeOriginal == null)
                return 0;
            if (cx < 0 || cy < 0 || cx >= map.PT_LxLikeOriginal || cy >= map.PT_LyLikeOriginal)
                return 0;
            int ofs = cx + (cy << map.PT_SHWLikeOriginal);
            if ((uint)ofs >= (uint)map.PointTexWeightLikeOriginal.Length)
                return 0;
            return map.PointTexWeightLikeOriginal[ofs];
        }

        private static int GetMiniTWeightLikeOriginal(ParsedMap map, int cx, int cy)
        {
            if (map == null || map.PointTexWeightLikeOriginal == null || map.PointTexIndexLikeOriginal == null)
                return 0;
            if (cx < 0 || cy < 0 || cx >= map.PT_LxLikeOriginal || cy >= map.PT_LyLikeOriginal)
                return 0;
            int ofs = cx + (cy << map.PT_SHWLikeOriginal);
            if ((uint)ofs >= (uint)map.PointTexWeightLikeOriginal.Length || (uint)ofs >= (uint)map.PointTexIndexLikeOriginal.Length)
                return 0;
            int tex = map.PointTexIndexLikeOriginal[ofs] >> 6;
            if ((uint)tex >= (uint)MiniTexMaskLikeOriginal.Length || MiniTexMaskLikeOriginal[tex] == 0)
                return 0;
            return map.PointTexWeightLikeOriginal[ofs];
        }

        private static void SetTWeightLikeOriginal(ParsedMap map, int cx, int cy, int w)
        {
            if (map == null || map.PointTexWeightLikeOriginal == null)
                return;
            if (cx < 0 || cy < 0 || cx >= map.PT_LxLikeOriginal || cy >= map.PT_LyLikeOriginal)
                return;
            int ofs = cx + (cy << map.PT_SHWLikeOriginal);
            if ((uint)ofs >= (uint)map.PointTexWeightLikeOriginal.Length)
                return;
            map.PointTexWeightLikeOriginal[ofs] = unchecked((sbyte)Mathf.Clamp(w, sbyte.MinValue, sbyte.MaxValue));
        }

        private static int GetPTextureLikeOriginal(ParsedMap map, int cx, int cy)
        {
            if (map == null || map.PointTexIndexLikeOriginal == null)
                return 0xFFFF;
            if (cx < 0 || cy < 0 || cx >= map.PT_LxLikeOriginal || cy >= map.PT_LyLikeOriginal)
                return 0xFFFF;
            int ofs = cx + (cy << map.PT_SHILikeOriginal);
            if ((uint)ofs >= (uint)map.PointTexIndexLikeOriginal.Length)
                return 0xFFFF;
            return map.PointTexIndexLikeOriginal[ofs];
        }

        private static void SetPTextureLikeOriginal(ParsedMap map, int cx, int cy, int tex)
        {
            if (map == null || map.PointTexIndexLikeOriginal == null)
                return;
            if (cx < 0 || cy < 0 || cx >= map.PT_LxLikeOriginal || cy >= map.PT_LyLikeOriginal)
                return;
            int ofs = cx + (cy << map.PT_SHILikeOriginal);
            if ((uint)ofs >= (uint)map.PointTexIndexLikeOriginal.Length)
                return;
            map.PointTexIndexLikeOriginal[ofs] = (ushort)Mathf.Clamp(tex, 0, 0xFFFF);
        }

        private static void FillUShortArrayLikeOriginal(ushort[] arr, ushort value)
        {
            if (arr == null)
                return;
            for (int i = 0; i < arr.Length; i++)
                arr[i] = value;
        }


        private static int GetValMaxCxLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return 0;
            return 64 << map.Addsh;
        }

        private static int GetValShfCxLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return 0;
            return 6 + map.Addsh;
        }

        private static void ClearGPMAPLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;
            if (map.GpMapLikeOriginal != null)
                Array.Clear(map.GpMapLikeOriginal, 0, map.GpMapLikeOriginal.Length);
            if (map.NInGpMapLikeOriginal != null)
                Array.Clear(map.NInGpMapLikeOriginal, 0, map.NInGpMapLikeOriginal.Length);
            if (map.DirtyGpCellsLikeOriginal != null)
                Array.Clear(map.DirtyGpCellsLikeOriginal, 0, map.DirtyGpCellsLikeOriginal.Length);
            map.DirtyGpCellCountLikeOriginal = 0;
        }

        private static void ClearAllGSpritesLikeOriginal(ParsedMap map)
        {
            if (map == null || map.GpMapLikeOriginal == null)
                return;

            for (int i = 0; i < map.GpMapLikeOriginal.Length; i++)
                map.GpMapLikeOriginal[i] = null;

            if (map.NInGpMapLikeOriginal != null)
                Array.Clear(map.NInGpMapLikeOriginal, 0, map.NInGpMapLikeOriginal.Length);
        }

        private static void FreeGPMAPLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;
            map.GpMapLikeOriginal = Array.Empty<OneGPieceLikeOriginal[]>();
            map.NInGpMapLikeOriginal = Array.Empty<ushort>();
            map.DirtyGpCellsLikeOriginal = Array.Empty<int>();
            map.DirtyGpCellCountLikeOriginal = 0;
            map.GpMapCellCountLikeOriginal = 0;
            FreeSFPICTLikeOriginal(map);
            map.GpMapInitializedLikeOriginal = false;
        }

        private static void AddGPieceLikeOriginal(ParsedMap map, int x, int y, ushort type)
        {
            if (map == null || map.GpMapLikeOriginal == null || map.NInGpMapLikeOriginal == null)
                return;

            int z = SampleHeightFromMapLikeOriginal(map, x, y);
            int yr = (y >> 1) - z;
            int xc = x >> 7;
            int yc = yr >> 6;
            int valMaxCx = GetValMaxCxLikeOriginal(map);
            if (valMaxCx <= 1)
                return;

            if (xc < 0 || yc < 0 || xc >= valMaxCx - 1 || yc >= valMaxCx - 1)
                return;

            int cell = xc + (yc << GetValShfCxLikeOriginal(map));
            if ((uint)cell >= (uint)map.GpMapLikeOriginal.Length || (uint)cell >= (uint)map.NInGpMapLikeOriginal.Length)
                return;

            ushort n = map.NInGpMapLikeOriginal[cell];
            if (n == ushort.MaxValue)
                return;

            OneGPieceLikeOriginal[] pieces = map.GpMapLikeOriginal[cell];
            int pieceCount = pieces != null ? pieces.Length : 0;
            if (pieces == null)
            {
                pieces = new OneGPieceLikeOriginal[1];
            }
            else
            {
                Array.Resize(ref pieces, pieceCount + 1);
            }

            pieces[pieces.Length - 1] = new OneGPieceLikeOriginal
            {
                Index = type,
                x = (byte)(x & 127),
                y = (byte)(yr & 63),
                z = (short)z,
                Shadow = 0
            };

            map.GpMapLikeOriginal[cell] = pieces;
            map.NInGpMapLikeOriginal[cell] = (ushort)(n + 1);

            int cx = x >> 5;
            int cy = yr >> 5;
            for (int dx = -1; dx <= 1; dx++)
                for (int dy = -1; dy <= 1; dy++)
                    MarkSqToRedrawLikeOriginal(map, cx + dx, cy + dy);
        }

        private static void UpdatePiecesLikeOriginal(ParsedMap map, int cx, int cy)
        {
            if (map == null || map.GpMapLikeOriginal == null || map.NInGpMapLikeOriginal == null)
                return;

            int valMaxCx = GetValMaxCxLikeOriginal(map);
            if (cx < 0 || cy < 0 || cx >= valMaxCx || cy >= valMaxCx)
                return;

            int cell = cx + (cy << GetValShfCxLikeOriginal(map));
            if ((uint)cell >= (uint)map.GpMapLikeOriginal.Length || (uint)cell >= (uint)map.NInGpMapLikeOriginal.Length)
                return;

            OneGPieceLikeOriginal[] pieces = map.GpMapLikeOriginal[cell];
            ushort count = map.NInGpMapLikeOriginal[cell];
            map.GpMapLikeOriginal[cell] = null;
            map.NInGpMapLikeOriginal[cell] = 0;

            if (pieces == null || count == 0)
                return;

            int limit = Math.Min(count, (ushort)pieces.Length);
            for (int i = 0; i < limit; i++)
            {
                OneGPieceLikeOriginal p = pieces[i];
                int ys = (((cy << 6) + p.y + p.z) << 1);
                AddGPieceLikeOriginal(map, (cx << 7) + p.x, ys, p.Index);
            }
        }

        private static void UpdateAllPiecesLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            int valMaxCx = GetValMaxCxLikeOriginal(map);
            for (int ix = 0; ix < valMaxCx; ix++)
            {
                for (int iy = 0; iy < valMaxCx; iy++)
                    UpdatePiecesLikeOriginal(map, ix, iy);
            }
        }

        private static void InitSFPICTLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            int cellCount = Math.Max(0, GetValMaxCxLikeOriginal(map) * GetValMaxCxLikeOriginal(map));
            if (map.SfPictLikeOriginal == null || map.SfPictLikeOriginal.Length != cellCount)
                map.SfPictLikeOriginal = new OneSurfPictureLikeOriginal[cellCount];
            else
                Array.Clear(map.SfPictLikeOriginal, 0, map.SfPictLikeOriginal.Length);
        }

        private static void ClearSFPICTLikeOriginal(ParsedMap map)
        {
            if (map?.SfPictLikeOriginal == null)
                return;
            Array.Clear(map.SfPictLikeOriginal, 0, map.SfPictLikeOriginal.Length);
        }

        private static void FreeSFPICTLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;
            map.SfPictLikeOriginal = Array.Empty<OneSurfPictureLikeOriginal>();
        }

        private static void MarkSqToRedrawLikeOriginal(ParsedMap map, int sx, int sy)
        {
            if (map == null || map.DirtyGpCellsLikeOriginal == null)
                return;

            int valMaxCx = GetValMaxCxLikeOriginal(map);
            if (sx < 0 || sy < 0 || sx >= valMaxCx || sy > valMaxCx)
                return;

            if (map.DirtyGpCellCountLikeOriginal >= MaxDirtyGpCellsLikeOriginal)
                return;

            int cell = sx + (sy << GetValShfCxLikeOriginal(map));
            for (int i = 0; i < map.DirtyGpCellCountLikeOriginal; i++)
                if (map.DirtyGpCellsLikeOriginal[i] == cell)
                    return;

            map.DirtyGpCellsLikeOriginal[map.DirtyGpCellCountLikeOriginal++] = cell;
        }

        private static void MakeDirtyPieceLikeOriginal(ParsedMap map, int x, int y)
        {
            if (map == null)
                return;

            int cy = ((y >> 1) - SampleHeightFromMapLikeOriginal(map, x, y)) >> 4;
            int cx = x >> 5;
            cy >>= 2;
            cx >>= 2;
            MarkSqToRedrawLikeOriginal(map, cx, cy);
        }

        private static void UpdateDirtyPiecesLikeOriginal(ParsedMap map)
        {
            if (map == null || map.DirtyGpCellsLikeOriginal == null)
                return;

            if (map.DirtyGpCellCountLikeOriginal >= MaxDirtyGpCellsLikeOriginal)
            {
                UpdateAllPiecesLikeOriginal(map);
            }
            else
            {
                for (int i = 0; i < map.DirtyGpCellCountLikeOriginal; i++)
                {
                    int c = map.DirtyGpCellsLikeOriginal[i];
                    UpdatePiecesLikeOriginal(map, c % GetValMaxCxLikeOriginal(map), c / GetValMaxCxLikeOriginal(map));
                }
            }

            Array.Clear(map.DirtyGpCellsLikeOriginal, 0, map.DirtyGpCellsLikeOriginal.Length);
            map.DirtyGpCellCountLikeOriginal = 0;
        }

        private static byte[] SavePointTexInfoLikeOriginal(ParsedMap map)
        {
            if (map == null || map.PointTexWeightLikeOriginal == null || map.PointTexIndexLikeOriginal == null)
                return Array.Empty<byte>();

            int weightBytes = map.PT_LxLikeOriginal * map.PT_LyLikeOriginal;
            int indexBytes = map.PT_LxLikeOriginal * map.PT_LyLikeOriginal * 2;
            int totalBytes = 8 + weightBytes + indexBytes;
            byte[] blob = new byte[totalBytes];

            byte[] sizeBytes = BitConverter.GetBytes(totalBytes);
            Buffer.BlockCopy(sizeBytes, 0, blob, 0, 4);

            for (int i = 0; i < weightBytes && i < map.PointTexWeightLikeOriginal.Length; i++)
                blob[4 + i] = unchecked((byte)map.PointTexWeightLikeOriginal[i]);

            int indexOffset = 4 + weightBytes;
            int indexCount = Math.Min(map.PT_LxLikeOriginal * map.PT_LyLikeOriginal, map.PointTexIndexLikeOriginal.Length);
            for (int i = 0; i < indexCount; i++)
            {
                ushort v = map.PointTexIndexLikeOriginal[i];
                blob[indexOffset + i * 2] = (byte)(v & 0xFF);
                blob[indexOffset + i * 2 + 1] = (byte)(v >> 8);
            }

            return blob;
        }

        private static void LoadPointTexInfoLikeOriginal(ParsedMap map, byte[] blob, int payloadOffset)
        {
            if (map == null || blob == null || map.PointTexWeightLikeOriginal == null || map.PointTexIndexLikeOriginal == null)
                return;

            int weightBytes = map.PT_LxLikeOriginal * map.PT_LyLikeOriginal;
            int indexCount = map.PT_LxLikeOriginal * map.PT_LyLikeOriginal;
            if (payloadOffset < 0 || payloadOffset + weightBytes + indexCount * 2 > blob.Length)
                return;

            for (int i = 0; i < weightBytes && i < map.PointTexWeightLikeOriginal.Length; i++)
                map.PointTexWeightLikeOriginal[i] = unchecked((sbyte)blob[payloadOffset + i]);

            int indexOffset = payloadOffset + weightBytes;
            for (int i = 0; i < indexCount && i < map.PointTexIndexLikeOriginal.Length; i++)
            {
                int ofs = indexOffset + i * 2;
                map.PointTexIndexLikeOriginal[i] = (ushort)(blob[ofs] | (blob[ofs + 1] << 8));
            }
        }

        private static void FreePointsTexLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            map.PointTexWeightLikeOriginal = Array.Empty<sbyte>();
            map.PointTexIndexLikeOriginal = Array.Empty<ushort>();
            map.PT_LxLikeOriginal = 0;
            map.PT_LyLikeOriginal = 0;
            map.PT_SHWLikeOriginal = 0;
            map.PT_SHILikeOriginal = 0;
            map.PenaGpLikeOriginal = 0;
            map.PenaGpNameLikeOriginal = "";
            map.FlowTexNamesLikeOriginal = Array.Empty<string>();
            map.FlowTexLikeOriginal = Array.Empty<byte>();
            map.WaveTexLikeOriginal = null;
            map.PenaTextureLikeOriginal = null;
            map.TCoverLikeOriginal = null;
            map.PointTexInitializedLikeOriginal = false;
            map.FlowTexInitializedLikeOriginal = false;
        }

        private static void InitializeSectMapLikeOriginal(ParsedMap map)
        {
            if (map == null || map.SectMapLikeOriginal == null || map.SectMapLikeOriginal.Length == 0)
                return;

            short[] randoma = GetRandomTableLikeOriginal(null);
            for (int i = 0; i < map.SectMapLikeOriginal.Length; i++)
                map.SectMapLikeOriginal[i] = (byte)(randoma[i & 8191] % 3);
        }

        
        private static string BuildRne2Summary(DecodedRoadNet net)
        {
            if (net == null)
                return "nodes=0";
            return $"nodes={net.NodeCount} stride={net.Stride} layout={net.Layout} activeSources={net.ActiveSources} hidden={net.HiddenCount} zeroDegree={net.ZeroDegree} maxDegree={net.MaxDegree} validRefs={net.ValidLinkRefs} invalidRefs={net.InvalidLinkRefs} reciprocal={net.ReciprocalDirected}";
        }

        private static string BuildRne2Samples(DecodedRoadNet net)
        {
            if (net == null || net.Nodes == null || net.Nodes.Count == 0)
                return "none";

            var picks = new List<int>();
            picks.Add(0);
            if (net.Nodes.Count > 2)
                picks.Add(net.Nodes.Count / 2);
            if (net.Nodes.Count > 1)
                picks.Add(net.Nodes.Count - 1);

            var parts = new List<string>();
            foreach (int idx in picks.Distinct())
            {
                if (idx < 0 || idx >= net.Nodes.Count)
                    continue;
                RoadKnot node = net.Nodes[idx];
                int degree = Math.Clamp(node.NLinks, 0, Rne2MaxLink);
                var edgeParts = new List<string>();
                for (int q = 0; q < degree && q < 3; q++)
                    edgeParts.Add($"{node.Links[q]}/r{node.RoadID[q]}/t{node.LinkType[q]}/w{node.WayPointToPointIndex[q]}");
                parts.Add($"{idx}@{node.X},{node.Y} deg={degree} hidden={node.Hidden} onRoad={(node.HasOnRoad ? 1 : 0)} edges={string.Join(",", edgeParts)}");
            }

            return parts.Count > 0 ? string.Join(" | ", parts) : "none";
        }

private static void ApplyRoadNetChunkLikeOriginal(ParsedMap map, BinaryReader br, int payloadLen)
        {
            if (map == null || br == null)
                return;

            map.ChunkRNE2 = br.ReadBytes(payloadLen);
            InvalidateITerraLikeOriginal(map, invalidateAabb: false, invalidateTexture: false, invalidateGeometry: false);
            if (TryDecodeRne2(map.ChunkRNE2, out var decodedRne2, out _, out _))
            {
                map.DecodedRne2 = decodedRne2;
                map.Rne2DecodedImmediateLikeOriginal = true;
            }
            EnsureTopologyRuntimeStateLikeOriginal(map);
            InstallGlobalMutableStateLikeOriginal(map, "ApplyRoadNetChunkLikeOriginal");
        }

        private static void ApplyTopologyChunkLikeOriginal(ParsedMap map, BinaryReader br, int payloadLen, int topType, string tag)
        {
            if (map == null || br == null)
                return;

            byte[] payload = br.ReadBytes(payloadLen);
            switch (topType)
            {
                case 0: map.Chunk0TPL = payload; break;
                case 1: map.Chunk1TPL = payload; break;
                case 2: map.Chunk2TPL = payload; break;
            }

            ApplySetupArraysImmediateStateLikeOriginal(map);
            EnsureTopologyRuntimeStateLikeOriginal(map);
            InstallGlobalMutableStateLikeOriginal(map, "ApplyTopologyChunkLikeOriginal:" + tag);
        }

        private static void EnsureTopologyRuntimeStateLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            ApplySetupArraysImmediateStateLikeOriginal(map);

            if (map.DecodedRne2 == null && map.ChunkRNE2 != null && map.ChunkRNE2.Length > 0)
            {
                if (TryDecodeRne2(map.ChunkRNE2, out var decodedRne2, out _, out _))
                {
                    map.DecodedRne2 = decodedRne2;
                    map.Rne2DecodedImmediateLikeOriginal = true;
                }
            }

            bool runtimeLockingReady = CreateTotalLockingLikeOriginal(map);
            EnsureTopologyCreateAreasAndWayRuntimeLikeOriginal(map);

            if (map.TopologyFieldsLikeOriginal != null)
            {
                int bestType = -1;
                int bestAreas = -1;
                for (int i = 0; i < map.TopologyFieldsLikeOriginal.Length; i++)
                {
                    TopologyHashTableLikeOriginal field = map.TopologyFieldsLikeOriginal[i];
                    int areas = field != null ? field.NAreas : 0;
                    if (areas > bestAreas)
                    {
                        bestAreas = areas;
                        bestType = i;
                    }
                }

                if (bestType >= 0 && bestType < map.TopologyFieldsLikeOriginal.Length)
                {
                    map.ActiveTopTypeLikeOriginal = bestType;
                    map.ActiveTopRefLikeOriginal = map.TopologyFieldsLikeOriginal[bestType].TopRef;
                    WarmupTopologyHashCacheLikeOriginal(map, map.TopologyFieldsLikeOriginal[bestType], 0xFFFFFFFFu);
                }
            }

            map.TopologyRuntimeReadyLikeOriginal = runtimeLockingReady || map.Rne2DecodedImmediateLikeOriginal || HasAnyTopologyTplPayloadLikeOriginal(map);
            InstallGlobalMutableStateLikeOriginal(map, "EnsureTopologyRuntimeStateLikeOriginal");
        }

        private static bool TryApplyTplChunkToTopologyFieldLikeOriginal(ParsedMap map, int topType, byte[] payload, string tag, out string error)
        {
            error = "";
            if (map == null)
            {
                error = "map null";
                return false;
            }

            ApplySetupArraysImmediateStateLikeOriginal(map);
            if (map.TopologyFieldsLikeOriginal == null || topType < 0 || topType >= map.TopologyFieldsLikeOriginal.Length)
            {
                error = "topology field missing";
                return false;
            }

            TopologyHashTableLikeOriginal field = map.TopologyFieldsLikeOriginal[topType];
            if (field == null)
            {
                field = new TopologyHashTableLikeOriginal();
                map.TopologyFieldsLikeOriginal[topType] = field;
            }

            field.TopType = (byte)topType;
            field.SourceChunkTag = tag ?? "";

            int topCellCount = Math.Max(0, map.TopLx * map.TopLx);
            if (field.TopRef == null || field.TopRef.Length != topCellCount)
                field.TopRef = new ushort[topCellCount];

            if (payload == null || payload.Length == 0)
            {
                FillUShortArrayLikeOriginal(field.TopRef, 0xFFFF);
                field.TopMap = Array.Empty<TopologyAreaLikeOriginal>();
                field.NAreas = 0;
                field.MaxArea = 0;
                map.TopologyDecodedImmediateLikeOriginal = true;
                return false;
            }

            if (!TryReadTplAreaLinks(payload, out ushort[] ax, out ushort[] ay, out ushort[] linkCounts, out ushort[][] q0, out ushort[][] q1, out ushort[][] q2, out ushort[][] q3, out string areaError))
            {
                error = areaError;
                return false;
            }

            if (!TryReadTplTopRef(payload, map.MaxTH, out int areaCount, out int topLx, out ushort[] topRefs, out string topError))
            {
                error = topError;
                return false;
            }

            if (topCellCount != topRefs.Length)
            {
                error = $"topref-size mismatch expected={topCellCount} actual={topRefs.Length} topLx={topLx}";
                return false;
            }

            Buffer.BlockCopy(topRefs, 0, field.TopRef, 0, topRefs.Length * sizeof(ushort));
            field.TopMap = new TopologyAreaLikeOriginal[areaCount];
            field.NAreas = areaCount;
            field.MaxArea = areaCount;
            for (int i = 0; i < areaCount; i++)
            {
                TopologyAreaLikeOriginal areaLikeOriginal = new TopologyAreaLikeOriginal
                {
                    X = ax != null && i < ax.Length ? ax[i] : (ushort)0,
                    Y = ay != null && i < ay.Length ? ay[i] : (ushort)0,
                    NLinks = linkCounts != null && i < linkCounts.Length ? linkCounts[i] : (ushort)0,
                    Q0 = q0 != null && i < q0.Length && q0[i] != null ? (ushort[])q0[i].Clone() : Array.Empty<ushort>(),
                    Q1 = q1 != null && i < q1.Length && q1[i] != null ? (ushort[])q1[i].Clone() : Array.Empty<ushort>(),
                    Q2 = q2 != null && i < q2.Length && q2[i] != null ? (ushort[])q2[i].Clone() : Array.Empty<ushort>(),
                    Q3 = q3 != null && i < q3.Length && q3[i] != null ? (ushort[])q3[i].Clone() : Array.Empty<ushort>()
                };
                DecodeTopologyAreaLinksFromTplLikeOriginal(areaLikeOriginal);
                field.TopMap[i] = areaLikeOriginal;
            }

            map.ActiveTopTypeLikeOriginal = topType;
            map.ActiveTopRefLikeOriginal = field.TopRef;
            map.TopologyDecodedImmediateLikeOriginal = true;
            return true;
        }


        private static void EnsureTopologyCreateAreasAndWayRuntimeLikeOriginal(ParsedMap map)
        {
            if (map == null || map.TopologyFieldsLikeOriginal == null)
                return;

            for (int i = 0; i < map.TopologyFieldsLikeOriginal.Length; i++)
            {
                TopologyHashTableLikeOriginal field = map.TopologyFieldsLikeOriginal[i];
                if (field == null)
                    continue;

                CreateAreasLikeOriginal(map, field);
            }
        }

        private static void DecodeAllTopologyLinksFromTplLikeOriginal(TopologyHashTableLikeOriginal field)
        {
            if (field == null || field.TopMap == null)
                return;

            for (int i = 0; i < field.TopMap.Length; i++)
            {
                if (field.TopMap[i] != null)
                    DecodeTopologyAreaLinksFromTplLikeOriginal(field.TopMap[i]);
            }
        }

        private static void DecodeTopologyAreaLinksFromTplLikeOriginal(TopologyAreaLikeOriginal area)
        {
            if (area == null)
                return;

            int count = Math.Max(0,
                Math.Max(area.Q0 != null ? area.Q0.Length : 0,
                Math.Max(area.Q1 != null ? area.Q1.Length : 0,
                Math.Max(area.Q2 != null ? area.Q2.Length : 0, area.Q3 != null ? area.Q3.Length : 0))));

            if (count <= 0)
            {
                area.NLinks = 0;
                area.MaxLink = 0;
                area.Link = Array.Empty<OneLinkInfoLikeOriginal>();
                return;
            }

            area.EnsureLinkCapacityLikeOriginal(count);
            for (int i = 0; i < count; i++)
            {
                OneLinkInfoLikeOriginal link = area.Link[i] ?? (area.Link[i] = new OneLinkInfoLikeOriginal());
                link.NextAreaID = area.Q0 != null && i < area.Q0.Length ? area.Q0[i] : (ushort)0xFFFF;
                link.NextAreaDist = area.Q1 != null && i < area.Q1.Length ? area.Q1[i] : (ushort)1;
                uint mask = ((uint)(area.Q2 != null && i < area.Q2.Length ? area.Q2[i] : 0xFFFF))
                          | (((uint)(area.Q3 != null && i < area.Q3.Length ? area.Q3[i] : 0xFFFF)) << 16);
                if (mask == 0u)
                    mask = 0xFFFFFFFFu;
                link.LinkNatMask = mask;
            }
            area.NLinks = (ushort)Math.Min(count, 0xFFFF);
            area.MaxLink = (ushort)Math.Max((int)area.MaxLink, count);
        }

        private static bool HasAnyTopologyTplPayloadLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return false;
            return (map.Chunk0TPL != null && map.Chunk0TPL.Length > 0)
                || (map.Chunk1TPL != null && map.Chunk1TPL.Length > 0)
                || (map.Chunk2TPL != null && map.Chunk2TPL.Length > 0);
        }

        private static bool FieldHasMeaningfulTopRefLikeOriginal(TopologyHashTableLikeOriginal field)
        {
            if (field == null || field.TopRef == null || field.TopRef.Length == 0)
                return false;

            for (int i = 0; i < field.TopRef.Length; i++)
            {
                ushort v = field.TopRef[i];
                if (v != 0xFFFF && v != 0xFFFE)
                    return true;
            }
            return false;
        }

        private static bool IsTopologyCellBlockedLikeOriginal(TopologyHashTableLikeOriginal field, int index)
        {
            if (field == null || field.TopRef == null || index < 0 || index >= field.TopRef.Length)
                return false;
            return field.TopRef[index] == 0xFFFE;
        }


        private static bool HasMeaningfulTopologyMotionFieldLikeOriginal(ParsedMap map, int topType)
        {
            if (map == null || map.MotionFieldMapsLikeOriginal == null || topType < 0 || topType >= map.MotionFieldMapsLikeOriginal.Length)
                return false;
            byte[] motion = map.MotionFieldMapsLikeOriginal[topType];
            if (motion == null || motion.Length == 0)
                return false;
            for (int i = 0; i < motion.Length; i++)
            {
                if (motion[i] != 0)
                    return true;
            }
            return false;
        }

        private static int GetTopologyMotionFieldIndexLikeOriginal(ParsedMap map, int x, int y)
        {
            if (map == null || x < 0 || y < 0 || x >= map.MAPSX || y >= map.MAPSY)
                return -1;
            return (x << map.MAPSHF) + (y >> 3);
        }

        private static bool GetTopologyCheckPtLikeOriginal(ParsedMap map, int topType, int x, int y)
        {
            if (map == null || x < 0 || y < 0 || x >= map.MAPSX || y >= map.MAPSY)
                return true;
            if (map.MotionFieldMapsLikeOriginal == null || topType < 0 || topType >= map.MotionFieldMapsLikeOriginal.Length)
                return false;
            byte[] motion = map.MotionFieldMapsLikeOriginal[topType];
            if (motion == null || motion.Length == 0)
                return false;
            int idx = GetTopologyMotionFieldIndexLikeOriginal(map, x, y);
            if (idx < 0 || idx >= motion.Length)
                return true;
            int bit = 1 << (y & 7);
            return (motion[idx] & bit) != 0;
        }

        private static void SetTopologyBlockedPtLikeOriginal(ParsedMap map, int topType, int x, int y)
        {
            if (map == null || x < 0 || y < 0 || x >= map.MAPSX || y >= map.MAPSY)
                return;
            if (map.MotionFieldMapsLikeOriginal == null || topType < 0 || topType >= map.MotionFieldMapsLikeOriginal.Length)
                return;
            byte[] motion = map.MotionFieldMapsLikeOriginal[topType];
            if (motion == null || motion.Length == 0)
                return;
            int idx = GetTopologyMotionFieldIndexLikeOriginal(map, x, y);
            if (idx < 0 || idx >= motion.Length)
                return;
            motion[idx] = (byte)(motion[idx] | (1 << (y & 7)));
        }

        private static bool GetTopologyCheckVLineLikeOriginal(ParsedMap map, int topType, int x, int y, int ly)
        {
            for (int i = 0; i < ly; i++)
            {
                if (GetTopologyCheckPtLikeOriginal(map, topType, x, y + i))
                    return true;
            }
            return false;
        }

        private static bool GetTopologyCheckBarLikeOriginal(ParsedMap map, int topType, int x, int y, int lx, int ly)
        {
            for (int ix = 0; ix < lx; ix++)
            {
                if (GetTopologyCheckVLineLikeOriginal(map, topType, x + ix, y, ly))
                    return true;
            }
            return false;
        }

        private static bool GetTCStatusLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field, int x, int y, ushort[] previousTopRef)
        {
            if (map == null || field == null)
                return false;

            int ofs = x + (y << map.TopSH);
            if (previousTopRef != null && ofs >= 0 && ofs < previousTopRef.Length && previousTopRef[ofs] == 0xFFFE)
                return true;

            if (HasMeaningfulTopologyMotionFieldLikeOriginal(map, field.TopType))
            {
                int xxx = x << 2;
                int yyy = y << 2;
                if (GetTopologyCheckBarLikeOriginal(map, field.TopType, xxx, yyy, 4, 4))
                    return true;
            }

            if (field.TopType == 1 && map.Water != null && map.Water.HasSea2Payload && map.Heights != null && map.Heights.Length > 0)
            {
                int vx = Mathf.Clamp(x << 1, 0, Math.Max(0, map.VertInLine - 1));
                int vy = Mathf.Clamp(y << 1, 0, Math.Max(0, map.MaxTH - 1));
                int vidx = vy * map.VertInLine + vx;
                if (vidx >= 0 && vidx < map.Heights.Length)
                    return map.Heights[vidx] <= 0;
            }

            return false;
        }


        private static short DecodeSpriteSignLikeOriginal(BinaryReader br)
        {
            return br.ReadInt16();
        }

        private static bool IsTreeSpriteSignLikeOriginal(short sign)
        {
            return sign == (short)('G' | ('A' << 8));
        }

        private static bool IsStoneSpriteSignLikeOriginal(short sign)
        {
            return sign == (short)('T' | ('S' << 8));
        }

        private static bool IsHoleSpriteSignLikeOriginal(short sign)
        {
            return sign == (short)('O' | ('H' << 8));
        }

        private static bool IsComplexSpriteSignLikeOriginal(short sign)
        {
            return sign == (short)('O' | ('C' << 8));
        }

        private static bool IsResourceSpriteLikeOriginal(DecodedSpriteLikeOriginal sprite)
        {
            return sprite != null && (sprite.IsTreeLikeOriginal || sprite.IsStoneLikeOriginal || sprite.IsHoleLikeOriginal);
        }

        private static void EnsureDecodedTre2SpritesLikeOriginal(ParsedMap map)
        {
            if (map == null || map.Tre2DecodedLikeOriginal)
                return;

            map.Tre2DecodedLikeOriginal = true;
            map.DecodedSpritesLikeOriginal = Array.Empty<DecodedSpriteLikeOriginal>();
            map.SpRefListsLikeOriginal = Array.Empty<int[]>();

            if (map.NSpriLikeOriginal != null)
                Array.Clear(map.NSpriLikeOriginal, 0, map.NSpriLikeOriginal.Length);
            if (map.SpRefsLikeOriginal != null)
                Array.Clear(map.SpRefsLikeOriginal, 0, map.SpRefsLikeOriginal.Length);

            byte[] payload = map.ChunkTRE2;
            if (payload == null || payload.Length < 4)
                return;

            try
            {
                using (var ms = new MemoryStream(payload, false))
                using (var br = new BinaryReader(ms))
                {
                    int ns = br.ReadInt32();
                    if (ns < 0 || ns > 1_000_000)
                        return;

                    var list = new List<DecodedSpriteLikeOriginal>(Math.Max(0, ns));
                    for (int i = 0; i < ns && ms.Position + 15 <= ms.Length; i++)
                    {
                        var sprite = new DecodedSpriteLikeOriginal();
                        sprite.SignLikeOriginal = DecodeSpriteSignLikeOriginal(br);
                        sprite.X = br.ReadInt32();
                        sprite.Y = br.ReadInt32();
                        sprite.GroupIndexLikeOriginal = br.ReadUInt16();
                        ushort nind = br.ReadUInt16();
                        sprite.NIndexLikeOriginal = (ushort)(nind & 4095);
                        sprite.LockingLikeOriginal = (byte)(nind >> 12);
                        byte hasM4 = br.ReadByte();
                        if (hasM4 != 0)
                        {
                            const int matrixBytes = 64;
                            if (ms.Position + matrixBytes > ms.Length)
                                break;
                            ms.Position += matrixBytes;
                            sprite.HasMatrixLikeOriginal = true;
                        }

                        sprite.IsTreeLikeOriginal = IsTreeSpriteSignLikeOriginal(sprite.SignLikeOriginal);
                        sprite.IsStoneLikeOriginal = IsStoneSpriteSignLikeOriginal(sprite.SignLikeOriginal);
                        sprite.IsHoleLikeOriginal = IsHoleSpriteSignLikeOriginal(sprite.SignLikeOriginal);
                        sprite.IsComplexLikeOriginal = IsComplexSpriteSignLikeOriginal(sprite.SignLikeOriginal);
                        list.Add(sprite);
                    }

                    map.DecodedSpritesLikeOriginal = list.ToArray();
                }
            }
            catch
            {
                map.DecodedSpritesLikeOriginal = Array.Empty<DecodedSpriteLikeOriginal>();
            }

            RebuildSpriteCellRefsLikeOriginal(map);
        }

        private static void RebuildSpriteCellRefsLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            int stride = map.SafeMLx > 0 ? map.SafeMLx : 0;
            int size = map.NSpriLikeOriginal != null ? map.NSpriLikeOriginal.Length : 0;
            if (stride <= 0 || size <= 0)
            {
                map.SpRefListsLikeOriginal = Array.Empty<int[]>();
                return;
            }

            var temp = new List<int>[size];
            if (map.NSpriLikeOriginal != null)
                Array.Clear(map.NSpriLikeOriginal, 0, map.NSpriLikeOriginal.Length);
            if (map.SpRefsLikeOriginal != null)
                Array.Clear(map.SpRefsLikeOriginal, 0, map.SpRefsLikeOriginal.Length);

            DecodedSpriteLikeOriginal[] sprites = map.DecodedSpritesLikeOriginal;
            if (sprites == null || sprites.Length == 0)
            {
                map.SpRefListsLikeOriginal = Array.Empty<int[]>();
                return;
            }

            for (int i = 0; i < sprites.Length; i++)
            {
                DecodedSpriteLikeOriginal sprite = sprites[i];
                if (sprite == null)
                    continue;

                int cellX = sprite.X >> 7;
                int cellY = sprite.Y >> 7;
                if (cellX < 0 || cellY < 0 || cellX >= stride)
                    continue;
                int idx = cellX + cellY * stride;
                if (idx < 0 || idx >= size)
                    continue;

                if (temp[idx] == null)
                    temp[idx] = new List<int>(4);
                temp[idx].Add(i);
            }

            var packed = new int[size][];
            for (int i = 0; i < size; i++)
            {
                List<int> cell = temp[i];
                if (cell == null || cell.Count == 0)
                    continue;
                packed[i] = cell.ToArray();
                if (map.NSpriLikeOriginal != null && i < map.NSpriLikeOriginal.Length)
                    map.NSpriLikeOriginal[i] = (byte)Math.Min(255, cell.Count);
                if (map.SpRefsLikeOriginal != null && i < map.SpRefsLikeOriginal.Length)
                    map.SpRefsLikeOriginal[i] = cell[0];
            }

            map.SpRefListsLikeOriginal = packed;
        }

        private static void EnsureDecodedUni3ObjectsLikeOriginal(ParsedMap map)
        {
            if (map == null || map.Uni3DecodedLikeOriginal)
                return;

            map.Uni3DecodedLikeOriginal = true;
            map.DecodedUnitsLikeOriginal = Array.Empty<DecodedUnitLikeOriginal>();

            byte[] payload = map.ChunkUNI3;
            if (payload == null || payload.Length < 4)
                return;

            try
            {
                using (var ms = new MemoryStream(payload, false))
                using (var br = new BinaryReader(ms))
                {
                    int nu = br.ReadInt32();
                    if (nu < 0 || nu > 1_000_000)
                        return;

                    var list = new List<DecodedUnitLikeOriginal>(Math.Max(0, nu));
                    for (int i = 0; i < nu && ms.Position + 54 <= ms.Length; i++)
                    {
                        var unit = new DecodedUnitLikeOriginal();
                        unit.NationLikeOriginal = br.ReadByte();
                        unit.UnitIndexLikeOriginal = br.ReadUInt16();
                        unit.RealX = br.ReadInt32();
                        unit.RealY = br.ReadInt32();
                        unit.LifeLikeOriginal = br.ReadUInt16();
                        unit.StageLikeOriginal = br.ReadUInt16();
                        unit.WallXLikeOriginal = br.ReadInt16();
                        unit.WallYLikeOriginal = br.ReadInt16();
                        unit.DirLikeOriginal = br.ReadByte();
                        unit.OptLikeOriginal = br.ReadByte();
                        byte[] nameBytes = br.ReadBytes(33);
                        int zero = Array.IndexOf(nameBytes, (byte)0);
                        if (zero < 0)
                            zero = nameBytes.Length;
                        unit.NameLikeOriginal = Encoding.ASCII.GetString(nameBytes, 0, zero);

                        string lname = unit.NameLikeOriginal != null ? unit.NameLikeOriginal.ToLowerInvariant() : string.Empty;
                        bool looksBuilding = unit.WallXLikeOriginal != 0 || unit.WallYLikeOriginal != 0;
                        looksBuilding |= unit.StageLikeOriginal != 0 && unit.StageLikeOriginal != 0xFFFF;
                        looksBuilding |= lname.Contains("farm") || lname.Contains("tower") || lname.Contains("port") || lname.Contains("mill") || lname.Contains("meln") || lname.Contains("sklad") || lname.Contains("store") || lname.Contains("dep") || lname.Contains("house") || lname.Contains("hall") || lname.Contains("church") || lname.Contains("mine");
                        unit.LooksLikeBuildingLikeOriginal = looksBuilding;

                        if (looksBuilding)
                        {
                            if (lname.Contains("port")) unit.CantBuildMaskLikeOriginal |= CB_PortLikeOriginal;
                            if (lname.Contains("farm")) unit.CantBuildMaskLikeOriginal |= CB_FarmLikeOriginal;
                            if (lname.Contains("tower")) unit.CantBuildMaskLikeOriginal |= CB_TowerLikeOriginal;
                            if (lname.Contains("mill") || lname.Contains("meln")) unit.CantBuildMaskLikeOriginal |= CB_MelnicaLikeOriginal;
                            if (lname.Contains("sklad") || lname.Contains("store") || lname.Contains("dep")) unit.CantBuildMaskLikeOriginal |= CB_SkladLikeOriginal;
                            unit.CantBuildMaskLikeOriginal |= CB_BuildingLikeOriginal;
                        }

                        list.Add(unit);
                    }

                    map.DecodedUnitsLikeOriginal = list.ToArray();
                }
            }
            catch
            {
                map.DecodedUnitsLikeOriginal = Array.Empty<DecodedUnitLikeOriginal>();
            }
        }

        private static string DecodeSpriteSignTokenLikeOriginal(short sign)
        {
            char c0 = (char)(sign & 0xFF);
            char c1 = (char)((sign >> 8) & 0xFF);
            return new string(new[] { c0, c1 });
        }

        private static string BuildSpriteRuntimeKeyLikeOriginal(DecodedSpriteLikeOriginal sprite)
        {
            if (sprite == null)
                return string.Empty;
            return BuildSpriteRuntimeKeyLikeOriginal(sprite.SignLikeOriginal, sprite.GroupIndexLikeOriginal, sprite.NIndexLikeOriginal);
        }

        private static string BuildSpriteRuntimeKeyLikeOriginal(short sign, ushort groupIndex, ushort nIndex)
        {
            return DecodeSpriteSignTokenLikeOriginal(sign) + ":" + groupIndex + ":" + nIndex;
        }

        private static SpriteRuntimeDefinitionLikeOriginal GetSpriteRuntimeDefinitionLikeOriginal(ParsedMap map, DecodedSpriteLikeOriginal sprite)
        {
            if (map == null || sprite == null || map.SpriteRuntimeDefsByKeyLikeOriginal == null)
                return null;

            SpriteRuntimeDefinitionLikeOriginal def;
            string exactKey = BuildSpriteRuntimeKeyLikeOriginal(sprite);
            if (map.SpriteRuntimeDefsByKeyLikeOriginal.TryGetValue(exactKey, out def) && def != null)
                return def;

            string looseKey = DecodeSpriteSignTokenLikeOriginal(sprite.SignLikeOriginal) + ":" + sprite.GroupIndexLikeOriginal;
            if (map.SpriteRuntimeDefsByKeyLikeOriginal.TryGetValue(looseKey, out def) && def != null)
                return def;

            return null;
        }

        private static UnitRuntimeDefinitionLikeOriginal GetUnitRuntimeDefinitionLikeOriginal(ParsedMap map, DecodedUnitLikeOriginal unit)
        {
            if (map == null || unit == null)
                return null;

            UnitRuntimeDefinitionLikeOriginal def;
            if (map.UnitRuntimeDefsByIndexLikeOriginal != null && map.UnitRuntimeDefsByIndexLikeOriginal.TryGetValue(unit.UnitIndexLikeOriginal, out def) && def != null)
                return def;

            if (!string.IsNullOrEmpty(unit.NameLikeOriginal) && map.UnitRuntimeDefsByNameLikeOriginal != null)
            {
                string key = unit.NameLikeOriginal.ToLowerInvariant();
                if (map.UnitRuntimeDefsByNameLikeOriginal.TryGetValue(key, out def) && def != null)
                    return def;
            }

            return null;
        }

        private static bool PointInsidePolygonLikeOriginal(int px, int py, LockPointLikeOriginal[] points)
        {
            if (points == null || points.Length < 3)
                return false;

            bool inside = false;
            int j = points.Length - 1;
            for (int i = 0; i < points.Length; i++)
            {
                int xi = points[i].X;
                int yi = points[i].Y;
                int xj = points[j].X;
                int yj = points[j].Y;

                bool intersects = ((yi > py) != (yj > py)) &&
                                  (px < (double)(xj - xi) * (py - yi) / Math.Max(1e-9, yj - yi) + xi);
                if (intersects)
                    inside = !inside;
                j = i;
            }

            return inside;
        }

        private static void ApplyLockPolygonLikeOriginal(ParsedMap map, byte[] motion, int x0, int y0, LockPointLikeOriginal[] lockInfo)
        {
            if (map == null || motion == null || lockInfo == null || lockInfo.Length < 3)
                return;

            int minx = int.MaxValue;
            int miny = int.MaxValue;
            int maxx = int.MinValue;
            int maxy = int.MinValue;
            var worldPoints = new LockPointLikeOriginal[lockInfo.Length];
            for (int i = 0; i < lockInfo.Length; i++)
            {
                var src = lockInfo[i];
                int wx = x0 + src.X;
                int wy = y0 + src.Y;
                worldPoints[i] = new LockPointLikeOriginal { X = wx, Y = wy };
                if (wx < minx) minx = wx;
                if (wy < miny) miny = wy;
                if (wx > maxx) maxx = wx;
                if (wy > maxy) maxy = wy;
            }

            minx = (minx >> 4) - 4;
            miny = (miny >> 3) - 4;
            maxx = (maxx >> 4) + 4;
            maxy = (maxy >> 3) + 4;
            for (int dx = minx; dx <= maxx; dx++)
            {
                for (int dy = miny; dy <= maxy; dy++)
                {
                    if (PointInsidePolygonLikeOriginal((dx << 4) + 8, (dy << 3) + 4, worldPoints))
                        SetMotionFieldPointLikeOriginal(map, motion, dx, dy);
                }
            }
        }

        private static LockPointLikeOriginal[] BuildFallbackSpritePolygonLikeOriginal(DecodedSpriteLikeOriginal sprite)
        {
            if (sprite == null)
                return Array.Empty<LockPointLikeOriginal>();

            int rx = 16;
            int ry = 8;
            if (sprite.IsStoneLikeOriginal)
            {
                rx = 24;
                ry = 12;
            }
            else if (sprite.IsHoleLikeOriginal)
            {
                rx = 18;
                ry = 9;
            }
            else if (sprite.IsComplexLikeOriginal)
            {
                rx = 32;
                ry = 16;
            }
            else if (sprite.LockingLikeOriginal >= 2)
            {
                rx = 20;
                ry = 10;
            }

            return new[]
            {
                new LockPointLikeOriginal { X = -rx, Y = 0 },
                new LockPointLikeOriginal { X = 0, Y = -ry },
                new LockPointLikeOriginal { X = rx, Y = 0 },
                new LockPointLikeOriginal { X = 0, Y = ry },
            };
        }

        private static void ApplySpriteLockLikeOriginal(ParsedMap map, byte[] motion, DecodedSpriteLikeOriginal sprite, bool resourcesOnly)
        {
            if (map == null || motion == null || sprite == null)
                return;

            SpriteRuntimeDefinitionLikeOriginal def = GetSpriteRuntimeDefinitionLikeOriginal(map, sprite);
            if (def != null)
            {
                bool isResource = def.IntResTypeLikeOriginal >= 0 && def.IntResTypeLikeOriginal < 8;
                bool isObstacle = def.IntResTypeLikeOriginal > 7;
                if ((resourcesOnly && !isResource) || (!resourcesOnly && !isObstacle && def.LockInfoLikeOriginal.Length == 0))
                    return;

                if (def.LockInfoLikeOriginal != null && def.LockInfoLikeOriginal.Length >= 3)
                {
                    int x0 = sprite.X - def.CenterXLikeOriginal;
                    int y0 = (sprite.Y >> 1) - def.CenterYLikeOriginal;
                    ApplyLockPolygonLikeOriginal(map, motion, x0, y0, def.LockInfoLikeOriginal);
                    return;
                }
            }

            bool fallbackResource = IsResourceSpriteLikeOriginal(sprite);
            if ((resourcesOnly && !fallbackResource) || (!resourcesOnly && fallbackResource && !sprite.IsComplexLikeOriginal && sprite.LockingLikeOriginal == 0))
                return;

            int x0f = sprite.X;
            int y0f = sprite.Y >> 1;
            ApplyLockPolygonLikeOriginal(map, motion, x0f, y0f, BuildFallbackSpritePolygonLikeOriginal(sprite));
        }

        private static void ApplyApproxSpriteLockLikeOriginal(ParsedMap map, byte[] motion, DecodedSpriteLikeOriginal sprite)
        {
            ApplySpriteLockLikeOriginal(map, motion, sprite, true);
        }

        private static void ApplyExactUnitFootprintLikeOriginal(ParsedMap map, byte[] motion, DecodedUnitLikeOriginal unit, UnitRuntimeDefinitionLikeOriginal def)
        {
            if (map == null || motion == null || unit == null || def == null)
                return;

            bool useBuild = unit.StageLikeOriginal < def.ProduceStagesLikeOriginal && def.BLockXLikeOriginal != null && def.BLockYLikeOriginal != null && def.BLockXLikeOriginal.Length == def.BLockYLikeOriginal.Length && def.BLockXLikeOriginal.Length > 0;
            byte[] lockX = useBuild ? def.BLockXLikeOriginal : def.LockXLikeOriginal;
            byte[] lockY = useBuild ? def.BLockYLikeOriginal : def.LockYLikeOriginal;
            if (lockX == null || lockY == null || lockX.Length == 0 || lockX.Length != lockY.Length)
                return;

            int xx = (unit.RealX >> 4) + def.PicDxLikeOriginal;
            int yy = (unit.RealY >> 4) + (def.PicDyLikeOriginal << 1);
            for (int i = 0; i < lockX.Length; i++)
                SetMotionFieldPointLikeOriginal(map, motion, xx + lockX[i], yy + lockY[i]);
        }

        private static void ApplyApproxBuildingLockLikeOriginal(ParsedMap map, byte[] motion, DecodedUnitLikeOriginal unit)
        {
            if (map == null || motion == null || unit == null)
                return;

            UnitRuntimeDefinitionLikeOriginal def = GetUnitRuntimeDefinitionLikeOriginal(map, unit);
            if (def != null)
            {
                ApplyExactUnitFootprintLikeOriginal(map, motion, unit, def);
                return;
            }

            int dx = unit.RealX >> 4;
            int dy = unit.RealY >> 4;
            int radiusX = 2;
            int radiusY = 2;
            if (unit.WallXLikeOriginal != 0 || unit.WallYLikeOriginal != 0)
            {
                radiusX = 3;
                radiusY = 3;
            }
            if ((unit.CantBuildMaskLikeOriginal & CB_PortLikeOriginal) != 0)
            {
                radiusX = 5;
                radiusY = 4;
            }
            else if ((unit.CantBuildMaskLikeOriginal & CB_FarmLikeOriginal) != 0)
            {
                radiusX = 4;
                radiusY = 4;
            }
            SetTopologyBlockedSquareLikeOriginal(map, motion, dx - radiusX, dy - radiusY, radiusX * 2 + 1, radiusY * 2 + 1);
        }

        private static void ClearTopologyBlockedPtLikeOriginal(ParsedMap map, byte[] motion, int x, int y)
        {
            if (map == null || motion == null || x < 0 || y < 0 || x >= map.MAPSX || y >= map.MAPSY)
                return;
            int idx = GetTopologyMotionFieldIndexLikeOriginal(map, x, y);
            if (idx < 0 || idx >= motion.Length)
                return;
            motion[idx] = (byte)(motion[idx] & ~(1 << (y & 7)));
        }

        private static void SetMotionFieldPointLikeOriginal(ParsedMap map, byte[] motion, int x, int y)
        {
            if (map == null || motion == null || x < 0 || y < 0 || x >= map.MAPSX || y >= map.MAPSY)
                return;
            int idx = GetTopologyMotionFieldIndexLikeOriginal(map, x, y);
            if (idx < 0 || idx >= motion.Length)
                return;
            motion[idx] = (byte)(motion[idx] | (1 << (y & 7)));
        }

        private static void ClearMotionFieldPointLikeOriginal(ParsedMap map, byte[] motion, int x, int y)
        {
            if (map == null || motion == null || x < 0 || y < 0 || x >= map.MAPSX || y >= map.MAPSY)
                return;
            int idx = GetTopologyMotionFieldIndexLikeOriginal(map, x, y);
            if (idx < 0 || idx >= motion.Length)
                return;
            motion[idx] = (byte)(motion[idx] & ~(1 << (y & 7)));
        }

        private static void SetTopologyBlockedBarLikeOriginal(ParsedMap map, byte[] motion, int x, int y, int lx, int ly)
        {
            if (map == null || motion == null || lx <= 0 || ly <= 0)
                return;
            for (int ix = 0; ix < lx; ix++)
            {
                for (int iy = 0; iy < ly; iy++)
                    SetMotionFieldPointLikeOriginal(map, motion, x + ix, y + iy);
            }
        }

        private static void ClearTopologyBlockedBarLikeOriginal(ParsedMap map, byte[] motion, int x, int y, int lx, int ly)
        {
            if (map == null || motion == null || lx <= 0 || ly <= 0)
                return;
            for (int ix = 0; ix < lx; ix++)
            {
                for (int iy = 0; iy < ly; iy++)
                    ClearMotionFieldPointLikeOriginal(map, motion, x + ix, y + iy);
            }
        }

        private static bool CheckTopologyBlockedBarLikeOriginal(ParsedMap map, byte[] motion, int x, int y, int lx, int ly)
        {
            if (map == null || motion == null || lx <= 0 || ly <= 0)
                return false;
            for (int ix = 0; ix < lx; ix++)
            {
                for (int iy = 0; iy < ly; iy++)
                {
                    int sx = x + ix;
                    int sy = y + iy;
                    int idx = GetTopologyMotionFieldIndexLikeOriginal(map, sx, sy);
                    if (idx >= 0 && idx < motion.Length && (motion[idx] & (1 << (sy & 7))) != 0)
                        return true;
                }
            }
            return false;
        }

        private static void SetTopologyBlockedSquareLikeOriginal(ParsedMap map, byte[] motion, int x, int y, int lx, int ly)
        {
            if (map == null || motion == null || lx <= 0 || ly <= 0)
                return;
            int x0 = Mathf.Clamp(x, 0, map.MAPSX);
            int y0 = Mathf.Clamp(y, 0, map.MAPSY);
            int x1 = Mathf.Clamp(x + lx, 0, map.MAPSX);
            int y1 = Mathf.Clamp(y + ly, 0, map.MAPSY);
            for (int ix = x0; ix < x1; ix++)
            {
                for (int iy = y0; iy < y1; iy++)
                    SetMotionFieldPointLikeOriginal(map, motion, ix, iy);
            }
        }

        private static void ApplyTopologyMaskLikeOriginal(ParsedMap map, byte[] motion, int x, int y, string mask)
        {
            if (map == null || motion == null || string.IsNullOrEmpty(mask) || mask.Length < 16)
                return;
            int pos = 0;
            for (int iy = 0; iy < 4; iy++)
            {
                for (int ix = 0; ix < 4; ix++)
                {
                    if (mask[pos] == '*')
                        SetMotionFieldPointLikeOriginal(map, motion, x + ix, y + iy);
                    else
                        ClearMotionFieldPointLikeOriginal(map, motion, x + ix, y + iy);
                    pos++;
                }
            }
        }

        private static int SampleHeightFromMapLikeOriginal(ParsedMap map, int x, int y)
        {
            if (map == null || map.THMapLikeOriginal == null || map.THMapLikeOriginal.Length == 0 || map.VertInLine <= 0 || map.MaxTH <= 0)
                return 0;

            int col = Mathf.Clamp(Mathf.RoundToInt(x / 32.0f), 0, map.VertInLine - 1);
            int row = Mathf.Clamp(Mathf.RoundToInt(y / 64.0f), 0, map.MaxTH - 1);
            int idx = row * map.VertInLine + col;
            if (idx < 0 || idx >= map.THMapLikeOriginal.Length)
                return 0;
            return map.THMapLikeOriginal[idx];
        }

        private static void ClearRuntimeLockingMapsLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;
            if (map.MotionFieldMapsLikeOriginal != null)
            {
                for (int i = 0; i < map.MotionFieldMapsLikeOriginal.Length; i++)
                {
                    if (map.MotionFieldMapsLikeOriginal[i] != null)
                        Array.Clear(map.MotionFieldMapsLikeOriginal[i], 0, map.MotionFieldMapsLikeOriginal[i].Length);
                }
            }
            if (map.TempMFMapLikeOriginal != null)
                Array.Clear(map.TempMFMapLikeOriginal, 0, map.TempMFMapLikeOriginal.Length);
            if (map.UnitsFieldMapLikeOriginal != null)
                Array.Clear(map.UnitsFieldMapLikeOriginal, 0, map.UnitsFieldMapLikeOriginal.Length);
            if (map.NObj3LikeOriginal != null)
                Array.Clear(map.NObj3LikeOriginal, 0, map.NObj3LikeOriginal.Length);
            if (map.InfoMapLikeOriginal != null)
                Array.Clear(map.InfoMapLikeOriginal, 0, map.InfoMapLikeOriginal.Length);
            if (map.CantBuildLikeOriginal != null)
                Array.Clear(map.CantBuildLikeOriginal, 0, map.CantBuildLikeOriginal.Length);
            map.FishLxLikeOriginal = 0;
            map.FishMapLikeOriginal = Array.Empty<byte>();
        }

        private static void CreateFishMapLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            int fishLx = Mathf.Max(0, map.MAPSX >> FishSXLikeOriginal);
            map.FishLxLikeOriginal = fishLx;
            if (fishLx <= 0)
            {
                map.FishMapLikeOriginal = Array.Empty<byte>();
                return;
            }

            int fishCount = fishLx * fishLx;
            if (map.FishMapLikeOriginal == null || map.FishMapLikeOriginal.Length != fishCount)
                map.FishMapLikeOriginal = new byte[fishCount];
            else
                Array.Clear(map.FishMapLikeOriginal, 0, map.FishMapLikeOriginal.Length);

            int sx = FishSXLikeOriginal + 1;
            int size = 2 << FishSXLikeOriginal;
            for (int x = 0; x < fishLx; x++)
            {
                for (int y = 0; y < fishLx; y++)
                {
                    if (GetTopologyCheckBarLikeOriginal(map, 1, x << sx, y << sx, size, size))
                        map.FishMapLikeOriginal[x + y * fishLx] = 2;
                }
            }
        }

        private static byte TestFishMapLikeOriginal(ParsedMap map, int x, int y)
        {
            if (map == null || map.FishLxLikeOriginal <= 0 || map.FishMapLikeOriginal == null)
                return 0;
            if (x < 0 || y < 0 || x >= map.FishLxLikeOriginal || y >= map.FishLxLikeOriginal)
                return 0;

            int sx = FishSXLikeOriginal + 1;
            int size = 2 << FishSXLikeOriginal;
            int px = x << sx;
            int py = y << sx;
            if (map.UnitsFieldMapLikeOriginal != null && CheckTopologyBlockedBarLikeOriginal(map, map.UnitsFieldMapLikeOriginal, px, py, size, size))
                return 1;
            if (GetTopologyCheckBarLikeOriginal(map, 1, px, py, size, size))
                return 1;
            return map.FishMapLikeOriginal[x + y * map.FishLxLikeOriginal];
        }

        private static void CreateAdditionalObjectsLockingLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            // HexagonalNet.cpp registers extra height objects through WMAP.ExObjs.
            // Battle .m3d parse path currently has no literal WMAP.ExObjs source,
            // so this stage remains an explicit hook only. Static TRE2 obstacle sprites
            // are already folded into CreateLandLockingLikeOriginal() via ApplySpriteLockLikeOriginal(..., false).
            EnsureDecodedTre2SpritesLikeOriginal(map);
        }

        private static void CreateLandLockingLikeOriginal(ParsedMap map, int tAlp, bool forVision)
        {
            if (map == null || map.MotionFieldMapsLikeOriginal == null || map.MotionFieldMapsLikeOriginal.Length < TopologyFieldCountLikeOriginal)
                return;

            byte[] ground = map.MotionFieldMapsLikeOriginal[0];
            byte[] water = map.MotionFieldMapsLikeOriginal[1];
            byte[] horse = map.MotionFieldMapsLikeOriginal[2];
            byte[] deep = map.MotionFieldMapsLikeOriginal[3];
            if (ground == null || water == null || horse == null || deep == null)
                return;

            int mxx = map.MAPSX >> 1;
            int myy = map.MAPSY >> 1;
            for (int ix = 0; ix < mxx; ix++)
            {
                for (int iy = myy - 1; iy >= 0; iy--)
                {
                    int x0 = ix << 6;
                    int y0 = iy << 6;
                    int ppx = ix << 2;
                    int ppy = iy << 2;
                    int z0 = SampleHeightFromMapLikeOriginal(map, x0, y0);
                    int z1 = SampleHeightFromMapLikeOriginal(map, x0 + 64, y0);
                    int z2 = SampleHeightFromMapLikeOriginal(map, x0, y0 + 64);
                    int z3 = SampleHeightFromMapLikeOriginal(map, x0 + 64, y0 + 64);
                    int za = (z0 + z1 + z2 + z3) >> 2;

                    if (Math.Abs(z0 - za) >= 23 || Math.Abs(z1 - za) >= 23 || Math.Abs(z2 - za) >= 23 || Math.Abs(z3 - za) >= 23)
                        SetTopologyBlockedBarLikeOriginal(map, ground, ppx, ppy, 4, 4);
                    else
                        ClearTopologyBlockedBarLikeOriginal(map, ground, ppx, ppy, 4, 4);

                    if (za < -10)
                    {
                        SetTopologyBlockedBarLikeOriginal(map, ground, ppx, ppy, 4, 4);
                        SetTopologyBlockedBarLikeOriginal(map, deep, ppx, ppy, 4, 4);
                    }
                    if (za < 0)
                        SetTopologyBlockedBarLikeOriginal(map, horse, ppx, ppy, 4, 4);
                    if (za > 0)
                        SetTopologyBlockedBarLikeOriginal(map, water, ppx, ppy, 4, 4);
                    else
                        ClearTopologyBlockedBarLikeOriginal(map, water, ppx, ppy, 4, 4);
                }
            }

            EnsureDecodedTre2SpritesLikeOriginal(map);
            DecodedSpriteLikeOriginal[] sprites = map.DecodedSpritesLikeOriginal;
            if (sprites != null)
            {
                for (int i = 0; i < sprites.Length; i++)
                    ApplySpriteLockLikeOriginal(map, ground, sprites[i], false);
            }

            if (map.UnLockBarsLikeOriginal != null)
            {
                for (int i = 0; i < map.UnLockBarsLikeOriginal.Length; i++)
                {
                    BlockCellLikeOriginal bc = map.UnLockBarsLikeOriginal[i];
                    ClearTopologyBlockedBarLikeOriginal(map, ground, bc.x << 2, bc.y << 2, 4, 4);
                }
            }
            if (map.LockBarsLikeOriginal != null)
            {
                for (int i = 0; i < map.LockBarsLikeOriginal.Length; i++)
                {
                    BlockCellLikeOriginal bc = map.LockBarsLikeOriginal[i];
                    SetTopologyBlockedBarLikeOriginal(map, ground, bc.x << 2, bc.y << 2, 4, 4);
                }
            }
            if (map.HorseLockBarsLikeOriginal != null)
            {
                for (int i = 0; i < map.HorseLockBarsLikeOriginal.Length; i++)
                {
                    BlockCellLikeOriginal bc = map.HorseLockBarsLikeOriginal[i];
                    SetTopologyBlockedBarLikeOriginal(map, horse, bc.x << 2, bc.y << 2, 4, 4);
                }
            }

            for (int ix = 1; ix < mxx; ix++)
            {
                for (int iy = 1; iy < myy; iy++)
                {
                    int ppx = ix << 2;
                    int ppy = iy << 2;
                    int n = 0;
                    if (CheckTopologyBlockedBarLikeOriginal(map, ground, ppx, ppy, 4, 4))
                    {
                        if (CheckTopologyBlockedBarLikeOriginal(map, ground, ppx, ppy, 2, 2)) n++;
                        if (CheckTopologyBlockedBarLikeOriginal(map, ground, ppx + 2, ppy, 2, 2)) n++;
                        if (CheckTopologyBlockedBarLikeOriginal(map, ground, ppx, ppy + 2, 2, 2)) n++;
                        if (CheckTopologyBlockedBarLikeOriginal(map, ground, ppx + 2, ppy + 2, 2, 2)) n++;
                    }
                    if (n < 3) ClearTopologyBlockedBarLikeOriginal(map, ground, ppx, ppy, 4, 4);
                    else SetTopologyBlockedBarLikeOriginal(map, ground, ppx, ppy, 4, 4);
                }
            }

            byte[] temp = (byte[])ground.Clone();
            for (int ix = 1; ix < mxx; ix++)
            {
                for (int iy = 1; iy < myy; iy++)
                {
                    int ppx = ix << 2;
                    int ppy = iy << 2;
                    byte c = 0;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 1, ppy - 3, 2, 2)) c |= 1;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 5, ppy + 1, 2, 2)) c |= 2;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 1, ppy + 5, 2, 2)) c |= 4;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx - 3, ppy + 1, 2, 2)) c |= 8;
                    if (!CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 1, ppy + 1, 2, 2))
                    {
                        switch (c)
                        {
                            case 3: ApplyTopologyMaskLikeOriginal(map, ground, ppx, ppy, "**** ***  **   *"); break;
                            case 6: ApplyTopologyMaskLikeOriginal(map, ground, ppx, ppy, "   *  ** *******"); break;
                            case 12: ApplyTopologyMaskLikeOriginal(map, ground, ppx, ppy, "*   **  *** ****"); break;
                            case 9: ApplyTopologyMaskLikeOriginal(map, ground, ppx, ppy, "******* **  *   "); break;
                            case 7:
                            case 11:
                            case 13:
                            case 14:
                                SetTopologyBlockedBarLikeOriginal(map, ground, ppx, ppy, 4, 4);
                                break;
                        }
                    }
                }
            }

            temp = (byte[])ground.Clone();
            for (int ix = 1; ix < mxx; ix++)
            {
                for (int iy = 1; iy < myy; iy++)
                {
                    int ppx = ix << 2;
                    int ppy = iy << 2;
                    byte c = 0;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 1, ppy - 3, 2, 2)) c |= 1;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 5, ppy + 1, 2, 2)) c |= 2;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 1, ppy + 5, 2, 2)) c |= 4;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx - 3, ppy + 1, 2, 2)) c |= 8;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 1, ppy + 1, 2, 2))
                    {
                        switch (c)
                        {
                            case 3: ApplyTopologyMaskLikeOriginal(map, ground, ppx, ppy, "**** ***  **   *"); break;
                            case 6: ApplyTopologyMaskLikeOriginal(map, ground, ppx, ppy, "   *  ** *******"); break;
                            case 12: ApplyTopologyMaskLikeOriginal(map, ground, ppx, ppy, "*   **  *** ****"); break;
                            case 9: ApplyTopologyMaskLikeOriginal(map, ground, ppx, ppy, "******* **  *   "); break;
                        }
                    }
                }
            }
        }

        private static void SmoothFieldLikeOriginal(ParsedMap map, int index)
        {
            if (map == null || map.MotionFieldMapsLikeOriginal == null || index < 0 || index >= map.MotionFieldMapsLikeOriginal.Length)
                return;

            byte[] mf = map.MotionFieldMapsLikeOriginal[index];
            if (mf == null)
                return;
            Array.Clear(mf, 0, mf.Length);

            int mxx = map.MAPSX >> 1;
            int myy = map.MAPSY >> 1;
            for (int ix = 0; ix < mxx; ix++)
            {
                for (int iy = myy - 1; iy >= 0; iy--)
                {
                    int x0 = ix << 6;
                    int y0 = iy << 6;
                    int ppx = ix << 2;
                    int ppy = iy << 2;
                    int z0 = SampleHeightFromMapLikeOriginal(map, x0, y0);
                    int z1 = SampleHeightFromMapLikeOriginal(map, x0 + 64, y0);
                    int z2 = SampleHeightFromMapLikeOriginal(map, x0, y0 + 64);
                    int z3 = SampleHeightFromMapLikeOriginal(map, x0 + 64, y0 + 64);
                    int za = (z0 + z1 + z2 + z3) >> 2;
                    if (Math.Abs(z0 - za) >= 23 || Math.Abs(z1 - za) >= 23 || Math.Abs(z2 - za) >= 23 || Math.Abs(z3 - za) >= 23)
                        SetTopologyBlockedBarLikeOriginal(map, mf, ppx, ppy, 4, 4);
                    else
                        ClearTopologyBlockedBarLikeOriginal(map, mf, ppx, ppy, 4, 4);

                    if (index == 2 && za < 0)
                        SetTopologyBlockedBarLikeOriginal(map, mf, ppx, ppy, 4, 4);
                    if (index == 3 && za < -10)
                        SetTopologyBlockedBarLikeOriginal(map, mf, ppx, ppy, 4, 4);
                }
            }

            if (index == 2 && map.HorseLockBarsLikeOriginal != null)
            {
                for (int i = 0; i < map.HorseLockBarsLikeOriginal.Length; i++)
                {
                    BlockCellLikeOriginal bc = map.HorseLockBarsLikeOriginal[i];
                    SetTopologyBlockedBarLikeOriginal(map, mf, bc.x << 2, bc.y << 2, 4, 4);
                }
            }

            if (map.UnLockBarsLikeOriginal != null)
            {
                for (int i = 0; i < map.UnLockBarsLikeOriginal.Length; i++)
                {
                    BlockCellLikeOriginal bc = map.UnLockBarsLikeOriginal[i];
                    ClearTopologyBlockedBarLikeOriginal(map, mf, bc.x << 2, bc.y << 2, 4, 4);
                }
            }
            if (map.LockBarsLikeOriginal != null)
            {
                for (int i = 0; i < map.LockBarsLikeOriginal.Length; i++)
                {
                    BlockCellLikeOriginal bc = map.LockBarsLikeOriginal[i];
                    SetTopologyBlockedBarLikeOriginal(map, mf, bc.x << 2, bc.y << 2, 4, 4);
                }
            }

            for (int ix = 1; ix < mxx; ix++)
            {
                for (int iy = 1; iy < myy; iy++)
                {
                    int ppx = ix << 2;
                    int ppy = iy << 2;
                    int n = 0;
                    if (CheckTopologyBlockedBarLikeOriginal(map, mf, ppx, ppy, 4, 4))
                    {
                        if (CheckTopologyBlockedBarLikeOriginal(map, mf, ppx, ppy, 2, 2)) n++;
                        if (CheckTopologyBlockedBarLikeOriginal(map, mf, ppx + 2, ppy, 2, 2)) n++;
                        if (CheckTopologyBlockedBarLikeOriginal(map, mf, ppx, ppy + 2, 2, 2)) n++;
                        if (CheckTopologyBlockedBarLikeOriginal(map, mf, ppx + 2, ppy + 2, 2, 2)) n++;
                    }
                    if (n < 3) ClearTopologyBlockedBarLikeOriginal(map, mf, ppx, ppy, 4, 4);
                    else SetTopologyBlockedBarLikeOriginal(map, mf, ppx, ppy, 4, 4);
                }
            }

            byte[] temp = (byte[])mf.Clone();
            for (int ix = 1; ix < mxx; ix++)
            {
                for (int iy = 1; iy < myy; iy++)
                {
                    int ppx = ix << 2;
                    int ppy = iy << 2;
                    byte c = 0;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 1, ppy - 3, 2, 2)) c |= 1;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 5, ppy + 1, 2, 2)) c |= 2;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 1, ppy + 5, 2, 2)) c |= 4;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx - 3, ppy + 1, 2, 2)) c |= 8;
                    if (!CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 1, ppy + 1, 2, 2))
                    {
                        switch (c)
                        {
                            case 3: ApplyTopologyMaskLikeOriginal(map, mf, ppx, ppy, "**** ***  **   *"); break;
                            case 6: ApplyTopologyMaskLikeOriginal(map, mf, ppx, ppy, "   *  ** *******"); break;
                            case 12: ApplyTopologyMaskLikeOriginal(map, mf, ppx, ppy, "*   **  *** ****"); break;
                            case 9: ApplyTopologyMaskLikeOriginal(map, mf, ppx, ppy, "******* **  *   "); break;
                            case 7:
                            case 11:
                            case 13:
                            case 14:
                                SetTopologyBlockedBarLikeOriginal(map, mf, ppx, ppy, 4, 4);
                                break;
                        }
                    }
                }
            }

            temp = (byte[])mf.Clone();
            for (int ix = 1; ix < mxx; ix++)
            {
                for (int iy = 1; iy < myy; iy++)
                {
                    int ppx = ix << 2;
                    int ppy = iy << 2;
                    byte c = 0;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 1, ppy - 3, 2, 2)) c |= 1;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 5, ppy + 1, 2, 2)) c |= 2;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 1, ppy + 5, 2, 2)) c |= 4;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx - 3, ppy + 1, 2, 2)) c |= 8;
                    if (CheckTopologyBlockedBarLikeOriginal(map, temp, ppx + 1, ppy + 1, 2, 2))
                    {
                        switch (c)
                        {
                            case 3: ApplyTopologyMaskLikeOriginal(map, mf, ppx, ppy, "**** ***  **   *"); break;
                            case 6: ApplyTopologyMaskLikeOriginal(map, mf, ppx, ppy, "   *  ** *******"); break;
                            case 12: ApplyTopologyMaskLikeOriginal(map, mf, ppx, ppy, "*   **  *** ****"); break;
                            case 9: ApplyTopologyMaskLikeOriginal(map, mf, ppx, ppy, "******* **  *   "); break;
                        }
                    }
                }
            }
        }

        private static void CreateMinesLockingLikeOriginal(ParsedMap map)
        {
            if (map == null || map.MotionFieldMapsLikeOriginal == null || map.MotionFieldMapsLikeOriginal.Length == 0)
                return;
            byte[] ground = map.MotionFieldMapsLikeOriginal[0];
            if (ground == null)
                return;

            EnsureDecodedTre2SpritesLikeOriginal(map);
            DecodedSpriteLikeOriginal[] sprites = map.DecodedSpritesLikeOriginal;
            if (sprites == null)
                return;
            for (int i = 0; i < sprites.Length; i++)
                ApplySpriteLockLikeOriginal(map, ground, sprites[i], true);
        }

        private static void ApplyCantBuildFootprintLikeOriginal(ParsedMap map, DecodedUnitLikeOriginal unit, UnitRuntimeDefinitionLikeOriginal def, byte mask)
        {
            if (map == null || map.CantBuildLikeOriginal == null || mask == 0 || unit == null)
                return;

            int stride = map.SafeMLx > 0 ? map.SafeMLx : 0;
            if (stride <= 0)
                return;

            if (def != null)
            {
                bool useBuild = unit.StageLikeOriginal < def.ProduceStagesLikeOriginal && def.BLockXLikeOriginal != null && def.BLockYLikeOriginal != null && def.BLockXLikeOriginal.Length == def.BLockYLikeOriginal.Length && def.BLockXLikeOriginal.Length > 0;
                byte[] lockX = useBuild ? def.BLockXLikeOriginal : def.LockXLikeOriginal;
                byte[] lockY = useBuild ? def.BLockYLikeOriginal : def.LockYLikeOriginal;
                int xx = (unit.RealX >> 4) + def.PicDxLikeOriginal;
                int yy = (unit.RealY >> 4) + (def.PicDyLikeOriginal << 1);
                if (lockX != null && lockY != null && lockX.Length == lockY.Length && lockX.Length > 0)
                {
                    for (int i = 0; i < lockX.Length; i++)
                    {
                        int sx = (xx + lockX[i]) >> 3;
                        int sy = (yy + lockY[i]) >> 3;
                        int ofst = sx + sy * stride;
                        if (ofst >= 0 && ofst < map.CantBuildLikeOriginal.Length)
                            map.CantBuildLikeOriginal[ofst] = (byte)(map.CantBuildLikeOriginal[ofst] | mask);
                    }
                    return;
                }
            }

            int cx = unit.RealX >> 7;
            int cy = unit.RealY >> 7;
            int ofst0 = cx + cy * stride;
            if (ofst0 >= 0 && ofst0 < map.CantBuildLikeOriginal.Length)
                map.CantBuildLikeOriginal[ofst0] = (byte)(map.CantBuildLikeOriginal[ofst0] | mask);
        }

        private static void CreateUnitsLockingLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            if (map.UnitsFieldMapLikeOriginal != null)
                Array.Clear(map.UnitsFieldMapLikeOriginal, 0, map.UnitsFieldMapLikeOriginal.Length);
            if (map.NObj3LikeOriginal != null)
                Array.Clear(map.NObj3LikeOriginal, 0, map.NObj3LikeOriginal.Length);

            EnsureDecodedUni3ObjectsLikeOriginal(map);
            DecodedUnitLikeOriginal[] units = map.DecodedUnitsLikeOriginal;
            if (units == null || units.Length == 0)
                return;

            byte[] ground = map.MotionFieldMapsLikeOriginal != null && map.MotionFieldMapsLikeOriginal.Length > 0 ? map.MotionFieldMapsLikeOriginal[0] : null;
            int stride = map.SafeMLx > 0 ? map.SafeMLx : 0;
            for (int i = 0; i < units.Length; i++)
            {
                DecodedUnitLikeOriginal unit = units[i];
                if (unit == null)
                    continue;

                int sx = unit.RealX >> 7;
                int sy = unit.RealY >> 7;
                if (stride > 0 && map.NObj3LikeOriginal != null)
                {
                    int idx = sx + sy * stride;
                    if (idx >= 0 && idx < map.NObj3LikeOriginal.Length && map.NObj3LikeOriginal[idx] < ushort.MaxValue)
                        map.NObj3LikeOriginal[idx]++;
                }

                if (map.UnitsFieldMapLikeOriginal != null)
                    SetMotionFieldPointLikeOriginal(map, map.UnitsFieldMapLikeOriginal, unit.RealX >> 4, unit.RealY >> 4);

                if (unit.LooksLikeBuildingLikeOriginal && ground != null)
                    ApplyApproxBuildingLockLikeOriginal(map, ground, unit);
            }
        }

        private static byte GuessCantBuildMaskFromNameLikeOriginal(string nameLikeOriginal)
        {
            if (string.IsNullOrEmpty(nameLikeOriginal))
                return 0;
            string n = nameLikeOriginal.ToLowerInvariant();
            if (n.Contains("meln") || n.Contains("mill") || n.Contains("windmill"))
                return CB_MelnicaLikeOriginal;
            if (n.Contains("farm") || n.Contains("ferma") || n.Contains("field"))
                return CB_FarmLikeOriginal;
            if (n.Contains("sklad") || n.Contains("store") || n.Contains("warehouse") || n.Contains("depot"))
                return CB_SkladLikeOriginal;
            if (n.Contains("port") || n.Contains("dock") || n.Contains("harbor") || n.Contains("shipyard") || n.Contains("pier"))
                return CB_PortLikeOriginal;
            if (n.Contains("tower") || n.Contains("fort") || n.Contains("bastion") || n.Contains("wall") || n.Contains("turret"))
                return CB_TowerLikeOriginal;
            return CB_BuildingLikeOriginal;
        }

        private static void CreateInfoMapLikeOriginal(ParsedMap map)
        {
            if (map == null || map.InfoMapLikeOriginal == null)
                return;

            EnsureDecodedTre2SpritesLikeOriginal(map);
            EnsureDecodedUni3ObjectsLikeOriginal(map);
            if (map.CantBuildLikeOriginal != null)
                Array.Clear(map.CantBuildLikeOriginal, 0, map.CantBuildLikeOriginal.Length);

            int mmax = map.SafeMLx > 0 ? map.SafeMLx - 1 : 0;
            int mmay = map.SafeMLx > 0 ? (map.InfoMapLikeOriginal.Length / Math.Max(1, map.SafeMLx)) - 1 : 0;
            int[][] spLists = map.SpRefListsLikeOriginal ?? Array.Empty<int[]>();
            DecodedSpriteLikeOriginal[] sprites = map.DecodedSpritesLikeOriginal ?? Array.Empty<DecodedSpriteLikeOriginal>();
            for (int y = 0; y <= mmay; y++)
            {
                for (int x = 0; x <= mmax; x++)
                {
                    int ofst = x + y * map.SafeMLx;
                    if (ofst < 0 || ofst >= map.InfoMapLikeOriginal.Length)
                        continue;

                    byte ms = 0;
                    if (!GetTopologyCheckBarLikeOriginal(map, 0, x << 3, y << 3, 8, 8))
                        ms |= 8;

                    int x0 = x << 7;
                    int y0 = y << 7;
                    int h1 = SampleHeightFromMapLikeOriginal(map, x0, y0);
                    int h2 = SampleHeightFromMapLikeOriginal(map, x0 + 128, y0);
                    int h3 = SampleHeightFromMapLikeOriginal(map, x0, y0 + 128);
                    int h4 = SampleHeightFromMapLikeOriginal(map, x0 + 128, y0 + 128);
                    int hh = (h1 + h2 + h3 + h4) >> 2;
                    if (Math.Abs(h1 - hh) < 20 && Math.Abs(h2 - hh) < 20 && Math.Abs(h3 - hh) < 20 && Math.Abs(h4 - hh) < 20)
                        ms |= 16;

                    int n = 0;
                    int nTrees = 0;
                    int nStones = 0;
                    int[] refs = ofst >= 0 && ofst < spLists.Length ? spLists[ofst] : null;
                    if (refs != null)
                    {
                        n = refs.Length;
                        for (int i = 0; i < refs.Length; i++)
                        {
                            int sid = refs[i];
                            if (sid < 0 || sid >= sprites.Length)
                                continue;
                            DecodedSpriteLikeOriginal sprite = sprites[sid];
                            if (sprite == null)
                                continue;
                            if (sprite.IsTreeLikeOriginal) nTrees++;
                            if (sprite.IsStoneLikeOriginal) nStones++;
                        }
                    }

                    if ((ms & 8) != 0 && (ms & 16) != 0 && n == 0)
                        ms |= 4;
                    if (nTrees > 2)
                        ms |= 1;
                    if (nStones > 5)
                        ms |= 2;
                    if (nTrees != 0 || nStones != 0)
                        ms = (byte)(ms & ~4);
                    map.InfoMapLikeOriginal[ofst] = ms;
                }
            }

            if (map.DecodedUnitsLikeOriginal != null)
            {
                for (int i = 0; i < map.DecodedUnitsLikeOriginal.Length; i++)
                {
                    DecodedUnitLikeOriginal unit = map.DecodedUnitsLikeOriginal[i];
                    if (unit == null || !unit.LooksLikeBuildingLikeOriginal)
                        continue;
                    UnitRuntimeDefinitionLikeOriginal def = GetUnitRuntimeDefinitionLikeOriginal(map, unit);
                    byte mask = unit.CantBuildMaskLikeOriginal;
                    if (def != null && def.CantBuildMaskLikeOriginal != 0)
                        mask = def.CantBuildMaskLikeOriginal;
                    if (mask == 0)
                        mask = GuessCantBuildMaskFromNameLikeOriginal(unit.NameLikeOriginal);
                    if (mask == 0)
                        mask = CB_BuildingLikeOriginal;
                    ApplyCantBuildFootprintLikeOriginal(map, unit, def, mask);
                }
            }
        }

        private static void CreateMapLockingLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            ClearRuntimeLockingMapsLikeOriginal(map);
            CreateLandLockingLikeOriginal(map, 120 * 64 / 56, true);
            for (int f = 2; f < TopologyFieldCountLikeOriginal; f++)
                SmoothFieldLikeOriginal(map, f);
            CreateFishMapLikeOriginal(map);
            CreateAdditionalObjectsLockingLikeOriginal(map);

            int maxx = Mathf.Max(0, map.MaxMapX << 1);
            int maxy = Mathf.Max(0, map.MaxMapY << 1);
            int l1 = 32 << map.Addsh;
            for (int i = 0; i < TopologyFieldCountLikeOriginal; i++)
            {
                byte[] motion = map.MotionFieldMapsLikeOriginal != null && i < map.MotionFieldMapsLikeOriginal.Length ? map.MotionFieldMapsLikeOriginal[i] : null;
                if (motion == null)
                    continue;
                SetTopologyBlockedSquareLikeOriginal(map, motion, 0, 0, maxx, 4);
                SetTopologyBlockedSquareLikeOriginal(map, motion, 0, maxy - 4, maxx, l1);
                SetTopologyBlockedSquareLikeOriginal(map, motion, 0, 4, 4, Math.Max(0, maxy - 4));
                SetTopologyBlockedSquareLikeOriginal(map, motion, maxx, 0, l1, 512 << map.Addsh);
            }

            int mxx = map.MAPSX >> 1;
            for (int ix = 0; ix < mxx; ix++)
            {
                for (int iy = 1; iy < 25; iy++)
                {
                    int sampleY = (iy << 6);
                    if ((iy << 5) - SampleHeightFromMapLikeOriginal(map, (ix << 6) + 32, sampleY) < 16)
                    {
                        for (int i = 0; i < TopologyFieldCountLikeOriginal; i++)
                        {
                            byte[] motion = map.MotionFieldMapsLikeOriginal != null && i < map.MotionFieldMapsLikeOriginal.Length ? map.MotionFieldMapsLikeOriginal[i] : null;
                            if (motion != null)
                                SetTopologyBlockedBarLikeOriginal(map, motion, ix << 2, iy << 2, 4, 4);
                        }
                    }
                }
            }
        }

        private static void EnsureDecodedLoc2LikeOriginal(ParsedMap map)
        {
            if (map == null || map.Loc2DecodedLikeOriginal)
                return;

            map.Loc2DecodedLikeOriginal = true;
            map.LockBarsLikeOriginal = Array.Empty<BlockCellLikeOriginal>();
            map.UnLockBarsLikeOriginal = Array.Empty<BlockCellLikeOriginal>();
            map.HorseLockBarsLikeOriginal = Array.Empty<BlockCellLikeOriginal>();

            byte[] payload = map.ChunkLOC2;
            if (payload == null || payload.Length < 8)
                return;

            try
            {
                using (var ms = new MemoryStream(payload, false))
                using (var br = new BinaryReader(ms))
                {
                    int lockN = br.ReadInt32();
                    int unlockN = br.ReadInt32();
                    int horseN = 0;
                    long remainingAfterCounts = ms.Length - ms.Position;
                    long needForTwo = ((long)Math.Max(0, lockN) + Math.Max(0, unlockN)) * 4L;
                    if (remainingAfterCounts >= needForTwo + 4)
                        horseN = br.ReadInt32();
                    else if (remainingAfterCounts < needForTwo)
                        return;

                    map.LockBarsLikeOriginal = ReadBlockCellsLikeOriginal(br, lockN, ms);
                    map.UnLockBarsLikeOriginal = ReadBlockCellsLikeOriginal(br, unlockN, ms);
                    map.HorseLockBarsLikeOriginal = ReadBlockCellsLikeOriginal(br, horseN, ms);
                }
            }
            catch (Exception ex)
            {
                Debug.LogWarning("[C2:TOPO] LOC2 decode failed: " + ex.Message);
                map.LockBarsLikeOriginal = Array.Empty<BlockCellLikeOriginal>();
                map.UnLockBarsLikeOriginal = Array.Empty<BlockCellLikeOriginal>();
                map.HorseLockBarsLikeOriginal = Array.Empty<BlockCellLikeOriginal>();
            }
        }

        private static BlockCellLikeOriginal[] ReadBlockCellsLikeOriginal(BinaryReader br, int count, MemoryStream ms)
        {
            if (count <= 0)
                return Array.Empty<BlockCellLikeOriginal>();
            long bytesNeed = (long)count * 4L;
            long remaining = ms.Length - ms.Position;
            if (bytesNeed > remaining)
                count = (int)Math.Max(0, remaining / 4L);
            if (count <= 0)
                return Array.Empty<BlockCellLikeOriginal>();

            BlockCellLikeOriginal[] arr = new BlockCellLikeOriginal[count];
            for (int i = 0; i < count; i++)
            {
                arr[i] = new BlockCellLikeOriginal
                {
                    x = br.ReadUInt16(),
                    y = br.ReadUInt16()
                };
            }
            return arr;
        }

        private static bool CreateTotalLockingLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return false;

            ApplySetupArraysImmediateStateLikeOriginal(map);
            EnsureDecodedLoc2LikeOriginal(map);
            EnsureDecodedTre2SpritesLikeOriginal(map);
            EnsureDecodedUni3ObjectsLikeOriginal(map);
            CreateMapLockingLikeOriginal(map);
            CreateMinesLockingLikeOriginal(map);
            CreateUnitsLockingLikeOriginal(map);
            CreateInfoMapLikeOriginal(map);
            map.TopologyRuntimeReadyLikeOriginal = true;
            InstallGlobalMutableStateLikeOriginal(map, "CreateTotalLockingLikeOriginal");
            return true;
        }

        private static void MakeCellSingledLikeOriginal(ParsedMap map, int tx, int ty, int topType)

        {
            if (map == null || !HasMeaningfulTopologyMotionFieldLikeOriginal(map, topType))
                return;

            byte[] tt = new byte[16];
            byte[] l = new byte[16];
            for (int i = 0; i < tt.Length; i++) tt[i] = 0xFF;
            bool change;
            int x0 = tx << 2;
            int y0 = ty << 2;
            int n = 0;
            for (int ix = 0; ix < 4; ix++)
            {
                for (int iy = 0; iy < 4; iy++)
                {
                    bool blocked = GetTopologyCheckPtLikeOriginal(map, topType, x0 + ix, y0 + iy);
                    l[ix + (iy << 2)] = (byte)(blocked ? 1 : 0);
                    if (blocked) n++;
                }
            }

            if (n == 0 || n == 16)
                return;

            int nTop = 0;
            do
            {
                change = false;
                for (int ix = 0; ix < 4; ix++)
                {
                    for (int iy = 0; iy < 4; iy++)
                    {
                        int of = ix + (iy << 2);
                        if (l[of] == 0)
                        {
                            int tL = ix > 0 ? tt[of - 1] : 0xFF;
                            int tR = ix < 3 ? tt[of + 1] : 0xFF;
                            int tU = iy > 0 ? tt[of - 4] : 0xFF;
                            int tD = iy < 3 ? tt[of + 4] : 0xFF;
                            int tC = tt[of];
                            int tm = Math.Min(tC, Math.Min(Math.Min(tL, tR), Math.Min(tU, tD)));
                            if (tm == 255)
                            {
                                tt[of] = (byte)nTop;
                                nTop++;
                                change = true;
                            }
                            else if (tt[of] != tm)
                            {
                                tt[of] = (byte)tm;
                                change = true;
                            }
                        }
                    }
                }
            } while (change);

            byte[] nZon = new byte[16];
            for (int i = 0; i < 16; i++)
            {
                int t = tt[i];
                if (t != 255 && t < nZon.Length)
                    nZon[t]++;
            }

            int maxIdx = -1;
            int cm = 0;
            for (int i = 0; i < nTop; i++)
            {
                int t = nZon[i];
                if (t > cm)
                {
                    cm = t;
                    maxIdx = i;
                }
            }

            if (maxIdx == -1)
                return;

            for (int i = 0; i < 16; i++)
            {
                if (tt[i] != maxIdx && tt[i] != 255)
                    SetTopologyBlockedPtLikeOriginal(map, topType, x0 + (i & 3), y0 + (i >> 2));
            }
        }

        private static byte GetCellLinksLikeOriginal(ParsedMap map, int tx, int ty, int topType)
        {
            bool linkL = false;
            bool linkR = false;
            bool linkU = false;
            bool linkD = false;

            int x0 = tx << 2;
            int y0 = ty << 2;
            for (int i = 0; i < 4; i++)
            {
                linkL |= !(GetTopologyCheckPtLikeOriginal(map, topType, x0 - 1, y0 + i) || GetTopologyCheckPtLikeOriginal(map, topType, x0, y0 + i));
                linkR |= !(GetTopologyCheckPtLikeOriginal(map, topType, x0 + 3, y0 + i) || GetTopologyCheckPtLikeOriginal(map, topType, x0 + 4, y0 + i));
                linkU |= !(GetTopologyCheckPtLikeOriginal(map, topType, x0 + i, y0) || GetTopologyCheckPtLikeOriginal(map, topType, x0 + i, y0 - 1));
                linkD |= !(GetTopologyCheckPtLikeOriginal(map, topType, x0 + i, y0 + 3) || GetTopologyCheckPtLikeOriginal(map, topType, x0 + i, y0 + 4));
            }

            return (byte)((linkL ? 1 : 0) | (linkR ? 2 : 0) | (linkU ? 4 : 0) | (linkD ? 8 : 0));
        }

        private static bool AddAreaSeedLikeOriginal(TopologyHashTableLikeOriginal field, short x, short y, byte sliv)
        {
            if (field == null)
                return false;

            const int minNorm = 1;
            if (sliv != 2 && field.TopMap != null)
            {
                for (int i = 0; i < field.NAreas && i < field.TopMap.Length; i++)
                {
                    TopologyAreaLikeOriginal ar = field.TopMap[i];
                    if (ar == null)
                        continue;
                    int norm = Mathf.Max(Math.Abs(ar.X - x), Math.Abs(ar.Y - y));
                    if (norm <= minNorm)
                    {
                        if (sliv != 0)
                        {
                            ar.X = (ushort)((ar.X + x) >> 1);
                            ar.Y = (ushort)((ar.Y + y) >> 1);
                        }
                        return false;
                    }
                }
            }

            if (field.MaxArea <= 0)
                field.MaxArea = 200;

            if (field.TopMap == null || field.TopMap.Length < field.MaxArea)
            {
                int target = Math.Max(field.MaxArea, field.TopMap != null ? field.TopMap.Length : 0);
                if (target <= 0)
                    target = 200;
                Array.Resize(ref field.TopMap, target);
                field.MaxArea = Math.Max(field.MaxArea, field.TopMap != null ? field.TopMap.Length : 0);
            }

            if (field.TopMap == null || field.TopMap.Length == 0)
            {
                field.MaxArea = Math.Max(field.MaxArea, 200);
                field.TopMap = new TopologyAreaLikeOriginal[field.MaxArea];
            }

            if (field.NAreas >= field.MaxArea || field.NAreas >= field.TopMap.Length)
            {
                field.MaxArea = Math.Max(field.MaxArea, field.TopMap.Length) + 120;
                Array.Resize(ref field.TopMap, field.MaxArea);
            }

            var area = new TopologyAreaLikeOriginal
            {
                X = (ushort)x,
                Y = (ushort)y,
                Importance = 0,
                IslandIDLikeOriginal = -1
            };
            area.EnsureLinkCapacityLikeOriginal(6);
            field.TopMap[field.NAreas] = area;
            field.NAreas++;
            return true;
        }

        private static int FindNearestTopologyAreaLikeOriginal(TopologyHashTableLikeOriginal field, int x, int y, int maxNorm)
        {
            if (field == null || field.TopMap == null || field.NAreas <= 0)
                return -1;

            int best = -1;
            int bestNorm = int.MaxValue;
            for (int i = 0; i < field.NAreas && i < field.TopMap.Length; i++)
            {
                TopologyAreaLikeOriginal area = field.TopMap[i];
                if (area == null)
                    continue;
                int norm = Mathf.Max(Math.Abs(area.X - x), Math.Abs(area.Y - y));
                if (norm <= maxNorm && norm < bestNorm)
                {
                    bestNorm = norm;
                    best = i;
                }
            }
            return best;
        }

        private static bool IsRoadAreaLikeOriginal(TopologyHashTableLikeOriginal field, int areaIndex)
        {
            if (field == null || field.RoadAreaMapLikeOriginal == null)
                return false;
            for (int i = 0; i < field.RoadAreaMapLikeOriginal.Length; i++)
            {
                if (field.RoadAreaMapLikeOriginal[i] == areaIndex)
                    return true;
            }
            return false;
        }


        private static int GetRoadSeedWidthLikeOriginal(ParsedMap map, RoadKnot node, int linkIndex)
        {
            int type = 0;
            if (node != null && node.LinkType != null && linkIndex >= 0 && linkIndex < node.LinkType.Length)
                type = node.LinkType[linkIndex];

            RoadPhysLikeOriginal phys = null;
            if (map != null && map.RoadPhysByTypeLikeOriginal != null)
                map.RoadPhysByTypeLikeOriginal.TryGetValue(type, out phys);

            if (phys != null && phys.RWidth > 0)
                return Mathf.Max(1, phys.RWidth * 2);

            int baseWidth = Mathf.Max(12, Mathf.RoundToInt(RoadSurfaceWidth) - Mathf.Max(0, type) * 2);
            return Mathf.Max(1, baseWidth * 2);
        }

        private static void StampAreaAnchorsIntoTopRefLikeOriginal(TopologyHashTableLikeOriginal field, int topLx, int topLy)
        {
            if (field == null || field.TopMap == null || field.TopRef == null)
                return;

            for (int i = 0; i < field.NAreas && i < field.TopMap.Length; i++)
            {
                TopologyAreaLikeOriginal ar = field.TopMap[i];
                if (ar == null)
                    continue;

                int ax = ar.X;
                int ay = ar.Y;
                if (ax < 0 || ay < 0 || ax >= topLx || ay >= topLy)
                    continue;

                int ofs = ax + ay * topLx;
                if (ofs >= 0 && ofs < field.TopRef.Length && field.TopRef[ofs] != 0xFFFE)
                    field.TopRef[ofs] = (ushort)i;
            }
        }

        private static void AddHexAreaSeedsLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field, int topLx, int topLy)
        {
            if (map == null || field == null || topLx <= 0 || topLy <= 0)
                return;

            int hexSize = 64 * 5;
            int maxWorld = map.Addsh > 0 ? (16384 << (map.Addsh - 1)) : 16384;
            int nmax = Math.Max(0, maxWorld / hexSize);

            for (int i = 0; i < nmax; i++)
            {
                if ((i & 1) != 0)
                {
                    for (int j = 0; j < nmax - 1; j++)
                    {
                        int xx = hexSize + j * hexSize;
                        int yy = (hexSize >> 1) + i * hexSize;
                        int x = xx >> 6;
                        int y = yy >> 6;
                        if (x > 1 && y > 1 && x < topLx - 4 && y < topLy - 4)
                        {
                            bool empty = true;
                            for (int dx = -1; dx <= 1 && empty; dx++)
                            {
                                for (int dy = -1; dy <= 1 && empty; dy++)
                                {
                                    if (field.TopRef[x + dx + (y + dy) * topLx] != 0xFFFE)
                                        empty = false;
                                }
                            }

                            if (empty && !GetTopologyCheckBarLikeOriginal(map, field.TopType, (x << 2) - 4, (y << 2) - 4, 12, 12))
                                AddAreaSeedLikeOriginal(field, (short)x, (short)y, 2);
                        }
                    }
                }
                else
                {
                    for (int j = 0; j < nmax; j++)
                    {
                        int xx = (hexSize >> 1) + j * hexSize;
                        int yy = (hexSize >> 1) + i * hexSize;
                        int x = xx >> 6;
                        int y = yy >> 6;
                        if (x > 1 && y > 1 && x < topLx - 4 && y < topLy - 4)
                        {
                            bool empty = true;
                            for (int dx = -1; dx <= 1 && empty; dx++)
                            {
                                for (int dy = -1; dy <= 1 && empty; dy++)
                                {
                                    if (field.TopRef[x + dx + (y + dy) * topLx] != 0xFFFE)
                                        empty = false;
                                }
                            }

                            if (empty && !GetTopologyCheckBarLikeOriginal(map, field.TopType, (x << 2) - 4, (y << 2) - 4, 12, 12))
                                AddAreaSeedLikeOriginal(field, (short)x, (short)y, 2);
                        }
                    }
                }
            }
        }

        private static void PreCreateTopLinksLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field)
        {
            if (map == null || field == null || field.TopType == 1 || map.DecodedRne2 == null || map.DecodedRne2.Nodes == null)
                return;

            int topLx = Math.Max(0, map.TopLx);
            int topLy = Math.Max(0, map.TopLy > 0 ? map.TopLy : map.TopLx);
            field.RoadAreaMapLikeOriginal = new int[map.DecodedRne2.Nodes.Count];
            for (int i = 0; i < field.RoadAreaMapLikeOriginal.Length; i++)
                field.RoadAreaMapLikeOriginal[i] = -1;

            for (int i = 0; i < map.DecodedRne2.Nodes.Count; i++)
            {
                RoadKnot node = map.DecodedRne2.Nodes[i];
                if (node == null)
                    continue;

                int seedWorldX = node.X;
                int seedWorldY = node.Y;
                int degree = Math.Max(0, node.NLinks);
                if (degree == 2 && node.Links != null && node.Links.Length >= 2)
                {
                    int z1 = node.Links[0];
                    int z2 = node.Links[1];
                    if (z1 >= 0 && z1 < map.DecodedRne2.Nodes.Count && z2 >= 0 && z2 < map.DecodedRne2.Nodes.Count)
                    {
                        RoadKnot n1 = map.DecodedRne2.Nodes[z1];
                        RoadKnot n2 = map.DecodedRne2.Nodes[z2];
                        if (n1 != null && n2 != null)
                        {
                            int x = node.X;
                            int y = node.Y;
                            int x1 = n1.X;
                            int y1 = n1.Y;
                            int x2 = n2.X;
                            int y2 = n2.Y;
                            int w = GetRoadSeedWidthLikeOriginal(map, node, 0);

                            int n1Len = Mathf.Max(1, Mathf.RoundToInt(Mathf.Sqrt((x1 - x) * (x1 - x) + (y1 - y) * (y1 - y))));
                            int n2Len = Mathf.Max(1, Mathf.RoundToInt(Mathf.Sqrt((x2 - x) * (x2 - x) + (y2 - y) * (y2 - y))));
                            x1 = x + ((x1 - x) * w) / n1Len;
                            y1 = y + ((y1 - y) * w) / n1Len;
                            x2 = x + ((x2 - x) * w) / n2Len;
                            y2 = y + ((y2 - y) * w) / n2Len;
                            seedWorldX = (x1 + x2 + x + x + x + x) / 6;
                            seedWorldY = (y1 + y2 + y + y + y + y) / 6;
                        }
                    }
                }

                int sx = seedWorldX >> 6;
                int sy = seedWorldY >> 6;
                if (sx < 0 || sy < 0 || sx >= topLx || sy >= topLy)
                    continue;
                if (GetTCStatusLikeOriginal(map, field, sx, sy, null))
                    continue;

                if (AddAreaSeedLikeOriginal(field, (short)sx, (short)sy, 2))
                    field.RoadAreaMapLikeOriginal[i] = field.NAreas - 1;
                else
                    field.RoadAreaMapLikeOriginal[i] = FindNearestTopologyAreaLikeOriginal(field, sx, sy, 1);
            }
        }


        private static bool CanPropagateTopologyEdgeLikeOriginal(byte[] temp, int topLx, int from, int to)
        {
            if (temp == null || from < 0 || to < 0 || from >= temp.Length || to >= temp.Length || topLx <= 0)
                return false;
            int delta = to - from;
            if (delta == 1)
                return (temp[from] & 2) != 0 && (temp[to] & 1) != 0;
            if (delta == -1)
                return (temp[from] & 1) != 0 && (temp[to] & 2) != 0;
            if (delta == topLx)
                return (temp[from] & 8) != 0 && (temp[to] & 4) != 0;
            if (delta == -topLx)
                return (temp[from] & 4) != 0 && (temp[to] & 8) != 0;
            return false;
        }

        private static int GetRoadAreaCountLikeOriginal(TopologyHashTableLikeOriginal field)
        {
            if (field == null)
                return 0;
            if (field.InitialRoadAreaCountLikeOriginal > 0)
                return field.InitialRoadAreaCountLikeOriginal;
            if (field.RoadAreaMapLikeOriginal == null)
                return 0;
            int best = -1;
            for (int i = 0; i < field.RoadAreaMapLikeOriginal.Length; i++)
            {
                if (field.RoadAreaMapLikeOriginal[i] > best)
                    best = field.RoadAreaMapLikeOriginal[i];
            }
            return best + 1;
        }

        private static bool CheckIfRoadZoneLikeOriginal(TopologyHashTableLikeOriginal field, int areaIndex)
        {
            return field != null && areaIndex >= 0 && areaIndex < GetRoadAreaCountLikeOriginal(field);
        }

        private static bool TryGetDirectedRoadEdgeByNodeIndicesLikeOriginal(ParsedMap map, int fromNodeIndex, int toNodeIndex, out int linkIndex)
        {
            linkIndex = -1;
            if (map == null || map.DecodedRne2 == null || map.DecodedRne2.Nodes == null)
                return false;
            if (fromNodeIndex < 0 || toNodeIndex < 0 || fromNodeIndex >= map.DecodedRne2.Nodes.Count || toNodeIndex >= map.DecodedRne2.Nodes.Count)
                return false;

            RoadKnot node = map.DecodedRne2.Nodes[fromNodeIndex];
            if (node == null || node.Links == null)
                return false;

            int degree = Math.Min(Math.Max(node.NLinks, 0), node.Links.Length);
            for (int q = 0; q < degree; q++)
            {
                if (node.Links[q] == toNodeIndex)
                {
                    linkIndex = q;
                    return true;
                }
            }
            return false;
        }

        private static bool TryResolveRoadNodeIndexByAreaLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field, int areaIndex, out int nodeIndex)
        {
            nodeIndex = -1;
            if (map == null || map.DecodedRne2 == null || map.DecodedRne2.Nodes == null || areaIndex < 0)
                return false;

            if (areaIndex < map.DecodedRne2.Nodes.Count)
            {
                nodeIndex = areaIndex;
                return true;
            }

            if (field == null || field.RoadAreaMapLikeOriginal == null)
                return false;

            for (int i = 0; i < field.RoadAreaMapLikeOriginal.Length; i++)
            {
                if (field.RoadAreaMapLikeOriginal[i] == areaIndex)
                {
                    nodeIndex = i;
                    return true;
                }
            }
            return false;
        }

        private static bool TryGetDirectedRoadEdgeByAreasLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field, int fromArea, int toArea, out int fromNodeIndex, out int linkIndex, out int targetNodeIndex)
        {
            fromNodeIndex = -1;
            linkIndex = -1;
            targetNodeIndex = -1;
            if (map == null || field == null || map.DecodedRne2 == null || map.DecodedRne2.Nodes == null)
                return false;
            if (fromArea < 0 || toArea < 0)
                return false;

            if (TryResolveRoadNodeIndexByAreaLikeOriginal(map, field, fromArea, out int directFrom) &&
                TryResolveRoadNodeIndexByAreaLikeOriginal(map, field, toArea, out int directTo) &&
                TryGetDirectedRoadEdgeByNodeIndicesLikeOriginal(map, directFrom, directTo, out int directLink))
            {
                fromNodeIndex = directFrom;
                linkIndex = directLink;
                targetNodeIndex = directTo;
                return true;
            }

            if (field.RoadAreaMapLikeOriginal == null)
                return false;

            int nodeCount = Math.Min(map.DecodedRne2.Nodes.Count, field.RoadAreaMapLikeOriginal.Length);
            for (int i = 0; i < nodeCount; i++)
            {
                if (field.RoadAreaMapLikeOriginal[i] != fromArea)
                    continue;

                RoadKnot node = map.DecodedRne2.Nodes[i];
                if (node == null || node.Links == null)
                    continue;

                int degree = Math.Min(Math.Max(node.NLinks, 0), node.Links.Length);
                for (int q = 0; q < degree; q++)
                {
                    int targetNode = node.Links[q];
                    if (targetNode < 0 || targetNode >= nodeCount)
                        continue;
                    if (field.RoadAreaMapLikeOriginal[targetNode] != toArea)
                        continue;

                    fromNodeIndex = i;
                    linkIndex = q;
                    targetNodeIndex = targetNode;
                    return true;
                }
            }
            return false;
        }

        private static int GetRoadLinkPrioryLikeOriginal(ParsedMap map, int nodeIndex, int linkIndex)
        {
            if (map == null || map.DecodedRne2 == null || map.DecodedRne2.Nodes == null || nodeIndex < 0 || nodeIndex >= map.DecodedRne2.Nodes.Count)
                return 0;

            RoadKnot node = map.DecodedRne2.Nodes[nodeIndex];
            if (node == null || node.LinkType == null || linkIndex < 0 || linkIndex >= node.LinkType.Length)
                return 0;

            EnsureRoadRuntimeDescriptorsLikeOriginal(null, map);

            int type = node.LinkType[linkIndex];
            if (map.RoadPhysByTypeLikeOriginal != null &&
                map.RoadPhysByTypeLikeOriginal.TryGetValue(type, out RoadPhysLikeOriginal phys) &&
                phys != null && phys.Priory > 0)
                return phys.Priory;

            if (!map.RoadDescriptorsLoadedFromFileLikeOriginal &&
                map.RoadPrioryByTypeLikeOriginal != null &&
                map.RoadPrioryByTypeLikeOriginal.TryGetValue(type, out short fallbackPriory) &&
                fallbackPriory > 0)
                return fallbackPriory;

            return 0;
        }

        private static int GetLinkScaleLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field, int n1, int n2)
        {
            if (field == null)
                return 16;
            if (field.TopType != 0 && field.TopType != 2)
                return 16;
            if (!CheckIfRoadZoneLikeOriginal(field, n1) || !CheckIfRoadZoneLikeOriginal(field, n2))
                return 16;
            if (!TryGetDirectedRoadEdgeByAreasLikeOriginal(map, field, n1, n2, out int nodeIndex, out int linkIndex, out _))
                return 16;

            int priory = GetRoadLinkPrioryLikeOriginal(map, nodeIndex, linkIndex);
            if (priory <= 0)
                return 16;

            int p = (16 * 256) / Math.Max(1, priory);
            return Math.Max(1, p);
        }

        private static int GetNextWayPointsLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field, int fromArea, int toArea)
        {
            if (map == null || field == null)
                return 0;
            if (!CheckIfRoadZoneLikeOriginal(field, fromArea) || !CheckIfRoadZoneLikeOriginal(field, toArea))
                return 0;

            EnsureRoadNetRuntimeLikeOriginal(map);

            if (!TryGetDirectedRoadEdgeByAreasLikeOriginal(map, field, fromArea, toArea, out int fromNode, out int linkIndex, out int targetNode))
                return 0;
            if (fromNode < 0 || targetNode < 0 || map.DecodedRne2 == null || map.DecodedRne2.Nodes == null || fromNode >= map.DecodedRne2.Nodes.Count)
                return 0;

            RoadKnot node = map.DecodedRne2.Nodes[fromNode];
            if (node == null || node.Links == null || node.WayPointToPointIndex == null)
                return 0;

            int degree = Math.Min(Math.Max(node.NLinks, 0), Math.Min(node.Links.Length, node.WayPointToPointIndex.Length));
            if (linkIndex < 0 || linkIndex >= degree)
                return 0;
            if (node.Links[linkIndex] != targetNode)
                return 0;

            ushort wpIndex = node.WayPointToPointIndex[linkIndex];
            if (wpIndex == 0xFFFF || map.RoadWayPointToPointLikeOriginal == null || wpIndex >= map.RoadWayPointToPointLikeOriginal.Length)
                return 0;

            return GetRoadWayPointCountLikeOriginal(map, fromNode, targetNode, wpIndex);
        }

        private static readonly Vector2Int[][] CachedRarrOffsetsLikeOriginal = BuildCachedRarrOffsetsLikeOriginal();

        private static Vector2Int[][] BuildCachedRarrOffsetsLikeOriginal()
        {
            var rings = new Vector2Int[8][];
            rings[0] = Array.Empty<Vector2Int>();
            for (int radius = 1; radius < rings.Length; radius++)
                rings[radius] = BuildSingleRarrOffsetsLikeOriginal(radius);
            return rings;
        }

        private static Vector2Int[] BuildSingleRarrOffsetsLikeOriginal(int radius)
        {
            if (radius <= 0)
                return Array.Empty<Vector2Int>();

            var result = new List<Vector2Int>(Math.Max(1, radius * 8));
            for (int dx = -radius; dx <= radius; dx++)
            {
                result.Add(new Vector2Int(dx, -radius));
                result.Add(new Vector2Int(dx, radius));
            }
            for (int dy = -radius + 1; dy <= radius - 1; dy++)
            {
                result.Add(new Vector2Int(-radius, dy));
                result.Add(new Vector2Int(radius, dy));
            }
            return result.ToArray();
        }

        private static IReadOnlyList<Vector2Int> BuildRarrOffsetsLikeOriginal(int radius)
        {
            if (radius <= 0 || radius >= CachedRarrOffsetsLikeOriginal.Length)
                return Array.Empty<Vector2Int>();
            return CachedRarrOffsetsLikeOriginal[radius];
        }

        private static bool TryClaimTopologyCellFromNeighborsLikeOriginal(TopologyHashTableLikeOriginal field, byte[] temp, int topLx, int ofs, ushort ownerFilter, out ushort claimed)
        {
            claimed = 0xFFFF;
            if (field == null || temp == null || field.TopRef == null || ofs < 0 || ofs >= field.TopRef.Length)
                return false;

            byte t = temp[ofs];
            if (t == 0)
                return false;

            ushort tL = field.TopRef[ofs - 1];
            ushort tR = field.TopRef[ofs + 1];
            ushort tU = field.TopRef[ofs - topLx];
            ushort tD = field.TopRef[ofs + topLx];

            if ((t & 1) != 0 && tL < 0xFFFE && (ownerFilter >= 0xFFFE || tL == ownerFilter)) { claimed = tL; return true; }
            if ((t & 2) != 0 && tR < 0xFFFE && (ownerFilter >= 0xFFFE || tR == ownerFilter)) { claimed = tR; return true; }
            if ((t & 4) != 0 && tU < 0xFFFE && (ownerFilter >= 0xFFFE || tU == ownerFilter)) { claimed = tU; return true; }
            if ((t & 8) != 0 && tD < 0xFFFE && (ownerFilter >= 0xFFFE || tD == ownerFilter)) { claimed = tD; return true; }
            return false;
        }

        private static void AddTopologyNeighborLinksFromCellLikeOriginal(TopologyHashTableLikeOriginal field, byte[] temp, int topLx, int ofs)
        {
            if (field == null || temp == null || field.TopRef == null || ofs < 0 || ofs >= field.TopRef.Length)
                return;

            byte t = temp[ofs];
            ushort tC = field.TopRef[ofs];
            if (t == 0 || tC >= 0xFFFE)
                return;

            ushort tL = field.TopRef[ofs - 1];
            ushort tR = field.TopRef[ofs + 1];
            ushort tU = field.TopRef[ofs - topLx];
            ushort tD = field.TopRef[ofs + topLx];

            if ((t & 1) != 0 && tL < 0xFFFE && tL != tC) { AddTopologyAdjacencyLinkLikeOriginal(field, tC, tL, 0xFFFFFFFFu); AddTopologyAdjacencyLinkLikeOriginal(field, tL, tC, 0xFFFFFFFFu); }
            if ((t & 2) != 0 && tR < 0xFFFE && tR != tC) { AddTopologyAdjacencyLinkLikeOriginal(field, tC, tR, 0xFFFFFFFFu); AddTopologyAdjacencyLinkLikeOriginal(field, tR, tC, 0xFFFFFFFFu); }
            if ((t & 4) != 0 && tU < 0xFFFE && tU != tC) { AddTopologyAdjacencyLinkLikeOriginal(field, tC, tU, 0xFFFFFFFFu); AddTopologyAdjacencyLinkLikeOriginal(field, tU, tC, 0xFFFFFFFFu); }
            if ((t & 8) != 0 && tD < 0xFFFE && tD != tC) { AddTopologyAdjacencyLinkLikeOriginal(field, tC, tD, 0xFFFFFFFFu); AddTopologyAdjacencyLinkLikeOriginal(field, tD, tC, 0xFFFFFFFFu); }
        }

        private static int AddDirectRoadLinksLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field)
        {
            if (map == null || field == null || field.TopType != 0 || map.DecodedRne2 == null || map.DecodedRne2.Nodes == null || field.RoadAreaMapLikeOriginal == null)
                return 0;

            int roadRelink = 0;
            for (int i = 0; i < map.DecodedRne2.Nodes.Count && i < field.RoadAreaMapLikeOriginal.Length; i++)
            {
                int fromArea = field.RoadAreaMapLikeOriginal[i];
                if (fromArea < 0 || fromArea >= field.NAreas)
                    continue;

                RoadKnot node = map.DecodedRne2.Nodes[i];
                if (node == null || node.Links == null)
                    continue;

                int linkCount = Math.Min(node.NLinks, node.Links.Length);
                for (int j = 0; j < linkCount; j++)
                {
                    int targetNode = node.Links[j];
                    if (targetNode < 0 || targetNode >= field.RoadAreaMapLikeOriginal.Length)
                        continue;

                    int toArea = field.RoadAreaMapLikeOriginal[targetNode];
                    if (toArea < 0 || toArea >= field.NAreas || toArea == fromArea)
                        continue;

                    AddTopologyAdjacencyLinkLikeOriginal(field, (ushort)fromArea, (ushort)toArea, 0xFFFFFFFFu);
                    AddTopologyAdjacencyLinkLikeOriginal(field, (ushort)toArea, (ushort)fromArea, 0xFFFFFFFFu);
                    roadRelink++;
                }
            }
            return roadRelink;
        }

        private static bool HasGateNameTokenLikeOriginal(string value)
        {
            if (string.IsNullOrEmpty(value))
                return false;
            string lo = value.ToLowerInvariant();
            return lo.Contains("gate")
                || lo.Contains("vorot")
                || lo.Contains("ворот")
                || lo.Contains("ворота")
                || lo.Contains("portal")
                || lo.Contains("door");
        }

        private static bool HasWallLikeNameTokenLikeOriginal(string value)
        {
            if (string.IsNullOrEmpty(value))
                return false;
            string lo = value.ToLowerInvariant();
            return lo.Contains("wall")
                || lo.Contains("tower")
                || lo.Contains("fort")
                || lo.Contains("bastion")
                || lo.Contains("turret")
                || lo.Contains("стен")
                || lo.Contains("баш")
                || lo.Contains("форт");
        }

        private static bool LooksLikeGateUnitLikeOriginal(DecodedUnitLikeOriginal unit, UnitRuntimeDefinitionLikeOriginal def)
        {
            if (unit == null)
                return false;

            string name = unit.NameLikeOriginal != null ? unit.NameLikeOriginal.ToLowerInvariant() : string.Empty;
            string defName = def != null && def.NameLikeOriginal != null ? def.NameLikeOriginal.ToLowerInvariant() : string.Empty;
            bool hasWallFootprint = unit.WallXLikeOriginal != 0 || unit.WallYLikeOriginal != 0;
            bool looksBuilding = unit.LooksLikeBuildingLikeOriginal || (def != null && def.NewBuildingLikeOriginal);

            if (HasGateNameTokenLikeOriginal(name) || HasGateNameTokenLikeOriginal(defName))
                return true;

            if (!hasWallFootprint || !looksBuilding)
                return false;

            if (HasWallLikeNameTokenLikeOriginal(name) || HasWallLikeNameTokenLikeOriginal(defName))
                return false;

            return string.IsNullOrEmpty(name) && string.IsNullOrEmpty(defName);
        }

        private static uint GetGateNationMaskLikeOriginal(DecodedUnitLikeOriginal unit)
        {
            if (unit == null)
                return 0xFFFFFFFFu;
            return unit.NationLikeOriginal < 32 ? (1u << unit.NationLikeOriginal) : 0xFFFFFFFFu;
        }

        private static bool TryGetGateLinkCellsLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field, DecodedUnitLikeOriginal unit, out ushort t0, out ushort t1)
        {
            t0 = 0xFFFF;
            t1 = 0xFFFF;
            if (map == null || field == null || field.TopRef == null || unit == null)
                return false;

            int topLx = Math.Max(0, map.TopLx);
            int topLy = Math.Max(0, map.TopLy > 0 ? map.TopLy : map.TopLx);
            if (topLx <= 0 || topLy <= 0)
                return false;

            float ang = (unit.DirLikeOriginal & 255) * (Mathf.PI * 2.0f / 256.0f);
            int dx = Mathf.RoundToInt(Mathf.Cos(ang) * 256.0f);
            int dy = Mathf.RoundToInt(Mathf.Sin(ang) * 256.0f);
            if (dx == 0 && dy == 0)
                dx = 256;

            int x0 = (unit.RealX + dx * 8) >> 10;
            int y0 = (unit.RealY + dy * 8) >> 10;
            int x1 = (unit.RealX - dx * 8) >> 10;
            int y1 = (unit.RealY - dy * 8) >> 10;

            if (x0 < 0 || y0 < 0 || x1 < 0 || y1 < 0 || x0 >= topLx || x1 >= topLx || y0 >= topLy || y1 >= topLy)
                return false;

            t0 = field.TopRef[x0 + (y0 << map.TopSH)];
            t1 = field.TopRef[x1 + (y1 << map.TopSH)];
            if (t0 >= field.NAreas || t1 >= field.NAreas || t0 == t1)
                return false;

            return true;
        }

        private static int CreateNationDependentLinksForGatesLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field)
        {
            if (map == null || field == null || field.TopMap == null || field.TopRef == null || field.TopType == 1)
                return 0;

            EnsureDecodedUni3ObjectsLikeOriginal(map);
            DecodedUnitLikeOriginal[] units = map.DecodedUnitsLikeOriginal;
            if (units == null || units.Length == 0)
                return 0;

            int added = 0;
            for (int i = 0; i < units.Length; i++)
            {
                DecodedUnitLikeOriginal unit = units[i];
                if (unit == null)
                    continue;

                UnitRuntimeDefinitionLikeOriginal def = GetUnitRuntimeDefinitionLikeOriginal(map, unit);
                if (!LooksLikeGateUnitLikeOriginal(unit, def))
                    continue;

                ushort t0;
                ushort t1;
                if (!TryGetGateLinkCellsLikeOriginal(map, field, unit, out t0, out t1))
                    continue;

                uint mask = GetGateNationMaskLikeOriginal(unit);
                if (AddTopologyAdjacencyLinkLikeOriginal(field, t0, t1, mask))
                    added++;
                if (AddTopologyAdjacencyLinkLikeOriginal(field, t1, t0, mask))
                    added++;
            }
            return added;
        }


        private static void AssignTopologyCellsFromAnchorsLikeOriginal(TopologyHashTableLikeOriginal field, int topLx, byte[] temp)
        {
            if (field == null || field.TopRef == null || field.TopMap == null)
                return;

            var queue = new Queue<int>();
            for (int i = 0; i < field.NAreas && i < field.TopMap.Length; i++)
            {
                TopologyAreaLikeOriginal area = field.TopMap[i];
                if (area == null)
                    continue;
                int x = area.X;
                int y = area.Y;
                if (x < 0 || y < 0 || x >= topLx || y >= topLx)
                    continue;
                int ofs = x + y * topLx;
                if (field.TopRef[ofs] != 0xFFFE)
                {
                    field.TopRef[ofs] = (ushort)i;
                    queue.Enqueue(ofs);
                }
            }

            while (queue.Count > 0)
            {
                int cur = queue.Dequeue();
                ushort owner = field.TopRef[cur];
                if (owner >= 0xFFFE)
                    continue;

                int x = cur % topLx;
                int y = cur / topLx;
                if (x > 0)
                {
                    int n = cur - 1;
                    if (field.TopRef[n] == 0xFFFF && CanPropagateTopologyEdgeLikeOriginal(temp, topLx, cur, n))
                    {
                        field.TopRef[n] = owner;
                        queue.Enqueue(n);
                    }
                }
                if (x + 1 < topLx)
                {
                    int n = cur + 1;
                    if (field.TopRef[n] == 0xFFFF && CanPropagateTopologyEdgeLikeOriginal(temp, topLx, cur, n))
                    {
                        field.TopRef[n] = owner;
                        queue.Enqueue(n);
                    }
                }
                if (y > 0)
                {
                    int n = cur - topLx;
                    if (field.TopRef[n] == 0xFFFF && CanPropagateTopologyEdgeLikeOriginal(temp, topLx, cur, n))
                    {
                        field.TopRef[n] = owner;
                        queue.Enqueue(n);
                    }
                }
                if (y + 1 < topLx)
                {
                    int n = cur + topLx;
                    if (field.TopRef[n] == 0xFFFF && CanPropagateTopologyEdgeLikeOriginal(temp, topLx, cur, n))
                    {
                        field.TopRef[n] = owner;
                        queue.Enqueue(n);
                    }
                }
            }
        }

        private static void ApplyRoadRelinkingLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field)
        {
            if (map == null || field == null)
                return;
            field.RoadRelinkCountLikeOriginal = AddDirectRoadLinksLikeOriginal(map, field);
            field.GateRelinkCountLikeOriginal = 0;
        }


        private static void ResearchIslandsLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field)
        {
            if (field == null || field.TopMap == null || field.NAreas <= 0)
                return;

            int na = field.NAreas;
            field.TopIslandsLikeOriginal = new ushort[na];
            field.NearWaterLikeOriginal = new ushort[na];
            for (int i = 0; i < na; i++)
            {
                field.TopIslandsLikeOriginal[i] = 0xFFFF;
                field.NearWaterLikeOriginal[i] = 0xFFFF;
            }

            int islandCount = 0;
            int largest = 0;
            var queue = new Queue<int>();
            for (int j = 0; j < na; j++)
            {
                if (field.TopIslandsLikeOriginal[j] != 0xFFFF)
                    continue;

                queue.Clear();
                queue.Enqueue(j);
                field.TopIslandsLikeOriginal[j] = (ushort)islandCount;
                int size = 0;
                int sumX = 0;
                int sumY = 0;

                while (queue.Count > 0)
                {
                    int cur = queue.Dequeue();
                    if (cur < 0 || cur >= na)
                        continue;
                    TopologyAreaLikeOriginal ar = field.TopMap[cur];
                    if (ar == null)
                        continue;

                    size++;
                    sumX += ar.X;
                    sumY += ar.Y;
                    ar.IslandIDLikeOriginal = islandCount;

                    int nLinks = ar.Link != null ? Math.Min(ar.NLinks, (ushort)ar.Link.Length) : 0;
                    for (int i = 0; i < nLinks; i++)
                    {
                        OneLinkInfoLikeOriginal link = ar.Link[i];
                        if (link == null)
                            continue;
                        int nxt = link.NextAreaID;
                        if (nxt >= 0 && nxt < na && field.TopIslandsLikeOriginal[nxt] == 0xFFFF)
                        {
                            field.TopIslandsLikeOriginal[nxt] = (ushort)islandCount;
                            queue.Enqueue(nxt);
                        }
                    }
                }

                if (size > largest)
                    largest = size;
                islandCount++;
            }

            field.IslandCenterXLikeOriginal = new int[islandCount];
            field.IslandCenterYLikeOriginal = new int[islandCount];
            int[] islandCounts = new int[islandCount];
            for (int i = 0; i < na; i++)
            {
                TopologyAreaLikeOriginal ar = field.TopMap[i];
                if (ar == null)
                    continue;
                int isl = field.TopIslandsLikeOriginal[i];
                if (isl < 0 || isl >= islandCount)
                    continue;
                field.IslandCenterXLikeOriginal[isl] += ar.X;
                field.IslandCenterYLikeOriginal[isl] += ar.Y;
                islandCounts[isl]++;
            }

            for (int i = 0; i < islandCount; i++)
            {
                if (islandCounts[i] > 0)
                {
                    field.IslandCenterXLikeOriginal[i] /= islandCounts[i];
                    field.IslandCenterYLikeOriginal[i] /= islandCounts[i];
                }
            }

            for (int i = 0; i < na; i++)
            {
                TopologyAreaLikeOriginal area = field.TopMap[i];
                if (area == null)
                    continue;
                area.Importance = (byte)Mathf.Clamp(islandCounts[field.TopIslandsLikeOriginal[i]], 0, 255);
            }

            TopologyHashTableLikeOriginal waterField = null;
            if (map != null && map.TopologyFieldsLikeOriginal != null && map.TopologyFieldsLikeOriginal.Length > 1)
                waterField = map.TopologyFieldsLikeOriginal[1];
            if (waterField != null && waterField.TopRef != null && waterField.TopMap != null && map != null)
            {
                int topLx = Math.Max(0, map.TopLx);
                int topLy = Math.Max(0, map.TopLy > 0 ? map.TopLy : map.TopLx);
                for (int ix = 3; ix < topLx - 3; ix++)
                {
                    for (int iy = 3; iy < topLy - 3; iy++)
                    {
                        int ofs = ix + (iy << map.TopSH);
                        if (ofs < 0 || ofs >= field.TopRef.Length)
                            continue;
                        ushort ctp = field.TopRef[ofs];
                        if (ctp >= 0xFFFE || ctp >= field.NAreas)
                            continue;

                        for (int dx = -3; dx <= 3; dx++)
                        {
                            for (int dy = -3; dy <= 3; dy++)
                            {
                                int wx = ix + dx;
                                int wy = iy + dy;
                                if (wx < 0 || wy < 0 || wx >= topLx || wy >= topLy)
                                    continue;
                                int wofs = wx + (wy << map.TopSH);
                                if (wofs < 0 || wofs >= waterField.TopRef.Length)
                                    continue;
                                ushort wtp = waterField.TopRef[wofs];
                                if (wtp >= 0xFFFE || wtp >= waterField.NAreas)
                                    continue;

                                if (field.NearWaterLikeOriginal[ctp] == 0xFFFF)
                                {
                                    field.NearWaterLikeOriginal[ctp] = wtp;
                                }
                                else
                                {
                                    TopologyAreaLikeOriginal car = field.TopMap[ctp];
                                    TopologyAreaLikeOriginal olda = waterField.TopMap[field.NearWaterLikeOriginal[ctp]];
                                    TopologyAreaLikeOriginal newa = waterField.TopMap[wtp];
                                    if (car != null && olda != null && newa != null)
                                    {
                                        int odx = car.X - olda.X;
                                        int ody = car.Y - olda.Y;
                                        int ndx = car.X - newa.X;
                                        int ndy = car.Y - newa.Y;
                                        int oldNorm = CalcNormaLikeOriginal(odx, ody);
                                        int newNorm = CalcNormaLikeOriginal(ndx, ndy);
                                        if (newNorm < oldNorm)
                                            field.NearWaterLikeOriginal[ctp] = wtp;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            field.ResearchIslandsAppliedLikeOriginal = true;
            field.IslandCountLikeOriginal = islandCount;
            field.LargestIslandLikeOriginal = largest;
            ResearchAllCurrentIslandsLikeOriginal(map, field);
        }

        private static bool TryGetAreaIslandFromUnitLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field, DecodedUnitLikeOriginal unit, out int areaIndex, out int islandIndex)
        {
            areaIndex = -1;
            islandIndex = -1;
            if (map == null || field == null || unit == null || field.TopRef == null || field.TopIslandsLikeOriginal == null)
                return false;

            int topLx = Math.Max(0, map.TopLx);
            int topLy = Math.Max(0, map.TopLy > 0 ? map.TopLy : map.TopLx);
            if (topLx <= 0 || topLy <= 0)
                return false;

            int tx = unit.RealX >> 10;
            int ty = unit.RealY >> 10;
            if (tx < 0 || ty < 0 || tx >= topLx || ty >= topLy)
                return false;

            int ofs = tx + (ty << map.TopSH);
            if (ofs < 0 || ofs >= field.TopRef.Length)
                return false;

            ushort tp = field.TopRef[ofs];
            if (tp >= 0xFFFE || tp >= field.NAreas || tp >= field.TopIslandsLikeOriginal.Length)
                return false;

            ushort isl = field.TopIslandsLikeOriginal[tp];
            if (isl == 0xFFFF || isl >= field.IslandCountLikeOriginal)
                return false;

            areaIndex = tp;
            islandIndex = isl;
            return true;
        }

        private static void ResearchCurrentIslandLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field, byte nationIndex)
        {
            if (map == null || field == null || field.IslandCountLikeOriginal <= 0 || field.TopIslandsLikeOriginal == null || field.TopIslandsLikeOriginal.Length == 0)
                return;
            if (field.CurrentIslandByNationLikeOriginal == null || field.CurrentIslandByNationLikeOriginal.Length == 0)
                return;
            if (nationIndex >= field.CurrentIslandByNationLikeOriginal.Length)
                return;

            DecodedUnitLikeOriginal[] units = map.DecodedUnitsLikeOriginal;
            if (units == null || units.Length == 0)
            {
                field.CurrentIslandByNationLikeOriginal[nationIndex] = 0xFF;
                return;
            }

            int[] unitsPerIsland = new int[field.IslandCountLikeOriginal];
            bool hasAny = false;
            int bestIsland = -1;
            int bestCount = 0;

            for (int i = 0; i < units.Length; i++)
            {
                DecodedUnitLikeOriginal unit = units[i];
                if (unit == null || unit.NationLikeOriginal != nationIndex)
                    continue;
                if (!TryGetAreaIslandFromUnitLikeOriginal(map, field, unit, out _, out int isl))
                    continue;

                hasAny = true;
                int count = ++unitsPerIsland[isl];
                if (count > bestCount)
                {
                    bestCount = count;
                    bestIsland = isl;
                }
            }

            field.CurrentIslandByNationLikeOriginal[nationIndex] = hasAny && bestIsland >= 0 && bestIsland < 255 ? (byte)bestIsland : (byte)0xFF;
        }

        private static void ResearchAllCurrentIslandsLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field)
        {
            if (field == null)
                return;

            const int MaxResearchNationsLikeOriginal = 8;
            field.CurrentIslandByNationLikeOriginal = new byte[MaxResearchNationsLikeOriginal];
            for (int i = 0; i < field.CurrentIslandByNationLikeOriginal.Length; i++)
                field.CurrentIslandByNationLikeOriginal[i] = 0xFF;

            if (map == null || map.DecodedUnitsLikeOriginal == null || map.DecodedUnitsLikeOriginal.Length == 0 || field.IslandCountLikeOriginal <= 0)
                return;

            bool[] seen = new bool[MaxResearchNationsLikeOriginal];
            for (int i = 0; i < map.DecodedUnitsLikeOriginal.Length; i++)
            {
                DecodedUnitLikeOriginal unit = map.DecodedUnitsLikeOriginal[i];
                if (unit == null)
                    continue;
                int nat = unit.NationLikeOriginal;
                if (nat < 0 || nat >= MaxResearchNationsLikeOriginal || seen[nat])
                    continue;
                seen[nat] = true;
                ResearchCurrentIslandLikeOriginal(map, field, (byte)nat);
            }
        }

        private static void CreateAreasLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field)
        {
            if (map == null || field == null)
                return;

            int topLx = Math.Max(0, map.TopLx);
            int topLy = Math.Max(0, map.TopLy > 0 ? map.TopLy : map.TopLx);
            int cellCount = checked(topLx * topLy);
            bool hasRuntimeMotion = HasMeaningfulTopologyMotionFieldLikeOriginal(map, field.TopType);
            bool canBuildRuntime = hasRuntimeMotion || (field.TopType == 1 && map.Water != null && map.Water.HasSea2Payload && map.Heights != null && map.Heights.Length > 0);

            byte[] tplPayload = null;
            switch (field.TopType)
            {
                case 0: tplPayload = map.Chunk0TPL; break;
                case 1: tplPayload = map.Chunk1TPL; break;
                case 2: tplPayload = map.Chunk2TPL; break;
            }

            if (field.TopRef == null || field.TopRef.Length != cellCount)
                field.TopRef = new ushort[cellCount];

            field.RoadAreaMapLikeOriginal = Array.Empty<int>();
            FillUShortArrayLikeOriginal(field.TopRef, 0xFFFF);
            field.MaxArea = 200;
            field.NAreas = 0;
            field.TopMap = new TopologyAreaLikeOriginal[field.MaxArea];
            field.LastCreateAreasSourceLikeOriginal = canBuildRuntime ? "runtime-motion-seeded" : "seeded-primary-fallback";

            for (int x = 0; x < topLx; x++)
            {
                for (int y = 0; y < topLy; y++)
                {
                    if (GetTCStatusLikeOriginal(map, field, x, y, null))
                        field.TopRef[x + y * topLx] = 0xFFFE;
                }
            }

            PreCreateTopLinksLikeOriginal(map, field);
            StampAreaAnchorsIntoTopRefLikeOriginal(field, topLx, topLy);
            AddHexAreaSeedsLikeOriginal(map, field, topLx, topLy);
            field.InitialRoadAreaCountLikeOriginal = field.RoadAreaMapLikeOriginal != null ? field.RoadAreaMapLikeOriginal.Count(v => v >= 0) : 0;

            if (field.NAreas <= 0 && !canBuildRuntime && tplPayload != null && tplPayload.Length > 0)
            {
                if (TryApplyTplChunkToTopologyFieldLikeOriginal(map, field.TopType, tplPayload, field.TopType + "TPL", out _))
                {
                    FillUShortArrayLikeOriginal(field.TopRef, 0xFFFF);
                    for (int x = 0; x < topLx; x++)
                    {
                        for (int y = 0; y < topLy; y++)
                        {
                            if (GetTCStatusLikeOriginal(map, field, x, y, null))
                                field.TopRef[x + y * topLx] = 0xFFFE;
                        }
                    }

                    if (FieldHasMeaningfulTopRefLikeOriginal(field))
                    {
                        NormalizeTopologyAreasFromTopRefLikeOriginal(field, topLx);
                        field.LastCreateAreasSourceLikeOriginal = "tpl-fallback-after-seeds";
                    }
                }
            }

            if (field.NAreas <= 0)
            {
                BuildTopologyAreasByFloodFillLikeOriginal(field, topLx);
                field.LastCreateAreasSourceLikeOriginal = canBuildRuntime ? "runtime-emergency-floodfill" : "fallback-emergency-floodfill";
            }

            StampAreaAnchorsIntoTopRefLikeOriginal(field, topLx, topLy);
            ReCreateAreasLikeOriginal(map, field, 0, 0, topLx - 1, topLy - 1);
            ResearchIslandsLikeOriginal(map, field);
            field.CreateAreasAppliedLikeOriginal = true;
        }


        private static void BuildTopologyAreasFromTopRefLikeOriginal(TopologyHashTableLikeOriginal field, int topLx)
        {
            if (field == null)
                return;

            var remap = new Dictionary<ushort, ushort>();
            var areas = new List<TopologyAreaLikeOriginal>();

            for (int i = 0; i < field.TopRef.Length; i++)
            {
                ushort v = field.TopRef[i];
                if (v == 0xFFFF || v == 0xFFFE)
                    continue;

                if (!remap.TryGetValue(v, out ushort newId))
                {
                    newId = (ushort)areas.Count;
                    remap[v] = newId;
                    areas.Add(new TopologyAreaLikeOriginal
                    {
                        X = (ushort)(i % topLx),
                        Y = (ushort)(i / topLx)
                    });
                }

                field.TopRef[i] = newId;
            }

            field.TopMap = areas.ToArray();
            field.NAreas = field.TopMap.Length;
            field.MaxArea = Math.Max(field.MaxArea, field.NAreas);
        }

        private static void BuildTopologyAreasByFloodFillLikeOriginal(TopologyHashTableLikeOriginal field, int topLx)
        {
            if (field == null || field.TopRef == null)
                return;

            var areas = new List<TopologyAreaLikeOriginal>();
            int cellCount = field.TopRef.Length;
            var queue = new Queue<int>();

            for (int i = 0; i < cellCount; i++)
            {
                if (field.TopRef[i] != 0xFFFF)
                    continue;
                if (IsTopologyCellBlockedLikeOriginal(field, i))
                    continue;

                ushort areaId = (ushort)areas.Count;
                int sx = i % topLx;
                int sy = i / topLx;
                areas.Add(new TopologyAreaLikeOriginal
                {
                    X = (ushort)sx,
                    Y = (ushort)sy
                });

                field.TopRef[i] = areaId;
                queue.Enqueue(i);
                while (queue.Count > 0)
                {
                    int cur = queue.Dequeue();
                    int cx = cur % topLx;
                    int cy = cur / topLx;

                    if (cx > 0)
                    {
                        int n = cur - 1;
                        if (field.TopRef[n] == 0xFFFF && !IsTopologyCellBlockedLikeOriginal(field, n))
                        {
                            field.TopRef[n] = areaId;
                            queue.Enqueue(n);
                        }
                    }
                    if (cx + 1 < topLx)
                    {
                        int n = cur + 1;
                        if (field.TopRef[n] == 0xFFFF && !IsTopologyCellBlockedLikeOriginal(field, n))
                        {
                            field.TopRef[n] = areaId;
                            queue.Enqueue(n);
                        }
                    }
                    if (cy > 0)
                    {
                        int n = cur - topLx;
                        if (field.TopRef[n] == 0xFFFF && !IsTopologyCellBlockedLikeOriginal(field, n))
                        {
                            field.TopRef[n] = areaId;
                            queue.Enqueue(n);
                        }
                    }
                    if (cy + 1 < topLx)
                    {
                        int n = cur + topLx;
                        if (field.TopRef[n] == 0xFFFF && !IsTopologyCellBlockedLikeOriginal(field, n))
                        {
                            field.TopRef[n] = areaId;
                            queue.Enqueue(n);
                        }
                    }
                }
            }

            field.TopMap = areas.ToArray();
            field.NAreas = areas.Count;
            field.MaxArea = Math.Max(field.MaxArea, field.NAreas);
        }

        private static void NormalizeTopologyAreasFromTopRefLikeOriginal(TopologyHashTableLikeOriginal field, int topLx)
        {
            if (field == null || field.TopMap == null)
                return;

            var firstCell = new int[field.TopMap.Length];
            for (int fi = 0; fi < firstCell.Length; fi++) firstCell[fi] = -1;

            for (int i = 0; i < field.TopRef.Length; i++)
            {
                ushort areaId = field.TopRef[i];
                if (areaId == 0xFFFF || areaId == 0xFFFE || areaId >= field.TopMap.Length)
                    continue;
                if (firstCell[areaId] < 0)
                    firstCell[areaId] = i;
            }

            var remap = new int[field.TopMap.Length];
            for (int ri = 0; ri < remap.Length; ri++) remap[ri] = -1;
            var normalized = new List<TopologyAreaLikeOriginal>();
            for (int i = 0; i < field.TopMap.Length; i++)
            {
                if (firstCell[i] < 0)
                    continue;
                remap[i] = normalized.Count;
                TopologyAreaLikeOriginal src = field.TopMap[i] ?? new TopologyAreaLikeOriginal();
                int cell = firstCell[i];
                src.X = (ushort)(cell % topLx);
                src.Y = (ushort)(cell / topLx);
                DecodeTopologyAreaLinksFromTplLikeOriginal(src);
                normalized.Add(src);
            }

            for (int i = 0; i < field.TopRef.Length; i++)
            {
                ushort areaId = field.TopRef[i];
                if (areaId == 0xFFFF || areaId == 0xFFFE || areaId >= remap.Length || remap[areaId] < 0)
                {
                    if (areaId != 0xFFFE)
                        field.TopRef[i] = 0xFFFF;
                    continue;
                }
                field.TopRef[i] = (ushort)remap[areaId];
            }

            field.TopMap = normalized.ToArray();
            field.NAreas = field.TopMap.Length;
            field.MaxArea = Math.Max(field.MaxArea, field.NAreas);

            for (int i = 0; i < field.TopMap.Length; i++)
            {
                TopologyAreaLikeOriginal area = field.TopMap[i];
                if (area == null)
                    continue;

                DecodeTopologyAreaLinksFromTplLikeOriginal(area);
                if (area.Link == null)
                    continue;

                for (int j = 0; j < area.Link.Length; j++)
                {
                    OneLinkInfoLikeOriginal link = area.Link[j];
                    if (link == null)
                        continue;

                    ushort oldId = link.NextAreaID;
                    if (oldId >= remap.Length || remap[oldId] < 0)
                    {
                        link.NextAreaID = 0xFFFF;
                    }
                    else
                    {
                        link.NextAreaID = (ushort)remap[oldId];
                    }
                }
                CompactTopologyAreaLinksLikeOriginal(area);
            }
        }


        private static void ReCreateAreasLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field, int x0, int y0, int x1, int y1)
        {
            if (map == null || field == null || field.TopMap == null || field.TopRef == null)
                return;

            int topLx = Math.Max(0, map.TopLx);
            int topLy = Math.Max(0, map.TopLy > 0 ? map.TopLy : map.TopLx);
            if (topLx <= 0 || topLy <= 0)
                return;

            x0 = Mathf.Clamp(x0, 0, topLx - 1);
            y0 = Mathf.Clamp(y0, 0, topLy - 1);
            x1 = Mathf.Clamp(x1, 0, topLx - 1);
            y1 = Mathf.Clamp(y1, 0, topLy - 1);

            for (int ix = x0; ix <= x1; ix++)
            {
                for (int iy = y0; iy <= y1; iy++)
                {
                    int ofs = ix + (iy << map.TopSH);
                    field.TopRef[ofs] = GetTCStatusLikeOriginal(map, field, ix, iy, field.TopRef) ? (ushort)0xFFFE : (ushort)0xFFFF;
                }
            }

            x0 = Mathf.Clamp(x0 - 10, 0, topLx - 1);
            y0 = Mathf.Clamp(y0 - 10, 0, topLy - 1);
            x1 = Mathf.Clamp(x1 + 10, 0, topLx - 1);
            y1 = Mathf.Clamp(y1 + 10, 0, topLy - 1);

            var linksList = new List<int>(Math.Min(Math.Max(1, field.NAreas), 4096));
            for (int i = 0; i < field.NAreas && i < field.TopMap.Length; i++)
            {
                TopologyAreaLikeOriginal area = field.TopMap[i];
                if (area == null)
                    continue;

                if (area.X >= x0 && area.Y >= y0 && area.X <= x1 && area.Y <= y1)
                {
                    area.Link = Array.Empty<OneLinkInfoLikeOriginal>();
                    area.NLinks = 0;
                    if (linksList.Count < 4096)
                        linksList.Add(i);
                }
            }

            int mmx = topLx - 1;
            int mmy = topLy - 1;
            int nr = field.TopType == 0 ? GetRoadAreaCountLikeOriginal(field) : 0;
            for (int i = 0; i < field.NAreas && i < field.TopMap.Length; i++)
            {
                TopologyAreaLikeOriginal area = field.TopMap[i];
                if (area == null)
                    continue;

                if (GetTCStatusLikeOriginal(map, field, area.X, area.Y, field.TopRef) || i < nr)
                {
                    int ofs = area.X + area.Y * topLx;
                    if (ofs >= 0 && ofs < field.TopRef.Length)
                        field.TopRef[ofs] = (ushort)i;
                }
            }

            int roadRelink = 0;
            if (field.TopType == 0)
                roadRelink = AddDirectRoadLinksLikeOriginal(map, field);

            for (int ix = x0; ix <= x1; ix++)
            {
                for (int iy = y0; iy < y1; iy++)
                    MakeCellSingledLikeOriginal(map, ix, iy, field.TopType);
            }

            byte[] temp = new byte[topLx * topLy];
            field.TopCellBlockedCountLikeOriginal = 0;
            field.TopCellOpenCountLikeOriginal = 0;
            for (int ix = x0; ix <= x1; ix++)
            {
                for (int iy = y0; iy < y1; iy++)
                {
                    int ofs = ix + (iy << map.TopSH);
                    temp[ofs] = GetCellLinksLikeOriginal(map, ix, iy, field.TopType);
                    if (field.TopRef[ofs] == 0xFFFE) field.TopCellBlockedCountLikeOriginal++;
                    else field.TopCellOpenCountLikeOriginal++;
                }
            }

            bool change = true;
            for (int ring = 1; ring < 8 && change; ring++)
            {
                change = false;
                IReadOnlyList<Vector2Int> offsets = BuildRarrOffsetsLikeOriginal(ring);
                for (int k = 0; k < offsets.Count; k++)
                {
                    Vector2Int off = offsets[k];
                    for (int q = 0; q < linksList.Count; q++)
                    {
                        int j = linksList[q];
                        if (ring >= 3 && j < nr && field.TopType == 0)
                            continue;

                        TopologyAreaLikeOriginal area = field.TopMap[j];
                        if (area == null)
                            continue;

                        int x = area.X + off.x;
                        int y = area.Y + off.y;
                        if (x <= 0 || y <= 0 || x >= mmx || y >= mmy)
                            continue;

                        int ofs = x + (y << map.TopSH);
                        ushort tC = field.TopRef[ofs];
                        if (temp[ofs] != 0 && tC >= 0xFFFE)
                        {
                            ushort claimed;
                            if (TryClaimTopologyCellFromNeighborsLikeOriginal(field, temp, topLx, ofs, (ushort)j, out claimed))
                            {
                                field.TopRef[ofs] = claimed;
                                tC = claimed;
                                change = true;
                            }
                        }

                        if (field.TopRef[ofs] < 0xFFFE)
                            AddTopologyNeighborLinksFromCellLikeOriginal(field, temp, topLx, ofs);
                    }
                }
            }

            change = true;
            for (int iter = 0; iter < 8 && change; iter++)
            {
                change = false;
                for (int ix = x0; ix <= x1; ix++)
                {
                    for (int iy = y0; iy <= y1; iy++)
                    {
                        if (ix <= 0 || iy <= 0 || ix >= mmx || iy >= mmy)
                            continue;

                        int ofs = ix + (iy << map.TopSH);
                        byte T = temp[ofs];
                        ushort tC = field.TopRef[ofs];
                        if (T != 0 && tC >= 0xFFFE)
                        {
                            ushort claimed;
                            if (TryClaimTopologyCellFromNeighborsLikeOriginal(field, temp, topLx, ofs, 0xFFFF, out claimed))
                            {
                                field.TopRef[ofs] = claimed;
                                tC = claimed;
                                change = true;
                            }

                            if (tC < 0xFFFE)
                                AddTopologyNeighborLinksFromCellLikeOriginal(field, temp, topLx, ofs);
                        }
                    }
                }
            }

            int gateRelink = CreateNationDependentLinksForGatesLikeOriginal(map, field);
            field.RoadRelinkCountLikeOriginal = roadRelink;
            field.GateRelinkCountLikeOriginal = gateRelink;
            field.ClearHashLikeOriginal();
            field.SingledCellsLikeOriginal = HasMeaningfulTopologyMotionFieldLikeOriginal(map, field.TopType) ? field.TopCellBlockedCountLikeOriginal : 0;
            field.ReCreateAreasAppliedLikeOriginal = true;
        }



        private static bool AddTopologyAdjacencyLinkLikeOriginal(TopologyHashTableLikeOriginal field, ushort fromId, ushort toId, uint mask = 0xFFFFFFFFu)
        {
            if (field == null || field.TopMap == null)
                return false;
            if (fromId >= field.TopMap.Length || toId >= field.TopMap.Length)
                return false;

            ParsedMap map = EnsureGlobalParsedMapFacadeLikeOriginal();
            if (CheckIfRoadZoneLikeOriginal(field, fromId) && CheckIfRoadZoneLikeOriginal(field, toId) && GetNextWayPointsLikeOriginal(map, field, fromId, toId) == 0)
                return false;

            TopologyAreaLikeOriginal from = field.TopMap[fromId];
            TopologyAreaLikeOriginal to = field.TopMap[toId];
            if (from == null || to == null)
                return false;

            DecodeTopologyAreaLinksFromTplLikeOriginal(from);
            if (from.Link == null)
                from.Link = Array.Empty<OneLinkInfoLikeOriginal>();

            int activeLinks = Math.Min(Math.Max((int)from.NLinks, 0), from.Link.Length);
            ushort dist = ComputeTopologyAreaDistanceLikeOriginal(map, field, fromId, toId, from, to);
            uint appliedMask = mask == 0u ? 0xFFFFFFFFu : mask;

            for (int i = 0; i < activeLinks; i++)
            {
                OneLinkInfoLikeOriginal existing = from.Link[i];
                if (existing != null && existing.NextAreaID == toId)
                {
                    existing.LinkNatMask |= appliedMask;
                    if (existing.NextAreaDist == 0)
                        existing.NextAreaDist = dist;
                    return true;
                }
            }

            int capacity = Math.Max(Math.Max((int)from.MaxLink, from.Link.Length), activeLinks);
            if (activeLinks >= capacity)
            {
                capacity = capacity > 0 ? capacity + 4 : 4;
                Array.Resize(ref from.Link, capacity);
            }
            else if (from.Link.Length < capacity)
            {
                Array.Resize(ref from.Link, capacity);
            }

            if (from.Link[activeLinks] == null)
                from.Link[activeLinks] = new OneLinkInfoLikeOriginal();
            from.Link[activeLinks].NextAreaID = toId;
            from.Link[activeLinks].NextAreaDist = dist;
            from.Link[activeLinks].LinkNatMask = appliedMask;
            from.NLinks = (ushort)Math.Min(activeLinks + 1, 0xFFFF);
            from.MaxLink = (ushort)Math.Min(Math.Max(capacity, activeLinks + 1), 0xFFFF);
            return true;
        }

        private static ushort ComputeTopologyAreaDistanceLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field, int fromId, int toId, TopologyAreaLikeOriginal a, TopologyAreaLikeOriginal b)
        {
            if (a == null || b == null)
                return 1;
            int dx = a.X - b.X;
            int dy = a.Y - b.Y;
            int norma = Math.Max(1, CalcNormaLikeOriginal(dx, dy));
            int scale = GetLinkScaleLikeOriginal(map, field, fromId, toId);
            int dist = (norma * Math.Max(1, scale)) >> 4;
            if (dist <= 0)
                dist = 1;
            return (ushort)Mathf.Clamp(dist, 1, 0xFFFF);
        }

        private static void CompactTopologyAreaLinksLikeOriginal(TopologyAreaLikeOriginal area)
        {
            if (area == null || area.Link == null || area.Link.Length == 0)
            {
                if (area != null)
                {
                    area.Link = Array.Empty<OneLinkInfoLikeOriginal>();
                    area.NLinks = 0;
                    area.MaxLink = 0;
                }
                return;
            }

            var used = new HashSet<ushort>();
            var list = new List<OneLinkInfoLikeOriginal>();
            for (int i = 0; i < area.Link.Length; i++)
            {
                OneLinkInfoLikeOriginal link = area.Link[i];
                if (link == null || link.NextAreaID == 0xFFFF)
                    continue;
                if (used.Add(link.NextAreaID))
                    list.Add(link);
            }

            area.Link = list.ToArray();
            area.NLinks = (ushort)area.Link.Length;
            area.MaxLink = (ushort)area.Link.Length;
        }

        private static void WarmupTopologyHashCacheLikeOriginal(ParsedMap map, TopologyHashTableLikeOriginal field, uint mask)
        {
            if (map == null || field == null || field.TopMap == null || field.NAreas <= 1)
                return;

            int limit = Math.Min(field.NAreas, 12);
            for (int i = 0; i < limit; i++)
            {
                TopologyAreaLikeOriginal area = field.TopMap[i];
                if (area == null || area.Link == null)
                    continue;

                int linkLimit = Math.Min(area.Link.Length, 4);
                for (int j = 0; j < linkLimit; j++)
                {
                    OneLinkInfoLikeOriginal link = area.Link[j];
                    if (link == null || link.NextAreaID == 0xFFFF || link.NextAreaID >= field.NAreas)
                        continue;

                    TryGetNextAreaOnTheWayToLikeOriginal(field, i, link.NextAreaID, 0, mask, out _, out _);
                }
            }
        }

        private static bool TryGetNextAreaOnTheWayToLikeOriginal(TopologyHashTableLikeOriginal field, int start, int final, byte nationIndex, uint mask, out int nextArea, out int linkDist)
        {
            nextArea = 0xFFFF;
            linkDist = 0xFFFF;
            if (field == null || field.NAreas <= 0)
                return false;
            if (start < 0 || final < 0 || start >= field.NAreas || final >= field.NAreas)
                return false;
            if (final == start)
            {
                nextArea = start;
                linkDist = 0;
                return true;
            }

            int ofs = start + final * field.NAreas;
            return TryGetHashTopLikeOriginal(field, ofs, nationIndex, mask, out nextArea, out linkDist);
        }

        private static bool TryGetHashTopLikeOriginal(TopologyHashTableLikeOriginal field, int ofs, byte nationIndex, uint mask, out int motionLink, out int linkDist)
        {
            motionLink = 0xFFFF;
            linkDist = 0xFFFF;
            if (field == null || field.NAreas <= 0)
                return false;

            ushort key0 = (ushort)(ofs & 1023);
            ushort key1 = (ushort)(ofs >> 10);
            int startSlot = key0 * 40;
            int endSlot = Math.Min(startSlot + 40, field.HashKey1LikeOriginal != null ? field.HashKey1LikeOriginal.Length : 0);
            if (startSlot < 0 || endSlot <= startSlot)
                return false;

            int bestFreeOrLow = startSlot;
            byte bestPrio = byte.MaxValue;
            for (int i = startSlot; i < endSlot; i++)
            {
                if (field.HashNationLikeOriginal[i] == nationIndex)
                {
                    if (field.HashKey1LikeOriginal[i] == key1)
                    {
                        if (field.HashPriorityLikeOriginal[i] < 7)
                            field.HashPriorityLikeOriginal[i]++;
                        motionLink = field.HashMotionLinksLikeOriginal[i] == 8191 ? 0xFFFF : field.HashMotionLinksLikeOriginal[i];
                        linkDist = field.HashLinksDistLikeOriginal[i];
                        field.LastCalculateWayHitCountLikeOriginal++;
                        return true;
                    }
                    if (field.HashKey1LikeOriginal[i] == 0xFFFF)
                    {
                        bestFreeOrLow = i;
                        bestPrio = 0;
                    }
                    else if (field.HashPriorityLikeOriginal[i] <= bestPrio)
                    {
                        bestPrio = field.HashPriorityLikeOriginal[i];
                        bestFreeOrLow = i;
                    }
                }
            }

            if (!CalculateWayLikeOriginal(field, ofs, mask, out int ml, out int ld))
                return false;

            field.HashKey1LikeOriginal[bestFreeOrLow] = key1;
            field.HashNationLikeOriginal[bestFreeOrLow] = nationIndex;
            field.HashMotionLinksLikeOriginal[bestFreeOrLow] = (ushort)(ml == 0xFFFF ? 8191 : ml);
            field.HashLinksDistLikeOriginal[bestFreeOrLow] = (ushort)Mathf.Clamp(ld, 0, 0xFFFF);
            field.HashPriorityLikeOriginal[bestFreeOrLow] = 0;

            motionLink = ml;
            linkDist = ld;
            field.LastCalculateWayMissCountLikeOriginal++;
            return true;
        }

        private static bool CalculateWayLikeOriginal(TopologyHashTableLikeOriginal field, int ofs, uint mask, out int motionLink, out int linkDist)
        {
            motionLink = 0xFFFF;
            linkDist = 0xFFFF;
            if (field == null || field.NAreas <= 0)
                return false;

            int start = ofs / field.NAreas;
            int fin = ofs % field.NAreas;
            if (start < 0 || fin < 0 || start >= field.NAreas || fin >= field.NAreas)
                return false;

            int n = field.NAreas;
            if (n <= 0 || n > 16384)
                return false;

            const ushort INF = 0xFFFF;
            ushort[] precisePointWeight = new ushort[n];
            ushort[] precisePointPrevIndex = new ushort[n];
            ushort[] candidatPointWeight = new ushort[n];
            ushort[] candidatPointPrevIndex = new ushort[n];
            ushort[] candidatList = new ushort[n];

            for (int i = 0; i < n; i++)
            {
                precisePointWeight[i] = INF;
                precisePointPrevIndex[i] = INF;
                candidatPointWeight[i] = INF;
                candidatPointPrevIndex[i] = INF;
            }

            candidatList[0] = (ushort)fin;
            candidatPointWeight[fin] = 0;
            candidatPointPrevIndex[fin] = INF;
            int nCandidats = 1;

            while (nCandidats > 0)
            {
                nCandidats--;
                ushort tz = candidatList[nCandidats];
                precisePointWeight[tz] = candidatPointWeight[tz];
                candidatPointWeight[tz] = INF;
                precisePointPrevIndex[tz] = candidatPointPrevIndex[tz];

                if (tz == start)
                {
                    ushort[] fullWay = new ushort[128];
                    int nwpts = 1;
                    ushort t0 = tz;
                    fullWay[0] = t0;
                    while (t0 != INF)
                    {
                        t0 = candidatPointPrevIndex[t0];
                        if (t0 != INF)
                        {
                            if (nwpts < fullWay.Length)
                            {
                                fullWay[nwpts] = t0;
                                nwpts++;
                            }
                        }
                    }

                    ushort[] clipped = new ushort[nwpts];
                    Array.Copy(fullWay, 0, clipped, 0, nwpts);
                    field.FullWayLikeOriginal = clipped;
                    field.LastPathStartLikeOriginal = start;
                    field.LastPathFinalLikeOriginal = fin;
                    field.LastPathMaskLikeOriginal = mask;
                    field.LastPathCostLikeOriginal = precisePointWeight[tz];
                    motionLink = precisePointPrevIndex[tz];
                    linkDist = precisePointWeight[tz];
                    return true;
                }

                TopologyAreaLikeOriginal area = field.TopMap != null && tz < field.TopMap.Length ? field.TopMap[tz] : null;
                if (area == null)
                    continue;
                DecodeTopologyAreaLinksFromTplLikeOriginal(area);

                int nl = area.Link != null ? area.Link.Length : 0;
                int w0 = precisePointWeight[tz];
                for (int i = 0; i < nl; i++)
                {
                    OneLinkInfoLikeOriginal link = area.Link[i];
                    if (link == null || (link.LinkNatMask & mask) == 0u)
                        continue;

                    int pi = link.NextAreaID;
                    if (pi < 0 || pi >= n)
                        continue;
                    if (precisePointWeight[pi] != INF)
                        continue;

                    int wiInt = Math.Max(1, (int)link.NextAreaDist) + w0;
                    ushort wi = (ushort)Mathf.Clamp(wiInt, 1, 0xFFFE);
                    ushort wc = candidatPointWeight[pi];
                    bool add = true;
                    if (wc != INF)
                    {
                        if (wc > wi)
                        {
                            for (int j = 0; j < nCandidats; j++)
                            {
                                if (candidatList[j] == pi)
                                {
                                    if (j < nCandidats - 1)
                                        Array.Copy(candidatList, j + 1, candidatList, j, nCandidats - j - 1);
                                    nCandidats--;
                                    break;
                                }
                            }
                            candidatPointWeight[pi] = wi;
                        }
                        else
                        {
                            add = false;
                        }
                    }

                    if (!add || nCandidats >= candidatList.Length)
                        continue;

                    if (nCandidats == 0)
                    {
                        candidatList[0] = (ushort)pi;
                        candidatPointWeight[pi] = wi;
                        candidatPointPrevIndex[pi] = tz;
                        nCandidats++;
                    }
                    else
                    {
                        int idxMax = 0;
                        int idxMin = nCandidats - 1;
                        ushort wcMax = candidatPointWeight[candidatList[idxMax]];
                        ushort wcMin = candidatPointWeight[candidatList[idxMin]];
                        if (wi <= wcMin)
                        {
                            candidatList[nCandidats] = (ushort)pi;
                            candidatPointWeight[pi] = wi;
                            candidatPointPrevIndex[pi] = tz;
                            nCandidats++;
                        }
                        else if (wi > wcMax)
                        {
                            Array.Copy(candidatList, 0, candidatList, 1, nCandidats);
                            candidatList[0] = (ushort)pi;
                            candidatPointWeight[pi] = wi;
                            candidatPointPrevIndex[pi] = tz;
                            nCandidats++;
                        }
                        else
                        {
                            while (idxMax != idxMin - 1)
                            {
                                int idxMid = (idxMin + idxMax) >> 1;
                                ushort wm = candidatPointWeight[candidatList[idxMid]];
                                if (wm > wi)
                                    idxMax = idxMid;
                                else
                                    idxMin = idxMid;
                            }
                            Array.Copy(candidatList, idxMin, candidatList, idxMin + 1, nCandidats - idxMin);
                            candidatList[idxMin] = (ushort)pi;
                            candidatPointWeight[pi] = wi;
                            candidatPointPrevIndex[pi] = tz;
                            nCandidats++;
                        }
                    }
                }
            }

            field.FullWayLikeOriginal = Array.Empty<ushort>();
            field.LastPathStartLikeOriginal = start;
            field.LastPathFinalLikeOriginal = fin;
            field.LastPathMaskLikeOriginal = mask;
            field.LastPathCostLikeOriginal = -1;
            return false;
        }

        private static void SelectSurfaceTypeLikeOriginal(ParsedMap map, bool isNewSurface)
        {
            if (map == null)
                return;

            map.SurfaceTypeNewLikeOriginal = isNewSurface;
            map.SurfaceTypeLikeOriginal = isNewSurface ? "new-surface" : "old-surface";

            ITerraBackendLikeOriginal terra = EnsureITerraBackendLikeOriginal();
            terra.SurfaceTypeNewLikeOriginal = isNewSurface;
            if (isNewSurface)
            {
                ITerraSetTextureCallbackLikeOriginal(null);
                ITerraSetGeometryCallbackLikeOriginal(ITCreateGeometryCallbackLikeOriginal);
                terra.DoSkewLikeOriginal = false;
                terra.DoBillboardingLikeOriginal = true;
            }
            else
            {
                ITerraSetTextureCallbackLikeOriginal(CreateGroundTextureCallbackLikeOriginal);
                ITerraSetGeometryCallbackLikeOriginal(CreateGroundGeometryCallbackLikeOriginal);
                terra.DoSkewLikeOriginal = true;
                terra.DoBillboardingLikeOriginal = false;
            }

            InstallGlobalMutableStateLikeOriginal(map, "SelectSurfaceTypeLikeOriginal");
        }

        private static void ClearRiverMapsLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            if (map.RivDirLikeOriginal != null)
                Array.Clear(map.RivDirLikeOriginal, 0, map.RivDirLikeOriginal.Length);
            if (map.RivVolLikeOriginal != null)
                Array.Clear(map.RivVolLikeOriginal, 0, map.RivVolLikeOriginal.Length);
        }

        private static void CopyPrimaryTilesIntoOriginalStateLikeOriginal(ParsedMap map)
        {
            if (map == null || map.TilePrimary == null || map.TilePrimary.Length == 0)
                return;

            ApplySetupArraysImmediateStateLikeOriginal(map);
            if (map.TexMapLikeOriginal == null || map.TexMapLikeOriginal.Length == 0)
                return;

            int count = Mathf.Min(map.TexMapLikeOriginal.Length, map.TilePrimary.Length);
            Buffer.BlockCopy(map.TilePrimary, 0, map.TexMapLikeOriginal, 0, count);
            InvalidateITerraLikeOriginal(map, invalidateAabb: false, invalidateTexture: true, invalidateGeometry: false);
            InstallGlobalMutableStateLikeOriginal(map, "CopyPrimaryTilesIntoOriginalStateLikeOriginal");
        }

        private static void CopyFacturesIntoOriginalStateLikeOriginal(ParsedMap map)
        {
            if (map == null)
                return;

            ApplySetupArraysImmediateStateLikeOriginal(map);

            if (map.FactureMap != null && map.FactureMapStorageLikeOriginal != null)
            {
                int count = Mathf.Min(map.FactureMapStorageLikeOriginal.Length, map.FactureMap.Length);
                Buffer.BlockCopy(map.FactureMap, 0, map.FactureMapStorageLikeOriginal, 0, count);
            }

            if (map.FactureWeight != null && map.FactureWeightStorageLikeOriginal != null)
            {
                int count = Mathf.Min(map.FactureWeightStorageLikeOriginal.Length, map.FactureWeight.Length);
                Buffer.BlockCopy(map.FactureWeight, 0, map.FactureWeightStorageLikeOriginal, 0, count);
            }

            InvalidateITerraLikeOriginal(map, invalidateAabb: false, invalidateTexture: true, invalidateGeometry: false);
            InstallGlobalMutableStateLikeOriginal(map, "CopyFacturesIntoOriginalStateLikeOriginal");
        }

        private static void ApplySurfaceChunkLikeOriginal(ParsedMap map, BinaryReader br, int payloadLen)
        {
            if (map == null || br == null)
                return;

            ApplySetupArraysImmediateStateLikeOriginal(map);
            SelectSurfaceTypeLikeOriginal(map, false);
            map.HasSurfChunkLikeOriginal = true;

            int expectedShorts = GetMaxPointIndexLikeOriginal(map);
            int readableShorts = Mathf.Max(0, payloadLen / 2);
            int copyCount = Mathf.Min(expectedShorts, readableShorts);

            if (map.THMapLikeOriginal == null || map.THMapLikeOriginal.Length != expectedShorts)
                map.THMapLikeOriginal = new short[Mathf.Max(0, expectedShorts)];

            for (int i = 0; i < copyCount; i++)
                map.THMapLikeOriginal[i] = br.ReadInt16();

            if (expectedShorts > copyCount)
                Array.Clear(map.THMapLikeOriginal, copyCount, expectedShorts - copyCount);

            int unreadPayloadBytes = payloadLen - (copyCount * 2);
            if (unreadPayloadBytes > 0)
                br.ReadBytes(unreadPayloadBytes);

            map.SurfaceChunkExpectedBytesLikeOriginal = expectedShorts * 2;
            map.SurfaceChunkReadBytesLikeOriginal = copyCount * 2;
            map.Heights = map.THMapLikeOriginal;
            ClearRiverMapsLikeOriginal(map);
            InvalidateITerraLikeOriginal(map, invalidateAabb: true, invalidateTexture: true, invalidateGeometry: true);
            InstallGlobalMutableStateLikeOriginal(map, "ApplySurfaceChunkLikeOriginal");
        }

        private static bool TryApplyNewSurfaceChunkLikeOriginal(ParsedMap map, BinaryReader br, int payloadLen, out string error)
        {
            error = "";
            if (map == null || br == null)
            {
                error = "map/br null";
                return false;
            }

            if (payloadLen < 8)
            {
                error = "HSEM payload too short";
                return false;
            }

            ApplySetupArraysImmediateStateLikeOriginal(map);
            SelectSurfaceTypeLikeOriginal(map, true);
            map.HasHsemChunkLikeOriginal = true;

            int vertexCount = br.ReadInt32();
            int indexCount = br.ReadInt32();
            if (vertexCount < 0 || indexCount < 0)
            {
                error = "Некорректные counts в HSEM.";
                return false;
            }

            map.IsMeshSurface = true;
            map.MeshVertices = new Vector3[vertexCount];
            map.MeshVerticesOriginal = new Vector3[vertexCount];
            map.MeshIndices = new int[indexCount];
            map.MeshIndicesOriginal = new int[indexCount];
            map.MeshColors = new Color32[vertexCount];
            map.MeshShadow = new byte[vertexCount];
            map.MeshFacture = new byte[vertexCount];
            map.MeshNormals = new Vector3[vertexCount];
            map.MeshNormalsOriginal = new Vector3[vertexCount];

            for (int i = 0; i < vertexCount; i++)
            {
                short x = br.ReadInt16();
                short y = br.ReadInt16();
                short z = br.ReadInt16();
                uint colorPacked = br.ReadUInt32();
                byte shadow = br.ReadByte();
                byte facture = br.ReadByte();
                sbyte nxRaw = br.ReadSByte();
                sbyte nyRaw = br.ReadSByte();
                sbyte nzRaw = br.ReadSByte();
                br.ReadByte();

                byte cb = (byte)(colorPacked & 0xFF);
                byte cg = (byte)((colorPacked >> 8) & 0xFF);
                byte cr = (byte)((colorPacked >> 16) & 0xFF);
                byte ca = (byte)((colorPacked >> 24) & 0xFF);

                map.MeshVerticesOriginal[i] = new Vector3(x, y, z);
                map.MeshVertices[i] = new Vector3(x, z, y);
                map.MeshColors[i] = new Color32(cr, cg, cb, ca);
                map.MeshShadow[i] = shadow;
                map.MeshFacture[i] = facture;
                map.MeshNormalsOriginal[i] = new Vector3(nxRaw / 127f, nyRaw / 127f, nzRaw / 127f);
                map.MeshNormals[i] = new Vector3(nxRaw / 127f, nzRaw / 127f, nyRaw / 127f);
            }

            for (int i = 0; i < indexCount; i++)
            {
                int idxLikeOriginal = br.ReadInt32();
                map.MeshIndicesOriginal[i] = idxLikeOriginal;
                map.MeshIndices[i] = idxLikeOriginal;
            }

            map.MeshQuadSystem = BuildMeshQuadSystemLikeOriginal(map);
            map.THMapLikeOriginal = BuildMeshSurfaceHeightMapLikeOriginal(map, map.MeshQuadSystem);
            map.Heights = map.THMapLikeOriginal;
            EnsureMapXyShiftLikeOriginal(map);

            if (map.Heights == null || map.Heights.Length == 0)
            {
                error = "FillMapOfHeights-like support не построен.";
                return false;
            }

            InvalidateITerraLikeOriginal(map, invalidateAabb: true, invalidateTexture: true, invalidateGeometry: true);
            InstallGlobalMutableStateLikeOriginal(map, "TryApplyNewSurfaceChunkLikeOriginal");
            return true;
        }

        private static byte[] SliceBytes(byte[] src, int offset, int count)
        {
            if (src == null || count <= 0 || offset < 0 || offset >= src.Length)
                return new byte[0];

            int safeCount = Math.Min(count, src.Length - offset);
            byte[] dst = new byte[safeCount];
            Buffer.BlockCopy(src, offset, dst, 0, safeCount);
            return dst;
        }

        private static byte[] NormalizeDecodedMapPayload(byte[] decoded, out string info)
        {
            info = "";

            if (decoded == null || decoded.Length == 0)
            {
                info = "decoded empty";
                return null;
            }

            byte[] current = decoded;
            for (int pass = 0; pass < 3; pass++)
            {
                string magic = ReadMagic4(current);
                Debug.Log($"[C2:MAP] Normalize pass={pass} len={current.Length} magic={magic} head={ToHexHead(current, 16)}");

                if (IsSupportedMapMagic(magic))
                {
                    info = pass == 0 ? "map stream" : ("nested BZip pass=" + pass);
                    return current;
                }

                if (!StartsWithBzipMagic(current))
                {
                    info = "magic=" + magic + " head=" + ToHexHead(current, 16);
                    return null;
                }

                if (!TryDecodeBzipPayload(current, 0, out current, out string nestedInfo))
                {
                    info = "nested BZip failed: " + nestedInfo;
                    return null;
                }
            }

            info = "nested BZip depth exceeded, magic=" + ReadMagic4(current) + " head=" + ToHexHead(current, 16);
            return null;
        }

        private static bool TryDecodeBzipPayload(byte[] payload, int expectedLen, out byte[] decoded, out string info)
        {
            decoded = null;
            info = "";

            if (payload == null || payload.Length == 0)
            {
                info = "payload empty";
                return false;
            }

            try
            {
                decoded = SharpBZip2Compat.Decompress(payload);
                if (decoded != null && decoded.Length > 0)
                {
                    info = $"CompatSharpBZip len={decoded.Length} magic={ReadMagic4(decoded)} expectedLen={expectedLen} sameAsPayload={ByteArraysEqual(decoded, payload)}";
                    if (expectedLen > 0 && decoded.Length != expectedLen)
                        Debug.LogWarning($"[C2:MAP] CompatSharpBZip len mismatch: expected={expectedLen} actual={decoded.Length}");
                    return true;
                }

                info = "CompatSharpBZip returned empty payload";
            }
            catch (Exception ex)
            {
                info = "CompatSharpBZip " + ex.GetType().Name + ": " + ex.Message;
            }

            Type bzipType = FindBzip2InputStreamType();
            if (bzipType == null)
            {
                info += " | Ionic.BZip2.BZip2InputStream type not found";
                return false;
            }

            int capacity = expectedLen > 0
                ? Math.Max(1024, expectedLen + 16)
                : Math.Max(1024, payload.Length * 8 + 1024);

            string firstSuspicious = null;

            foreach (bool? boolArg in new bool?[] { null, false, true })
            {
                try
                {
                    using (var src = new MemoryStream(payload, false))
                    {
                        string ctorInfo;
                        using (var bz = CreateBzipStream(bzipType, src, boolArg, out ctorInfo))
                        using (var dst = new MemoryStream(capacity))
                        {
                            bz.CopyTo(dst);
                            byte[] candidate = dst.ToArray();
                            string candidateMagic = ReadMagic4(candidate);
                            bool passthrough = ByteArraysEqual(candidate, payload);

                            if (candidate.Length > 0 && !passthrough)
                            {
                                decoded = candidate;
                                info += " | " + bzipType.Assembly.GetName().Name + " " + ctorInfo + " len=" + candidate.Length + " magic=" + candidateMagic;
                                return true;
                            }

                            if (candidate.Length > 0 && firstSuspicious == null)
                                firstSuspicious = bzipType.Assembly.GetName().Name + " " + ctorInfo + " suspicious passthrough len=" + candidate.Length + " magic=" + candidateMagic;
                        }
                    }
                }
                catch (Exception ex)
                {
                    if (firstSuspicious == null)
                        firstSuspicious = (boolArg.HasValue ? ("ctor(Stream," + boolArg.Value + ")") : "ctor(Stream)") + " -> " + ex.GetType().Name + ": " + ex.Message;
                }
            }

            if (!string.IsNullOrEmpty(firstSuspicious))
                info += " | " + firstSuspicious;
            return false;
        }

        private static bool TryReadFCompressorHeader(byte[] raw, out byte type, out int inLen, out int outLen)
        {
            type = 0;
            inLen = 0;
            outLen = 0;

            if (raw == null || raw.Length < 9)
                return false;

            type = raw[0];
            inLen = BitConverter.ToInt32(raw, 1);
            outLen = BitConverter.ToInt32(raw, 5);

            if (type > 4)
                return false;
            if (inLen <= 0 || outLen <= 0)
                return false;
            if (9 + inLen > raw.Length)
                return false;

            return true;
        }

        private static bool TryInvokeManagedDecompress(byte[] fcompBlock, byte[] payload, int expectedOutLen, out byte[] decoded, out string info)
        {
            decoded = null;
            info = "";

            if (fcompBlock == null || fcompBlock.Length == 0)
            {
                info = "input empty";
                return false;
            }

            try
            {
                Assembly asm = typeof(CodecFacade).Assembly;
                if (asm == null)
                {
                    info = "Melinoja assembly not found";
                    return false;
                }

                Type t = asm.GetType("G2DLib.G2DCodec", false);
                if (t == null)
                {
                    info = "G2DLib.G2DCodec not found in " + asm.GetName().Name;
                    return false;
                }

                MethodInfo mi = t.GetMethod(
                    "DecompressBlock",
                    BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static,
                    null,
                    new[] { typeof(byte[]), typeof(uint), typeof(byte[]).MakeByRefType() },
                    null);

                if (mi == null)
                {
                    info = "G2DCodec.DecompressBlock(byte[],uint,out byte[]) not found. methods=" + DescribeMethods(t, "Decompress");
                    return false;
                }

                if (TryInvokeExactManagedDecompress(mi, fcompBlock, out decoded, out string exactInfo))
                {
                    info = exactInfo;
                    return true;
                }

                if (payload != null && payload.Length > 0 && TryInvokeExactManagedDecompress(mi, payload, out decoded, out string payloadInfo))
                {
                    info = payloadInfo + " [payload-only]";
                    return true;
                }

                info = "G2DCodec.DecompressBlock failed for both block and payload";
                return false;
            }
            catch (Exception ex)
            {
                info = ex.GetType().Name + ": " + ex.Message;
                return false;
            }
        }

        private static bool TryInvokeExactManagedDecompress(MethodInfo mi, byte[] input, out byte[] decoded, out string info)
        {
            decoded = null;
            info = "";

            if (mi == null)
            {
                info = "method == null";
                return false;
            }

            if (input == null || input.Length == 0)
            {
                info = "input empty";
                return false;
            }

            try
            {
                object[] args = { input, (uint)input.Length, null };
                object ret = mi.Invoke(null, args);
                bool ok = ret is bool b && b;
                decoded = args[2] as byte[];

                info = (mi.DeclaringType != null ? (mi.DeclaringType.FullName + ".") : "")
                    + mi.Name
                    + $"(len={input.Length}) ret={ret} outLen={(decoded != null ? decoded.Length : 0)} outMagic={ReadMagic4(decoded)} outHead={ToHexHead(decoded, 16)} sameAsInput={ByteArraysEqual(decoded, input)}";

                return ok && decoded != null && decoded.Length > 0;
            }
            catch (Exception ex)
            {
                info = ex.GetType().Name + ": " + ex.Message;
                return false;
            }
        }

        private static string DescribeMethods(Type t, string nameContains)
        {
            if (t == null) return "<null type>";
            const BindingFlags flags = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance;
            var parts = new List<string>();
            foreach (MethodInfo mi in t.GetMethods(flags))
            {
                if (mi == null) continue;
                if (!string.IsNullOrEmpty(nameContains) && mi.Name.IndexOf(nameContains, StringComparison.OrdinalIgnoreCase) < 0)
                    continue;

                string paramSig = string.Join(", ", mi.GetParameters().Select(p =>
                {
                    string pt = p.ParameterType != null ? p.ParameterType.Name : "?";
                    return pt + " " + p.Name;
                }));

                parts.Add(mi.Name + "(" + paramSig + ")");
            }

            return parts.Count > 0 ? string.Join(" | ", parts) : "<no matching methods>";
        }

        private static Type FindBzip2InputStreamType()
        {
            try
            {
                Assembly melinojaAsm = typeof(CodecFacade).Assembly;
                if (melinojaAsm != null)
                {
                    Type exact = melinojaAsm.GetType("Ionic.BZip2.BZip2InputStream", false);
                    if (exact != null)
                    {
                        Debug.Log("[C2:MAP] Using Melinoja BZip type from assembly: " + melinojaAsm.GetName().Name);
                        return exact;
                    }
                }
            }
            catch (Exception ex)
            {
                Debug.LogWarning("[C2:MAP] Melinoja BZip lookup failed: " + ex.Message);
            }

            Type direct = Type.GetType("Ionic.BZip2.BZip2InputStream, Melinoja", false);
            if (direct != null)
            {
                Debug.Log("[C2:MAP] Using direct BZip type: " + direct.Assembly.GetName().Name);
                return direct;
            }

            foreach (Assembly asm in AppDomain.CurrentDomain.GetAssemblies())
            {
                if (asm == null) continue;
                Type t = asm.GetType("Ionic.BZip2.BZip2InputStream", false);
                if (t != null)
                {
                    Debug.LogWarning("[C2:MAP] Falling back to foreign BZip type from assembly: " + asm.GetName().Name);
                    return t;
                }
            }

            return null;
        }

        private static Stream CreateBzipStream(Type bzipType, Stream src, bool? boolArg, out string ctorInfo)
        {
            if (bzipType == null) throw new ArgumentNullException(nameof(bzipType));
            if (src == null) throw new ArgumentNullException(nameof(src));

            const BindingFlags flags = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;

            if (!boolArg.HasValue)
            {
                ConstructorInfo ctor1 = bzipType.GetConstructor(flags, null, new[] { typeof(Stream) }, null);
                if (ctor1 != null)
                {
                    ctorInfo = ".ctor(Stream)";
                    return (Stream)ctor1.Invoke(new object[] { src });
                }
            }

            ConstructorInfo ctor2 = bzipType.GetConstructor(flags, null, new[] { typeof(Stream), typeof(bool) }, null);
            if (ctor2 != null)
            {
                bool flag = boolArg ?? false;
                ctorInfo = ".ctor(Stream, bool=" + flag + ")";
                return (Stream)ctor2.Invoke(new object[] { src, flag });
            }

            ctorInfo = "<missing ctor>";
            throw new MissingMethodException(bzipType.FullName, ".ctor(Stream) / .ctor(Stream, bool)");
        }

        private static bool ByteArraysEqual(byte[] a, byte[] b)
        {
            if (ReferenceEquals(a, b)) return true;
            if (a == null || b == null || a.Length != b.Length) return false;
            for (int i = 0; i < a.Length; i++)
                if (a[i] != b[i])
                    return false;
            return true;
        }

        private static string ToHexHead(byte[] raw, int count)
        {
            if (raw == null || raw.Length == 0) return "<empty>";
            int take = Math.Min(Math.Max(count, 0), raw.Length);
            char[] chars = new char[take * 3 - 1];
            const string hex = "0123456789ABCDEF";
            int p = 0;
            for (int i = 0; i < take; i++)
            {
                byte b = raw[i];
                chars[p++] = hex[b >> 4];
                chars[p++] = hex[b & 15];
                if (i + 1 < take) chars[p++] = ' ';
            }
            return new string(chars);
        }

        private void ApplyTerrainMaterialRuntimeState(bool forceLog)
        {
            if (_terrainMaterial == null)
                return;

            if (_terrainMaterial.HasProperty("_FactureEnabled"))
                _terrainMaterial.SetFloat("_FactureEnabled", _factureEnabled ? 1.0f : 0.0f);
            if (_terrainMaterial.HasProperty("_FactureStrength"))
                _terrainMaterial.SetFloat("_FactureStrength", PreviewFactureStrength);
            if (_terrainMaterial.HasProperty("_SecondWeightScale"))
                _terrainMaterial.SetFloat("_SecondWeightScale", PreviewSecondWeightScale);
            if (_terrainMaterial.HasProperty("_FactureWeightScale"))
                _terrainMaterial.SetFloat("_FactureWeightScale", PreviewFactureWeightScale);
            if (_terrainMaterial.HasProperty("_GroundTiling"))
                _terrainMaterial.SetFloat("_GroundTiling", PreviewGroundTiling);
            if (_terrainMaterial.HasProperty("_SecondaryTiling"))
                _terrainMaterial.SetFloat("_SecondaryTiling", PreviewSecondTiling);
            if (_terrainMaterial.HasProperty("_FactureTiling"))
                _terrainMaterial.SetFloat("_FactureTiling", PreviewFactureTiling);
            if (_terrainMaterial.HasProperty("_SlopeBlendPower"))
                _terrainMaterial.SetFloat("_SlopeBlendPower", PreviewSlopeBlendPower);
            if (_terrainMaterial.HasProperty("_SlopeSecondAtten"))
                _terrainMaterial.SetFloat("_SlopeSecondAtten", PreviewSlopeSecondAtten);
            if (_terrainMaterial.HasProperty("_SlopeFactureAtten"))
                _terrainMaterial.SetFloat("_SlopeFactureAtten", PreviewSlopeFactureAtten);
            if (_terrainMaterial.HasProperty("_AmbientStrength"))
                _terrainMaterial.SetFloat("_AmbientStrength", AmbientLightStrength);
            if (_terrainMaterial.HasProperty("_DiffuseStrength"))
                _terrainMaterial.SetFloat("_DiffuseStrength", DiffuseLightStrength);
            if (_terrainMaterial.HasProperty("_Brightness"))
                _terrainMaterial.SetFloat("_Brightness", TerrainBrightness);
            if (_terrainMaterial.HasProperty("_FakeLightDir"))
                _terrainMaterial.SetVector("_FakeLightDir", GetShaderLightDirection());
            if (_terrainMaterial.HasProperty("_DebugMode"))
                _terrainMaterial.SetFloat("_DebugMode", _terrainDebugMode);

            if (forceLog)
                Debug.Log($"[C2:REN] runtimeState mode={_terrainDebugMode} ({DescribeTerrainMode(_terrainDebugMode)}) factureEnabled={_factureEnabled} factureStrength={PreviewFactureStrength:0.###} secondWeightScale={PreviewSecondWeightScale:0.###} factureWeightScale={PreviewFactureWeightScale:0.###} groundTiling={PreviewGroundTiling:0.###} secondTiling={PreviewSecondTiling:0.###} factureTiling={PreviewFactureTiling:0.###} slopeBlend={PreviewSlopeBlendPower:0.###} slopeSecondAtten={PreviewSlopeSecondAtten:0.###} slopeFactureAtten={PreviewSlopeFactureAtten:0.###} ambient={AmbientLightStrength:0.###} diffuse={DiffuseLightStrength:0.###} brightness={TerrainBrightness:0.###}");
        }

        private Vector4 GetShaderLightDirection()
        {
            Vector3 dir = (_light != null) ? (-_light.transform.forward.normalized) : new Vector3(0.45f, 0.85f, 0.35f).normalized;
            return new Vector4(dir.x, dir.y, dir.z, 0.0f);
        }

        private string GetMaterialTextureDebugName(Material mat)
        {
            if (mat == null)
                return "<none>";

            if (mat.HasProperty("_MainTex"))
            {
                var tex = mat.GetTexture("_MainTex");
                if (tex != null) return tex.name;
            }

            if (mat.HasProperty("_BaseMap"))
            {
                var tex = mat.GetTexture("_BaseMap");
                if (tex != null) return tex.name;
            }

            if (mat.HasProperty("_Control0"))
            {
                var tex = mat.GetTexture("_Control0");
                if (tex != null) return tex.name;
            }

            return "<none>";
        }

        private string BuildMaterialTextureAssignmentLog(Material mat, string phase)
        {
            Texture mainTex = (mat != null && mat.HasProperty("_MainTex")) ? mat.GetTexture("_MainTex") : null;
            Texture baseMap = (mat != null && mat.HasProperty("_BaseMap")) ? mat.GetTexture("_BaseMap") : null;
            return $"phase={phase} shader={mat?.shader?.name ?? "<null>"} mainTex={DescribeTextureObject(mainTex)} baseMap={DescribeTextureObject(baseMap)} sameObject={ReferenceEquals(mainTex, baseMap)}";
        }

        private static string DescribeTextureObject(Texture tex)
        {
            if (tex == null)
                return "<null>";

            int w = tex.width;
            int h = tex.height;
            return $"{tex.name}#{tex.GetInstanceID()}[{w}x{h}]";
        }

        private bool WasWaterDiagnosticsDumpPressed()
        {
#if ENABLE_INPUT_SYSTEM
            if (Keyboard.current == null)
                return false;
            bool enter = Keyboard.current.enterKey != null && Keyboard.current.enterKey.wasPressedThisFrame;
            bool keypad = Keyboard.current.numpadEnterKey != null && Keyboard.current.numpadEnterKey.wasPressedThisFrame;
            return enter || keypad;
#else
            return Input.GetKeyDown(KeyCode.Return) || Input.GetKeyDown(KeyCode.KeypadEnter);
#endif
        }
        private void DumpWaterDiagnostics(string trigger)
        {
            try
            {
                string report = BuildWaterDiagnosticsReport(trigger);
                foreach (string line in report.Split('\n'))
                {
                    if (!string.IsNullOrWhiteSpace(line))
                        Debug.Log(line.TrimEnd('\r'));
                }

                try
                {
                    string path = Path.Combine(Application.persistentDataPath, "C2WaterDebugLast.txt");
                    File.WriteAllText(path, report, Encoding.UTF8);
                    Debug.Log($"[C2:WATERDBG] file={path}");
                }
                catch (Exception ex)
                {
                    Debug.LogWarning("[C2:WATERDBG] saveFailed " + ex.Message);
                }
            }
            catch (Exception ex)
            {
                Debug.LogWarning("[C2:WATERDBG] dumpFailed " + ex.GetType().Name + " " + ex.Message);
            }
        }

        private string BuildWaterDiagnosticsReport(string trigger)
        {
            var sb = new StringBuilder(4096);
            EnsureExternalWaterPresetInitialized();
            var p = s_externalWaterPreset;
            sb.AppendLine($"[C2:WATERDBG] ===== begin trigger={trigger} time={Time.unscaledTime:0.000} map={_selectedId} =====");
            sb.AppendLine($"[C2:WATERDBG] runtime pivot={_pivot} dist={_distance:0.###} yaw={_yaw:0.###} pitch={_pitch:0.###} initialPivot={_initialPivot} initialDist={_initialDistance:0.###} initialYaw={_initialYaw:0.###} initialPitch={_initialPitch:0.###}");

            if (_camera != null)
            {
                Vector3 toPivot = (_pivot - _camera.transform.position).normalized;
                float lookDot = Vector3.Dot(_camera.transform.forward.normalized, toPivot);
                sb.AppendLine($"[C2:WATERDBG] cam pos={_camera.transform.position} rot={_camera.transform.eulerAngles} forward={_camera.transform.forward} up={_camera.transform.up} lookDot={lookDot:0.######} fov={_camera.fieldOfView:0.###} near={_camera.nearClipPlane:0.###} far={_camera.farClipPlane:0.###} aspect={_camera.aspect:0.######}");
                sb.AppendLine($"[C2:WATERDBG] cam worldToCamera={FormatMatrix(_camera.worldToCameraMatrix)}");
                sb.AppendLine($"[C2:WATERDBG] cam projection={FormatMatrix(_camera.projectionMatrix)}");
            }
            else
            {
                sb.AppendLine("[C2:WATERDBG] cam <null>");
            }

            sb.AppendLine($"[C2:WATERDBG] water mode={_lastWaterReflectionMode} writer={_lastWaterReflectionWriter} projectiveActive={_waterReflectionProjectiveActive} uvST={_waterReflectionUvST} targetState={_lastWaterReflectionTargetState} assigned={_lastWaterReflectionAssignedTex} fallback={_lastWaterReflectionFallbackTex} mapInfo={_lastWaterMapDataInfo}");
            sb.AppendLine($"[C2:WATERDBG] water projectiveMatrix={FormatMatrix(_waterReflectionProjectiveMatrix)}");
            sb.AppendLine($"[C2:WATERDBG] water planeY={GetWaterPlaneY():0.###} worldZSign={WorldZSign:0.###} usesStaticFallback={_waterUsesStaticFallbackData}");

            if (p != null)
            {
                sb.AppendLine($"[C2:WATERDBG] debugPreset normalAngle={p.NormalDirectionDeg:0.###} fallbackRot={p.ReflectionFallbackRotateDeg:0.###} fallbackFlipX={(p.ReflectionFallbackFlipX?1:0)} fallbackFlipY={(p.ReflectionFallbackFlipY?1:0)} projRot={p.ReflectionProjectiveRotateDeg:0.###} projFlipX={(p.ReflectionProjectiveFlipX?1:0)} projFlipY={(p.ReflectionProjectiveFlipY?1:0)} cloud={(p.EnableCloudReflection?1:0)} opacity={p.OpacityPercent:0.###} shoreOpacity={p.ShorelineOpacityPercent:0.###} shoreWidth={p.ShorelineWidthPercent:0.###}");
            }

            if (_waterReflectionCamera != null)
            {
                sb.AppendLine($"[C2:WATERDBG] reflCam pos={_waterReflectionCamera.transform.position} rot={_waterReflectionCamera.transform.eulerAngles} forward={_waterReflectionCamera.transform.forward} near={_waterReflectionCamera.nearClipPlane:0.###} far={_waterReflectionCamera.farClipPlane:0.###} aspect={_waterReflectionCamera.aspect:0.######}");
                sb.AppendLine($"[C2:WATERDBG] reflCam worldToCamera={FormatMatrix(_waterReflectionCamera.worldToCameraMatrix)}");
                sb.AppendLine($"[C2:WATERDBG] reflCam projection={FormatMatrix(_waterReflectionCamera.projectionMatrix)}");
            }
            else
            {
                sb.AppendLine("[C2:WATERDBG] reflCam <null>");
            }

            if (_waterMaterial != null)
            {
                sb.AppendLine($"[C2:WATERDBG] material shader={(_waterMaterial.shader != null ? _waterMaterial.shader.name : "<null>")} reflTex={GetWaterTexDebugName(_waterMaterial, "_ReflectionTex")} fallbackTex={GetWaterTexDebugName(_waterMaterial, "_ReflectionFallbackTex")} seaTex={GetWaterTexDebugName(_waterMaterial, "_SeaDataTex")} flowTex={GetWaterTexDebugName(_waterMaterial, "_FlowDataTex")} riverTex={GetWaterTexDebugName(_waterMaterial, "_RiverDataTex")}");
                sb.AppendLine($"[C2:WATERDBG] material alphaStrength={ReadMatFloat(_waterMaterial, "_AlphaStrength"):0.######} alphaCurve={ReadMatFloat(_waterMaterial, "_AlphaCurve"):0.######} reflectionStrength={ReadMatFloat(_waterMaterial, "_ReflectionStrength"):0.######} reflectionMix={ReadMatFloat(_waterMaterial, "_ReflectionMix"):0.######} skyBlend={ReadMatFloat(_waterMaterial, "_ReflectionSkyBlend"):0.######} realBlend={ReadMatFloat(_waterMaterial, "_ReflectionRealBlend"):0.######} minVisibleAlpha={ReadMatFloat(_waterMaterial, "_MinVisibleAlpha"):0.######}");
            }
            else
            {
                sb.AppendLine("[C2:WATERDBG] material <null>");
            }

            AppendWaterProjectionCoverage(sb, p);
            sb.AppendLine("[C2:WATERDBG] ===== end =====");
            return sb.ToString();
        }

        private void AppendWaterProjectionCoverage(StringBuilder sb, ExternalWaterPreset preset)
        {
            var mf = _waterGo != null ? _waterGo.GetComponent<MeshFilter>() : null;
            var mesh = mf != null ? mf.sharedMesh : null;
            if (mesh == null)
            {
                sb.AppendLine("[C2:WATERDBG] coverage mesh=<null>");
                return;
            }

            Vector3[] verts = mesh.vertices;
            if (verts == null || verts.Length == 0)
            {
                sb.AppendLine("[C2:WATERDBG] coverage verts=0");
                return;
            }

            int step = Mathf.Max(1, verts.Length / 256);
            Matrix4x4 l2w = _waterGo.transform.localToWorldMatrix;
            int total = 0;
            int positiveW = 0;
            int rawInside = 0;
            int debugInside = 0;
            float minRawX = float.PositiveInfinity, minRawY = float.PositiveInfinity, maxRawX = float.NegativeInfinity, maxRawY = float.NegativeInfinity;
            float minDbgX = float.PositiveInfinity, minDbgY = float.PositiveInfinity, maxDbgX = float.NegativeInfinity, maxDbgY = float.NegativeInfinity;
            Vector2 sampleRaw = Vector2.zero;
            Vector2 sampleDbg = Vector2.zero;
            float sampleW = 0.0f;
            Vector3 sampleWorld = Vector3.zero;
            bool sampleTaken = false;

            for (int i = 0; i < verts.Length; i += step)
            {
                Vector3 wp = l2w.MultiplyPoint3x4(verts[i]);
                Vector4 rp = _waterReflectionProjectiveMatrix * new Vector4(wp.x, wp.y, wp.z, 1.0f);
                total++;
                if (rp.w > 1e-5f)
                    positiveW++;

                if (Mathf.Abs(rp.w) > 1e-5f)
                {
                    Vector2 uvRaw = new Vector2(rp.x / rp.w, rp.y / rp.w) * 0.5f + Vector2.one * 0.5f;
                    Vector2 uvDbg = ApplyDebugUvTransformCpu(uvRaw,
                        preset != null ? preset.ReflectionProjectiveRotateDeg : 0.0f,
                        preset != null && preset.ReflectionProjectiveFlipX,
                        preset != null && preset.ReflectionProjectiveFlipY);

                    minRawX = Mathf.Min(minRawX, uvRaw.x); minRawY = Mathf.Min(minRawY, uvRaw.y);
                    maxRawX = Mathf.Max(maxRawX, uvRaw.x); maxRawY = Mathf.Max(maxRawY, uvRaw.y);
                    minDbgX = Mathf.Min(minDbgX, uvDbg.x); minDbgY = Mathf.Min(minDbgY, uvDbg.y);
                    maxDbgX = Mathf.Max(maxDbgX, uvDbg.x); maxDbgY = Mathf.Max(maxDbgY, uvDbg.y);

                    bool rawOk = rp.w > 1e-5f && uvRaw.x >= 0.0f && uvRaw.x <= 1.0f && uvRaw.y >= 0.0f && uvRaw.y <= 1.0f;
                    bool dbgOk = rp.w > 1e-5f && uvDbg.x >= 0.0f && uvDbg.x <= 1.0f && uvDbg.y >= 0.0f && uvDbg.y <= 1.0f;
                    if (rawOk) rawInside++;
                    if (dbgOk) debugInside++;
                    if (!sampleTaken)
                    {
                        sampleTaken = true;
                        sampleRaw = uvRaw;
                        sampleDbg = uvDbg;
                        sampleW = rp.w;
                        sampleWorld = wp;
                    }
                }
            }

            sb.AppendLine($"[C2:WATERDBG] coverage sampledVerts={total} positiveW={positiveW} rawInside01={rawInside} debugInside01={debugInside} rawUvMin=({minRawX:0.######},{minRawY:0.######}) rawUvMax=({maxRawX:0.######},{maxRawY:0.######}) dbgUvMin=({minDbgX:0.######},{minDbgY:0.######}) dbgUvMax=({maxDbgX:0.######},{maxDbgY:0.######})");
            if (sampleTaken)
                sb.AppendLine($"[C2:WATERDBG] coverage sampleWorld={sampleWorld} sampleW={sampleW:0.######} sampleRawUv={sampleRaw} sampleDbgUv={sampleDbg}");
        }

        private static Vector2 ApplyDebugUvTransformCpu(Vector2 uv, float rotateDeg, bool flipX, bool flipY)
        {
            Vector2 p = uv - Vector2.one * 0.5f;
            if (flipX)
                p.x = -p.x;
            if (flipY)
                p.y = -p.y;
            if (Mathf.Abs(rotateDeg) > 0.0001f)
            {
                float rad = rotateDeg * Mathf.Deg2Rad;
                float s = Mathf.Sin(rad);
                float c = Mathf.Cos(rad);
                p = new Vector2(p.x * c - p.y * s, p.x * s + p.y * c);
            }
            return p + Vector2.one * 0.5f;
        }

        private static string FormatMatrix(Matrix4x4 m)
        {
            return $"[{m.m00:0.######},{m.m01:0.######},{m.m02:0.######},{m.m03:0.######}; {m.m10:0.######},{m.m11:0.######},{m.m12:0.######},{m.m13:0.######}; {m.m20:0.######},{m.m21:0.######},{m.m22:0.######},{m.m23:0.######}; {m.m30:0.######},{m.m31:0.######},{m.m32:0.######},{m.m33:0.######}]";
        }

